/* Load a single string from a STR# resource.
 * index is 0-based; GetIndString uses 1-based indexing. */
static void LoadSTRString(short strListID, short index, Str255 outStr)
{
    GetIndString(outStr, strListID, index + 1);
    /* If resource missing, outStr[0] will be 0 (empty Pascal string) */
}

/* Get a cached string from a STR# resource table.
 * Returns pointer to Pascal string, or fallback if resource unavailable. */
static const unsigned char *GetCachedString(short strListID, short index,
                                            const unsigned char *fallback)
{
    short i;
    for (i = 0; i < STR_CACHE_COUNT; i++) {
        if (sStrCache[i].strListID == strListID) {
            if (!sStrCache[i].loaded) {
                short j;
                for (j = 0; j < sStrCache[i].count && j < MAX_CACHED_STRINGS; j++) {
                    GetIndString(sStrCache[i].strings[j], strListID, j + 1);
                }
                sStrCache[i].loaded = true;
            }
            if (index >= 0 && index < sStrCache[i].count &&
                sStrCache[i].strings[index][0] > 0) {
                return sStrCache[i].strings[index];
            }
            return fallback;
        }
    }
    return fallback;
}

/* ===== DAT 1000 Master String Table ===== */
/* Contains all in-game text: defeat/victory messages, military advisor quotes,
 * terrain descriptions, combat bonus text, loading screen messages.
 * Stored as null-delimited strings in a single resource. */
#define DAT_MASTER_STRINGS  1000
#define MAX_DAT_STRINGS     256
#define MAX_DAT_STRING_LEN  128

static char sDATStrings[MAX_DAT_STRINGS][MAX_DAT_STRING_LEN];
static short sDATStringCount = 0;
static Boolean sDATStringsLoaded = false;

static void LoadDATMasterStrings(void)
{
    Handle h;
    if (sDATStringsLoaded) return;
    sDATStringsLoaded = true;

    h = GetResource('DAT ', DAT_MASTER_STRINGS);
    if (h == NULL) return;

    HLock(h);
    {
        long size = GetHandleSize(h);
        const char *p = (const char *)*h;
        const char *end = p + size;
        short idx = 0;

        while (p < end && idx < MAX_DAT_STRINGS) {
            short len = 0;
            while (p + len < end && p[len] != '\0' && len < MAX_DAT_STRING_LEN - 1)
                len++;
            if (len > 0) {
                BlockMoveData(p, sDATStrings[idx], len);
                sDATStrings[idx][len] = '\0';
                idx++;
            }
            p += len;
            if (p < end && *p == '\0') p++;  /* skip null terminator */
        }
        sDATStringCount = idx;
    }
    HUnlock(h);
}

/* Get a string from the DAT 1000 master table as a Pascal string */
static void GetDATString(short index, Str255 outStr, const char *fallback)
{
    if (!sDATStringsLoaded) LoadDATMasterStrings();
    if (index >= 0 && index < sDATStringCount && sDATStrings[index][0] != '\0') {
        short len = 0;
        while (len < 255 && sDATStrings[index][len] != '\0') len++;
        outStr[0] = (unsigned char)len;
        BlockMoveData(sDATStrings[index], outStr + 1, len);
    } else if (fallback) {
        short len = 0;
        while (len < 255 && fallback[len] != '\0') len++;
        outStr[0] = (unsigned char)len;
        BlockMoveData(fallback, outStr + 1, len);
    } else {
        outStr[0] = 0;
    }
}

/* ===== DAT 1000 Terrain Descriptions ===== */
/* The terrain name/description block in DAT 1000 starts with 10 terrain names
 * (Road, Bridge, Water, Shore, Forest, Hills, Mountains, Plain, Marsh, Tower)
 * followed immediately by 10 matching descriptions.
 * We locate the block by searching for the anchor "Road\0Bridge\0" and then
 * map each DAT terrain index to our internal terrain-type numbering. */

#define TERRAIN_DESC_COUNT 10
static char sTerrainDesc[TERRAIN_DESC_COUNT][64];
static Boolean sTerrainDescLoaded = false;

/* Maps terrain type (0-9) to DAT 1000 terrain description index.
 * 68k terrain types: 0=Road, 1=Bridge, 2=Water, 3=Shore, 4=Forest,
 * 5=Hills, 6=Mountains, 7=Plains, 8=Marsh, 9=Sea */
static const short kTerrTypeToDAT[10] = {
    0, /* 0: Road      → Road (DAT index 0)   */
    1, /* 1: Bridge    → Bridge (DAT index 1)  */
    2, /* 2: Water     → Water (DAT index 2)   */
    3, /* 3: Shore     → Shore (DAT index 3)   */
    4, /* 4: Forest    → Forest (DAT index 4)  */
    5, /* 5: Hills     → Hills (DAT index 5)   */
    6, /* 6: Mountains → Mountains (DAT index 6) */
    7, /* 7: Plains    → Plain (DAT index 7)   */
    8, /* 8: Marsh     → Marsh (DAT index 8)   */
    2  /* 9: Sea       → Water (DAT index 2)   */
};

static void LoadTerrainDescriptions(void)
{
    Handle h;
    if (sTerrainDescLoaded) return;
    sTerrainDescLoaded = true;

    h = GetResource('DAT ', DAT_MASTER_STRINGS);
    if (h == NULL) return;

    HLock(h);
    {
        long size = GetHandleSize(h);
        const char *p = (const char *)*h;
        const char *end = p + size;
        /* Locate anchor: "Road\0Bridge\0" */
        const char *anchor = NULL;
        const char *scan = p;
        while (scan + 12 < end) {
            if (scan[0]=='R' && scan[1]=='o' && scan[2]=='a' && scan[3]=='d' &&
                scan[4]=='\0' &&
                scan[5]=='B' && scan[6]=='r' && scan[7]=='i' && scan[8]=='d' &&
                scan[9]=='g' && scan[10]=='e' && scan[11]=='\0') {
                anchor = scan;
                break;
            }
            scan++;
        }
        if (anchor) {
            /* Skip 10 terrain names to reach descriptions */
            const char *cur = anchor;
            short i;
            for (i = 0; i < TERRAIN_DESC_COUNT && cur < end; i++) {
                while (cur < end && *cur != '\0') cur++;
                if (cur < end) cur++; /* skip null */
            }
            /* Now cur points to first description; read 10 descriptions */
            for (i = 0; i < TERRAIN_DESC_COUNT && cur < end; i++) {
                short len = 0;
                while (cur + len < end && cur[len] != '\0' && len < 63) len++;
                BlockMoveData(cur, sTerrainDesc[i], len);
                sTerrainDesc[i][len] = '\0';
                cur += len;
                if (cur < end) cur++; /* skip null */
            }
        }
    }
    HUnlock(h);
}

/* ===== DAT 1011 Item Definitions ===== */
/* Contains 39 ruin items with names, category codes, and bonus values.
 * If loaded successfully, overrides the hardcoded sItemTable names. */
#define DAT_ITEM_DEFS  1011

static Boolean sDAT1011Loaded = false;

static void LoadDATItemDefs(void)
{
    Handle h;
    if (sDAT1011Loaded) return;
    sDAT1011Loaded = true;

    h = GetResource('DAT ', DAT_ITEM_DEFS);
    if (h == NULL) return;

    HLock(h);
    {
        long size = GetHandleSize(h);
        const unsigned char *p = (const unsigned char *)*h;
        short idx = 0;

        /* DAT 1011 format: each entry is a packed record with a Pascal-style
         * name string followed by type and value fields.
         * Try parsing as: [name_len] [name_bytes...] [type:2] [value:2]
         * If that doesn't work, fall back to null-terminated strings. */
        while ((const char *)p < (const char *)*h + size && idx < MAX_ITEMS) {
            short nameLen = (short)*p;
            if (nameLen > 0 && nameLen < 20 &&
                (const char *)p + 1 + nameLen + 4 <= (const char *)*h + size) {
                /* Pascal-style entry */
                ItemDef *item = (ItemDef *)&sItemTable[idx];  /* cast away const to update */
                short copyLen = nameLen < 19 ? nameLen : 19;
                BlockMoveData(p + 1, item->name, copyLen);
                item->name[copyLen] = '\0';
                item->type = *(short *)(p + 1 + nameLen);
                item->value = *(short *)(p + 1 + nameLen + 2);
                p += 1 + nameLen + 4;
                idx++;
            } else {
                /* Skip unknown data */
                break;
            }
        }
    }
    HUnlock(h);
}

/* ===== Game item records (PPC 1.0.7 FUN_1003956c) =====
 * gs+0xD12 + i*0x1E, 22 records (i = 0..21):
 *   +0x00 name[20], +0x14 type (byte), +0x15 value (byte),
 *   +0x16 status (short): 0 not in play / sunk, 1 on the ground,
 *                         2 hidden in a ruin, 3 carried
 *   +0x18 carrier (short): army index (carried) / site index (hidden)
 *   +0x1A, +0x1C ground x, y (shorts).
 * Records 0-7 are the per-player Standards (type 8), 8-21 unique picks
 * from the 39-entry ITM list (sItemTable).  Hero item slots hold the
 * 1-based record number. */
#define GAME_ITEM_COUNT     22
#define ITEM_ST_NONE        0
#define ITEM_ST_GROUND      1
#define ITEM_ST_RUIN        2
#define ITEM_ST_CARRIED     3
#define ITEM_STATUS(r)      (*(short *)((r) + 0x16))
#define ITEM_CARRIER(r)     (*(short *)((r) + 0x18))

/* Site reward kinds (site record +0x0C; temples/empty sites have no search) */
#define SITE_KIND(s)        ((s)[0x0C])
#define SITE_ALLY_RANK(s)   ((s)[0x0E])  /* 0-3 strongest, 4-6 next, 0xFF weakest */
#define SITE_ITEM(s)        ((s)[0x10])
#define SITE_HARD(s)        ((s)[0x1C])
#define SITE_GUARDIAN(s)    ((s)[0x1A])
#define SITE_EMPTY          0
#define SITE_TEMPLE         1
#define SITE_ITEM_KIND      2
#define SITE_SAGE           3
#define SITE_GOLD           4
#define SITE_ALLIES         5

/* Per-player Standard names, read from SCN+0xCE9 + i*0x1D at GameInit
 * (before anything is written over that part of gs). */
static char sStandardNames[8][20];

/* GameItemRec — record for a 1-based item id, NULL if out of range. */
static unsigned char *GameItemRec(short itemId)
{
    if (*gGameState == 0 || itemId < 1 || itemId > GAME_ITEM_COUNT) return NULL;
    return (unsigned char *)*gGameState + 0xD12 + (itemId - 1) * 0x1E;
}

static short GameItemType(short itemId)
{
    unsigned char *r = GameItemRec(itemId);
    return r ? (short)r[0x14] : 0;
}

static short GameItemValue(short itemId)
{
    unsigned char *r = GameItemRec(itemId);
    return r ? (short)r[0x15] : 0;
}

/* GameItemPName — the record's name as a Pascal string. */
static void GameItemPName(short itemId, Str255 out)
{
    unsigned char *r = GameItemRec(itemId);
    short n = 0;
    if (r) while (n < 19 && r[n]) { out[n + 1] = r[n]; n++; }
    out[0] = (unsigned char)n;
}

/* GameItemDef — copy a record's name/type/value into an ItemDef view so the
 * display code can keep its ItemDef shape (never read sItemTable[id-1] for a
 * game item: the records are random picks). */
static const ItemDef *GameItemDef(short itemId, ItemDef *buf)
{
    unsigned char *r = GameItemRec(itemId);
    short n = 0;
    if (r) while (n < 19 && r[n]) { buf->name[n] = (char)r[n]; n++; }
    buf->name[n] = 0;
    buf->type = r ? (short)r[0x14] : 0;
    buf->value = r ? (short)r[0x15] : 0;
    return buf;
}

/* "Special" item (FUN_1003956c): movement, flying, command > 1, standard. */
static Boolean IsSpecialItemTV(short type, short value)
{
    return type == ITEM_TYPE_MOVEMENT || type == ITEM_TYPE_FLYING ||
           (type == ITEM_TYPE_COMMAND && value > 1) || type == ITEM_TYPE_FLAT_PLUS;
}

/* Dice: 1dS = 1..S */
static short RollDie(short sides)
{
    if (sides < 1) return 1;
    return (short)((unsigned short)Random() % (unsigned short)sides) + 1;
}

