/* Unit type definition table: loaded from DAT 30000 (terrain file) or DAT 20000 (armies file).
 * Each entry is 0x3E (62) bytes: byte sprite_index + byte reserved + char[20] name + short[20] stats.
 * Stats stored as big-endian shorts, high byte = game value:
 *   [0]=strength, [1]=prod_turns, [2]=gold_cost, [3]=movement,
 *   [16]=flying_flag, [19]=naval_flag.
 * Up to 29 entries (type IDs 0-28). */
#define UTE_STAT_NAVAL    0x3C  /* offset of stat[19] high byte: 1 = naval unit */
#define UTE_STAT_FLYING   0x36  /* offset of stat[16] high byte: 1 = aerial/flying */
#define MAX_UNIT_TYPES    29
#define UNIT_TYPE_ENTRY   0x3E  /* 62 bytes per entry */
/* Per-sprite terrain type table. The original's gs+0x711 is SCN+0x710: its
 * game state is one byte off from the raw scenario (as gold at SCN+0x185),
 * and the remake keeps the raw SCN in gs. Verified on Erythea: plains sprites
 * 31/9 -> 7, water 39/45 -> 2, and moves into marsh tiles cost 5 as on the
 * original (reading 0x711 gave plains = Shore, i.e. impassable). */
#define TERRAIN_TYPE_OFS  0x710
#define UNIT_CLASS_FLIGHT 0x40  /* GetEffectiveUnitClass: hero with a flight item
                                 * (was 0x0E, which is a real standard type) */
static unsigned char sUnitTypeTable[MAX_UNIT_TYPES * UNIT_TYPE_ENTRY];
static unsigned char sUnitTypeTableBase[MAX_UNIT_TYPES * UNIT_TYPE_ENTRY]; /* original (pre-variance) */

/* The game's unit type numbers are the standard type numbers, which equal
 * each entry's sprite index (byte 0); the army-set DAT lists them in another
 * order (Grasslands: Scouts, Giant Bats, Light Inf., ...). Verified on
 * Erythea: Mirea's SCN slots 01 04 05 0a are Heavy Inf., Heavy Cav., Navy
 * (dropped, not a port) and Catapults, and the starting type 4 is Heavy Cav.
 * (upkeep 8/2 = 4, as the original shows). Reorder so index == sprite. */
static short sUnitDatOrder[MAX_UNIT_TYPES];   /* standard id of army-file entry i */
static void IndexUnitTypesBySprite(unsigned char *tbl, short count)
{
    static unsigned char tmp[MAX_UNIT_TYPES * UNIT_TYPE_ENTRY];
    Boolean seen[MAX_UNIT_TYPES];
    short i;
    for (i = 0; i < count; i++) { seen[i] = false; sUnitDatOrder[i] = i; }
    for (i = 0; i < count; i++) sUnitDatOrder[i] = tbl[i * UNIT_TYPE_ENTRY] < count ? tbl[i * UNIT_TYPE_ENTRY] : i;
    for (i = 0; i < count; i++) {
        short k = tbl[i * UNIT_TYPE_ENTRY];
        if (k >= count || seen[k]) return;      /* not a permutation: leave as is */
        seen[k] = true;
        BlockMoveData(tbl + i * UNIT_TYPE_ENTRY, tmp + k * UNIT_TYPE_ENTRY, UNIT_TYPE_ENTRY);
    }
    BlockMoveData(tmp, tbl, (long)count * UNIT_TYPE_ENTRY);
}
