static void DrawPaletteArt(const short *art, short w, short h, short x, short y)
{
    short i, j;
    RGBColor c;
    for (j = 0; j < h; j++)
        for (i = 0; i < w; i++) {
            short idx = art[j * w + i];
            if (idx < 0 || sGamePal == NULL) continue;
            GetEntryColor(sGamePal, idx, &c);
            SetCPixel(x + i, y + j, &c);
        }
}

/* MacApp T3DCheckBox, measured on the original: 12x12 black square filled
 * 0xDDDD at (left+2,top+2), in a 1px bevel dark 0x5555 above/left and light
 * 0xBBBB below/right. */
static void DrawT3DCheckBox(short left, short top, Boolean on)
{
    RGBColor dark = {0x5555, 0x5555, 0x5555}, light = {0xBBBB, 0xBBBB, 0xBBBB};
    RGBColor fill = {0xDDDD, 0xDDDD, 0xDDDD}, black = {0, 0, 0};
    Rect b;
    RGBForeColor(&dark);
    MoveTo(left + 1, top + 14); LineTo(left + 1, top + 1); LineTo(left + 14, top + 1);
    RGBForeColor(&light);
    MoveTo(left + 2, top + 14); LineTo(left + 14, top + 14); LineTo(left + 14, top + 2);
    SetRect(&b, left + 2, top + 2, left + 14, top + 14);
    RGBForeColor(&black); FrameRect(&b);
    InsetRect(&b, 1, 1);
    RGBForeColor(&fill); PaintRect(&b);
    if (on) {   /* corner-to-corner X across the 10x10 interior (captured) */
        RGBForeColor(&black);
        MoveTo(b.left, b.top); LineTo(b.right - 1, b.bottom - 1);
        MoveTo(b.right - 1, b.top); LineTo(b.left, b.bottom - 1);
    }
}

#include "mac_ui_art.h"

/* T3DPopup: frame art from the original plus the current item in Chicago 12. */
static void DrawT3DPopup(short left, short top, ConstStr255Param item)
{
    short i, j;
    RGBColor c, black = {0, 0, 0};
    for (j = 0; j < POPUP_ART_H; j++)
        for (i = 0; i < POPUP_ART_W; i++) {
            if (sGamePal == NULL) break;
            GetEntryColor(sGamePal, kPopupArt[j][i], &c);
            SetCPixel(left + i, top + j, &c);
        }
    TextFont(ChicagoFont()); TextSize(12); TextFace(0);
    RGBForeColor(&black);
    {   /* the original clips the item to the text area (cuts the 'g' tail) */
        Rect clip;
        RgnHandle saved = NewRgn();
        GetClip(saved);
        SetRect(&clip, left + 4, top + 3, left + 105, top + 15);
        ClipRect(&clip);
        MoveTo(left + 6, top + 13);
        DrawString(item);
        SetClip(saved);
        DisposeRgn(saved);
    }
}

static void DrawT3DRadio(short left, short top, Boolean on)
{
    DrawPaletteArt(on ? &kRadioOn[0][0] : &kRadioOff[0][0], 12, 12, left + 2, top + 2);
}

/* ===================================================================
 * RunEasyGameSetup — View 3024 "Easy game setup" (the original's default
 * Game Setup). 353x286 altDBoxProc window centred below the menu bar.
 * Radios, checkbox and popup are real Control Manager controls: on 8.6 the
 * original's T3D controls are the Appearance (Platinum) CDEFs with labels
 * drawn embossed by MacApp. Returns 0 = Begin Game, 1 = More Choices,
 * 2 = cancelled (Escape).
 * =================================================================== */
#define EASY_W 353
#define EASY_H 286
static short RunEasyGameSetup(char names[][FACTION_NAME_LEN + 1], short factionCount,
                              short *side, short *skill)
{
    WindowPtr win;
    Rect wr, r;
    short i, result = -1, mbar = GetMBarHeight();
    Rect screen = qd.screenBits.bounds;
    MenuHandle presetMenu;
    Rect editR, moreR, goR, goBtn, popR;
    Str255 s;
    static const short compStr[3] = {13, 14, 5};   /* STR# 3020: Knight, Lord, Warlord */
    Boolean aiAssigned = false;

    /* MacApp centres the window including altDBoxProc's 2px shadow */
    SetRect(&wr, (screen.right - (EASY_W + 2)) / 2, mbar + (screen.bottom - mbar - (EASY_H + 2)) / 2, 0, 0);
    wr.right = wr.left + EASY_W; wr.bottom = wr.top + EASY_H;
    win = NewCWindow(NULL, &wr, "\p", false, altDBoxProc, (WindowPtr)-1L, false, 0);
    if (win == NULL) return 2;
    ApplyGamePalette(win);
    SetPort(win);
    TextFont(ChicagoFont()); TextSize(12);     /* control titles / popup use the window font */


    presetMenu = NewMenu(240, "\p");                 /* CMNU 70 items */
    AppendMenu(presetMenu, "\pBeginner;Intermediate;Advanced");
    InsertMenu(presetMenu, -1);
    SetRect(&popR, 179 + 16, 132 + 20, 179 + 16 + 132, 132 + 20 + 19);   /* 'popu' */

    SetRect(&editR, 179 + 16, 132 + 49, 179 + 16 + 132, 132 + 49 + 21);
    SetRect(&moreR, 13, 252, 13 + 132, 252 + 21);
    SetRect(&goR, 204, 248, 204 + 140, 248 + 29);
    goBtn = goR; InsetRect(&goBtn, 4, 4);

    ShowWindow(win);
    FlushEvents(everyEvent, 0);

    while (result < 0) {
        EventRecord evt;
        if (!WaitNextEvent(everyEvent, &evt, 30, NULL)) continue;
        if (evt.what == updateEvt && (WindowPtr)evt.message == win) {
            RGBColor black = {0, 0, 0};
            BeginUpdate(win);
            {   /* TPlainPicture: PICT 1001 marble at the origin */
                PicHandle marble = GetPicture(1001);
                if (marble != NULL) {
                    Rect pf = (**marble).picFrame;
                    OffsetRect(&pf, -pf.left, -pf.top);
                    DrawPicture(marble, &pf);
                }
            }
            SetRect(&r, 0, 8, EASY_W, 48);
            DrawSunkenText(&r, ViewString(s, 3010, 20, "\pGame setup"), IlluriaFont(), 36, 1);

            SetRect(&r, 9, 48, 9 + 162, 48 + 166);
            DrawT3DCluster(&r, ViewString(s, 3020, 11, "\pSide to play"));
            SetRect(&r, 179, 48, 179 + 162, 48 + 81);
            DrawT3DCluster(&r, ViewString(s, 3020, 12, "\pComputer Level"));
            SetRect(&r, 179, 132, 179 + 162, 132 + 108);
            DrawT3DCluster(&r, ViewString(s, 3020, 4, "\pOptions"));

            TextFont(ChicagoFont()); TextSize(12); TextFace(0);
            for (i = 0; i < factionCount && i < MAX_FACTIONS; i++) {
                Rect sh;
                RGBColor cream = {0xFFFF, 0xFFFF, 0xCCCC};
                short n = 0;
                SetRect(&sh, 9 + 11, 48 + 21 + 17 * i, 9 + 11 + 11, 48 + 21 + 17 * i + 14);
                DrawSmallShieldIcon(i, &sh);           /* TPicCopyView, native 11x14 */
                DrawT3DRadio(9 + 22, 48 + 20 + 17 * i, i == *side);
                while (n < FACTION_NAME_LEN && names[i][n]) n++;
                s[0] = (unsigned char)n; BlockMoveData(names[i], s + 1, n);
                DrawEmbossedString(s, 9 + 22 + 17, 48 + 20 + 17 * i + 11, &cream);
            }
            for (i = 0; i < 3; i++) {
                RGBColor cream = {0xFFFF, 0xFFFF, 0xCCCC};
                DrawT3DRadio(179 + 14, 48 + 20 + 17 * i, i == *skill);
                DrawEmbossedString(ViewString(s, 3020, compStr[i], "\p"), 179 + 14 + 17,
                                   48 + 20 + 17 * i + 11, &cream);
            }
            {
                RGBColor cream = {0xFFFF, 0xFFFF, 0xCCCC};
                DrawT3DCheckBox(179 + 14, 132 + 80, sIAmGreatest);
                DrawEmbossedString(ViewString(s, 3020, 2, "\pI am the Greatest"), 179 + 14 + 17,
                                   132 + 80 + 11, &cream);
            }
            {
                Str255 num, line;
                /* The original rates the game state's AI players: none until a
                 * side / level radio is clicked (SCNs ship without AIs). */
                short rating = aiAssigned ? CalcDifficultyRating(*skill) : CalcDifficultyRatingNoAI();
                NumToString((long)rating, num);
                BlockMoveData("\pDifficulty Rating ", line, 19);
                BlockMoveData(num + 1, line + 1 + line[0], num[0]); line[0] += num[0];
                line[++line[0]] = '%';
                SetRect(&r, 10, 220, 10 + 162, 220 + 19);
                DrawSunkenText(&r, line, IlluriaFont(), 17, 1);
            }
            DrawT3DButton(&editR, ViewString(s, 3010, 9, "\pEdit Options\311"));
            DrawT3DButton(&moreR, ViewString(s, 3010, 21, "\pMore Choices"));
            RGBForeColor(&black);
            PenSize(3, 3); FrameRoundRect(&goR, 16, 16); PenSize(1, 1);
            DrawT3DButton(&goBtn, ViewString(s, 3010, 11, "\pBegin Game"));
            {
                Str255 item;
                GetMenuItemText(presetMenu, sOptionsPreset + 1, item);
                DrawT3DPopup(popR.left, popR.top, item);
            }
            EndUpdate(win);
        } else if (evt.what == mouseDown) {
            WindowPtr hit;
            Point pt = evt.where;
            if (FindWindow(pt, &hit) != inContent || hit != win) continue;
            GlobalToLocal(&pt);
            {   /* T3DRadio views: the whole 16-tall row is the hit area */
                Rect rr;
                for (i = 0; i < factionCount && i < MAX_FACTIONS; i++) {
                    SetRect(&rr, 9 + 22, 48 + 20 + 17 * i, 9 + 22 + 135, 48 + 20 + 17 * i + 16);
                    if (PtInRect(pt, &rr)) { *side = i; aiAssigned = true; InvalRect(&win->portRect); }
                }
                for (i = 0; i < 3; i++) {
                    SetRect(&rr, 179 + 14, 48 + 20 + 17 * i, 179 + 14 + 140, 48 + 20 + 17 * i + 16);
                    if (PtInRect(pt, &rr)) { *skill = i; aiAssigned = true; InvalRect(&win->portRect); }
                }
                SetRect(&rr, 179 + 14, 132 + 80, 179 + 14 + 138, 132 + 80 + 16);   /* 'grea' */
                if (PtInRect(pt, &rr)) { sIAmGreatest = !sIAmGreatest; InvalRect(&win->portRect); }
            }
            if (PtInRect(pt, &popR)) {
                Point g;
                long choice;
                g.h = popR.left; g.v = popR.top;
                LocalToGlobal(&g);
                choice = PopUpMenuSelect(presetMenu, g.v, g.h, sOptionsPreset + 1);
                if ((choice & 0xFFFF) != 0) {
                    sOptionsPreset = (short)(choice & 0xFFFF) - 1;
                    ApplyOptionsPreset(sOptionsPreset);
                }
                InvalRect(&win->portRect);   /* difficulty rating may change */
            } else if (PtInRect(pt, &goR)) {
                result = 0;
            } else if (PtInRect(pt, &moreR)) {
                result = 1;
            } else if (PtInRect(pt, &editR)) {
                ShowEditOptions();
                SetPort(win);
                InvalRect(&win->portRect);
            }
        } else if (evt.what == keyDown) {
            char key = evt.message & charCodeMask;
            if (key == 0x0D || key == 0x03) result = 0;
            else if (key == 0x1B) result = 2;
        }
    }
    DisposeWindow(win);
    DeleteMenu(240);
    DisposeMenu(presetMenu);
    return result;
}

/* ===================================================================
 * ShowGameSetup — Display game setup dialog
 *
 * Shows a modal window where the player chooses their faction and
 * the computer AI skill level before starting the game.
 * Faction names are parsed from SCN resource data in gGameState.
 * Returns true if "Begin Game" was clicked, false on Escape.
 * =================================================================== */
static Boolean ShowGameSetup(void)
{
    WindowPtr  setupWin;
    GWorldPtr  offscreen = NULL;
    Rect       winRect;
    Boolean    done = false;
    Boolean    beginGame = false;
    short      selectedSide = 0;
    short      computerSkill = 0;
    Boolean    showMoreChoices = false;
    Rect       screenRect = qd.screenBits.bounds;
    char       factionNames[MAX_FACTIONS][FACTION_NAME_LEN + 1];
    short      factionCount = 0;
    short      i;
    short      winW, winH;

    static const unsigned char *aiLabels[4] = {
        "\pHuman", "\pKnight", "\pLord", "\pWarlord"
    };
    static const unsigned char *presetLabels[3] = {
        "\pBeginner", "\pIntermediate", "\pAdvanced"
    };

    /* Parse faction names from SCN resource (offset 0, 8x20 bytes) */
    if (*gGameState != 0) {
        unsigned char *scnData = (unsigned char *)*gGameState;
        for (i = 0; i < MAX_FACTIONS; i++) {
            BlockMoveData(scnData + i * FACTION_NAME_LEN,
                          factionNames[i], FACTION_NAME_LEN);
            factionNames[i][FACTION_NAME_LEN] = 0;
            if (factionNames[i][0] != 0)
                factionCount = i + 1;
        }
    }

    if (factionCount == 0)
        factionCount = MAX_FACTIONS;

    /* The original's default setup is View 3024 (easy); "More Choices" opens
     * the expanded one, still the remake's own layout below. */
    {
        short easy = RunEasyGameSetup(factionNames, factionCount, &selectedSide, &computerSkill);
        for (i = 0; i < factionCount; i++)
            sFactionAI[i] = (i == selectedSide) ? 0 : (sIAmGreatest ? 1 : computerSkill + 1);
        if (easy == 0)      { done = true; beginGame = true; }
        else if (easy == 2) { done = true; }
        else                showMoreChoices = true;
    }

    /* Simple mode: 460x340 */
    winW = showMoreChoices ? 560 : 460;
    winH = showMoreChoices ? 420 : 340;

    SetRect(&winRect,
        (screenRect.right - winW) / 2,
        (screenRect.bottom - winH) / 2,
        (screenRect.right - winW) / 2 + winW,
        (screenRect.bottom - winH) / 2 + winH);

    setupWin = done ? NULL : NewCWindow(NULL, &winRect, "\p", false,
                          plainDBox, (WindowPtr)-1L, false, 0);
    if (setupWin == NULL && !done)
        return false;

    if (setupWin != NULL) {
        SetPort(setupWin);
        ShowWindow(setupWin);
    }   /* show up front — we draw directly now (the old
                             * ShowWindow lived inside the offscreen-blit block). */

    {
        /* Draw the setup screen DIRECTLY to the window (no offscreen buffer).
         * An offscreen GWorld matched PICT 1001's dark-granite marble to the
         * wrong palette and washed it out (same regression as the city-build
         * dialog). The window has the correct screen palette, so drawing
         * straight to it keeps the marble dark, matching the original. Redraw is
         * on-demand (only after a click), so there is no continuous flicker.
         * offscreen stays NULL; every `if (offscreen != NULL)` path is skipped. */
        offscreen = NULL;
    }

    FlushEvents(everyEvent, 0);

    {
        Boolean needsRedraw = true;
        Boolean setupShown = false;
        unsigned long startTick = TickCount();

        while (!done) {
            EventRecord evt;

            if (needsRedraw) {
                Rect r;
                CGrafPtr savedPort;
                GDHandle savedDevice;
                SetRect(&r, 0, 0, winW, winH);

                if (offscreen != NULL) {
                    GetGWorld(&savedPort, &savedDevice);
                    SetGWorld(offscreen, NULL);
                    LockPixels(GetGWorldPixMap(offscreen));
                }

                /* Dark background */
                {
                    DrawMarbleBackground(&r);
                }

                /* Title */
                {
                    RGBColor gold = {0xFFFF, 0xCCCC, 0x3333};
                    RGBForeColor(&gold);
                    TextFont(2);
                    TextSize(18);
                    TextFace(bold);
                    MoveTo(20, 30);
                    DrawString(GetCachedString(STR_GAME_SETUP, 0, "\pGame Setup"));
                }

                if (!showMoreChoices) {
                    /* ========== SIMPLE MODE ========== */

                    /* "Side to play" label */
                    {
                        RGBColor labelColor = {0xFFFF, 0xCCCC, 0x3333};
                        RGBForeColor(&labelColor);
                        TextFont(2);
                        TextSize(12);
                        TextFace(bold);
                        MoveTo(30, 60);
                        DrawString(GetCachedString(STR_GAME_SETUP, 1, "\pSide to play"));
                    }

                    /* Faction radio buttons with shield icons */
                    TextFont(3);
                    TextSize(10);
                    TextFace(0);
                    for (i = 0; i < factionCount; i++) {
                        short yPos = 78 + i * 22;
                        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                        Rect radioRect;

                        SetRect(&radioRect, 35, yPos - 9, 47, yPos + 3);
                        RGBForeColor(&white);
                        FrameOval(&radioRect);

                        if (i == selectedSide) {
                            Rect fillRect;
                            SetRect(&fillRect, 38, yPos - 6, 44, yPos);
                            PaintOval(&fillRect);
                        }

                        /* Shield icon next to radio button (13x15 small shield) */
                        if (sShieldsLoaded) {
                            Rect shR;
                            SetRect(&shR, 52, yPos - 10, 52 + 13, yPos + 5);
                            DrawSmallShieldIcon(i, &shR);
                        }

                        RGBForeColor(&white);
                        MoveTo(70, yPos);
                        {
                            Str255 pName;
                            short nlen = 0;
                            while (nlen < FACTION_NAME_LEN && factionNames[i][nlen] != 0)
                                nlen++;
                            pName[0] = (unsigned char)nlen;
                            BlockMoveData(factionNames[i], pName + 1, nlen);
                            DrawString(pName);
                        }
                    }

                    /* "Computer Level" label (matches the original game) */
                    {
                        RGBColor labelColor = {0xFFFF, 0xCCCC, 0x3333};
                        RGBForeColor(&labelColor);
                        TextFont(2);
                        TextSize(12);
                        TextFace(bold);
                        MoveTo(260, 60);
                        DrawString(GetCachedString(STR_GAME_SETUP, 2, "\pComputer Level"));
                    }

                    /* Skill level radio buttons */
                    TextFont(3);
                    TextSize(10);
                    TextFace(0);
                    for (i = 0; i < 3; i++) {
                        short yPos = 78 + i * 22;
                        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                        Rect radioRect;

                        SetRect(&radioRect, 265, yPos - 9, 277, yPos + 3);
                        RGBForeColor(&white);
                        FrameOval(&radioRect);

                        if (i == computerSkill) {
                            Rect fillRect;
                            SetRect(&fillRect, 268, yPos - 6, 274, yPos);
                            PaintOval(&fillRect);
                        }

                        MoveTo(282, yPos);
                        if (i == 0) DrawString(GetCachedString(STR_GAME_SETUP, 3, "\pKnight"));
                        else if (i == 1) DrawString(GetCachedString(STR_GAME_SETUP, 4, "\pLord"));
                        else DrawString(GetCachedString(STR_GAME_SETUP, 5, "\pWarlord"));
                    }

                    /* "Options" label */
                    {
                        RGBColor labelColor = {0xFFFF, 0xCCCC, 0x3333};
                        RGBForeColor(&labelColor);
                        TextFont(2);
                        TextSize(12);
                        TextFace(bold);
                        MoveTo(260, 160);
                        DrawString(GetCachedString(STR_GAME_SETUP, 6, "\pOptions"));
                    }

                    /* Preset dropdown */
                    {
                        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                        RGBColor black = {0, 0, 0};
                        Rect dropRect;
                        SetRect(&dropRect, 260, 170, 410, 188);
                        RGBForeColor(&white);
                        PaintRect(&dropRect);
                        RGBForeColor(&black);
                        FrameRect(&dropRect);
                        TextFont(3);
                        TextSize(10);
                        TextFace(0);
                        MoveTo(266, 184);
                        DrawString(presetLabels[sOptionsPreset]);
                    }

                    /* "Edit Options..." button */
                    {
                        RGBColor black = {0, 0, 0};
                        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                        Rect editOptBtn;
                        SetRect(&editOptBtn, 260, 196, 410, 214);
                        RGBForeColor(&white);
                        PaintRoundRect(&editOptBtn, 8, 8);
                        RGBForeColor(&black);
                        FrameRoundRect(&editOptBtn, 8, 8);
                        TextFont(3);
                        TextSize(10);
                        TextFace(0);
                        MoveTo(editOptBtn.left + 18, editOptBtn.bottom - 5);
                        DrawString(GetCachedString(STR_GAME_SETUP, 7, "\pEdit Options..."));
                    }

                    /* "I am the Greatest" checkbox (original shows it here, in the
                     * main view's Options section) — sets all AI to easiest. */
                    {
                        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                        Rect cbRect;
                        SetRect(&cbRect, 260, 220, 272, 232);
                        if (sIAmGreatest) {
                            RGBColor checkGreen = {0x4444, 0xFFFF, 0x4444};
                            RGBForeColor(&checkGreen);
                            PaintRect(&cbRect);
                            RGBForeColor(&white);
                            MoveTo(cbRect.left + 2, cbRect.bottom - 3);
                            LineTo(cbRect.left + 4, cbRect.bottom - 1);
                            LineTo(cbRect.right - 2, cbRect.top + 2);
                        } else {
                            RGBColor dark = {0x2222, 0x2222, 0x2222};
                            RGBForeColor(&dark);
                            PaintRect(&cbRect);
                        }
                        RGBForeColor(&white);
                        FrameRect(&cbRect);
                        TextFont(3); TextSize(10); TextFace(0);
                        MoveTo(278, 230);
                        DrawString(GetCachedString(STR_GAME_SETUP, 13, "\pI am the Greatest"));
                    }

                    /* Difficulty rating */
                    {
                        RGBColor valueColor = {0xCCCC, 0xDDDD, 0xFFFF};
                        Str255 numStr;
                        short rating = CalcDifficultyRating(computerSkill);
                        RGBForeColor(&valueColor);
                        TextFont(3);
                        TextSize(10);
                        TextFace(0);
                        MoveTo(260, 252);
                        DrawString(GetCachedString(STR_GAME_SETUP, 8, "\pDifficulty Rating: "));
                        NumToString((long)rating, numStr);
                        DrawString(numStr);
                        DrawString("\p%");
                    }

                    /* Army Set dropdown */
                    if (sArmySetCount > 0) {
                        RGBColor labelColor = {0xFFFF, 0xCCCC, 0x3333};
                        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                        RGBColor black = {0, 0, 0};
                        Rect armyDropRect;
                        RGBForeColor(&labelColor);
                        TextFont(2);
                        TextSize(12);
                        TextFace(bold);
                        MoveTo(30, 260);
                        DrawString(GetCachedString(STR_GAME_SETUP, 9, "\pArmy Set"));

                        SetRect(&armyDropRect, 30, 268, 220, 286);
                        RGBForeColor(&white);
                        PaintRect(&armyDropRect);
                        RGBForeColor(&black);
                        FrameRect(&armyDropRect);
                        TextFont(3);
                        TextSize(10);
                        TextFace(0);
                        MoveTo(36, 282);
                        {
                            Str255 setName;
                            short sn;
                            for (sn = 0; sArmySetNames[sSelectedArmySet][sn] && sn < 255; sn++)
                                setName[sn + 1] = sArmySetNames[sSelectedArmySet][sn];
                            setName[0] = (unsigned char)sn;
                            DrawString(setName);
                        }
                    }

                    /* Buttons */
                    {
                        RGBColor black = {0, 0, 0};
                        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                        Rect moreBtnRect, beginBtnRect;

                        SetRect(&moreBtnRect, 30, 300, 170, 322);
                        SetRect(&beginBtnRect, 290, 300, 430, 322);

                        /* "More Choices" */
                        RGBForeColor(&white);
                        PaintRoundRect(&moreBtnRect, 8, 8);
                        RGBForeColor(&black);
                        FrameRoundRect(&moreBtnRect, 8, 8);
                        TextFont(3);
                        TextSize(10);
                        TextFace(0);
                        MoveTo(moreBtnRect.left + 22, moreBtnRect.bottom - 5);
                        DrawString(GetCachedString(STR_GAME_SETUP, 10, "\pMore Choices"));

                        /* "Begin Game" (default button) */
                        RGBForeColor(&white);
                        PaintRoundRect(&beginBtnRect, 8, 8);
                        RGBForeColor(&black);
                        FrameRoundRect(&beginBtnRect, 8, 8);
                        PenSize(2, 2);
                        FrameRoundRect(&beginBtnRect, 8, 8);
                        PenSize(1, 1);
                        TextFace(bold);
                        MoveTo(beginBtnRect.left + 26, beginBtnRect.bottom - 5);
                        DrawString(GetCachedString(STR_GAME_SETUP, 11, "\pBegin Game"));
                    }
                } else {
                    /* ========== EXPANDED MODE (More Choices) ========== */

                    /* 4 rows x 2 columns of faction boxes */
                    for (i = 0; i < factionCount; i++) {
                        short col = i % 2;
                        short row = i / 2;
                        short bx = 15 + col * 145;
                        short by = 50 + row * 68;
                        Rect boxRect;
                        RGBColor borderColor;
                        RGBColor boxBg = {0x2000, 0x1800, 0x3000};
                        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                        RGBColor black = {0, 0, 0};

                        SetRect(&boxRect, bx, by, bx + 135, by + 60);

                        /* Box background */
                        RGBForeColor(&boxBg);
                        PaintRect(&boxRect);

                        /* Colored border from player colors */
                        borderColor = sPlayerColors[i + 1];
                        RGBForeColor(&borderColor);
                        PenSize(2, 2);
                        FrameRect(&boxRect);
                        PenSize(1, 1);

                        /* Shield icon in faction box (13x15 small shield) */
                        if (sShieldsLoaded) {
                            Rect shR;
                            SetRect(&shR, bx + 4, by + 3, bx + 4 + 13, by + 3 + 15);
                            DrawSmallShieldIcon(i, &shR);
                        }

                        /* Faction name (bold, offset for shield) */
                        TextFont(3);
                        TextSize(10);
                        TextFace(bold);
                        RGBForeColor(&white);
                        MoveTo(bx + 22, by + 14);
                        {
                            Str255 pName;
                            short nlen = 0;
                            while (nlen < FACTION_NAME_LEN && factionNames[i][nlen] != 0)
                                nlen++;
                            pName[0] = (unsigned char)nlen;
                            BlockMoveData(factionNames[i], pName + 1, nlen);
                            DrawString(pName);
                        }

                        /* AI dropdown text */
                        TextFace(0);
                        {
                            Rect aiRect;
                            SetRect(&aiRect, bx + 6, by + 22, bx + 90, by + 36);
                            RGBForeColor(&white);
                            PaintRect(&aiRect);
                            RGBForeColor(&black);
                            FrameRect(&aiRect);
                            MoveTo(bx + 10, by + 34);
                            DrawString(aiLabels[sFactionAI[i]]);
                        }

                        /* Character checkbox */
                        {
                            Rect cbRect;
                            SetRect(&cbRect, bx + 6, by + 42, bx + 18, by + 54);
                            if (sFactionCharacter[i]) {
                                RGBColor checkGreen = {0x4444, 0xFFFF, 0x4444};
                                RGBForeColor(&checkGreen);
                                PaintRect(&cbRect);
                                RGBForeColor(&white);
                                MoveTo(cbRect.left + 2, cbRect.bottom - 3);
                                LineTo(cbRect.left + 4, cbRect.bottom - 1);
                                LineTo(cbRect.right - 2, cbRect.top + 2);
                            } else {
                                RGBColor dark = {0x2222, 0x2222, 0x2222};
                                RGBForeColor(&dark);
                                PaintRect(&cbRect);
                            }
                            RGBForeColor(&white);
                            FrameRect(&cbRect);
                            MoveTo(bx + 22, by + 52);
                            DrawString(GetCachedString(STR_GAME_SETUP, 12, "\pCharacter"));
                        }
                    }

                    /* Right column: Options section */
                    {
                        RGBColor labelColor = {0xFFFF, 0xCCCC, 0x3333};
                        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                        RGBColor black = {0, 0, 0};
                        RGBColor valueColor = {0xCCCC, 0xDDDD, 0xFFFF};
                        Str255 numStr;
                        short rating;

                        /* Options label */
                        RGBForeColor(&labelColor);
                        TextFont(2);
                        TextSize(12);
                        TextFace(bold);
                        MoveTo(310, 60);
                        DrawString(GetCachedString(STR_GAME_SETUP, 6, "\pOptions"));

                        /* Preset dropdown */
                        {
                            Rect dropRect;
                            SetRect(&dropRect, 310, 68, 540, 86);
                            RGBForeColor(&white);
                            PaintRect(&dropRect);
                            RGBForeColor(&black);
                            FrameRect(&dropRect);
                            TextFont(3);
                            TextSize(10);
                            TextFace(0);
                            MoveTo(316, 82);
                            DrawString(presetLabels[sOptionsPreset]);
                        }

                        /* "Edit Options..." button */
                        {
                            Rect editOptBtn;
                            SetRect(&editOptBtn, 310, 94, 540, 112);
                            RGBForeColor(&white);
                            PaintRoundRect(&editOptBtn, 8, 8);
                            RGBForeColor(&black);
                            FrameRoundRect(&editOptBtn, 8, 8);
                            TextFont(3);
                            TextSize(10);
                            TextFace(0);
                            MoveTo(editOptBtn.left + 18, editOptBtn.bottom - 5);
                            DrawString(GetCachedString(STR_GAME_SETUP, 7, "\pEdit Options..."));
                        }

                        /* "I am the Greatest" checkbox */
                        {
                            Rect cbRect;
                            SetRect(&cbRect, 315, 122, 327, 134);
                            if (sIAmGreatest) {
                                RGBColor checkGreen = {0x4444, 0xFFFF, 0x4444};
                                RGBForeColor(&checkGreen);
                                PaintRect(&cbRect);
                                RGBForeColor(&white);
                                MoveTo(cbRect.left + 2, cbRect.bottom - 3);
                                LineTo(cbRect.left + 4, cbRect.bottom - 1);
                                LineTo(cbRect.right - 2, cbRect.top + 2);
                            } else {
                                RGBColor dark = {0x2222, 0x2222, 0x2222};
                                RGBForeColor(&dark);
                                PaintRect(&cbRect);
                            }
                            RGBForeColor(&white);
                            FrameRect(&cbRect);
                            MoveTo(333, 132);
                            DrawString(GetCachedString(STR_GAME_SETUP, 13, "\pI am the Greatest"));
                        }

                        /* Difficulty rating */
                        rating = CalcDifficultyRating(computerSkill);
                        RGBForeColor(&valueColor);
                        TextFont(3);
                        TextSize(10);
                        TextFace(0);
                        MoveTo(310, 156);
                        DrawString(GetCachedString(STR_GAME_SETUP, 8, "\pDifficulty Rating: "));
                        NumToString((long)rating, numStr);
                        DrawString(numStr);
                        DrawString("\p%");

                        /* "E-mail game" checkbox (stub, disabled) */
                        {
                            RGBColor gray = {0x7777, 0x7777, 0x7777};
                            Rect cbRect;
                            SetRect(&cbRect, 315, 174, 327, 186);
                            RGBForeColor(&gray);
                            FrameRect(&cbRect);
                            MoveTo(333, 184);
                            DrawString(GetCachedString(STR_GAME_SETUP, 14, "\pE-mail game"));
                        }

                        /* "Set Addresses" button (stub) */
                        {
                            RGBColor gray = {0x7777, 0x7777, 0x7777};
                            Rect addrBtn;
                            SetRect(&addrBtn, 310, 194, 540, 212);
                            RGBForeColor(&gray);
                            PaintRoundRect(&addrBtn, 8, 8);
                            RGBForeColor(&black);
                            FrameRoundRect(&addrBtn, 8, 8);
                            TextFont(3);
                            TextSize(10);
                            TextFace(0);
                            RGBForeColor(&gray);
                            MoveTo(addrBtn.left + 18, addrBtn.bottom - 5);
                            DrawString(GetCachedString(STR_GAME_SETUP, 15, "\pSet Addresses"));
                        }

                        /* "Select Random Characters" button (stub) */
                        {
                            Rect randBtn;
                            SetRect(&randBtn, 310, 220, 540, 238);
                            RGBForeColor(&white);
                            PaintRoundRect(&randBtn, 8, 8);
                            RGBForeColor(&black);
                            FrameRoundRect(&randBtn, 8, 8);
                            TextFont(3);
                            TextSize(10);
                            TextFace(0);
                            MoveTo(randBtn.left + 4, randBtn.bottom - 5);
                            DrawString(GetCachedString(STR_GAME_SETUP, 16, "\pSelect Random Characters"));
                        }

                        /* Army Set dropdown (expanded mode) */
                        if (sArmySetCount > 0) {
                            RGBForeColor(&labelColor);
                            TextFont(2);
                            TextSize(12);
                            TextFace(bold);
                            MoveTo(310, 260);
                            DrawString(GetCachedString(STR_GAME_SETUP, 9, "\pArmy Set"));

                            {
                                Rect armyDropRect;
                                SetRect(&armyDropRect, 310, 268, 540, 286);
                                RGBForeColor(&white);
                                PaintRect(&armyDropRect);
                                RGBForeColor(&black);
                                FrameRect(&armyDropRect);
                                TextFont(3);
                                TextSize(10);
                                TextFace(0);
                                MoveTo(316, 282);
                                {
                                    Str255 setName;
                                    short sn;
                                    for (sn = 0; sArmySetNames[sSelectedArmySet][sn] && sn < 255; sn++)
                                        setName[sn + 1] = sArmySetNames[sSelectedArmySet][sn];
                                    setName[0] = (unsigned char)sn;
                                    DrawString(setName);
                                }
                            }
                        }
                    }

                    /* Bottom buttons */
                    {
                        RGBColor black = {0, 0, 0};
                        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                        Rect fewerBtnRect, beginBtnRect;

                        SetRect(&fewerBtnRect, 30, 390, 170, 410);
                        SetRect(&beginBtnRect, 390, 390, 530, 410);

                        /* "Fewer Choices" */
                        RGBForeColor(&white);
                        PaintRoundRect(&fewerBtnRect, 8, 8);
                        RGBForeColor(&black);
                        FrameRoundRect(&fewerBtnRect, 8, 8);
                        TextFont(3);
                        TextSize(10);
                        TextFace(0);
                        MoveTo(fewerBtnRect.left + 16, fewerBtnRect.bottom - 5);
                        DrawString(GetCachedString(STR_GAME_SETUP, 17, "\pFewer Choices"));

                        /* "Begin Game" (default button) */
                        RGBForeColor(&white);
                        PaintRoundRect(&beginBtnRect, 8, 8);
                        RGBForeColor(&black);
                        FrameRoundRect(&beginBtnRect, 8, 8);
                        PenSize(2, 2);
                        FrameRoundRect(&beginBtnRect, 8, 8);
                        PenSize(1, 1);
                        TextFace(bold);
                        MoveTo(beginBtnRect.left + 26, beginBtnRect.bottom - 5);
                        DrawString(GetCachedString(STR_GAME_SETUP, 11, "\pBegin Game"));
                    }
                }

                /* Blit offscreen buffer to window */
                if (offscreen != NULL) {
                    UnlockPixels(GetGWorldPixMap(offscreen));
                    SetGWorld(savedPort, savedDevice);
                    SetPort(setupWin);
                    CopyBits((BitMap *)*GetGWorldPixMap(offscreen),
                             &((GrafPtr)setupWin)->portBits,
                             &r, &setupWin->portRect,
                             srcCopy, NULL);
                }

                /* Show window after first blit to avoid white flash */
                if (!setupShown) {
                    ShowWindow(setupWin);
                    setupShown = true;
                }

                needsRedraw = false;
            }

            /* Wait for events */
            WaitNextEvent(everyEvent, &evt, 30, NULL);

            /* Service update events with a full redraw. We draw the setup screen
             * directly to the window (no offscreen buffer, so the marble keeps its
             * true dark palette), so an unserviced update would erase content. */
            if (evt.what == updateEvt && (WindowPtr)evt.message == setupWin) {
                BeginUpdate(setupWin);
                EndUpdate(setupWin);
                needsRedraw = true;
            }

            if (evt.what == mouseDown) {
                WindowPtr clickWin2;
                short partCode2 = FindWindow(evt.where, &clickWin2);

                if (partCode2 == inMenuBar) {
                    long menuResult = MenuSelect(evt.where);
                    short menuID2 = (menuResult >> 16) & 0xFFFF;
                    short menuItem2 = menuResult & 0xFFFF;
                    if (menuID2 == 2 && menuItem2 == 9) {
                        /* File > Quit */
                        DisposeWindow(setupWin);
                        if (offscreen != NULL) DisposeGWorld(offscreen);
                        ExitToShell();
                    }
                    HiliteMenu(0);
                } else {
                Point localPt = evt.where;
                SetPort(setupWin);
                GlobalToLocal(&localPt);

                if (!showMoreChoices) {
                    /* === Simple mode clicks === */

                    /* Faction radio clicks */
                    for (i = 0; i < factionCount; i++) {
                        Rect factionHitRect;
                        short yPos = 78 + i * 22;
                        SetRect(&factionHitRect, 30, yPos - 12, 220, yPos + 8);
                        if (PtInRect(localPt, &factionHitRect)) {
                            selectedSide = i;
                            needsRedraw = true;
                            break;
                        }
                    }

                    /* Skill level radio clicks */
                    for (i = 0; i < 3; i++) {
                        Rect skillHitRect;
                        short yPos = 78 + i * 22;
                        SetRect(&skillHitRect, 260, yPos - 12, 430, yPos + 8);
                        if (PtInRect(localPt, &skillHitRect)) {
                            computerSkill = i;
                            needsRedraw = true;
                            break;
                        }
                    }

                    /* Preset dropdown click — cycle through presets */
                    {
                        Rect dropRect;
                        SetRect(&dropRect, 260, 170, 410, 188);
                        if (PtInRect(localPt, &dropRect)) {
                            sOptionsPreset = (sOptionsPreset + 1) % 3;
                            ApplyOptionsPreset(sOptionsPreset);
                            needsRedraw = true;
                        }
                    }

                    /* "Edit Options..." button */
                    {
                        Rect editOptBtn;
                        SetRect(&editOptBtn, 260, 196, 410, 214);
                        if (PtInRect(localPt, &editOptBtn)) {
                            ShowEditOptions();
                            needsRedraw = true;
                        }
                    }

                    /* "I am the Greatest" checkbox click (checkbox + label hit area) */
                    {
                        Rect greatRect;
                        SetRect(&greatRect, 260, 218, 410, 234);
                        if (PtInRect(localPt, &greatRect)) {
                            sIAmGreatest = !sIAmGreatest;
                            if (sIAmGreatest) {
                                /* Set all AI factions to Knight (easiest) */
                                for (i = 0; i < factionCount; i++)
                                    if (sFactionAI[i] != 0) sFactionAI[i] = 1;
                            }
                            needsRedraw = true;
                        }
                    }

                    /* Army set dropdown click — cycle through sets */
                    if (sArmySetCount > 1) {
                        Rect armyDropRect;
                        SetRect(&armyDropRect, 30, 268, 220, 286);
                        if (PtInRect(localPt, &armyDropRect)) {
                            sSelectedArmySet = (sSelectedArmySet + 1) % sArmySetCount;
                            /* Reload shields to match the selected army set */
                            sShieldsLoaded = false;
                            LoadShieldIcons();
                            needsRedraw = true;
                        }
                    }

                    /* "Begin Game" button */
                    {
                        Rect beginBtnRect;
                        SetRect(&beginBtnRect, 290, 300, 430, 322);
                        if (PtInRect(localPt, &beginBtnRect)) {
                            done = true;
                            beginGame = true;
                        }
                    }

                    /* "More Choices" button — toggle to expanded */
                    {
                        Rect moreBtnRect;
                        SetRect(&moreBtnRect, 30, 300, 170, 322);
                        if (PtInRect(localPt, &moreBtnRect)) {
                            /* Sync: init sFactionAI from simple mode state */
                            for (i = 0; i < factionCount; i++)
                                sFactionAI[i] = (i == selectedSide) ? 0 : (computerSkill + 1);

                            showMoreChoices = true;
                            winW = 560;
                            winH = 420;

                            /* Recreate window and offscreen at new size */
                            if (offscreen != NULL) {
                                DisposeGWorld(offscreen);
                                offscreen = NULL;
                            }
                            DisposeWindow(setupWin);

                            SetRect(&winRect,
                                (screenRect.right - winW) / 2,
                                (screenRect.bottom - winH) / 2,
                                (screenRect.right - winW) / 2 + winW,
                                (screenRect.bottom - winH) / 2 + winH);
                            setupWin = NewCWindow(NULL, &winRect, "\p", true,
                                                   plainDBox, (WindowPtr)-1L, false, 0);
                            SetPort(setupWin);
                            {
                                Rect obounds;
                                SetRect(&obounds, 0, 0, winW, winH);
                                NewGWorld(&offscreen, 0, &obounds, NULL, NULL, 0);
                            }
                            needsRedraw = true;
                        }
                    }
                } else {
                    /* === Expanded mode clicks === */

                    /* Faction AI dropdown clicks */
                    for (i = 0; i < factionCount; i++) {
                        short col = i % 2;
                        short row = i / 2;
                        short bx = 15 + col * 145;
                        short by = 50 + row * 68;
                        Rect aiHitRect;
                        SetRect(&aiHitRect, bx + 6, by + 22, bx + 90, by + 36);
                        if (PtInRect(localPt, &aiHitRect)) {
                            sFactionAI[i] = (sFactionAI[i] + 1) % 4;
                            needsRedraw = true;
                            break;
                        }
                    }

                    /* Preset dropdown click */
                    {
                        Rect dropRect;
                        SetRect(&dropRect, 310, 68, 540, 86);
                        if (PtInRect(localPt, &dropRect)) {
                            sOptionsPreset = (sOptionsPreset + 1) % 3;
                            ApplyOptionsPreset(sOptionsPreset);
                            needsRedraw = true;
                        }
                    }

                    /* "Edit Options..." button */
                    {
                        Rect editOptBtn;
                        SetRect(&editOptBtn, 310, 94, 540, 112);
                        if (PtInRect(localPt, &editOptBtn)) {
                            ShowEditOptions();
                            needsRedraw = true;
                        }
                    }

                    /* "I am the Greatest" checkbox click */
                    {
                        Rect iagRect;
                        SetRect(&iagRect, 315, 122, 540, 134);
                        if (PtInRect(localPt, &iagRect)) {
                            sIAmGreatest = !sIAmGreatest;
                            if (sIAmGreatest) {
                                /* Set all AI factions to Knight (easiest) */
                                for (i = 0; i < factionCount; i++)
                                    if (sFactionAI[i] != 0) sFactionAI[i] = 1;
                            }
                            needsRedraw = true;
                        }
                    }

                    /* "Select Random Characters" button click */
                    {
                        Rect randBtn;
                        SetRect(&randBtn, 310, 220, 540, 238);
                        if (PtInRect(localPt, &randBtn)) {
                            /* Randomize AI level for non-human factions */
                            for (i = 0; i < factionCount; i++) {
                                if (sFactionAI[i] != 0)
                                    sFactionAI[i] = (short)((unsigned short)Random() % 3) + 1;
                            }
                            /* Toggle character flags randomly */
                            for (i = 0; i < factionCount; i++)
                                sFactionCharacter[i] = ((unsigned short)Random() % 3 != 0);
                            needsRedraw = true;
                        }
                    }

                    /* Faction "Character" checkbox clicks */
                    for (i = 0; i < factionCount; i++) {
                        short col = i % 2;
                        short row = i / 2;
                        short bx = 15 + col * 145;
                        short by = 50 + row * 68;
                        Rect charHitRect;
                        SetRect(&charHitRect, bx + 6, by + 42, bx + 90, by + 54);
                        if (PtInRect(localPt, &charHitRect)) {
                            sFactionCharacter[i] = !sFactionCharacter[i];
                            needsRedraw = true;
                            break;
                        }
                    }

                    /* Army set dropdown click — cycle through sets */
                    if (sArmySetCount > 1) {
                        Rect armyDropRect;
                        SetRect(&armyDropRect, 310, 268, 540, 286);
                        if (PtInRect(localPt, &armyDropRect)) {
                            sSelectedArmySet = (sSelectedArmySet + 1) % sArmySetCount;
                            /* Reload shields to match the selected army set */
                            sShieldsLoaded = false;
                            LoadShieldIcons();
                            needsRedraw = true;
                        }
                    }

                    /* "Begin Game" button */
                    {
                        Rect beginBtnRect;
                        SetRect(&beginBtnRect, 390, 390, 530, 410);
                        if (PtInRect(localPt, &beginBtnRect)) {
                            done = true;
                            beginGame = true;
                        }
                    }

                    /* "Fewer Choices" button — toggle back to simple */
                    {
                        Rect fewerBtnRect;
                        SetRect(&fewerBtnRect, 30, 390, 170, 410);
                        if (PtInRect(localPt, &fewerBtnRect)) {
                            /* Sync: derive selectedSide and computerSkill from sFactionAI */
                            {
                                short aiCounts[4] = {0, 0, 0, 0};
                                short maxAI = 1;
                                selectedSide = 0;
                                for (i = 0; i < factionCount; i++) {
                                    if (sFactionAI[i] == 0)
                                        selectedSide = i;
                                    else
                                        aiCounts[sFactionAI[i]]++;
                                }
                                /* Most common AI level */
                                if (aiCounts[2] >= aiCounts[1] && aiCounts[2] >= aiCounts[3])
                                    maxAI = 2;
                                else if (aiCounts[3] >= aiCounts[1] && aiCounts[3] >= aiCounts[2])
                                    maxAI = 3;
                                else
                                    maxAI = 1;
                                computerSkill = maxAI - 1; /* 0=Knight, 1=Lord, 2=Warlord */
                            }

                            showMoreChoices = false;
                            winW = 460;
                            winH = 340;

                            if (offscreen != NULL) {
                                DisposeGWorld(offscreen);
                                offscreen = NULL;
                            }
                            DisposeWindow(setupWin);

                            SetRect(&winRect,
                                (screenRect.right - winW) / 2,
                                (screenRect.bottom - winH) / 2,
                                (screenRect.right - winW) / 2 + winW,
                                (screenRect.bottom - winH) / 2 + winH);
                            setupWin = NewCWindow(NULL, &winRect, "\p", true,
                                                   plainDBox, (WindowPtr)-1L, false, 0);
                            SetPort(setupWin);
                            {
                                Rect obounds;
                                SetRect(&obounds, 0, 0, winW, winH);
                                NewGWorld(&offscreen, 0, &obounds, NULL, NULL, 0);
                            }
                            needsRedraw = true;
                        }
                    }
                }
                } /* end else (not inMenuBar) */
            }
            else if (evt.what == keyDown) {
                char key = evt.message & charCodeMask;

                /* Cmd+Q = Quit */
                if ((evt.modifiers & cmdKey) && (key == 'q' || key == 'Q')) {
                    DisposeWindow(setupWin);
                    if (offscreen != NULL) DisposeGWorld(offscreen);
                    ExitToShell();
                }

                if ((TickCount() - startTick) < 60)
                    continue;
                if (key == 0x0D || key == 0x03) {
                    done = true;
                    beginGame = true;
                }
                else if (key == 0x1B) {
                    done = true;
                }
                else if (!showMoreChoices) {
                    if (key == 0x1E) {
                        if (selectedSide > 0) {
                            selectedSide--;
                            needsRedraw = true;
                        }
                    }
                    else if (key == 0x1F) {
                        if (selectedSide < factionCount - 1) {
                            selectedSide++;
                            needsRedraw = true;
                        }
                    }
                }
            }
            else if (evt.what == updateEvt) {
                needsRedraw = true;
            }
        }
    }

    /* Store results */
    sPlayerSide = selectedSide;
    sComputerSkill = computerSkill;

    /* Write game state on Begin Game (Step 6) */
    if (beginGame && *gGameState != 0) {
        unsigned char *gs = (unsigned char *)*gGameState;

        /* Faction count and current player */
        *(short *)(gs + 0x10C) = factionCount;
        *(short *)(gs + 0x110) = selectedSide;

        /* Player types: human vs AI */
        for (i = 0; i < factionCount; i++) {
            *(short *)(gs + 0xd0 + i * 2) = (sFactionAI[i] == 0) ? 0 : 1;
        }

        /* Difficulty level: Knight=3, Lord=7, Warlord=15 */
        {
            short diffMap[4] = {0, 3, 7, 15};  /* Human, Knight, Lord, Warlord */
            /* In simple mode, computerSkill is 0-based (0=Knight, 1=Lord, 2=Warlord) */
            *(short *)(gs + 0x114) = diffMap[computerSkill + 1];
        }

        /* Option flags */
        *(short *)(gs + 0x116) = sOptHiddenMap ? 1 : 0;
        *(short *)(gs + 0x11a) = sOptQuests ? 1 : 0;
        *(short *)(gs + 0x11c) = sOptDiplomacy ? 1 : 0;
        *(short *)(gs + 0x122) = sOptRandomTurns ? 1 : 0;
        *(short *)(gs + 0x124) = sOptViewProd ? 1 : 0;
        *(short *)(gs + 0x126) = sNeutralCities;
        *(short *)(gs + 0x128) = sOptIntenseCombat ? 1 : 0;
        *(short *)(gs + 0x12a) = sOptViewEnemies ? 1 : 0;

        /* Alive flags: the scenario's factions as GameInit found them ("Not
         * Used" slots stay dead: re-enabling them put phantom AIs, heroes and
         * armies at junk capital coords - Isles of Sorcery player 2 in the sea). */
        for (i = 0; i < 8; i++) {
            *(short *)(gs + 0x138 + i * 2) =
                (i < factionCount && gs[i * 0x14] != 0 &&
                 !(gs[i * 0x14] == 'N' && gs[i * 0x14 + 1] == 'o' && gs[i * 0x14 + 2] == 't' &&
                   gs[i * 0x14 + 3] == ' ' && gs[i * 0x14 + 4] == 'U')) ? 1 : 0;
        }

        /* Initialize turn management */
        *(short *)(gs + 0x136) = 1;   /* Start at turn 1 */
        *(short *)(gs + 0x118) = 0;   /* Not end-of-round yet */
        *(short *)(gs + 0x174) = 0;   /* Order index starts at 0 */
        for (i = 0; i < 8; i++) {
            *(short *)(gs + 0x164 + i * 2) = i;  /* Sequential turn order */
        }

        /* 68k CODE_130 FUN_000005aa: if Random Turns option is on,
         * shuffle turn order 20 times using Fisher-Yates-style swaps. */
        if (*(short *)(gs + 0x122) != 0) {
            short sh;
            for (sh = 0; sh < 20; sh++) {
                short a = (short)((unsigned short)Random() % 8);
                short b = (short)((unsigned short)Random() % 8);
                short tmp = *(short *)(gs + 0x164 + a * 2);
                *(short *)(gs + 0x164 + a * 2) = *(short *)(gs + 0x164 + b * 2);
                *(short *)(gs + 0x164 + b * 2) = tmp;
            }
        }

        /* Re-initialize diplomacy matrix based on actual option setting.
         * GameInit() set all to peace (0x00), but the user may have
         * changed the diplomacy flag in Edit Options.
         * 68k CODE_117 FUN_00000ad2: clears bits 2-3, sets state 2 (war) if
         * diplomacy disabled, then copies bits 2-3 to bits 0-1. */
        {
            short di, dj;
            for (di = 0; di < 8; di++) {
                for (dj = 0; dj < 8; dj++) {
                    unsigned char *dip = gs + 0x1582 + di * 8 + dj;
                    unsigned char state = sOptDiplomacy ? DIPLO_PEACE : DIPLO_WAR;
                    *dip = DIPLO_SET_STATE(0, state) | (state & 3);  /* bits 2-3=state, bits 0-1=copy */
                }
            }
        }

        /* Clear per-faction tracking counters (68k CODE_117 FUN_00000a8e) */
        for (i = 0; i < 8; i++) {
            *(short *)(gs + 0x1122 + i * 2) = 0;       /* hero hire scores */
            *(short *)(gs + 0x1132 + i * 2) = (short)0xFFFF;  /* history min */
        }

        /* Set AI difficulty per-faction (Knight=1, Lord=2, Warlord=3) */
        for (i = 0; i < factionCount; i++) {
            if (sFactionAI[i] > 0) {
                /* 68k encoding (verified via the difficulty rating on the
                 * original): Knight 0, Lord 1, Warlord 2; 3 = not used.
                 * sFactionAI is 1..3 = Knight..Warlord. */
                *(short *)(gs + 0xc0 + i * 2) = sFactionAI[i] - 1;  /* AI level */
            } else {
                *(short *)(gs + 0xc0 + i * 2) = 0;  /* Human */
            }
        }

        /* Default faction names for dead/unused slots (68k CODE_116 FUN_00000332) */
        for (i = 0; i < 8; i++) {
            if (*(short *)(gs + 0x138 + i * 2) == 0) {
                /* Dead faction: set AI type to Warlord (3) */
                *(short *)(gs + 0xc0 + i * 2) = 3;
            }
        }

        /* Initialize fight order table (from CODE_060): 29 bytes per player
         * at gs + (player * 0x1D) + 0x60C.
         * Default: sequential ordering 0-28 (lower = fights first). */
        {
            short pi, ut;
            for (pi = 0; pi < 9; pi++) {
                for (ut = 0; ut < 29; ut++) {
                    gs[ut + pi * 0x1D + 0x60C] = (unsigned char)ut;
                }
            }
        }

        /* Additional init from 68k CODE_117 FUN_00001ab6 */
        *(short *)(gs + 0x15E) = 0;   /* endgame/domination flag — blocks hero offers */
        *(short *)(gs + 0x158) = 0;   /* special game mode */
        for (i = 0; i < 8; i++) {
            *(short *)(gs + 0x0E0 + i * 2) = 0;  /* enhancement flags */
            *(short *)(gs + 0x148 + i * 2) = sOptHiddenMap ? 1 : 0;  /* fog per player */
        }

        /* Clear per-player hero instance records (gs+0x1422, 0x2C bytes each) */
        for (i = 0; i < 8; i++) {
            short b;
            for (b = 0; b < 0x2C; b++)
                gs[0x1422 + i * 0x2C + b] = 0;
        }

        /* Clear quest records (gs+0x1142, 0x0C bytes per player) */
        for (i = 0; i < 8; i++) {
            short b;
            for (b = 0; b < 0x0C; b++)
                gs[0x1142 + i * 0x0C + b] = 0;
        }

        /* Item records (gs+0xD12) are NOT cleared here: GameInit already
         * built the Standards and placed the ruin items (FUN_1003956c). */

        /* Set not-playing factions' capitals to neutral army ownership */
        {
            short armyCount = *(short *)(gs + 0x1602);
            if (armyCount > 100) armyCount = 100;
            for (i = 0; i < 8; i++) {
                if (*(short *)(gs + 0x138 + i * 2) == 0) {
                    short capX = *(short *)(gs + 0x18A + i * 0x14);
                    short capY = *(short *)(gs + 0x18C + i * 0x14);
                    short ai2;
                    for (ai2 = 0; ai2 < armyCount; ai2++) {
                        unsigned char *army = gs + 0x1604 + ai2 * 0x42;
                        if (*(short *)(army + 0x00) == capX &&
                            *(short *)(army + 0x02) == capY) {
                            army[0x15] = 0x0F;  /* neutral owner */
                        }
                    }
                }
            }
        }
    }

    if (offscreen != NULL)
        DisposeGWorld(offscreen);
    if (setupWin != NULL) DisposeWindow(setupWin);
    return beginGame;
}


/* Terrain type colors for the main strategic map view.
 * 68k terrain types: 0=Road, 1=Bridge, 2=Water, 3=Shore, 4=Forest,
 * 5=Hills, 6=Mountains, 7=Plains, 8=Marsh, 9=Sea, 10=City, 11=Ruin */
#define NUM_TERRAIN_COLORS 12
static RGBColor sTerrainColors[NUM_TERRAIN_COLORS] = {
    {0xCFCF,0x8B8B,0x3B3B},  /* 0  road - tan */
    {0x9797,0x4B4B,0x0707},  /* 1  bridge - dark brown */
    {0x4B4B,0xEBEB,0xFFFF},  /* 2  water - light blue */
    {0xFFFF,0xDBDB,0x8B8B},  /* 3  shore - sand */
    {0x0000,0x8B8B,0x1313},  /* 4  forest - dark green */
    {0xAFAF,0x6B6B,0x1B1B},  /* 5  hills - brown */
    {0x8787,0x8787,0x8787},  /* 6  mountains - gray */
    {0x4F4F,0xEFEF,0x4F4F},  /* 7  plains - green */
    {0x6B6B,0x8B8B,0x3B3B},  /* 8  marsh - olive */
    {0x0000,0x6363,0xC3C3},  /* 9  sea/ocean - blue */
    {0xCFCF,0xCFCF,0xCFCF},  /* 10 city - light gray */
    {0x9F9F,0x9F9F,0x9F9F},  /* 11 temple/ruin - medium gray */
};

/* ===================================================================
 * DrawMapInWindow — Draw terrain using sprite sheets at 40x40 per tile
 *
 * Shows a viewport of the map using CopyBits from the terrain GWorlds.
 * Falls back to flat terrain-type colors if sprites aren't loaded.
 * Arrow keys scroll the viewport (handled in event loop).
 * =================================================================== */
static short sDebugShowTileSheet = 0;  /* press 'T' to toggle tile sheet view */

/* Forward declarations for movement cost and item-based movement helpers */
static short GetMovementCost(short mapX, short mapY, short unitClass);
static short GetEffectiveUnitClass(short armyIdx);
static Boolean ArmyHasFlightItem(short armyIdx);
static Boolean ArmyHasDoubleMoveItem(short armyIdx);
static Boolean IsHeroFemale(short armyIdx);
static short ComputeWavefrontPath(short srcX, short srcY, short dstX, short dstY, short unitClass);
static short ExecutePathSteps(short armyIdx);
static Boolean CheckAndResolveCombat(short movingArmyIdx);
static void CheckGroundItemPickup(short armyIdx);
static void TryAutoSearchRuin(short armyIdx);

static void DrawMapInWindow(WindowPtr win)
{
    unsigned char *mapData;
    unsigned char *scnData;
    Rect           winRect;
    short          tx, ty;
    short          tilesWide, tilesHigh;
    Boolean        hasScn;
    short          i;
    GWorldPtr      bufGW = NULL;
    WindowPtr      realWin = win;
    CGrafPtr       bufSavePort = NULL;
    GDHandle       bufSaveDev = NULL;

    if (!sMapLoaded || *gMapTiles == 0)
        return;

    mapData = (unsigned char *)*gMapTiles;
    hasScn  = (*gGameState != 0);
    scnData = hasScn ? (unsigned char *)*gGameState : NULL;
    winRect = win->portRect;

    /* Reserve space for scrollbars and shields at edges */
    winRect.right  -= SCROLLBAR_W;
    winRect.bottom -= SCROLLBAR_H;

    /* How many tiles fit in the window (+1 for the partial tile the
     * sub-tile scroll exposes on the right/bottom) */
    tilesWide = (winRect.right - winRect.left) / TERRAIN_TILE_W + 2;
    tilesHigh = (winRect.bottom - winRect.top) / TERRAIN_TILE_H + 2;

    /* Double buffer the map area (terrain, roads, cities, armies, path):
     * drawn straight to the window the layers showed one after another,
     * which blinked while a path was dragged. */
    {
        static short sBufW = 0, sBufH = 0;
        short bw = win->portRect.right - win->portRect.left;
        short bh = win->portRect.bottom - win->portRect.top;
        if (sMapBufGW != NULL && (bw != sBufW || bh != sBufH)) {
            DisposeGWorld(sMapBufGW); sMapBufGW = NULL;
        }
        if (sMapBufGW == NULL) {
            Rect b;
            Handle ct = (Handle)sGameCTab;
            SetRect(&b, 0, 0, bw, bh);
            if (ct == NULL || HandToHand(&ct) != noErr) ct = NULL;
            if (NewGWorld(&sMapBufGW, 8, &b, (CTabHandle)ct, NULL, 0) != noErr) sMapBufGW = NULL;
            sBufW = bw; sBufH = bh;
        }
        if (sMapBufGW != NULL && LockPixels(GetGWorldPixMap(sMapBufGW))) {
            GetGWorld(&bufSavePort, &bufSaveDev);
            realWin = win;
            SetGWorld(sMapBufGW, NULL);
            win = (WindowPtr)sMapBufGW;
            bufGW = sMapBufGW;
            {   /* a GWorld keeps its last colours: the map's CopyBits colourise
                 * with fore/back, so start from black on white every time */
                RGBColor black = {0, 0, 0}, white = {0xFFFF, 0xFFFF, 0xFFFF};
                RGBForeColor(&black); RGBBackColor(&white);
                PenNormal(); TextMode(srcOr);
            }
        }
    }

    /* Sub-tile scroll: draw everything in unscrolled coordinates with the
     * port origin moved by the pixel remainder, clipped to the map area. */
    {
        Rect mapClip = winRect;
        SetOrigin(sViewPixX, sViewPixY);
        OffsetRect(&mapClip, sViewPixX, sViewPixY);
        ClipRect(&mapClip);
    }

    /* Lock terrain sheet pixmaps for the draw loop */
    if (sTerrainLoaded) {
        if (sTerrainGW != NULL) LockPixels(GetGWorldPixMap(sTerrainGW));
        if (sTerrainGW2 != NULL) LockPixels(GetGWorldPixMap(sTerrainGW2));
    }

    for (ty = 0; ty < tilesHigh; ty++) {
        for (tx = 0; tx < tilesWide; tx++) {
            short mapX = sViewportX + tx;
            short mapY = sViewportY + ty;
            unsigned short tileOffset;
            unsigned char  terrainIdx;
            short          terrainType;
            Rect           dstRect;

            if (mapX >= sMapWidth || mapY >= sMapHeight)
                continue;

            tileOffset = mapY * 0xE0 + mapX * 2;
            terrainIdx = mapData[tileOffset];

            /* Get terrain category from SCN properties table */
            if (hasScn) {
                terrainType = (short)(unsigned char)scnData[terrainIdx + TERRAIN_TYPE_OFS];
            } else {
                terrainType = (terrainIdx >> 4) & 0x0F;
            }
            if (terrainType >= NUM_TERRAIN_COLORS)
                terrainType = 0;

            SetRect(&dstRect,
                winRect.left + tx * TERRAIN_TILE_W,
                winRect.top  + ty * TERRAIN_TILE_H,
                winRect.left + (tx + 1) * TERRAIN_TILE_W,
                winRect.top  + (ty + 1) * TERRAIN_TILE_H);

            /* Sprite-based rendering from terrain sheets.
             * PICT 30022 = tiles 0-95, PICT 30023 = tiles 96-191.
             * Each sheet: 16 cols x 6 rows of 40x40 tiles.
             * Tile N: sheet=N/96, local=N%96, col=local%16, row=local/16. */
            if (sTerrainLoaded) {
                short local = terrainIdx % TERRAIN_TILES_PER_SHEET;
                short spriteCol = local % TERRAIN_COLS;
                short spriteRow = local / TERRAIN_COLS;
                GWorldPtr sheet = (terrainIdx < TERRAIN_TILES_PER_SHEET)
                    ? sTerrainGW : sTerrainGW2;
                Rect srcRect;

                if (sheet != NULL) {
                    PixMapHandle srcPix = GetGWorldPixMap(sheet);
                    SetRect(&srcRect,
                        spriteCol * TERRAIN_TILE_W, spriteRow * TERRAIN_TILE_H,
                        (spriteCol + 1) * TERRAIN_TILE_W,
                        (spriteRow + 1) * TERRAIN_TILE_H);

                    CopyBits((BitMap *)*srcPix,
                             &((GrafPtr)win)->portBits,
                             &srcRect, &dstRect,
                             srcCopy, NULL);
                    continue;
                }
            }

            /* Fallback: flat terrain-type color */
            RGBForeColor(&sTerrainColors[terrainType]);
            PaintRect(&dstRect);
        }
    }

    /* Unlock terrain sheet pixmaps */
    if (sTerrainLoaded) {
        if (sTerrainGW != NULL) UnlockPixels(GetGWorldPixMap(sTerrainGW));
        if (sTerrainGW2 != NULL) UnlockPixels(GetGWorldPixMap(sTerrainGW2));
    }

    /* --- Road overlay --- */
    /* PICT 30021 (640x80): 17 road sprites, 13 per row, 48px horizontal stride,
     * 40px vertical stride. Each sprite is 40x40 with 8px horizontal padding.
     * RD byte bits 0-4 = road type (0=none, 1-17=road variant).
     * Tile index = rd - 1. srcX = (tileIdx % 13) * 48, srcY = (tileIdx / 13) * 40.
     * Formula from original PPC binary (PPC_0001.c lines 2992-2993). */
    if (*gRoadData != 0 && sMapLoaded && sRoadGW != NULL && sRoadBgColorValid) {
        unsigned char *roadData = (unsigned char *)*gRoadData;
        short rdMapH = sMapHeight;
        PixMapHandle roadPix = GetGWorldPixMap(sRoadGW);
        RGBColor oldBack;

        if (rdMapH > 156) rdMapH = 156;
        LockPixels(roadPix);

        /* Set background color once outside the loop for mode 36 transparency */
        GetBackColor(&oldBack);
        RGBBackColor(&sRoadBgColor);

        for (ty = 0; ty < tilesHigh; ty++) {
            for (tx = 0; tx < tilesWide; tx++) {
                short rMapX = sViewportX + tx;
                short rMapY = sViewportY + ty;
                unsigned char rd;
                Rect srcRect, dstRect;
                short tileIdx, srcX, srcY;

                if (rMapX < 0 || rMapX >= 112 || rMapY < 0 || rMapY >= rdMapH)
                    continue;
                rd = roadData[rMapY * 112 + rMapX] & 0x1F;
                if (rd == 0 || rd > 17) continue;

                tileIdx = rd - 1;
                srcX = (tileIdx % 13) * 48;
                srcY = (tileIdx / 13) * 40;
                SetRect(&srcRect, srcX, srcY, srcX + 40, srcY + 40);

                SetRect(&dstRect,
                    winRect.left + tx * TERRAIN_TILE_W,
                    winRect.top  + ty * TERRAIN_TILE_H,
                    winRect.left + (tx + 1) * TERRAIN_TILE_W,
                    winRect.top  + (ty + 1) * TERRAIN_TILE_H);

                CopyBits((BitMap *)*roadPix,
                         &((GrafPtr)win)->portBits,
                         &srcRect, &dstRect, 36, NULL);
            }
        }

        RGBBackColor(&oldBack);
        UnlockPixels(roadPix);
    }

    /* --- Port anchors (PPC FUN_1000419c / FUN_10005f90): MAP low byte bit 0x80,
     * PICT 30010 (0,0) 32x30 at the tile's top-left, after the roads and
     * before cities and armies. None on the minimap. --- */
    {
        short tx2, ty2;
        for (ty2 = 0; ty2 < tilesHigh; ty2++)
            for (tx2 = 0; tx2 < tilesWide; tx2++) {
                short mx2 = sViewportX + tx2, my2 = sViewportY + ty2;
                Rect ar;
                if (mx2 < 0 || mx2 >= sMapWidth || my2 < 0 || my2 >= sMapHeight) continue;
                if (!(mapData[my2 * 0xE0 + mx2 * 2 + 1] & 0x80)) continue;
                SetRect(&ar, winRect.left + tx2 * TERRAIN_TILE_W, winRect.top + ty2 * TERRAIN_TILE_H,
                        winRect.left + tx2 * TERRAIN_TILE_W + 32, winRect.top + ty2 * TERRAIN_TILE_H + 30);
                DrawPortAnchor(&ar);
            }
    }

    /* --- Fog of war: drawn AFTER all sprites (see block below stack badges) --- */

    /* --- Draw city/ruin/temple icons from SCN data at gs+0x812 --- */
    /* Each site record is 0x20 bytes: +0=x, +2=y, +4=owner, +6=defense, +8=income, +0x17=site_type */
    /* site_type: 0/1=city, 2=temple, 3=library, 4=treasure, 5=ally */
    /* Two passes: ruins first (they're smaller), then cities (80x80, srcCopy covers ruins) */
    if (hasScn) {
        short cityCount = sCityCount;
        short drawPass;
        if (cityCount > 139) cityCount = 139;

        for (drawPass = 0; drawPass < 2; drawPass++)
        for (i = 0; i < cityCount; i++) {
            unsigned char *city = sCityData +i * 0x20;
            short cx = *(short *)(city + 0x00);
            short cy = *(short *)(city + 0x02);
            short owner = *(short *)(city + 0x04);
            short siteType = (short)(unsigned char)city[0x17];
            short screenX, screenY;

            /* Pass 0: ruins only (sType >= 2). Pass 1: cities only (sType < 2). */
            if (drawPass == 0 && siteType < 2) continue;
            if (drawPass == 1 && siteType >= 2) continue;

            screenX = winRect.left + (cx - sViewportX) * TERRAIN_TILE_W;
            screenY = winRect.top  + (cy - sViewportY) * TERRAIN_TILE_H;

            if (screenX >= winRect.left - TERRAIN_TILE_W &&
                screenX < winRect.right &&
                screenY >= winRect.top - TERRAIN_TILE_H &&
                screenY < winRect.bottom) {

                /* Fog of war: hide unexplored cities/ruins */
                if (*(short *)(scnData + 0x116) != 0) {
                    short curP = *(short *)(scnData + 0x110);
                    if (curP >= 0 && curP < 8 &&
                        !FogGetBit(sFogExplored[curP], cx, cy))
                        continue;
                }

                if (siteType >= 2 && siteType <= 6) {
                    /* === Ruin / Temple overlay from terrain sprite sheet ===
                     * Tile index 10 = ruin sprite, tile index 11 = temple sprite
                     * in PICT 30022 (16 cols x 6 rows of 40x40 tiles). */
                    if (sTerrainGW != NULL) {
                        short tileIdx = (siteType == 2) ? 11 : 10; /* temple=11, ruin=10 */
                        short col = tileIdx % 16;
                        short row = tileIdx / 16;
                        Rect srcR, dstR;
                        PixMapHandle srcPix = GetGWorldPixMap(sTerrainGW);
                        SetRect(&srcR, col * 40, row * 40,
                                col * 40 + 40, row * 40 + 40);
                        SetRect(&dstR, screenX, screenY,
                                screenX + 40, screenY + 40);
                        LockPixels(srcPix);
                        CopyBits((BitMap *)*srcPix,
                                 &((GrafPtr)win)->portBits,
                                 &srcR, &dstR,
                                 srcCopy, NULL);
                        UnlockPixels(srcPix);
                    }
                } else {
                    /* === City icon === */
                    if (sTerrainGW2 != NULL) {
                        /* City sprites from PICT 30023 (terrain overlay sheet).
                         * Each city is 80×80 (2×2 of 40×40 tiles), opaque with grass bg.
                         * Layout: 7 per row. Row 0 = neutral + players 0-5 (indices 0-6),
                         *         Row 1 = players 6-7 (indices 7-8).
                         * Position (560,0) is mountain terrain, NOT a city.
                         * Owner mapping: cityIdx = owner+1 (0=neutral, 1-8=players). */
                        short cityIdx;
                        short srcX, srcY;
                        Rect srcRect, dstRect;
                        PixMapHandle srcPix = GetGWorldPixMap(sTerrainGW2);

                        if (owner >= 0 && owner < 8)
                            cityIdx = owner + 1;  /* players 0-7 → indices 1-8 */
                        else
                            cityIdx = 0;           /* neutral → index 0 */

                        /* 7 cities per row: row 0 indices 0-6, row 1 indices 7-8 */
                        srcX = (cityIdx % 7) * 80;
                        srcY = (cityIdx / 7) * 80;

                        SetRect(&srcRect, srcX, srcY, srcX + 80, srcY + 80);
                        SetRect(&dstRect, screenX, screenY,
                            screenX + 80, screenY + 80);

                        LockPixels(srcPix);
                        CopyBits((BitMap *)*srcPix,
                                 &((GrafPtr)win)->portBits,
                                 &srcRect, &dstRect,
                                 srcCopy, NULL);
                        UnlockPixels(srcPix);

                        /* Port anchors removed — terrain tiles handle port visuals */

                        /* (debug owner overlay removed) */
                    } else {
                        /* Fallback: programmatic castle icon */
                        RGBColor black = {0x0000, 0x0000, 0x0000};
                        RGBColor darkGray = {0x4444, 0x4444, 0x4444};
                        RGBColor lightGray = {0xBBBB, 0xBBBB, 0xBBBB};
                        short colorIdx;
                        Rect wallRect, towerL, towerR, gateRect, flagRect;

                        if (owner >= 0 && owner < 8)
                            colorIdx = owner + 1;
                        else
                            colorIdx = 8;

                        SetRect(&wallRect, screenX + 4, screenY + 8,
                                screenX + TERRAIN_TILE_W - 4, screenY + TERRAIN_TILE_H - 2);
                        RGBForeColor(&lightGray);
                        PaintRect(&wallRect);
                        RGBForeColor(&darkGray);
                        FrameRect(&wallRect);

                        SetRect(&towerL, screenX + 2, screenY + 2,
                                screenX + 10, screenY + TERRAIN_TILE_H - 2);
                        RGBForeColor(&lightGray);
                        PaintRect(&towerL);
                        RGBForeColor(&darkGray);
                        FrameRect(&towerL);

                        SetRect(&towerR, screenX + TERRAIN_TILE_W - 10, screenY + 2,
                                screenX + TERRAIN_TILE_W - 2, screenY + TERRAIN_TILE_H - 2);
                        RGBForeColor(&lightGray);
                        PaintRect(&towerR);
                        RGBForeColor(&darkGray);
                        FrameRect(&towerR);

                        {
                            short bx;
                            RGBForeColor(&darkGray);
                            for (bx = screenX + 2; bx < screenX + 10; bx += 4) {
                                Rect cren;
                                SetRect(&cren, bx, screenY + 2, bx + 2, screenY + 4);
                                PaintRect(&cren);
                            }
                            for (bx = screenX + TERRAIN_TILE_W - 10; bx < screenX + TERRAIN_TILE_W - 2; bx += 4) {
                                Rect cren;
                                SetRect(&cren, bx, screenY + 2, bx + 2, screenY + 4);
                                PaintRect(&cren);
                            }
                        }

                        SetRect(&gateRect, screenX + 12, screenY + 16,
                                screenX + 20, screenY + TERRAIN_TILE_H - 2);
                        RGBForeColor(&black);
                        PaintRect(&gateRect);

                        SetRect(&flagRect, screenX + 13, screenY + 6,
                                screenX + 19, screenY + 14);
                        RGBForeColor(&sPlayerColors[colorIdx]);
                        PaintRect(&flagRect);
                        RGBForeColor(&black);
                        FrameRect(&flagRect);
                    }
                }
            }
        }
    }

    /* --- Draw city names below castle icons ---
     * Remake-only overlay: the original map shows no city labels. */
    if (hasScn && sShowCityLabels) {
        short cityCount2 = sCityCount;
        if (cityCount2 > 139) cityCount2 = 139;
        TextFont(3);
        TextSize(9);
        TextFace(0);
        for (i = 0; i < cityCount2; i++) {
            unsigned char *city = sCityData +i * 0x20;
            short cx = *(short *)(city + 0x00);
            short cy = *(short *)(city + 0x02);
            short cityOwner = *(short *)(city + 0x04);
            short siteType = (short)(unsigned char)city[0x17];
            short screenX, screenY;

            if (siteType != 0) continue;  /* only label cities */

            screenX = winRect.left + (cx - sViewportX) * TERRAIN_TILE_W;
            screenY = winRect.top  + (cy - sViewportY) * TERRAIN_TILE_H;

            if (screenX >= winRect.left - TERRAIN_TILE_W &&
                screenX < winRect.right &&
                screenY >= winRect.top - TERRAIN_TILE_H &&
                screenY < winRect.bottom) {
                short colorIdx = (cityOwner >= 0 && cityOwner < 8) ? cityOwner + 1 : 8;
                RGBColor shadowCol = {0x0000, 0x0000, 0x0000};
                Str255 cityPName;

                /* Fog of war: hide city names in unexplored tiles */
                if (*(short *)(scnData + 0x116) != 0) {
                    short curP = *(short *)(scnData + 0x110);
                    if (curP >= 0 && curP < 8 &&
                        !FogGetBit(sFogExplored[curP], cx, cy))
                        continue;
                }
                short nameLen = 0;

                /* Get city name from CTY resource data, or fall back to faction name */
                if (i < sCityNameCount && sCityNames[i][0] != '\0') {
                    char *cn = sCityNames[i];
                    while (nameLen < MAX_CITY_NAME - 1 && cn[nameLen] != '\0')
                        nameLen++;
                    {
                        short ni2;
                        for (ni2 = 0; ni2 < nameLen; ni2++)
                            cityPName[ni2 + 1] = cn[ni2];
                    }
                } else if (cityOwner >= 0 && cityOwner < 8) {
                    char *fn = (char *)(scnData + cityOwner * 20);
                    while (nameLen < 12 && fn[nameLen] != 0)
                        nameLen++;
                    {
                        short ni2;
                        for (ni2 = 0; ni2 < nameLen; ni2++)
                            cityPName[ni2 + 1] = fn[ni2];
                    }
                } else {
                    nameLen = 7;
                    BlockMoveData("Neutral", cityPName + 1, 7);
                }
                cityPName[0] = (unsigned char)nameLen;

                /* Append production timer for own cities: " [N]" */
                if (*gExtState != 0 && cityOwner >= 0 && cityOwner < 8 &&
                    cityOwner == *(short *)(scnData + 0x110)) {
                    unsigned char *ext = (unsigned char *)*gExtState;
                    unsigned char *extCity = ext + 0x24c + i * 0x5c;
                    short prodType = *(short *)(extCity + 0x02);
                    short prodTurns = *(short *)(extCity + 0x58);
                    if (prodType >= 0 && nameLen + 4 <= 254) {
                        Str255 tn;
                        short ti2;
                        cityPName[++cityPName[0]] = ' ';
                        cityPName[++cityPName[0]] = '[';
                        NumToString((long)prodTurns, tn);
                        for (ti2 = 1; ti2 <= tn[0]; ti2++)
                            cityPName[++cityPName[0]] = tn[ti2];
                        cityPName[++cityPName[0]] = ']';
                    }
                }

                /* Shadow text */
                RGBForeColor(&shadowCol);
                MoveTo(screenX + 1, screenY + TERRAIN_TILE_H + 9);
                DrawString(cityPName);
                /* Colored text */
                RGBForeColor(&sPlayerColors[colorIdx]);
                MoveTo(screenX, screenY + TERRAIN_TILE_H + 8);
                DrawString(cityPName);
            }
        }
    }

    /* --- Draw army sprites from game state --- */
    if (hasScn) {
        short armyCount = *(short *)(scnData + 0x1602);
        if (armyCount > 100) armyCount = 100;

        for (i = 0; i < armyCount; i++) {
            unsigned char *army = scnData + 0x1604 + i * 0x42;
            short ax = *(short *)(army + 0x00);
            short ay = *(short *)(army + 0x02);
            short owner = (short)(unsigned char)army[0x15];
            short screenX, screenY;

            /* Skip invalid/empty army records */
            if (army[0x16] == 0xFF) continue;           /* no units */
            if (ax < 0 || ay < 0) continue;             /* invalid coords */
            if (ax >= sMapWidth || ay >= sMapHeight) continue;

            /* Fog of war: hide enemy armies in non-visible tiles */
            if (*(short *)(scnData + 0x116) != 0) {
                short curPlayer = *(short *)(scnData + 0x110);
                if (curPlayer >= 0 && curPlayer < 8 && owner != curPlayer) {
                    if (!FogGetBit(sFogVisible[curPlayer], ax, ay))
                        continue;
                }
            }

            /* One army sprite per tile, as the original: a hero if the stack
             * has one, else the first army there (Mirea turn 1: the hero
             * stands over the Heavy Cav.) */
            {
                Boolean iHero = ((unsigned char)army[0x16] == 0x1C);
                short aj;
                Boolean hidden = false, selHere = false;
                if (sSelectedArmy >= 0 && sSelectedArmy < armyCount) {
                    unsigned char *sel = scnData + 0x1604 + sSelectedArmy * 0x42;
                    if (*(short *)(sel + 0) == ax && *(short *)(sel + 2) == ay) {
                        if (i != sSelectedArmy) continue;    /* the selection is drawn on its tile */
                        selHere = true;
                    }
                }
                for (aj = 0; aj < armyCount && !hidden && !selHere; aj++) {
                    unsigned char *a2 = scnData + 0x1604 + aj * 0x42;
                    Boolean jHero;
                    if (aj == i || a2[0x16] == 0xFF) continue;
                    if (*(short *)(a2 + 0x00) != ax || *(short *)(a2 + 0x02) != ay) continue;
                    jHero = ((unsigned char)a2[0x16] == 0x1C);
                    if ((jHero && !iHero) || (jHero == iHero && aj < i)) hidden = true;
                }
                if (hidden) continue;
            }

            /* Skip naval/boat sprites on land tiles */
            if (*gMapTiles != 0 && ArmyIsNaval(i)) {
                unsigned char *md = (unsigned char *)*gMapTiles;
                short tIdx = (short)(unsigned char)md[ay * 0xE0 + ax * 2];
                short tType = (short)(unsigned char)scnData[tIdx + TERRAIN_TYPE_OFS];
                if (tType != 2 && tType != 9 && tType != 3)
                    continue;  /* not water/sea/shore: don't draw boat */
            }

            screenX = winRect.left + (ax - sViewportX) * TERRAIN_TILE_W;
            screenY = winRect.top  + (ay - sViewportY) * TERRAIN_TILE_H;

            if (screenX >= winRect.left - TERRAIN_TILE_W &&
                screenX < winRect.right &&
                screenY >= winRect.top - TERRAIN_TILE_H &&
                screenY < winRect.bottom) {

                short colorIdx = (owner >= 0 && owner < 8) ? owner + 1 : 0;
                /* 68k CODE_067 FUN_000014e2: uses army[0x14] (sprite_index) directly.
                 * This is the authoritative sprite index set by the scenario/game.
                 * Do NOT use army[0x16] (unit type) + table lookup — that gives
                 * wrong results for heroes and loaded scenarios. */
                short spriteIdx = (short)(unsigned char)army[0x14];
                short sheetIdx = (owner >= 0 && owner < 8) ? owner : 8;
                GWorldPtr armyGW;
                short spriteCol, spriteRow;

                /* Hero gender remapping: 68k FUN_000000ae remaps sprite 0x1C
                 * to 0x1D for female heroes (gs+0x594+slot*2 == 1).
                 * Uses IsHeroFemale() which scans hero instance records. */
                if (spriteIdx == 0x1C && IsHeroFemale(i))
                    spriteIdx = 0x1D;
#if DEV_SHIP_PROBE   /* DEV: label armies drawn as a ship that hold no naval unit */
                if (spriteIdx == 5) {
                    char b[64]; Str255 ps; short n;
                    RGBColor yel = {0xFFFF, 0xFFFF, 0}, blk = {0, 0, 0};
                    { unsigned char *md0 = (unsigned char *)*gMapTiles; short ti = md0[ay * 0xE0 + ax * 2];
                      sprintf(b, "#%d o%d t%d,%d,%d,%d tt%d n%d", i, owner, army[0x16], army[0x17], army[0x18], army[0x19],
                              scnData[ti + TERRAIN_TYPE_OFS], ArmyIsNaval(i)); }
                    for (n = 0; b[n] && n < 60; n++) ps[n + 1] = b[n];
                    ps[0] = (unsigned char)n;
                    TextFont(4); TextSize(9); TextMode(srcCopy);
                    RGBForeColor(&yel); RGBBackColor(&blk);
                    MoveTo(screenX, screenY + 48); DrawString(ps);
                    TextMode(srcOr); RGBForeColor(&blk);
                    { RGBColor w = {0xFFFF,0xFFFF,0xFFFF}; RGBBackColor(&w); }
                }
#endif

                /* Each 512x64 sheet has unit types in a 16x2 grid (32px cells).
                 * Sheet per faction: sArmyGW[owner]. */
                spriteCol = spriteIdx % 16;
                spriteRow = spriteIdx / 16;
                armyGW = (sArmyGW[sheetIdx] != NULL) ? sArmyGW[sheetIdx] :
                         (sArmyGW[0] != NULL) ? sArmyGW[0] : NULL;

                if (sArmyLoaded && armyGW != NULL) {
                    /* Blit army sprite from sprite sheet.
                     * 68k CODE_067 FUN_000001c4: srcRect 32×30 cells,
                     *   srcY = (idx/16)*30, srcX = (idx%16)*32.
                     * Dest: tile + 7px offset for centering within 40×40 tile.
                     * Mode 36 transparent blit: bg-colored pixels are not drawn. */
                    Rect srcRect, dstRect;
                    short srcX = spriteCol * 32;
                    short srcY = spriteRow * 30;  /* row stride is 30px, sprite is 29px tall (68k 0x1D) */
                    SetRect(&srcRect, srcX, srcY, srcX + 32, srcY + 29);
                    SetRect(&dstRect, screenX + 8, screenY + 7,
                            screenX + 8 + 32, screenY + 7 + 29);

                    LockPixels(GetGWorldPixMap(armyGW));
                    {
                        RGBColor savedBg;
                        GetBackColor(&savedBg);
                        RGBBackColor(&sArmyBgColor[sheetIdx]);
                        CopyBits((BitMap *)*GetGWorldPixMap(armyGW),
                                 &((GrafPtr)win)->portBits,
                                 &srcRect, &dstRect,
                                 36, NULL);
                        RGBBackColor(&savedBg);
                    }
                    UnlockPixels(GetGWorldPixMap(armyGW));
                } else {
                    /* No army sprites loaded — draw colored oval fallback */
                    Rect markerR;
                    RGBColor black = {0, 0, 0};
                    SetRect(&markerR, screenX + 6, screenY + 2,
                            screenX + TERRAIN_TILE_W - 6, screenY + TERRAIN_TILE_H - 12);
                    RGBForeColor(&sPlayerColors[colorIdx]);
                    PaintOval(&markerR);
                    RGBForeColor(&black);
                    FrameOval(&markerR);
                }
            }
        }
    }

    /* --- Stack flags ---
     * PPC FUN_10005d2c (68k CODE_067 FUN_000014e2): every occupied tile gets a
     * 40px pole (palette 14 dark brown at x+2 and x+4, 13 light at x+3) and a
     * pennant from the owner's army sheet (srcLeft 464, 48x8, transparent)
     * whose length shows the stack size 1..4; 5..8 add a second, full
     * pennant 8px lower. */
    if (hasScn) {
        static const short kPennantTop[4] = {29, 38, 47, 56};
        short armyCount = *(short *)(scnData + 0x1602);
        if (armyCount > 100) armyCount = 100;
        for (i = 0; i < armyCount; i++) {
            unsigned char *army = scnData + 0x1604 + i * 0x42;
            short ax, ay, aOwn, stackN, aj, sheetIdx;
            short screenX, screenY;
            GWorldPtr gw;
            if (army[0x16] == 0xFF) continue;
            ax = *(short *)(army + 0x00);
            ay = *(short *)(army + 0x02);
            aOwn = (short)(unsigned char)army[0x15];
            if (ax < 0 || ay < 0 || ax >= sMapWidth || ay >= sMapHeight) continue;
            /* Fog of war */
            if (*(short *)(scnData + 0x116) != 0) {
                short curP = *(short *)(scnData + 0x110);
                if (curP >= 0 && curP < 8 && aOwn != curP)
                    if (!FogGetBit(sFogVisible[curP], ax, ay)) continue;
            }
            /* One flag per tile: only for the first army there */
            {
                Boolean earlierSameTile = false;
                for (aj = 0; aj < i; aj++) {
                    unsigned char *a2 = scnData + 0x1604 + aj * 0x42;
                    if (a2[0x16] == 0xFF) continue;
                    if (*(short *)(a2 + 0x00) == ax && *(short *)(a2 + 0x02) == ay) {
                        earlierSameTile = true; break;
                    }
                }
                if (earlierSameTile) continue;
            }
            /* Units on the tile (the original keeps one unit per army) */
            stackN = 0;
            for (aj = 0; aj < armyCount; aj++) {
                unsigned char *a2 = scnData + 0x1604 + aj * 0x42;
                if (a2[0x16] == 0xFF) continue;
                if (*(short *)(a2 + 0x00) == ax && *(short *)(a2 + 0x02) == ay) {
                    short us;
                    for (us = 0; us < 4; us++)
                        if ((unsigned char)a2[0x16 + us] != 0xFF) stackN++;
                }
            }
            if (stackN < 1) continue;
            screenX = winRect.left + (ax - sViewportX) * TERRAIN_TILE_W;
            screenY = winRect.top  + (ay - sViewportY) * TERRAIN_TILE_H;
            if (screenX < winRect.left - TERRAIN_TILE_W || screenX >= winRect.right ||
                screenY < winRect.top - TERRAIN_TILE_H || screenY >= winRect.bottom) continue;
            {
                RGBColor dark = {0x9090, 0x5050, 0x0000}, light = {0xBBBB, 0x7373, 0x0000};
                RGBColor black = {0, 0, 0};
                RGBForeColor(&dark);
                MoveTo(screenX + 2, screenY); Line(0, 39);
                MoveTo(screenX + 4, screenY); Line(0, 39);
                RGBForeColor(&light);
                MoveTo(screenX + 3, screenY); Line(0, 39);
                RGBForeColor(&black);
            }
            sheetIdx = (aOwn >= 0 && aOwn < 8) ? aOwn : 8;
            gw = (sArmyGW[sheetIdx] != NULL) ? sArmyGW[sheetIdx] : sArmyGW[0];
            if (sArmyLoaded && gw != NULL) {
                PixMapHandle pm = GetGWorldPixMap(gw);
                RGBColor savedBg;
                short n = stackN, pass;
                LockPixels(pm);
                GetBackColor(&savedBg);
                RGBBackColor(&sArmyBgColor[sheetIdx]);
                for (pass = 0; pass < 2; pass++) {
                    short top, dy;
                    Rect sr, dr;
                    if (pass == 0) {
                        if (n <= 4) continue;
                        top = kPennantTop[0]; dy = 8; n -= 4;
                    } else {
                        if (n > 4) n = 4;
                        top = kPennantTop[n - 1]; dy = 0;
                    }
                    SetRect(&sr, 464, top, 512, top + 8);
                    SetRect(&dr, screenX, screenY + dy, screenX + 48, screenY + dy + 8);
                    CopyBits((BitMap *)*pm, &((GrafPtr)win)->portBits, &sr, &dr, 36, NULL);
                }
                RGBBackColor(&savedBg);
                UnlockPixels(pm);
            }
        }
    }

    /* --- Draw defend mode indicators on defending armies --- */
    if (hasScn) {
        short armyCount = *(short *)(scnData + 0x1602);
        if (armyCount > 100) armyCount = 100;
        for (i = 0; i < armyCount; i++) {
            unsigned char *army = scnData + 0x1604 + i * 0x42;
            /* Skip invalid/empty army records */
            if (army[0x16] == 0xFF) continue;
            {
                short ax = *(short *)(army + 0x00);
                short ay = *(short *)(army + 0x02);
                if (ax < 0 || ay < 0 || ax >= sMapWidth || ay >= sMapHeight) continue;
                /* Fog of war: hide enemy defend indicators */
                if (*(short *)(scnData + 0x116) != 0) {
                    short curP = *(short *)(scnData + 0x110);
                    short aOwn = (short)(unsigned char)army[0x15];
                    if (curP >= 0 && curP < 8 && aOwn != curP &&
                        !FogGetBit(sFogVisible[curP], ax, ay))
                        continue;
                }
            }
            if (*gExtState != 0 &&
                ((unsigned char *)*gExtState)[0x56 + i] == 7 && ArmyShownOnTile(i)) {
                /* Army is guarding (ext state army_state == 7): draw defend sprite.
                 * 68k CODE_067 FUN_000000ae: uses sprite index 5 as overlay. */
                short ax = *(short *)(army + 0x00);
                short ay = *(short *)(army + 0x02);
                short aOwner2 = (short)(unsigned char)army[0x15];
                short screenX = winRect.left + (ax - sViewportX) * TERRAIN_TILE_W;
                short screenY = winRect.top  + (ay - sViewportY) * TERRAIN_TILE_H;

                if (screenX >= winRect.left && screenX < winRect.right &&
                    screenY >= winRect.top && screenY < winRect.bottom &&
                    sArmyLoaded) {
                    short sheetIdx = (aOwner2 >= 0 && aOwner2 < 8) ? aOwner2 : 8;
                    GWorldPtr defGW = (sArmyGW[sheetIdx] != NULL) ? sArmyGW[sheetIdx] :
                                      (sArmyGW[0] != NULL) ? sArmyGW[0] : NULL;
                    if (defGW != NULL) {
                        /* Sprite 5: col=5, row=0 in 32x29 grid (68k FUN_000000ae) */
                        Rect srcR, dstR;
                        SetRect(&srcR, 5 * 32, 0, 5 * 32 + 32, 29);
                        SetRect(&dstR, screenX + 8, screenY + 7,
                                screenX + 8 + 32, screenY + 7 + 29);
                        LockPixels(GetGWorldPixMap(defGW));
                        {
                            RGBColor savedBg;
                            GetBackColor(&savedBg);
                            RGBBackColor(&sArmyBgColor[sheetIdx]);
                            CopyBits((BitMap *)*GetGWorldPixMap(defGW),
                                     &((GrafPtr)win)->portBits,
                                     &srcR, &dstR, 36, NULL);
                            RGBBackColor(&savedBg);
                        }
                        UnlockPixels(GetGWorldPixMap(defGW));
                    }
                }
            }
        }
    }

    /* --- Fog of war overlay (bitmap-based, drawn LAST per 68k CODE_067) --- */
    /* 68k draws fog AFTER all sprites (cities, armies, badges) so that
     * explored-but-not-visible tiles are properly dimmed including any
     * sprites. The selected army is drawn AFTER fog (in selection highlight). */
    if (hasScn && *(short *)(scnData + 0x116) != 0) {
        short curPlayer = *(short *)(scnData + 0x110);
        if (curPlayer >= 0 && curPlayer < 8) {
            for (ty = 0; ty < tilesHigh; ty++) {
                for (tx = 0; tx < tilesWide; tx++) {
                    short mapX = sViewportX + tx;
                    short mapY = sViewportY + ty;
                    Rect fogRect;

                    if (mapX < 0 || mapX >= sMapWidth || mapY < 0 || mapY >= sMapHeight)
                        continue;

                    if (FogGetBit(sFogVisible[curPlayer], mapX, mapY))
                        continue;  /* currently visible: no overlay */

                    SetRect(&fogRect,
                        winRect.left + tx * TERRAIN_TILE_W,
                        winRect.top  + ty * TERRAIN_TILE_H,
                        winRect.left + (tx + 1) * TERRAIN_TILE_W,
                        winRect.top  + (ty + 1) * TERRAIN_TILE_H);

                    if (FogGetBit(sFogExplored[curPlayer], mapX, mapY)) {
                        /* Explored but not currently visible: semi-transparent dim */
                        RGBColor dimColor = {0x6666, 0x6666, 0x6666};
                        RGBForeColor(&dimColor);
                        PenMode(subOver);
                        PaintRect(&fogRect);
                        PenMode(srcCopy);
                    } else {
                        /* Never explored: solid black */
                        RGBColor blackColor = {0x0000, 0x0000, 0x0000};
                        RGBForeColor(&blackColor);
                        PaintRect(&fogRect);
                    }
                }
            }
        }
    }

    /* Movement range overlay removed — original Warlords II does not show
     * movement range with grid outlines. The white FrameRect squares
     * were not aligned with the terrain tile artwork's dither pattern,
     * creating a visual mismatch. */

    /* --- Path preview while dragging (original: the mouse held down with an
     * army selected): each intermediate step gets a 14x14 ring at (+17,+13),
     * plain while affordable this turn, crossed beyond the moves left; the
     * last tile shows the army's ghost. No preview on plain hover. */
    /* A selected army with a pending order shows its remaining path the same
     * way (original turn 3: selecting the hero drew rings to its ghost). */
    if (!sDragPreview && sSelectedArmy >= 0 && hasScn && sAITurnPlayer < 0 &&   /* no path for AI moves */
        sSelectedArmy < *(short *)(scnData + 0x1602)) {
        static long lastSig = -1;
        unsigned char *sa = scnData + 0x1604 + sSelectedArmy * 0x42;
        long sig = -1;
        if (*(short *)(sa + 0x32) != 0)
            sig = (((long)sSelectedArmy * 160 + *(short *)(sa + 0)) * 160 + *(short *)(sa + 2)) * 160L * 160L +
                  *(short *)(sa + 0x34) * 160L + *(short *)(sa + 0x36);
        if (sig != lastSig || (sig >= 0 && sPreviewPathLen <= 1)) {
            lastSig = sig;
            sPreviewPathLen = 0;
            if (sig >= 0) {
                short ax = *(short *)(sa + 0), ay = *(short *)(sa + 2);
                sPathTargetX = *(short *)(sa + 0x34); sPathTargetY = *(short *)(sa + 0x36);
                ComputePathGridOnly(ax, ay, GetEffectiveUnitClass(sSelectedArmy));
                TracePreviewPath(ax, ay, sPathTargetX, sPathTargetY);
                sPreviewGridValid = false;
            }
        }
    }
    if (sAITurnPlayer < 0 && (sDragPreview || (sSelectedArmy >= 0 && hasScn &&
         *(short *)(scnData + 0x1604 + sSelectedArmy * 0x42 + 0x32) != 0)) &&
        sPreviewPathLen > 1 && sSelectedArmy >= 0 && hasScn) {
        static const char *ringArt[14] = {
            "....######....", "...########...", "..###....###..", ".###......###.",
            "###........###", "##..........##", "##..........##", "##..........##",
            "##..........##", "###........###", ".###......###.", "..###....###..",
            "...########...", "....######...." };
        static const char *crossArt[14] = {
            "....######....", "...########...", "..###....###..", ".####....####.",
            "######..######", "##..######..##", "##...####...##", "##...####...##",
            "##..######..##", "######..######", ".####....####.", "..###....###..",
            "...########...", "....######...." };
        unsigned char *selA = scnData + 0x1604 + sSelectedArmy * 0x42;
        short mp = (short)(unsigned char)selA[0x2e], cum = 0, pi, cls = GetEffectiveUnitClass(sSelectedArmy);
        RGBColor black = {0, 0, 0};
        RGBForeColor(&black);
        for (pi = 1; pi < sPreviewPathLen; pi++) {
            short tx = sPreviewPathX[pi], ty = sPreviewPathY[pi];
            short px = winRect.left + (tx - sViewportX) * TERRAIN_TILE_W;
            short py = winRect.top  + (ty - sViewportY) * TERRAIN_TILE_H;
            short c = GetMovementCost(tx, ty, cls);
            cum += (c > 0 ? c : 99);
            if (pi == sPreviewPathLen - 1) {
                short spr = (short)(unsigned char)selA[0x14];
                if (spr == 0x1C && IsHeroFemale(sSelectedArmy)) spr = 0x1D;
                DrawArmyGhostAt((short)(unsigned char)selA[0x15], spr, px + 8, py + 7);
            } else {
                const char **art = (cum <= mp) ? ringArt : crossArt;
                short i, j;
                for (j = 0; j < 14; j++)
                    for (i = 0; i < 14; i++)
                        if (art[j][i] == '#') { MoveTo(px + 17 + i, py + 13 + j); LineTo(px + 17 + i, py + 13 + j); }
            }
        }
    }

    /* --- Draw blinking selection highlight around selected army --- */
    if (sSelectedArmy >= 0 && hasScn) {
        short armyCount = *(short *)(scnData + 0x1602);
        if (sSelectedArmy < armyCount) {
            unsigned char *selArmy = scnData + 0x1604 + sSelectedArmy * 0x42;
            short sx = *(short *)(selArmy + 0x00);
            short sy = *(short *)(selArmy + 0x02);
            short screenX = winRect.left + (sx - sViewportX) * TERRAIN_TILE_W;
            short screenY = winRect.top  + (sy - sViewportY) * TERRAIN_TILE_H;

            if (screenX >= winRect.left - TERRAIN_TILE_W &&
                screenX < winRect.right &&
                screenY >= winRect.top - TERRAIN_TILE_H &&
                screenY < winRect.bottom) {
                /* Halo (PPC FUN_10082430/FUN_10082260): four 31x30 frames of
                 * blue rings in PICT 1002 (32 apart), cycled on idle, drawn at
                 * (+8,+7) with the selected army's sprite over it. */
                short selOwner = (short)(unsigned char)selArmy[0x15];
                short selSprite = (short)(unsigned char)selArmy[0x14];
                if (selSprite == 0x1C && IsHeroFemale(sSelectedArmy)) selSprite = 0x1D;
                if (sHaloGW == NULL) {
                    sHaloGW = LoadPICTIntoGWorld(1002);
                    if (sHaloGW != NULL) {
                        CGrafPtr sp; GDHandle sd;
                        GetGWorld(&sp, &sd);
                        SetGWorld(sHaloGW, NULL);
                        GetCPixel(0, 0, &sHaloKey);
                        SetGWorld(sp, sd);
                    }
                }
                if (sHaloGW != NULL) {
                    PixMapHandle pm = GetGWorldPixMap(sHaloGW);
                    Rect sr, dr;
                    RGBColor savedBg, black = {0, 0, 0};
                    LockPixels(pm);
                    GetBackColor(&savedBg);
                    RGBForeColor(&black);
                    RGBBackColor(&sHaloKey);
                    SetRect(&sr, (sHaloFrame & 3) * 32, 0, (sHaloFrame & 3) * 32 + 31, 30);
                    SetRect(&dr, screenX + 8, screenY + 7, screenX + 8 + 31, screenY + 7 + 30);
                    CopyBits((BitMap *)*pm, &((GrafPtr)win)->portBits, &sr, &dr, 36, NULL);
                    RGBBackColor(&savedBg);
                    UnlockPixels(pm);
                }
                DrawArmySpriteAt(selOwner, selSprite, screenX + 8, screenY + 7, false);
#if DEV_SHIP_PROBE
                if (selSprite == 5) {
                    char b[64]; Str255 ps; short n;
                    RGBColor yel = {0xFFFF, 0xFFFF, 0}, blk = {0, 0, 0}, w = {0xFFFF,0xFFFF,0xFFFF};
                    sprintf(b, "SEL#%d o%d t%d,%d,%d,%d", sSelectedArmy, selOwner, selArmy[0x16], selArmy[0x17], selArmy[0x18], selArmy[0x19]);
                    for (n = 0; b[n] && n < 60; n++) ps[n + 1] = b[n];
                    ps[0] = (unsigned char)n;
                    TextFont(4); TextSize(9); TextMode(srcCopy);
                    RGBForeColor(&yel); RGBBackColor(&blk);
                    MoveTo(screenX, screenY + 58); DrawString(ps);
                    TextMode(srcOr); RGBForeColor(&blk); RGBBackColor(&w);
                }
#endif
            }

            /* Destination of a pending order: the original draws a ghost of
             * the army's sprite there (black outline kept, other pixels white
             * on a checkerboard; measured turn 1 at Mirea), no box or line. */
            if (*(short *)(selArmy + 0x32) != 0) {
                short tx = *(short *)(selArmy + 0x34);
                short ty = *(short *)(selArmy + 0x36);
                short tScreenX = winRect.left + (tx - sViewportX) * TERRAIN_TILE_W;
                short tScreenY = winRect.top  + (ty - sViewportY) * TERRAIN_TILE_H;
                short spr = (short)(unsigned char)selArmy[0x14];
                if (spr == 0x1C && IsHeroFemale(sSelectedArmy)) spr = 0x1D;
                if (sPreviewPathLen <= 1 && (tx != sx || ty != sy) &&
                    tScreenX >= winRect.left - TERRAIN_TILE_W && tScreenX < winRect.right &&
                    tScreenY >= winRect.top - TERRAIN_TILE_H && tScreenY < winRect.bottom)
                    DrawArmyGhostAt((short)(unsigned char)selArmy[0x15], spr,
                                    tScreenX + 8, tScreenY + 7);
            }
        }
    }

    /* --- Draw city vectoring lines --- */
    if (hasScn && *gExtState != 0) {
        unsigned char *ext = (unsigned char *)*gExtState;
        short cityCount = sCityCount;
        short curPlayer = *(short *)(scnData + 0x110);
        short ci;
        if (cityCount > 139) cityCount = 139;
        for (ci = 0; ci < cityCount; ci++) {
            unsigned char *city = sCityData +ci * 0x20;
            unsigned char *extCity = ext + 0x24c + ci * 0x5c;
            short vTarget = *(short *)(extCity + 0x3e);
            if (*(short *)(city + 0x04) != curPlayer) continue;
            if (vTarget < 0 || vTarget >= cityCount || vTarget == ci) continue;
            {
                unsigned char *tgtCity = sCityData +vTarget * 0x20;
                short cx1 = *(short *)(city + 0x00);
                short cy1 = *(short *)(city + 0x02);
                short cx2 = *(short *)(tgtCity + 0x00);
                short cy2 = *(short *)(tgtCity + 0x02);
                short sx1 = winRect.left + (cx1 - sViewportX) * TERRAIN_TILE_W + TERRAIN_TILE_W / 2;
                short sy1 = winRect.top  + (cy1 - sViewportY) * TERRAIN_TILE_H + TERRAIN_TILE_H / 2;
                short sx2 = winRect.left + (cx2 - sViewportX) * TERRAIN_TILE_W + TERRAIN_TILE_W / 2;
                short sy2 = winRect.top  + (cy2 - sViewportY) * TERRAIN_TILE_H + TERRAIN_TILE_H / 2;
                /* Only draw if at least one endpoint is visible */
                if ((sx1 >= winRect.left && sx1 < winRect.right - SCROLLBAR_W) ||
                    (sx2 >= winRect.left && sx2 < winRect.right - SCROLLBAR_W)) {
                    RGBColor vecColor = {0x8888, 0xFFFF, 0x8888};  /* light green */
                    short vi2, vSteps;
                    short vdx = sx2 - sx1, vdy = sy2 - sy1;
                    vSteps = ((vdx < 0 ? -vdx : vdx) + (vdy < 0 ? -vdy : vdy)) / 8;
                    if (vSteps < 3) vSteps = 3;
                    if (vSteps > 60) vSteps = 60;
                    RGBForeColor(&vecColor);
                    for (vi2 = 0; vi2 <= vSteps; vi2++) {
                        if (vi2 % 2 == 0) {
                            short px = sx1 + (vdx * vi2) / vSteps;
                            short py = sy1 + (vdy * vi2) / vSteps;
                            Rect dot;
                            SetRect(&dot, px - 1, py - 1, px + 1, py + 1);
                            PaintRect(&dot);
                        }
                    }
                    /* Arrow at target end */
                    {
                        Rect arrR;
                        SetRect(&arrR, sx2 - 3, sy2 - 3, sx2 + 3, sy2 + 3);
                        PaintOval(&arrR);
                    }
                }
            }
        }
    }

    /* --- Draw movement order lines for all owned armies with orders --- */
    if (hasScn) {
        short armyCount = *(short *)(scnData + 0x1602);
        short curP = *(short *)(scnData + 0x110);
        short ai4;
        if (armyCount > 100) armyCount = 100;
        for (ai4 = 0; ai4 < armyCount; ai4++) {
            unsigned char *a = scnData + 0x1604 + ai4 * 0x42;
            short aOwner = (short)(unsigned char)a[0x15];
            if (aOwner != curP) continue;
            if (a[0x16] == 0xFF) continue;
            if (ai4 == sSelectedArmy) continue;  /* already drawn above */
            if (*(short *)(a + 0x32) != 0) {
                short ax3 = *(short *)(a + 0x00);
                short ay3 = *(short *)(a + 0x02);
                short tx3 = *(short *)(a + 0x34);
                short ty3 = *(short *)(a + 0x36);
                short sx3 = winRect.left + (ax3 - sViewportX) * TERRAIN_TILE_W + TERRAIN_TILE_W / 2;
                short sy3 = winRect.top  + (ay3 - sViewportY) * TERRAIN_TILE_H + TERRAIN_TILE_H / 2;
                short tx3s = winRect.left + (tx3 - sViewportX) * TERRAIN_TILE_W + TERRAIN_TILE_W / 2;
                short ty3s = winRect.top  + (ty3 - sViewportY) * TERRAIN_TILE_H + TERRAIN_TILE_H / 2;
                if ((sx3 >= winRect.left && sx3 < winRect.right) ||
                    (tx3s >= winRect.left && tx3s < winRect.right)) {
                    RGBColor ordColor = {0x8888, 0x8888, 0xFFFF};  /* light blue */
                    short odx = tx3s - sx3, ody = ty3s - sy3;
                    short oSteps = ((odx < 0 ? -odx : odx) + (ody < 0 ? -ody : ody)) / 10;
                    short oi;
                    if (oSteps < 2) oSteps = 2;
                    if (oSteps > 40) oSteps = 40;
                    RGBForeColor(&ordColor);
                    for (oi = 0; oi <= oSteps; oi++) {
                        if (oi % 3 == 0) {
                            short px = sx3 + (odx * oi) / oSteps;
                            short py = sy3 + (ody * oi) / oSteps;
                            Rect dot;
                            SetRect(&dot, px, py, px + 2, py + 2);
                            PaintRect(&dot);
                        }
                    }
                }
            }
        }
    }

    /* --- Draw signpost markers on map --- */
    {
        short si;
        RGBColor spColor = {0xFFFF, 0xFFFF, 0x6666};
        RGBColor spBorder = {0x0000, 0x0000, 0x0000};
        TextFont(3);
        TextSize(9);
        TextFace(0);
        for (si = 0; si < sSignpostCount; si++) {
            if (!sSignposts[si].active) continue;
            {
                short sx = sSignposts[si].x;
                short sy = sSignposts[si].y;
                short screenX = winRect.left + (sx - sViewportX) * TERRAIN_TILE_W;
                short screenY = winRect.top  + (sy - sViewportY) * TERRAIN_TILE_H;
                if (screenX >= winRect.left - TERRAIN_TILE_W &&
                    screenX < winRect.right &&
                    screenY >= winRect.top - TERRAIN_TILE_H &&
                    screenY < winRect.bottom) {
                    /* Draw small flag icon */
                    Rect flagR;
                    SetRect(&flagR, screenX + TERRAIN_TILE_W - 10, screenY,
                            screenX + TERRAIN_TILE_W - 2, screenY + 8);
                    RGBForeColor(&spColor);
                    PaintRect(&flagR);
                    RGBForeColor(&spBorder);
                    FrameRect(&flagR);
                    /* Draw text label below */
                    if (sSignposts[si].text[0] != 0) {
                        Str255 pStr;
                        short tl;
                        for (tl = 0; tl < 31 && sSignposts[si].text[tl]; tl++)
                            pStr[tl + 1] = sSignposts[si].text[tl];
                        pStr[0] = (unsigned char)tl;
                        RGBForeColor(&spColor);
                        MoveTo(screenX + 2, screenY + TERRAIN_TILE_H + 8);
                        DrawString(pStr);
                    }
                }
            }
        }

        /* --- Draw SGN scenario signposts (map place-name labels) --- */
        {
            RGBColor sgnColor = {0xDDDD, 0xFFFF, 0xDDDD};  /* pale green */
            TextFont(3);
            TextSize(9);
            TextFace(italic);
            for (si = 0; si < sSgnSignpostCount; si++) {
                if (!sSgnSignposts[si].active) continue;
                {
                    short sx = sSgnSignposts[si].x;
                    short sy = sSgnSignposts[si].y;
                    short screenX = winRect.left + (sx - sViewportX) * TERRAIN_TILE_W;
                    short screenY = winRect.top  + (sy - sViewportY) * TERRAIN_TILE_H;
                    if (screenX >= winRect.left - TERRAIN_TILE_W &&
                        screenX < winRect.right &&
                        screenY >= winRect.top - TERRAIN_TILE_H &&
                        screenY < winRect.bottom) {
                        if (sSgnSignposts[si].text[0] != 0) {
                            Str255 pStr;
                            short tl;
                            for (tl = 0; tl < 31 && sSgnSignposts[si].text[tl]; tl++)
                                pStr[tl + 1] = sSgnSignposts[si].text[tl];
                            pStr[0] = (unsigned char)tl;
                            RGBForeColor(&sgnColor);
                            MoveTo(screenX + 2, screenY + TERRAIN_TILE_H - 2);
                            DrawString(pStr);
                        }
                    }
                }
            }
            TextFace(0);
        }
    }

    SetOrigin(0, 0);
    ClipRect(&win->portRect);

#if DEV_SHIP_PROBE
    {   /* DEV: which army is selected */
        char b[160]; Str255 ps; short n;
        RGBColor yel = {0xFFFF, 0xFFFF, 0}, blk = {0, 0, 0}, w = {0xFFFF, 0xFFFF, 0xFFFF};
        sprintf(b, "sel=%d n=%d", sSelectedArmy, hasScn ? *(short *)(scnData + 0x1602) : -1);
        if (hasScn) {   /* units, records and moving records per player */
            short pl, q, nn = *(short *)(scnData + 0x1602);
            char *o = b; short len = 0;
            while (o[len]) len++;
            for (pl = 0; pl < 8 && len < 140; pl++) {
                short u = 0, recs = 0, ord = 0, kk;
                for (q = 0; q < nn && q < 100; q++) {
                    unsigned char *qa = scnData + 0x1604 + q * 0x42;
                    if (qa[0x15] != pl || qa[0x16] == 0xFF) continue;
                    recs++; if (*(short *)(qa + 0x32)) ord++;
                    for (kk = 0; kk < 4; kk++) if (qa[0x16 + kk] != 0xFF) u++;
                }
                {   short pc = 0, tmr = -9, ci;
                    unsigned char *ex = *gExtState ? (unsigned char *)*gExtState : NULL;
                    for (ci = 0; ex && ci < sCityCount && ci < 99; ci++) {
                        unsigned char *c = sCityData + ci * 0x20, *e = ex + 0x24c + ci * 0x5c;
                        if (c[0x17] >= 2 || *(short *)(c + 4) != pl) continue;
                        if (*(short *)(e + 2) >= 0) pc++;
                        tmr = *(short *)(e + 0x58);
                    }
                    len += sprintf(o + len, " %d:%d/%d/%d p%d t%d", pl, u, recs, ord, pc, tmr);
                }
            }
        }
        if (hasScn) {   /* every army whose sprite is the ship */
            short q, nn = *(short *)(scnData + 0x1602), yy = 24;
            for (q = 0; q < nn && q < 100; q++) {
                unsigned char *qa = scnData + 0x1604 + q * 0x42;
                if (qa[0x14] == 5) {
                    char b2[64]; Str255 p2; short m;
                    sprintf(b2, "#%d o%d (%d,%d) t%d,%d,%d,%d nav%d", q, qa[0x15], *(short *)qa, *(short *)(qa + 2),
                            qa[0x16], qa[0x17], qa[0x18], qa[0x19], ArmyIsNaval(q));
                    for (m = 0; b2[m] && m < 60; m++) p2[m + 1] = b2[m];
                    p2[0] = (unsigned char)m;
                    TextFont(4); TextSize(9); TextMode(srcCopy);
                    { RGBColor y2 = {0xFFFF, 0xFFFF, 0}, k2 = {0, 0, 0}; RGBForeColor(&y2); RGBBackColor(&k2); }
                    MoveTo(4, yy); DrawString(p2); yy += 11;
                }
            }
        }
        for (n = 0; b[n] && n < 150; n++) ps[n + 1] = b[n];
        ps[0] = (unsigned char)n;
        TextFont(4); TextSize(9); TextMode(srcCopy);
        RGBForeColor(&yel); RGBBackColor(&blk);
        MoveTo(4, 12); DrawString(ps);
        TextMode(srcOr); RGBForeColor(&blk); RGBBackColor(&w);
    }
#endif
    if (bufGW != NULL) {                    /* copy the finished map to the window */
        RGBColor black = {0, 0, 0}, white = {0xFFFF, 0xFFFF, 0xFFFF};
        Rect mr = winRect;
        SetGWorld(bufSavePort, bufSaveDev);
        win = realWin;
        SetOrigin(0, 0);
        ClipRect(&win->portRect);
        RGBForeColor(&black); RGBBackColor(&white);
        CopyBits((BitMap *)*GetGWorldPixMap(bufGW), &((GrafPtr)win)->portBits, &mr, &mr, srcCopy, NULL);
        UnlockPixels(GetGWorldPixMap(bufGW));
    }

    /* --- Native Mac scrollbar controls --- */
    {
        /* Only update values, not position/size (those are set on create/resize) */
        if (sVScrollBar != NULL) {
            short maxV = sMapHeight > tilesHigh ? sMapHeight - tilesHigh : 0;
            SetControlMaximum(sVScrollBar, maxV);
            SetControlValue(sVScrollBar, sViewportY);
            Draw1Control(sVScrollBar);
        }
        if (sHScrollBar != NULL) {
            short maxH = sMapWidth > tilesWide ? sMapWidth - tilesWide : 0;
            SetControlMaximum(sHScrollBar, maxH);
            SetControlValue(sHScrollBar, sViewportX);
            /* Draw1Control(sHScrollBar) deferred: the bottom bar PaintRect
             * (drawn further down) would erase the scrollbar.  We call
             * Draw1Control after all bottom-bar painting is finished. */
        }

        /* Standard grow box in the corner (clipped so DrawGrowIcon's
         * scroll-bar lines don't cross the turn strip) */
        {
            Rect corner = win->portRect;
            corner.left = corner.right - SCROLLBAR_W;
            corner.top  = corner.bottom - SCROLLBAR_H;
            ClipRect(&corner);
            DrawGrowIcon(win);
            ClipRect(&win->portRect);
        }
    }

    {
        Rect mapClip = winRect;
        SetOrigin(sViewPixX, sViewPixY);
        OffsetRect(&mapClip, sViewPixX, sViewPixY);
        ClipRect(&mapClip);
    }
    /* --- (remake-only yellow dotted path and red X: the original draws rings
     *      and a ghost instead, see the path preview) --- */
    if (0 && sSelectedArmy >= 0 && hasScn && scnData != NULL) {
        unsigned char *selA = scnData + 0x1604 + sSelectedArmy * 0x42;
        if (*(short *)(selA + 0x32) != 0) {
            /* Army has movement orders — draw dotted path to target */
            short sx = *(short *)(selA + 0x00);
            short sy = *(short *)(selA + 0x02);
            short tx = *(short *)(selA + 0x34);
            short ty = *(short *)(selA + 0x36);
            short px = sx, py = sy;
            short step;
            RGBColor pathCol = {0xFFFF, 0xFFFF, 0x0000};  /* yellow */
            RGBForeColor(&pathCol);

            for (step = 0; step < 60; step++) {
                short ddx = tx - px, ddy = ty - py;
                short stX = 0, stY = 0;
                short drawX, drawY;
                if (ddx > 0) stX = 1; else if (ddx < 0) stX = -1;
                if (ddy > 0) stY = 1; else if (ddy < 0) stY = -1;
                if (stX == 0 && stY == 0) break;
                px += stX;
                py += stY;

                /* Convert tile to screen coords */
                drawX = (px - sViewportX) * TERRAIN_TILE_W + TERRAIN_TILE_W / 2;
                drawY = (py - sViewportY) * TERRAIN_TILE_H + TERRAIN_TILE_H / 2;
                if (drawX < 0 || drawY < 0) continue;
                if (drawX >= win->portRect.right - SCROLLBAR_W) continue;
                if (drawY >= win->portRect.bottom - SCROLLBAR_H) continue;

                /* Draw small dot every tile (alternating for dashes) */
                if (step % 2 == 0) {
                    Rect dot;
                    SetRect(&dot, drawX - 1, drawY - 1, drawX + 2, drawY + 2);
                    PaintRect(&dot);
                }
            }

            /* Draw target marker (X) at destination */
            {
                short dX = (tx - sViewportX) * TERRAIN_TILE_W + TERRAIN_TILE_W / 2;
                short dY = (ty - sViewportY) * TERRAIN_TILE_H + TERRAIN_TILE_H / 2;
                if (dX > 0 && dY > 0 &&
                    dX < win->portRect.right - SCROLLBAR_W &&
                    dY < win->portRect.bottom - SCROLLBAR_H) {
                    RGBColor red = {0xFFFF, 0x3333, 0x3333};
                    RGBForeColor(&red);
                    PenSize(2, 2);
                    MoveTo(dX - 4, dY - 4); LineTo(dX + 4, dY + 4);
                    MoveTo(dX + 4, dY - 4); LineTo(dX - 4, dY + 4);
                    PenSize(1, 1);
                }
            }
        }
    }

    SetOrigin(0, 0);
    ClipRect(&win->portRect);

    /* --- Turn strip (TTurnView) left of the h scroll bar ---
     * Measured on the original (o_map2.png, local coords): white strip
     * x 0..TURN_VIEW_W, black top line at the map's bottom edge; "Turn N" in
     * Chicago 12; shields in turn order (gs+0x164) at x 67+16*slot, y+2;
     * the current player's slot sits in a black box 3px wider each side. */
    if (hasScn && scnData != NULL) {
        Rect fullPort = win->portRect;
        short factionCount = *(short *)(scnData + 0x10C);
        short curPlayer = *(short *)(scnData + 0x110);
        short turn = *(short *)(scnData + 0x136);
        short top = fullPort.bottom - SCROLLBAR_H;      /* black line row */
        short slotIdx, aliveSlot = 0;
        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
        RGBColor black = {0x0000, 0x0000, 0x0000};
        Rect strip;
        Str255 numStr;

        if (factionCount < 1) factionCount = 1;
        if (factionCount > 8) factionCount = 8;

        SetRect(&strip, fullPort.left, top + 1, fullPort.left + TURN_VIEW_W, fullPort.bottom);
        RGBForeColor(&white);
        PaintRect(&strip);
        RGBForeColor(&black);
        MoveTo(fullPort.left, top);
        LineTo(fullPort.left + TURN_VIEW_W - 1, top);

        TextFont(0);
        TextSize(12);
        TextFace(0);
        MoveTo(fullPort.left + TURN_TEXT_X, top + 11);
        DrawString(GetCachedString(STR_MISC, 12, "\pTurn "));
        NumToString((long)turn, numStr);
        DrawString(numStr);

        for (slotIdx = 0; slotIdx < factionCount; slotIdx++) {
            short factionIdx = *(short *)(scnData + 0x164 + slotIdx * 2);
            short sx;
            Rect sR;
            if (factionIdx < 0 || factionIdx >= 8) continue;
            if (*(short *)(scnData + 0x138 + factionIdx * 2) == 0) continue;
            sx = fullPort.left + 67 + aliveSlot * SHIELD_SLOT_W;
            if (factionIdx == curPlayer) {
                Rect bR;
                SetRect(&bR, sx - 3, top + 1, sx + SHIELD_ICON_W + 3, fullPort.bottom);
                RGBForeColor(&black);
                PaintRect(&bR);
            }
            SetRect(&sR, sx, top + 2, sx + SHIELD_ICON_W, top + 2 + SHIELD_ICON_H);
            if (sShieldsLoaded && (sShieldIcons[factionIdx] != NULL || sShieldSmallGW != NULL)) {
                DrawSmallShieldIcon(factionIdx, &sR);
            } else {
                RGBForeColor(&sPlayerColors[factionIdx + 1]);
                PaintRect(&sR);
            }
            aliveSlot++;
        }
        RGBForeColor(&black);
    }

    /* --- Horizontal scrollbar drawn LAST so bottom bar PaintRect doesn't erase it --- */
    if (sHScrollBar != NULL) {
        Draw1Control(sHScrollBar);
    }
}


/* ===================================================================
 * Overview map (TOverviewView), 2px per tile.
 *
 * The base image is built once per map like the original's PPC
 * FUN_10063af8 (CODE_128 only copies it and draws the overlays): PICT 1012
 * (ocean gradient) in a 224x312 8-bit GWorld on the game CLUT, then each
 * tile's four pixels from MAPCOLOR (terrain DAT 30020):
 *   +0     4 x 256 bytes, one table per quadrant (TL, TR, BL, BR)
 *   +1024  remap, 16 little-endian shorts (identity here)
 *   +1120  4 x 20 bytes for road tiles (RD & 0x1F, 1-based)
 * Values are pltt 1000 indices; 5 (water) is left out so the gradient shows.
 * Hill/mountain sprites 80..95 take their pixels from a pool of 256 values
 * 2..4 rolled up front; the 4th read can land one past the pool (white).
 * Validated against the original on Erythea: 100% of uncovered pixels.
 * =================================================================== */
static GWorldPtr sOverviewBaseGW = NULL;

static void BuildOverviewBase(void)
{
    unsigned char pool[257];
    long seed = 0x2AA0D649;      /* QuickDraw randSeed the hill pool was rolled
                                    from on the reference (Erythea) run */
    Rect b;
    PixMapHandle pm;
    unsigned char *base, *mapData, *rdData;
    long rb;
    short x, y, i, c = 0;
    CGrafPtr sp; GDHandle sd;

    if (*gMapTiles == 0) return;
    mapData = (unsigned char *)*gMapTiles;
    rdData = (*gRoadData != 0) ? (unsigned char *)*gRoadData : NULL;

    for (i = 0; i < 256; i++) {
        short r;
        long v;
        seed = (long)(((unsigned long long)seed * 16807ULL) % 0x7FFFFFFFUL);
        r = (short)(seed & 0xFFFF);
        if (r == -32768) r = 0;
        v = ((long)(r < 0 ? -r : r) * 3) / 32768 + 1 + 1;   /* RandomRange(1,3,1) */
        pool[i] = (unsigned char)(v < 2 ? 2 : v > 4 ? 4 : v);
    }
    pool[256] = 0;

    if (sOverviewBaseGW != NULL) { DisposeGWorld(sOverviewBaseGW); sOverviewBaseGW = NULL; }
    SetRect(&b, 0, 0, sMapWidth * 2, sMapHeight * 2);
    {
        /* Own copy of the game CLUT: the GWorld keeps the handle it is given
         * and disposing the GWorld on a rebuild must not free sGameCTab. */
        Handle ct = (Handle)sGameCTab;
        if (ct == NULL || HandToHand(&ct) != noErr) ct = NULL;
        if (NewGWorld(&sOverviewBaseGW, 8, &b, (CTabHandle)ct, NULL, 0) != noErr ||
            sOverviewBaseGW == NULL) {
            sOverviewBaseGW = NULL;
            return;
        }
    }
    pm = GetGWorldPixMap(sOverviewBaseGW);
    LockPixels(pm);
    GetGWorld(&sp, &sd);
    SetGWorld(sOverviewBaseGW, NULL);
    {
        PicHandle ocean = GetPicture(1012);
        if (ocean != NULL) DrawPicture(ocean, &b);
        else EraseRect(&b);
    }
    SetGWorld(sp, sd);

    base = (unsigned char *)GetPixBaseAddr(pm);
    rb = (**pm).rowBytes & 0x3FFF;
    for (y = 0; y < sMapHeight; y++) {
        for (x = 0; x < sMapWidth; x++) {
            short rd = rdData ? (rdData[y * 112 + x] & 0x1F) : 0;
            short idx = rd ? rd - 1 : mapData[y * 0xE0 + x * 2];
            Boolean hill = (!rd && idx >= 80 && idx <= 95);
            short q;
            for (q = 0; q < 4; q++) {
                unsigned char col;
                if (hill) {
                    col = pool[c + q + 1];
                } else if (sMapColorFullLoaded) {
                    col = rd ? sMapColorFull[1120 + q * 20 + idx] : sMapColorFull[q * 256 + idx];
                    if (col < 16) col = sMapColorFull[1024 + col * 2];   /* little-endian shorts */
                    if (!rd && col == 5) continue;            /* water: keep gradient */
                    /* pltt 1000 #15 is an explicit (pmExplicit) magenta placeholder:
                     * on screen it is device entry 15, white (city window minimap) */
                    if (col == 15) col = 0;
                } else {
                    continue;
                }
                base[(long)(y * 2 + (q >> 1)) * rb + x * 2 + (q & 1)] = col;
            }
            if (hill && (c += 4) > 255) c = 0;
        }
    }
    UnlockPixels(pm);
    sOverviewBaseFor = (Ptr)*gMapTiles;
}


static void DrawOverviewInWindow(WindowPtr win)
{
    DrawOverviewTo((GrafPtr)win, win->portRect, kOvFrame | kOvOverlays);
}

static void DrawOverviewTo(GrafPtr port, Rect r, short flags)
{
    Boolean viewFrame = (flags & kOvFrame) != 0;
    if (!sMapLoaded || *gMapTiles == 0)
        return;

    SetGWorld((CGrafPtr)port, GetMainDevice());

    if (sOverviewBaseGW == NULL || sOverviewBaseFor != (Ptr)*gMapTiles)
        BuildOverviewBase();
    if (sOverviewBaseGW != NULL) {
        PixMapHandle opm = GetGWorldPixMap(sOverviewBaseGW);
        RGBColor black = {0, 0, 0}, white = {0xFFFF, 0xFFFF, 0xFFFF};
        Rect srcR;
        RGBForeColor(&black); RGBBackColor(&white);
        if (LockPixels(opm)) {
            srcR = (**opm).bounds;
            OffsetRect(&srcR, r.left - srcR.left, r.top - srcR.top);
            CopyBits((BitMap *)*opm, &port->portBits, &(**opm).bounds, &srcR, srcCopy, NULL);
            UnlockPixels(opm);
        }
    }

    if (flags & kOvOverlays) {
        short scale = 2;

        /* Fog of war overlay on minimap */
        if (*gGameState != 0 && *(short *)((unsigned char *)*gGameState + 0x116) != 0) {
            unsigned char *gs2 = (unsigned char *)*gGameState;
            short curP = *(short *)(gs2 + 0x110);
            if (curP >= 0 && curP < 8) {
                RGBColor fogBlack = {0, 0, 0};
                RGBColor fogDim = {0x3333, 0x3333, 0x3333};
                short fx, fy;
                for (fy = 0; fy < sMapHeight; fy++) {
                    for (fx = 0; fx < sMapWidth; fx++) {
                        if (!FogGetBit(sFogExplored[curP], fx, fy)) {
                            /* Unexplored: solid black */
                            RGBForeColor(&fogBlack);
                            if (scale == 1) {
                                MoveTo(r.left + fx, r.top + fy);
                                LineTo(r.left + fx, r.top + fy);
                            } else {
                                Rect fpx;
                                SetRect(&fpx, r.left + fx * scale, r.top + fy * scale,
                                             r.left + fx * scale + scale, r.top + fy * scale + scale);
                                PaintRect(&fpx);
                            }
                        } else if (!FogGetBit(sFogVisible[curP], fx, fy)) {
                            /* Explored but not visible: dimmed */
                            RGBForeColor(&fogDim);
                            PenMode(subOver);
                            if (scale == 1) {
                                MoveTo(r.left + fx, r.top + fy);
                                LineTo(r.left + fx, r.top + fy);
                            } else {
                                Rect fpx;
                                SetRect(&fpx, r.left + fx * scale, r.top + fy * scale,
                                             r.left + fx * scale + scale, r.top + fy * scale + scale);
                                PaintRect(&fpx);
                            }
                            PenMode(srcCopy);
                        }
                    }
                }
            }
        }

        /* Draw army dots on minimap (drawn first, cities go on top).
         * Off: the original's overview showed no marker even for the human's
         * hero outside a city (turn 2, Erythea); kept for the remake's
         * debug overlays. */
        if (*gGameState != 0 && sShowCityLabels) {
            unsigned char *gs2 = (unsigned char *)*gGameState;
            short armyCount = *(short *)(gs2 + 0x1602);
            short ai;
            RGBColor black2 = {0, 0, 0};
            if (armyCount < 0) armyCount = 0;
            if (armyCount > 100) armyCount = 100;

            for (ai = 0; ai < armyCount; ai++) {
                unsigned char *army = gs2 + 0x1604 + ai * 0x42;
                short ax = *(short *)(army + 0x00);
                short ay = *(short *)(army + 0x02);
                short aOwner = (short)(unsigned char)army[0x15];
                short colorIdx = (aOwner >= 0 && aOwner < 8) ? aOwner + 1 : 8;

                if (army[0x16] == 0xFF) continue;
                if (ax >= 0 && ax < sMapWidth && ay >= 0 && ay < sMapHeight) {
                    /* Fog of war: hide enemy armies on minimap */
                    if (*(short *)(gs2 + 0x116) != 0) {
                        short curP = *(short *)(gs2 + 0x110);
                        if (curP >= 0 && curP < 8 && aOwner != curP &&
                            !FogGetBit(sFogVisible[curP], ax, ay))
                            continue;
                    }
                    /* Armies inside a city are covered by its shield in the
                     * original; the remake's marker peeked out as a dark
                     * shadow on the top/left of the grey shields. */
                    {
                        short cc, ncity = sCityCount > 139 ? 139 : sCityCount;
                        Boolean inCity = false;
                        for (cc = 0; cc < ncity && !inCity; cc++) {
                            unsigned char *ct = sCityData + cc * 0x20;
                            short ddx = ax - *(short *)(ct + 0), ddy = ay - *(short *)(ct + 2);
                            if (ct[0x17] < 2 && ddx >= 0 && ddx <= 1 && ddy >= 0 && ddy <= 1) inCity = true;
                        }
                        if (inCity) continue;
                    }
                    /* Colored dot for army position (68k CODE_128: 7px wide, from -2 to +5) */
                    Rect px;
                    SetRect(&px, r.left + ax * scale - 2, r.top + ay * scale - 2,
                                 r.left + ax * scale + 5, r.top + ay * scale + 5);
                    RGBForeColor(&black2);
                    PaintRect(&px);
                    InsetRect(&px, 1, 1);
                    RGBForeColor(&sPlayerColors[colorIdx]);
                    PaintRect(&px);
                }
            }
        }

        /* Draw city shields on minimap ON TOP of army dots.
         * CopyBits from PICT 30010 (sMasterSpriteGW):
         *   Grey shield:    (131, 54, 139, 62) for neutral
         *   Colored shields: (faction*16+7, 86, faction*16+15, 94) for factions
         * Uses mode 36 (transparent) with sMasterSpriteBgColor as key. */
        if (*gGameState != 0 && sMasterSpriteGW != NULL) {
            unsigned char *gs2 = (unsigned char *)*gGameState;
            PixMapHandle pm = GetGWorldPixMap(sMasterSpriteGW);
            short cityCount = sCityCount;
            short ci;
            if (cityCount > 139) cityCount = 139;

            if (LockPixels(pm)) {
                RGBColor savedBg;
                GetBackColor(&savedBg);
                RGBBackColor(&sMasterSpriteBgColor);

                for (ci = 0; ci < cityCount; ci++) {
                    unsigned char *city = sCityData + ci * 0x20;
                    short cx = *(short *)(city + 0x00);
                    short cy = *(short *)(city + 0x02);
                    short owner = *(short *)(city + 0x04);
                    short siteType = (short)(unsigned char)city[0x17];

                    if (cx >= 0 && cx < sMapWidth && cy >= 0 && cy < sMapHeight) {
                        /* Fog of war: hide unexplored cities on minimap */
                        if (*(short *)(gs2 + 0x116) != 0) {
                            short curP = *(short *)(gs2 + 0x110);
                            if (curP >= 0 && curP < 8 &&
                                !FogGetBit(sFogExplored[curP], cx, cy))
                                continue;
                        }
                        if (siteType >= 2) {
                            /* Ruins/temples: 2x2 white at the site's tile
                             * (Erythea "The Old Cave" 89,20 -> 178,40) */
                            RGBColor ruinCol = {0xFFFF, 0xFFFF, 0xFFFF};
                            Rect dot;
                            SetRect(&dot, r.left + cx * scale, r.top + cy * scale,
                                    r.left + cx * scale + 2, r.top + cy * scale + 2);
                            RGBForeColor(&ruinCol);
                            PaintRect(&dot);
                        } else {
                            /* City: shield sprite from PICT 30010 */
                            Rect srcR, dstR;
                            if (owner >= 0 && owner < 8) {
                                SetRect(&srcR, owner * 16 + 7, 86,
                                               owner * 16 + 15, 94);
                            } else {
                                SetRect(&srcR, 131, 54, 139, 62);
                            }
                            /* CODE_128 FUN_00000d96: 8x8 at (2x-1, 2y-1) */
                            SetRect(&dstR,
                                    r.left + cx * scale - 1,
                                    r.top  + cy * scale - 1,
                                    r.left + cx * scale + 7,
                                    r.top  + cy * scale + 7);
                            CopyBits((BitMap *)*pm,
                                     &port->portBits,
                                     &srcR, &dstR, 36, NULL);
                        }
                    }
                }

                RGBBackColor(&savedBg);
                UnlockPixels(pm);
            }
        }

        /* Highlight selected army with crosshair */
        if (*gGameState != 0) {
            unsigned char *gs2 = (unsigned char *)*gGameState;
            short armyCount = *(short *)(gs2 + 0x1602);
            if (sSelectedArmy >= 0 && sSelectedArmy < armyCount) {
                unsigned char *selA = gs2 + 0x1604 + sSelectedArmy * 0x42;
                short sx = *(short *)(selA + 0x00);
                short sy = *(short *)(selA + 0x02);
                if (sx >= 0 && sx < sMapWidth && sy >= 0 && sy < sMapHeight) {
                    RGBColor yellow = {0xFFFF, 0xFFFF, 0x0000};
                    short cx2 = r.left + sx * scale + scale / 2;
                    short cy2 = r.top + sy * scale + scale / 2;
                    RGBForeColor(&yellow);
                    /* Crosshair lines */
                    MoveTo(cx2 - 4, cy2);
                    LineTo(cx2 - 2, cy2);
                    MoveTo(cx2 + 2, cy2);
                    LineTo(cx2 + 4, cy2);
                    MoveTo(cx2, cy2 - 4);
                    LineTo(cx2, cy2 - 2);
                    MoveTo(cx2, cy2 + 2);
                    LineTo(cx2, cy2 + 4);
                }
            }
        }

        /* Viewport: 2px white frame around the visible map, measured on the
         * original: inner (px/20, py/20, ceil((px+W)/20)+1, ceil((py+H)/20)+1)
         * in map pixels (origin 3072,0 view 776x710 -> outer 151..196 x ..39) */
        if (viewFrame && gMainGameWindow != NULL && *gMainGameWindow != 0) {
            Rect p = ((WindowPtr)*gMainGameWindow)->portRect, vr;
            long vw = p.right - p.left - SCROLLBAR_W, vh = p.bottom - p.top - SCROLLBAR_H;
            long px = (long)sViewportX * TERRAIN_TILE_W + sViewPixX;
            long py = (long)sViewportY * TERRAIN_TILE_H + sViewPixY;
            RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
            SetRect(&vr, r.left + (short)(px / 20), r.top + (short)(py / 20),
                    r.left + (short)((px + vw + 19) / 20) + 1, r.top + (short)((py + vh + 19) / 20) + 1);
            InsetRect(&vr, -2, -2);
            RGBForeColor(&white);
            PenSize(2, 2);
            FrameRect(&vr);
            PenSize(1, 1);
        }
    }
}


/* ===================================================================
 * DrawMinimapInRect — draw a small overview map into any port rect
 *
 * Used by dialogs (hero hire, hero inspect, city info, etc.)
 * to show a minimap inset with an optional highlight marker.
 * highlightX/Y = -1 means no highlight.
 * =================================================================== */
static void DrawMinimapInRect(Rect *destRect, short highlightX, short highlightY)
{
    unsigned char *mapData;
    short x, y;

    if (!sMapLoaded || *gMapTiles == 0)
        return;

    mapData = (unsigned char *)*gMapTiles;

    /* Black background */
    {
        RGBColor bg = {0x0000, 0x0000, 0x3333};
        RGBForeColor(&bg);
        PaintRect(destRect);
    }

    /* 1 pixel per tile, clipped to destRect */
    {
        unsigned char *scnData = (*gGameState != 0) ? (unsigned char *)*gGameState : NULL;
        short destW = destRect->right - destRect->left;
        short destH = destRect->bottom - destRect->top;

        /* Fog check: if hidden map enabled, unexplored tiles rendered darker */
        { short curP = (scnData != NULL) ? *(short *)(scnData + 0x110) : -1;
          Boolean fogActive = (scnData != NULL && *(short *)(scnData + 0x116) != 0 &&
                               curP >= 0 && curP < 8);
          for (y = 0; y < sMapHeight && y < destH; y++) {
            for (x = 0; x < sMapWidth && x < destW; x++) {
                unsigned short tileOffset = y * 0xE0 + x * 2;
                unsigned char terrainIdx = mapData[tileOffset];
                Boolean explored = true;

                if (fogActive && !FogGetBit(sFogExplored[curP], x, y))
                    explored = false;

                if (!explored) {
                    /* Unexplored: dark blue */
                    RGBColor fogCol = {0x0000, 0x0000, 0x2222};
                    RGBForeColor(&fogCol);
                } else if (sMapColorLoaded && terrainIdx < MAPCOLOR_SIZE) {
                    short colorIdx = (short)sMapColor[terrainIdx];
                    if (colorIdx >= MINIMAP_PAL_SIZE) colorIdx = 0;
                    RGBForeColor(&sMinimapPalette[colorIdx]);
                } else if (scnData != NULL) {
                    short terrainType = (short)(unsigned char)scnData[terrainIdx + TERRAIN_TYPE_OFS];
                    if (terrainType >= NUM_TERRAIN_COLORS) terrainType = 0;
                    RGBForeColor(&sTerrainColors[terrainType]);
                } else {
                    RGBForeColor(&sMinimapPalette[10]);
                }
                MoveTo(destRect->left + x, destRect->top + y);
                LineTo(destRect->left + x, destRect->top + y);
            }
          }
        }

        /* City dots / shields */
        if (*gGameState != 0) {
            unsigned char *gs2 = (unsigned char *)*gGameState;
            short cityCount = sCityCount;
            short ci;
            short curP2 = *(short *)(gs2 + 0x110);
            Boolean fogActive2 = (*(short *)(gs2 + 0x116) != 0 && curP2 >= 0 && curP2 < 8);
            if (cityCount > 139) cityCount = 139;
            for (ci = 0; ci < cityCount; ci++) {
                unsigned char *city = sCityData +ci * 0x20;
                short cx = *(short *)(city + 0x00);
                short cy = *(short *)(city + 0x02);
                short owner = *(short *)(city + 0x04);
                short sType = (short)(unsigned char)city[0x17];
                /* Fog of war: skip cities in unexplored areas */
                if (fogActive2 && !FogGetBit(sFogExplored[curP2], cx, cy))
                    continue;
                if (cx >= 0 && cx < destW && cy >= 0 && cy < destH) {
                    if (sType >= 2) {
                        /* Ruins/temples: bright dot */
                        RGBColor ruinCol = (sType == 2) ?
                            (RGBColor){0xFFFF, 0xDDDD, 0x3333} :
                            (RGBColor){0xDDDD, 0xDDDD, 0xAAAA};
                        Rect dot;
                        SetRect(&dot, destRect->left + cx - 1, destRect->top + cy - 1,
                                destRect->left + cx + 2, destRect->top + cy + 2);
                        RGBForeColor(&ruinCol);
                        PaintRect(&dot);
                    } else {
                        /* City: colored dot (3x3) */
                        short colorIdx = (owner >= 0 && owner < 8) ? owner + 1 : 8;
                        Rect dot;
                        SetRect(&dot, destRect->left + cx - 1, destRect->top + cy - 1,
                                destRect->left + cx + 2, destRect->top + cy + 2);
                        RGBForeColor(&sPlayerColors[colorIdx]);
                        PaintRect(&dot);
                    }
                }
            }
        }

        /* Highlight marker (crosshair) */
        if (highlightX >= 0 && highlightY >= 0 &&
            highlightX < destW && highlightY < destH) {
            RGBColor yellow = {0xFFFF, 0xFFFF, 0x0000};
            short px = destRect->left + highlightX;
            short py = destRect->top + highlightY;
            RGBForeColor(&yellow);
            MoveTo(px - 5, py); LineTo(px - 2, py);
            MoveTo(px + 2, py); LineTo(px + 5, py);
            MoveTo(px, py - 5); LineTo(px, py - 2);
            MoveTo(px, py + 2); LineTo(px, py + 5);
        }

        /* Border */
        {
            RGBColor border = {0x6666, 0x6666, 0x6666};
            RGBForeColor(&border);
            FrameRect(destRect);
        }
    }
}


/* ===================================================================
 * ToggleMinimapZoom — cycle through 3 minimap zoom levels
 *
 * Small:  124x160, 1px/tile (default)
 * Medium: 180x220, 2px/tile
 * Large:  240x300, 2px/tile (more map visible)
 * =================================================================== */
static void ToggleMinimapZoom(void)
{
    WindowPtr overWin, infoWin;

    if (*gOverviewWindow == 0 || *gInfoWindow == 0)
        return;

    /* Get current overview window position for reference */
    overWin = (WindowPtr)*gOverviewWindow;
    infoWin = (WindowPtr)*gInfoWindow;

    sMinimapZoom = (sMinimapZoom + 1) % 3;

    {
        short newW, newH, infoTop;

        if (sMinimapZoom == 0) {
            /* Small: 2px/tile (drawing always uses 2), compact window */
            newW = sMapWidth * 2;
            newH = sMapHeight * 2;
            if (newW < 124) newW = 124;
            if (newH < 100) newH = 100;
            if (newW > 240) newW = 240;
            if (newH > 200) newH = 200;
        } else if (sMinimapZoom == 1) {
            /* Medium: 2px/tile, sized to fit map */
            newW = sMapWidth * 2;
            newH = sMapHeight * 2;
            if (newW > 300) newW = 300;
            if (newH > 350) newH = 350;
        } else {
            /* Large: sized to show entire map at 2px/tile */
            newW = sMapWidth * 2;
            newH = sMapHeight * 2;
            if (newW < 240) newW = 240;
            if (newH < 300) newH = 300;
            if (newW > 500) newW = 500;
            if (newH > 680) newH = 680;
        }

        SizeWindow(overWin, newW, newH, true);

        /* Info panel goes below minimap, moderate height */
        infoTop = 40 + newH + 2;
        MoveWindow(infoWin, 514, infoTop, false);
        SizeWindow(infoWin, newW, 160, true);
    }

    /* Force redraw of both windows */
    SetPort(overWin);
    InvalRect(&overWin->portRect);
    SetPort(infoWin);
    InvalRect(&infoWin->portRect);
}


/* ===================================================================
 * ShowHeroHire — Modal hero hire dialog
 *
 * Displays a hero offer with portrait (PICT 3200), name, stats,
 * and Hire / Don't Hire buttons.  Called at start of each human turn.
 * Returns true if the player hired the hero.
 *
 * Hero generation: random name from built-in list, stats scaled by
 * difficulty.  On hire, deducts gold and creates an army record.
 * =================================================================== */

/* ===================================================================
 * ShowSiteInfo — Modal dialog for ruins, temples, and other sites
 *
 * Shows site name and type. Uses PICT 4100 for ruins (crumbling castle)
 * and PICT 4101 for temples (classical temple columns).
 * =================================================================== */
static void ShowSiteInfo(short siteIndex)
{
    WindowPtr  siteWin;
    GWorldPtr  siteGW = NULL;
    Rect       winRect, gwRect, btnR;
    Boolean    done = false;
    unsigned char *site;
    short      siteType, siteX, siteY;
    Str255     siteName;
    short      winW = 460, winH = 340;
    short      panelX = 230;

    if (siteIndex < 0 || siteIndex >= sCityCount) return;
    if (*gGameState == 0) return;

    site = sCityData + siteIndex * 0x20;
    siteType = (short)(unsigned char)site[0x17];
    siteX = *(short *)(site + 0x00);
    siteY = *(short *)(site + 0x02);

    /* Get site name from gs+0x811 ruin records */
    {
        short ri, ruinOrd = 0;
        Boolean foundName = false;
        for (ri = 0; ri < siteIndex; ri++) {
            if ((unsigned char)(sCityData + ri * 0x20)[0x17] >= 2)
                ruinOrd++;
        }
        if (ruinOrd < 40) {
            unsigned char *rec = (unsigned char *)*gGameState + 0x811 + ruinOrd * 0x1F;
            unsigned char *nm = rec + 0x04;
            short ni;
            siteName[0] = 0;
            for (ni = 0; ni < 20 && nm[ni] != 0; ni++) {
                siteName[ni + 1] = nm[ni];
                siteName[0]++;
            }
            foundName = true;
        }
        if (!foundName) {
            siteName[0] = 4;
            siteName[1] = 'S'; siteName[2] = 'i'; siteName[3] = 't'; siteName[4] = 'e';
        }
    }

    /* Centered 460x340 dialog */
    {
        Rect screen = qd.screenBits.bounds;
        short sw = screen.right - screen.left;
        short sh = screen.bottom - screen.top;
        short dl = (sw - winW) / 2;
        short dt = (sh - winH) / 2;
        if (dt < 20) dt = 20;
        SetRect(&winRect, dl, dt, dl + winW, dt + winH);
    }

    siteWin = NewCWindow(NULL, &winRect, "\p", true,
                         dBoxProc, (WindowPtr)-1L, false, 0);
    if (siteWin == NULL) return;

    if (*gMainGameWindow != 0) {
        PaletteHandle gamePal = GetPalette((WindowPtr)*gMainGameWindow);
        if (gamePal != NULL)
            SetPalette(siteWin, gamePal, false);
    }

    SetRect(&gwRect, 0, 0, winW, winH);
    if (NewGWorld(&siteGW, 0, &gwRect, NULL, NULL, 0) != noErr || siteGW == NULL) {
        DisposeWindow(siteWin);
        return;
    }

    /* Done button rect */
    SetRect(&btnR, winW - 60, winH - 32, winW - 8, winH - 8);

    {
        CGrafPtr savePort; GDHandle saveGD;
        unsigned char *gs = (unsigned char *)*gGameState;
        short curPlayer = *(short *)(gs + 0x110);

        GetGWorld(&savePort, &saveGD);
        SetGWorld(siteGW, NULL);
        LockPixels(GetGWorldPixMap(siteGW));

        /* LEFT PANEL: marble + minimap */
        {
            Rect leftPanel;
            SetRect(&leftPanel, 0, 0, panelX, winH);
            DrawMarbleBackground(&leftPanel);
            if (sMapLoaded && *gMapTiles != 0 && sMapWidth > 0 && sMapHeight > 0) {
                unsigned char *mapData = (unsigned char *)*gMapTiles;
                short scaleX = panelX / sMapWidth;
                short scale  = (scaleX > 1) ? scaleX : 1;
                short mmW = sMapWidth * scale;
                short mmH = sMapHeight * scale;
                short mmX = (panelX - mmW) / 2;
                short mmY = (winH - mmH) / 2;
                short mx, my;
                for (my = 0; my < sMapHeight; my++) {
                    for (mx = 0; mx < sMapWidth; mx++) {
                        unsigned short tileOffset = my * 0xE0 + mx * 2;
                        unsigned char terrainIdx = mapData[tileOffset];
                        Rect tileR;
                        SetRect(&tileR,
                            mmX + mx * scale, mmY + my * scale,
                            mmX + mx * scale + scale, mmY + my * scale + scale);
                        if (sMapColorLoaded && terrainIdx < MAPCOLOR_SIZE) {
                            short colorIdx = (short)sMapColor[terrainIdx];
                            if (colorIdx >= MINIMAP_PAL_SIZE) colorIdx = 0;
                            RGBForeColor(&sMinimapPalette[colorIdx]);
                        } else {
                            short terrainType = (short)(unsigned char)gs[terrainIdx + TERRAIN_TYPE_OFS];
                            if (terrainType >= NUM_TERRAIN_COLORS) terrainType = 0;
                            RGBForeColor(&sTerrainColors[terrainType]);
                        }
                        PaintRect(&tileR);
                    }
                }
                /* City/site icons on minimap */
                {
                    short ci2, cc2 = sCityCount;
                    if (cc2 > 139) cc2 = 139;
                    for (ci2 = 0; ci2 < cc2; ci2++) {
                        unsigned char *c2 = sCityData + ci2 * 0x20;
                        short cx2 = *(short *)(c2 + 0x00);
                        short cy2 = *(short *)(c2 + 0x02);
                        short st = (short)(unsigned char)c2[0x17];
                        if (st >= 2) {
                            RGBColor ruinGray = {0x9999, 0x9999, 0x7777};
                            Rect rdot;
                            SetRect(&rdot, mmX+cx2*scale, mmY+cy2*scale,
                                           mmX+cx2*scale+3, mmY+cy2*scale+3);
                            RGBForeColor(&ruinGray);
                            PaintRect(&rdot);
                        } else {
                            Rect shR2;
                            SetRect(&shR2,
                                    mmX + cx2 * scale - 3, mmY + cy2 * scale - 3,
                                    mmX + cx2 * scale + 5, mmY + cy2 * scale + 5);
                            DrawMinimapShield(&shR2);
                        }
                    }
                }
                /* Highlight current site */
                {
                    Rect selR;
                    SetRect(&selR,
                            mmX + siteX * scale - 4, mmY + siteY * scale - 4,
                            mmX + siteX * scale + 6, mmY + siteY * scale + 6);
                    DrawMinimapSelectionShield(&selR);
                }
            }
        }

        /* RIGHT PANEL: marble background */
        {
            Rect rightR;
            SetRect(&rightR, panelX, 0, winW, winH);
            DrawMarbleBackground(&rightR);
        }

        /* Site name in gold, centered in right panel */
        {
            RGBColor gold = {0xFFFF, 0xDDDD, 0x4444};
            short tw;
            RGBForeColor(&gold);
            TextFont(2); TextSize(18); TextFace(bold);
            tw = StringWidth(siteName);
            MoveTo(panelX + ((winW - panelX) - tw) / 2, 28);
            DrawString(siteName);
            TextFace(0);
        }

        /* Illustration PICT (4100=ruin, 4101=temple) */
        {
            PicHandle illPic = GetPicture(siteType == 2 ? 4101 : 4100);
            Rect picDst;
            SetRect(&picDst, panelX + 10, 42, panelX + 160, 150);
            if (illPic != NULL) {
                HLock((Handle)illPic);
                DrawPicture(illPic, &picDst);
                HUnlock((Handle)illPic);
            } else {
                RGBColor dk = {0x2222, 0x2222, 0x2222};
                RGBForeColor(&dk);
                PaintRect(&picDst);
            }
            /* Dark border around illustration */
            {
                RGBColor bdr = {0x3333, 0x3333, 0x3333};
                RGBForeColor(&bdr);
                PenSize(2, 2);
                FrameRect(&picDst);
                PenSize(1, 1);
            }
        }

        /* Type and Explored status next to illustration */
        {
            const char *tl;
            Boolean explored;
            RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
            /* the original only distinguishes temples and ruins; what a ruin
             * holds (site+0x0C) is unknown until it is searched */
            if (siteType == 2) tl = "Temple";
            else tl = "Ruin";
            explored = (curPlayer >= 0 && curPlayer < 8) ?
                       (site[0x1E] & (1 << curPlayer)) != 0 : false;
            RGBForeColor(&white);
            TextFont(3); TextSize(10); TextFace(0);
            MoveTo(panelX + 170, 70);
            DrawString("\pType: ");
            {
                Str255 ts; short tl2 = 0;
                while (tl[tl2]) tl2++;
                ts[0] = (unsigned char)tl2;
                BlockMoveData(tl, ts + 1, tl2);
                DrawString(ts);
            }
            MoveTo(panelX + 170, 85);
            DrawString(explored ? "\pExplored: Yes" : "\pExplored: No");
        }

        /* Legend box */
        {
            Rect legR;
            RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
            RGBColor grey = {0x8888, 0x8888, 0x8888};
            RGBColor labelC = {0xDDDD, 0xDDDD, 0xDDDD};
            short legX = panelX + 10, legY = 162;
            SetRect(&legR, legX, legY, winW - 10, legY + 62);
            RGBForeColor(&white);
            PaintRect(&legR);
            RGBForeColor(&grey);
            FrameRect(&legR);

            TextFont(3); TextSize(9); TextFace(0);
            RGBForeColor(&labelC);
            /* Row 1: unexplored icon + explored icon */
            if (sRuinIcons[0] != NULL) {
                Rect ir; SetRect(&ir, legX + 6, legY + 6, legX + 22, legY + 22);
                PlotCIcon(&ir, sRuinIcons[0]);
            }
            {
                RGBColor dk = {0x3333, 0x3333, 0x3333};
                RGBForeColor(&dk);
            }
            MoveTo(legX + 26, legY + 18);
            DrawString("\pUnexplored");
            if (sRuinIcons[1] != NULL) {
                Rect ir; SetRect(&ir, legX + 108, legY + 6, legX + 124, legY + 22);
                PlotCIcon(&ir, sRuinIcons[1]);
            }
            MoveTo(legX + 128, legY + 18);
            DrawString("\pExplored");
            /* Row 2: temple + stronghold (colored squares) */
            {
                Rect sq;
                RGBColor tplC = {0x8888, 0x4444, 0xFFFF};
                RGBColor strC = {0xCCCC, 0x6666, 0x2222};
                RGBColor dk2 = {0x3333, 0x3333, 0x3333};
                SetRect(&sq, legX + 6, legY + 32, legX + 22, legY + 48);
                RGBForeColor(&tplC); PaintRect(&sq);
                RGBForeColor(&dk2);
                MoveTo(legX + 26, legY + 44);
                DrawString("\pTemple");
                SetRect(&sq, legX + 108, legY + 32, legX + 124, legY + 48);
                RGBForeColor(&strC); PaintRect(&sq);
                RGBForeColor(&dk2);
                MoveTo(legX + 128, legY + 44);
                DrawString("\pStronghold");
            }
        }

        /* Flavor text from sSiteDescs */
        if (siteIndex < 99 && sSiteDescs[siteIndex][0] != '\0') {
            char *desc = sSiteDescs[siteIndex];
            short descLen = 0, di = 0;
            short lineY = 240;
            RGBColor descC = {0xAAAA, 0xDDDD, 0xAAAA};
            while (desc[descLen]) descLen++;
            RGBForeColor(&descC);
            TextFont(3); TextSize(9); TextFace(italic);
            while (di < descLen && lineY <= 300) {
                short end = di + 38;
                short bp;
                if (end >= descLen) end = descLen;
                else {
                    bp = end;
                    while (bp > di && desc[bp] != ' ') bp--;
                    if (bp > di) end = bp;
                }
                {
                    Str255 ls;
                    short ll = end - di;
                    if (ll > 254) ll = 254;
                    ls[0] = (unsigned char)ll;
                    BlockMoveData(desc + di, ls + 1, ll);
                    MoveTo(panelX + 12, lineY);
                    DrawString(ls);
                }
                di = end;
                if (di < descLen && desc[di] == ' ') di++;
                lineY += 12;
            }
            TextFace(0);
        }

        /* Done button */
        {
            RGBColor grey = {0x9999, 0x9999, 0x9999};
            RGBColor dk = {0x3333, 0x3333, 0x3333};
            RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
            RGBForeColor(&grey);
            PaintRoundRect(&btnR, 8, 8);
            RGBForeColor(&dk);
            FrameRoundRect(&btnR, 8, 8);
            TextFont(0); TextSize(12); TextFace(bold);
            RGBForeColor(&white);
            MoveTo(btnR.left + (btnR.right - btnR.left - StringWidth("\pDone")) / 2,
                   btnR.top + 17);
            DrawString("\pDone");
        }

        /* Gold border */
        {
            RGBColor gbdr = {0xCCCC, 0xAAAA, 0x3333};
            RGBForeColor(&gbdr);
            PenSize(2, 2);
            FrameRect(&gwRect);
            PenSize(1, 1);
        }

        UnlockPixels(GetGWorldPixMap(siteGW));
        SetGWorld(savePort, saveGD);

        /* Blit to window */
        SetPort(siteWin);
        {
            Rect dr = siteWin->portRect;
            LockPixels(GetGWorldPixMap(siteGW));
            CopyBits((BitMap *)*GetGWorldPixMap(siteGW),
                     &((GrafPtr)siteWin)->portBits,
                     &gwRect, &dr, srcCopy, NULL);
            UnlockPixels(GetGWorldPixMap(siteGW));
        }
    }

    /* Event loop */
    while (!done) {
        EventRecord ev;
        if (WaitNextEvent(mDownMask | keyDownMask | updateMask, &ev, 10, NULL)) {
            if (ev.what == mouseDown) {
                Point lp = ev.where;
                SetPort(siteWin);
                GlobalToLocal(&lp);
                if (PtInRect(lp, &btnR)) done = true;
            } else if (ev.what == keyDown) {
                char key = ev.message & charCodeMask;
                if (key == '\r' || key == 0x03 || key == 0x1B) done = true;
            } else if (ev.what == updateEvt) {
                BeginUpdate(siteWin);
                SetPort(siteWin);
                {
                    Rect dr = siteWin->portRect;
                    LockPixels(GetGWorldPixMap(siteGW));
                    CopyBits((BitMap *)*GetGWorldPixMap(siteGW),
                             &((GrafPtr)siteWin)->portBits,
                             &gwRect, &dr, srcCopy, NULL);
                    UnlockPixels(GetGWorldPixMap(siteGW));
                }
                EndUpdate(siteWin);
            }
        }
    }

    DisposeGWorld(siteGW);
    DisposeWindow(siteWin);
}

/* ===================================================================
 * ShowCityInfo — Modal city dialog with info, production, and armies
 *
 * Full city management dialog matching original 68k behavior:
 * - Info tab: name, owner, defense, income, production status
 * - Production tab: change production type (own cities only)
 * - Armies at city: list of armies stationed here
 * cityIndex is the index into the SCN city table at gs+0x812.
 * =================================================================== */
static void ShowCityWindow(short cityIndex, short startTab);
static void ShowCityInfo(short cityIndex)
{
    /* the original's city window on its Info pane (View 3301) */
    if (1) { ShowCityWindow(cityIndex, 0); return; }
    WindowPtr  cityWin;
    GWorldPtr  offscreen = NULL;
    Rect       winRect;
    Boolean    done = false;
    Rect       screenRect = qd.screenBits.bounds;
    unsigned char *gs;
    unsigned char *city;
    short      cityX, cityY, owner, defense, income;
    short      curTab;  /* 0=Info, 1=Production, 2=Armies */
    Boolean    isOwnCity;
    short      curPlayer;
    #define CITY_WIN_W 460
    #define CITY_WIN_H 340

    if (*gGameState == 0)
        return;

    gs = (unsigned char *)*gGameState;

    {
        short cityCount = sCityCount;
        if (cityIndex < 0 || cityIndex >= cityCount)
            return;
    }

    city = sCityData +cityIndex * 0x20;
    cityX   = *(short *)(city + 0x00);
    cityY   = *(short *)(city + 0x02);
    owner   = *(short *)(city + 0x04);
    defense = *(short *)(city + 0x06);
    income  = *(short *)(city + 0x08);
    curPlayer = *(short *)(gs + 0x110);
    isOwnCity = (owner >= 0 && owner < 8 && owner == curPlayer);
    curTab = isOwnCity ? 0 : 2;  /* Armies tab default for non-owned cities */

    /* Centered window (matches ShowCityBuildSelection layout) */
    {
        short sw = screenRect.right - screenRect.left;
        short sh = screenRect.bottom - screenRect.top;
        short dl = (sw - CITY_WIN_W) / 2;
        short dt = (sh - CITY_WIN_H) / 2;
        if (dt < 20) dt = 20;
        SetRect(&winRect, dl, dt, dl + CITY_WIN_W, dt + CITY_WIN_H);
    }

    cityWin = NewCWindow(NULL, &winRect, "\p", true,
                          dBoxProc, (WindowPtr)-1L, false, 0);
    if (cityWin == NULL)
        return;

    SetPort(cityWin);

    {
        Rect obounds;
        SetRect(&obounds, 0, 0, CITY_WIN_W, CITY_WIN_H);
        NewGWorld(&offscreen, 0, &obounds, NULL, NULL, 0);
    }

    FlushEvents(everyEvent, 0);

    {
        Boolean needsRedraw = true;
        unsigned long startTick = TickCount();
        /* Production slot button rects (up to 4) */
        Rect prodBtnR[4];
        short numProdSlots = 0;
        /* Tab button rects */
        Rect tabR[3];

        while (!done) {
            EventRecord evt;

            if (needsRedraw) {
                Rect r;
                CGrafPtr savedPort;
                GDHandle savedDevice;
                RGBColor labelColor = {0xAAAA, 0xAAAA, 0xAAAA};
                RGBColor valueColor = {0xCCCC, 0xDDDD, 0xFFFF};
                RGBColor gold = {0xFFFF, 0xCCCC, 0x3333};
                RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                RGBColor black = {0, 0, 0};
                Str255 numStr;
                SetRect(&r, 0, 0, CITY_WIN_W, CITY_WIN_H);

                if (offscreen != NULL) {
                    GetGWorld(&savedPort, &savedDevice);
                    SetGWorld(offscreen, NULL);
                    LockPixels(GetGWorldPixMap(offscreen));
                }

                /* Background: left panel minimap + right panel marble */
                {
                    short panelX = CITY_WIN_W / 2;  /* 230 */
                    Rect leftPanel, rightPanel;
                    SetRect(&leftPanel, 0, 0, panelX, CITY_WIN_H);
                    SetRect(&rightPanel, panelX, 0, CITY_WIN_W, CITY_WIN_H);
                    DrawMarbleBackground(&leftPanel);
                    DrawMarbleBackground(&rightPanel);

                    /* Left panel: minimap (matches ShowCityBuildSelection) */
                    if (sMapLoaded && *gMapTiles != 0 && sMapWidth > 0 && sMapHeight > 0) {
                        unsigned char *mapData = (unsigned char *)*gMapTiles;
                        unsigned char *scnData2 = gs;
                        short scaleX = panelX / sMapWidth;
                        short scale  = (scaleX > 1) ? scaleX : 1;
                        short mmW = sMapWidth * scale;
                        short mmH = sMapHeight * scale;
                        short mmX = (panelX - mmW) / 2;
                        short mmY = (CITY_WIN_H - mmH) / 2;
                        short mx, my;
                        for (my = 0; my < sMapHeight; my++) {
                            for (mx = 0; mx < sMapWidth; mx++) {
                                unsigned short tileOffset = my * 0xE0 + mx * 2;
                                unsigned char terrainIdx = mapData[tileOffset];
                                Rect tileR;
                                SetRect(&tileR,
                                    mmX + mx * scale, mmY + my * scale,
                                    mmX + mx * scale + scale, mmY + my * scale + scale);
                                if (sMapColorLoaded && terrainIdx < MAPCOLOR_SIZE) {
                                    short colorIdx = (short)sMapColor[terrainIdx];
                                    if (colorIdx >= MINIMAP_PAL_SIZE) colorIdx = 0;
                                    RGBForeColor(&sMinimapPalette[colorIdx]);
                                } else if (scnData2 != NULL) {
                                    short terrainType = (short)(unsigned char)scnData2[terrainIdx + TERRAIN_TYPE_OFS];
                                    if (terrainType >= NUM_TERRAIN_COLORS) terrainType = 0;
                                    RGBForeColor(&sTerrainColors[terrainType]);
                                } else {
                                    RGBColor water = {0x0000, 0x4444, 0xAAAA};
                                    RGBForeColor(&water);
                                }
                                PaintRect(&tileR);
                            }
                        }
                        /* City shield icons on minimap */
                        {
                            short ci2;
                            short cc2 = sCityCount;
                            if (cc2 > 139) cc2 = 139;
                            for (ci2 = 0; ci2 < cc2; ci2++) {
                                unsigned char *c2 = sCityData + ci2 * 0x20;
                                short cx2 = *(short *)(c2 + 0x00);
                                short cy2 = *(short *)(c2 + 0x02);
                                short st = (short)(unsigned char)c2[0x17];
                                if (st >= 2) {
                                    /* Ruins/temples: small gray dot */
                                    RGBColor ruinGray = {0x9999, 0x9999, 0x7777};
                                    Rect rdot;
                                    SetRect(&rdot, mmX+cx2*scale, mmY+cy2*scale,
                                                   mmX+cx2*scale+3, mmY+cy2*scale+3);
                                    RGBForeColor(&ruinGray);
                                    PaintRect(&rdot);
                                } else {
                                    /* City: grey shield from PICT 30010 */
                                    Rect shR2;
                                    SetRect(&shR2,
                                            mmX + cx2 * scale - 3,
                                            mmY + cy2 * scale - 3,
                                            mmX + cx2 * scale + 5,
                                            mmY + cy2 * scale + 5);
                                    DrawMinimapShield(&shR2);
                                }
                            }
                        }
                        /* Selection shield on current city */
                        if (cityX >= 0 && cityY >= 0) {
                            Rect selR2;
                            SetRect(&selR2,
                                    mmX + cityX * scale - 4,
                                    mmY + cityY * scale - 4,
                                    mmX + cityX * scale + 6,
                                    mmY + cityY * scale + 6);
                            DrawMinimapSelectionShield(&selR2);
                        }
                    }
                }

                /* Owner-colored border on right panel */
                {
                    short panelX = CITY_WIN_W / 2;
                    Rect rightR2;
                    short colorIdx = (owner >= 0 && owner < 8) ? owner + 1 : 8;
                    SetRect(&rightR2, panelX, 0, CITY_WIN_W, CITY_WIN_H);
                    RGBForeColor(&sPlayerColors[colorIdx]);
                    PenSize(3, 3);
                    FrameRect(&rightR2);
                    PenSize(1, 1);
                }

                /* Owner shield */
                if (owner >= 0 && owner < 8) {
                    short panelX = CITY_WIN_W / 2;
                    Rect shR;
                    SetRect(&shR, panelX + 8, 10,
                            panelX + 8 + BIG_SHIELD_W, 10 + BIG_SHIELD_H);
                    DrawBigShield(owner, &shR);
                }

                /* City name */
                {
                    short panelX = CITY_WIN_W / 2;
                    RGBForeColor(&gold);
                    TextFont(2);
                    TextSize(18);
                    TextFace(bold);
                    MoveTo(panelX + 60, 28);
                    if (cityIndex < sCityNameCount && sCityNames[cityIndex][0] != '\0') {
                        Str255 pName;
                        char *cn = sCityNames[cityIndex];
                        short nlen = 0;
                        while (nlen < MAX_CITY_NAME - 1 && cn[nlen] != '\0') nlen++;
                        pName[0] = (unsigned char)nlen;
                        BlockMoveData(cn, pName + 1, nlen);
                        DrawString(pName);
                    } else if (owner >= 0 && owner < 8) {
                        Str255 pName;
                        unsigned char *namePtr = gs + owner * 20;
                        short nlen = 0;
                        while (nlen < 20 && namePtr[nlen] != 0) nlen++;
                        pName[0] = (unsigned char)nlen;
                        BlockMoveData(namePtr, pName + 1, nlen);
                        DrawString(pName);
                        DrawString("\p City");
                    } else {
                        DrawString("\pNeutral City");
                    }
                }

                /* Owner name below city name */
                if (owner >= 0 && owner < 8) {
                    short panelX = CITY_WIN_W / 2;
                    Str255 pName;
                    unsigned char *namePtr = gs + owner * 20;
                    short nlen = 0;
                    while (nlen < 20 && namePtr[nlen] != 0) nlen++;
                    pName[0] = (unsigned char)nlen;
                    BlockMoveData(namePtr, pName + 1, nlen);
                    RGBForeColor(&white);
                    TextFont(3);
                    TextSize(10);
                    TextFace(0);
                    MoveTo(panelX + 60, 42);
                    DrawString(pName);
                }

                /* CAPITAL badge if this city is a player's capital */
                {
                    short panelX = CITY_WIN_W / 2;
                    short pp;
                    short factionCount = *(short *)(gs + 0x10C);
                    if (factionCount > 8) factionCount = 8;
                    for (pp = 0; pp < factionCount; pp++) {
                        unsigned char *pstat = gs + 0x186 + pp * 0x14;
                        short capX = *(short *)(pstat + 0x04);
                        short capY = *(short *)(pstat + 0x06);
                        if (capX == cityX && capY == cityY) {
                            RGBColor capCol = {0xFFFF, 0xDDDD, 0x2222};
                            RGBForeColor(&capCol);
                            TextFont(3);
                            TextSize(9);
                            TextFace(bold);
                            MoveTo(panelX + 60, 54);
                            DrawString("\pCAPITAL");
                            TextFace(0);
                            break;
                        }
                    }
                }

                /* Content area (right panel, above bottom buttons) */
                {
                    short panelX = CITY_WIN_W / 2;
                    Rect contentR;
                    RGBColor contentBg = {0x1111, 0x1111, 0x1111};
                    SetRect(&contentR, panelX + 4, 58, CITY_WIN_W - 4, CITY_WIN_H - 46);
                    RGBForeColor(&contentBg);
                    PaintRect(&contentR);
                    {
                        RGBColor contentBdr = {0x5555, 0x5555, 0x5555};
                        RGBForeColor(&contentBdr);
                        FrameRect(&contentR);
                    }
                }

                /* Bottom nav buttons (matches ShowCityBuildSelection layout) */
                {
                    short panelX = CITY_WIN_W / 2;
                    short navBtnW2 = 36, navBtnH2 = 36;
                    short navBtnY2 = CITY_WIN_H - navBtnH2 - 6;
                    short navXs2[3];
                    short navCicnIDs2[3] = {3300, 3301, 3303};  /* ?=Info, tower=Build, arrows=Armies */
                    short ni2;
                    RGBColor navGrey2   = {0x9999, 0x9999, 0x9999};
                    RGBColor navBorder2 = {0x4444, 0x4444, 0x4444};
                    RGBColor navAmber2  = {0xFFFF, 0xAA00, 0x0000};
                    navXs2[0] = panelX + 4;
                    navXs2[1] = navXs2[0] + navBtnW2 + 2;
                    navXs2[2] = navXs2[1] + navBtnW2 + 2;
                    for (ni2 = 0; ni2 < 3; ni2++) {
                        CIconHandle navIcon2;
                        SetRect(&tabR[ni2], navXs2[ni2], navBtnY2,
                                navXs2[ni2] + navBtnW2, navBtnY2 + navBtnH2);
                        /* Grey background */
                        RGBForeColor(&navGrey2);
                        PaintRect(&tabR[ni2]);
                        /* Border: amber for active tab, dark grey otherwise */
                        RGBForeColor(ni2 == curTab ? &navAmber2 : &navBorder2);
                        PenSize(2, 2);
                        FrameRect(&tabR[ni2]);
                        PenSize(1, 1);
                        navIcon2 = GetCIcon(navCicnIDs2[ni2]);
                        if (navIcon2 != NULL) {
                            PlotCIcon(&tabR[ni2], navIcon2);
                            DisposeCIcon(navIcon2);
                        }
                    }
                    /* Done button (black bg, white border+text) */
                    {
                        short dBtnW = 44, dBtnH = navBtnH2;
                        short dBtnX = navXs2[2] + navBtnW2 + 4;
                        Rect doneR2;
                        short tw5;
                        SetRect(&doneR2, dBtnX, navBtnY2, dBtnX + dBtnW, navBtnY2 + dBtnH);
                        RGBForeColor(&black);
                        PaintRoundRect(&doneR2, 8, 8);
                        RGBForeColor(&white);
                        PenSize(2, 2);
                        FrameRoundRect(&doneR2, 8, 8);
                        PenSize(1, 1);
                        TextFont(0);
                        TextSize(10);
                        TextFace(bold);
                        tw5 = StringWidth("\pDone");
                        MoveTo(dBtnX + (dBtnW - tw5) / 2, navBtnY2 + dBtnH / 2 + 4);
                        DrawString("\pDone");
                        TextFace(0);
                    }
                }

                /* ---- Tab content ---- */
                if (curTab == 0) {
                    /* INFO TAB */
                    short xOff = CITY_WIN_W / 2;  /* panel offset */
                    short yBase = 90;
                    TextFont(3);
                    TextSize(10);
                    TextFace(0);

                    /* Defense */
                    RGBForeColor(&labelColor);
                    MoveTo(xOff + 12, yBase);
                    DrawString("\pDefense:");
                    RGBForeColor(&valueColor);
                    MoveTo(xOff + 90, yBase);
                    NumToString((long)defense, numStr);
                    DrawString(numStr);

                    /* Income */
                    RGBForeColor(&labelColor);
                    MoveTo(xOff + 12, yBase + 18);
                    DrawString("\pIncome:");
                    RGBForeColor(&valueColor);
                    MoveTo(xOff + 90, yBase + 18);
                    NumToString((long)income, numStr);
                    DrawString(numStr);
                    DrawString("\p gp/turn");

                    /* Production status (compact: current unit + turns remaining) */
                    if (*gExtState != 0) {
                        unsigned char *ext = (unsigned char *)*gExtState;
                        unsigned char *extCity = ext + 0x24c + cityIndex * 0x5c;
                        short producing = *(short *)(extCity + 0x02);
                        short prodTurns = *(short *)(extCity + 0x58);

                        RGBForeColor(&labelColor);
                        MoveTo(xOff + 12, yBase + 36);
                        DrawString("\pProducing:");
                        RGBForeColor(&valueColor);
                        MoveTo(xOff + 90, yBase + 36);
                        if (producing >= 0) {
                            Str255 prodName;
                            short totalTurns = GetProductionTurns(producing);
                            short elapsed = totalTurns - prodTurns;
                            short barW = CITY_WIN_W / 2 - 25;
                            short fillW;
                            Rect trackR2, fillR2;
                            RGBColor trackCol = {0x3333, 0x3333, 0x3333};
                            RGBColor fillCol = {0x3333, 0xBBBB, 0x3333};
                            GetUnitTypeName(producing, prodName);
                            DrawString(prodName);
                            DrawString("\p (");
                            NumToString((long)prodTurns, numStr);
                            DrawString(numStr);
                            DrawString("\p)");
                            /* Compact progress bar */
                            if (elapsed < 0) elapsed = 0;
                            if (elapsed > totalTurns) elapsed = totalTurns;
                            fillW = (totalTurns > 0) ? (elapsed * barW) / totalTurns : 0;
                            SetRect(&trackR2, xOff + 12, yBase + 42, xOff + 12 + barW, yBase + 48);
                            RGBForeColor(&trackCol);
                            PaintRoundRect(&trackR2, 3, 3);
                            if (fillW > 0) {
                                SetRect(&fillR2, xOff + 12, yBase + 42, xOff + 12 + fillW, yBase + 48);
                                RGBForeColor(&fillCol);
                                PaintRoundRect(&fillR2, 3, 3);
                            }
                            {
                                RGBColor bdr = {0x6666, 0x6666, 0x6666};
                                RGBForeColor(&bdr);
                                FrameRoundRect(&trackR2, 3, 3);
                            }
                        } else {
                            DrawString("\pNothing");
                        }

                        /* Available production unit icons (circular, 4 slots)
                         * Info-only: no highlighting, no selection */
                        {
                            short pi3, iconX = xOff + 8;
                            short iconY = yBase + 60;
                            short iconSz = 40;  /* circular icon diameter */
                            short pSheet = (owner >= 0 && owner < ARMY_SHEETS) ? owner : 0;
                            GWorldPtr pGW = sArmyGW[pSheet] ? sArmyGW[pSheet] : sArmyGW[0];
                            /* Only draw circles for valid production types (skip empty -1 slots) */
                            for (pi3 = 3; pi3 >= 0; pi3--) {
                                short pType = *(short *)(extCity + 0x06 + pi3 * 2);
                                Rect iconOval;
                                if (pType < 0 || pType >= MAX_UNIT_TYPES) continue;
                                SetRect(&iconOval, iconX, iconY, iconX + iconSz, iconY + iconSz);
                                {
                                    RGBColor circleBg = {0x2222, 0x2222, 0x2222};
                                    RGBColor circleBdr = {0x5555, 0x5555, 0x5555};
                                    RGBForeColor(&circleBg);
                                    PaintOval(&iconOval);
                                    RGBForeColor(&circleBdr);
                                    FrameOval(&iconOval);
                                }
                                /* Unit sprite centered in circle */
                                if (sArmyLoaded && pGW != NULL) {
                                    short si2 = pType;
                                    Rect srcR3, dstR3;
                                    PixMapHandle pm3;
                                    if (sUnitTypesLoaded && pType < sUnitTypeCount) {
                                        unsigned char *ute = sUnitTypeTable + pType * UNIT_TYPE_ENTRY;
                                        si2 = (short)ute[0x00];
                                    }
                                    SetRect(&srcR3, (si2 % 16) * 32, (si2 / 16) * 30,
                                            (si2 % 16) * 32 + 32, (si2 / 16) * 30 + 29);
                                    SetRect(&dstR3, iconX + 5, iconY + 4,
                                            iconX + iconSz - 5, iconY + iconSz - 4);
                                    pm3 = GetGWorldPixMap(pGW);
                                    if (LockPixels(pm3)) {
                                        RGBColor savedBg3;
                                        GetBackColor(&savedBg3);
                                        RGBBackColor(&sArmyBgColor[pSheet]);
                                        CopyBits((BitMap *)*pm3,
                                                 (BitMap *)*GetGWorldPixMap(offscreen),
                                                 &srcR3, &dstR3, 36, NULL);
                                        RGBBackColor(&savedBg3);
                                        UnlockPixels(pm3);
                                    }
                                }
                                iconX += iconSz + 6;
                            }
                        }
                    }

                    /* City description text from CTY resource */
                    if (cityIndex < sCityNameCount && sCityDescs[cityIndex][0] != '\0') {
                        char descBuf[MAX_CITY_DESC], *desc = descBuf;
                        { short q; for (q = 0; q < MAX_CITY_DESC; q++) {
                              descBuf[q] = sCityDescs[cityIndex][q] == '|' ? ' ' : sCityDescs[cityIndex][q];
                              if (!descBuf[q]) break; } }
                        short di = 0;
                        short descLen = 0;
                        short lineY = CITY_WIN_H - 70;  /* bottom area */
                        RGBColor descColor = {0x9999, 0xBBBB, 0x9999};  /* muted green */
                        while (desc[descLen]) descLen++;
                        RGBForeColor(&descColor);
                        TextFont(3);
                        TextSize(9);
                        TextFace(italic);
                        /* Word-wrap description into lines of ~30 chars each */
                        while (di < descLen && lineY < CITY_WIN_H - 42) {
                            short lineEnd = di;
                            short lastSpace = di;
                            /* Find break point for ~30 chars or at word boundary */
                            while (lineEnd < descLen && lineEnd - di < 32) {
                                if (desc[lineEnd] == ' ') lastSpace = lineEnd;
                                lineEnd++;
                            }
                            if (lineEnd < descLen && lastSpace > di) lineEnd = lastSpace;
                            {
                                Str255 lineStr;
                                short slen = lineEnd - di;
                                if (slen > 30) slen = 30;
                                lineStr[0] = (unsigned char)slen;
                                BlockMoveData(desc + di, lineStr + 1, slen);
                                MoveTo(xOff + 8, lineY);
                                DrawString(lineStr);
                            }
                            di = lineEnd;
                            if (di < descLen && desc[di] == ' ') di++;
                            lineY += 13;
                        }
                        TextFace(0);
                    }

                } else if (curTab == 1) {
                    /* PRODUCTION TAB - show available production types for this city */
                    short xOff = CITY_WIN_W / 2;
                    short yBase = 84;
                    numProdSlots = 0;

                    TextFont(3);
                    TextSize(10);

                    if (!isOwnCity) {
                        RGBForeColor(&labelColor);
                        TextFace(0);
                        MoveTo(xOff + 12, yBase + 20);
                        DrawString("\pYou do not control this city.");
                    } else if (*gExtState != 0) {
                        unsigned char *ext = (unsigned char *)*gExtState;
                        unsigned char *extCity = ext + 0x24c + cityIndex * 0x5c;
                        short producing = *(short *)(extCity + 0x02);
                        short pi2;

                        /* Column headers */
                        RGBForeColor(&labelColor);
                        TextFace(bold);
                        TextSize(9);
                        MoveTo(xOff + 12, yBase);
                        DrawString("\pUnit Type");
                        MoveTo(xOff + 130, yBase);
                        DrawString("\pStr");
                        MoveTo(xOff + 155, yBase);
                        DrawString("\pMov");
                        MoveTo(xOff + 180, yBase);
                        DrawString("\pCost");
                        MoveTo(xOff + 205, yBase);
                        DrawString("\pTrn");
                        {
                            RGBColor lineCol = {0x4444, 0x4444, 0x4444};
                            RGBForeColor(&lineCol);
                            MoveTo(xOff + 8, yBase + 4);
                            LineTo(CITY_WIN_W - 8, yBase + 4);
                        }

                        /* List available production slots (strongest first) */
                        for (pi2 = 3; pi2 >= 0; pi2--) {
                            short pType = *(short *)(extCity + 0x06 + pi2 * 2);
                            if (pType >= 0 && pType < 29) {
                                Str255 uName;
                                short str2, mov, turns;
                                short rowY = yBase + 12 + numProdSlots * 28;
                                Boolean isCurrent = (pType == producing);

                                GetUnitTypeName(pType, uName);
                                str2 = GetUnitTypeStat(pType, 0);
                                mov = GetUnitTypeStat(pType, 3);
                                turns = GetProductionTurns(pType);

                                /* Button background */
                                SetRect(&prodBtnR[numProdSlots], xOff + 6, rowY - 8,
                                        CITY_WIN_W - 6, rowY + 16);
                                if (isCurrent) {
                                    RGBColor selBg = {0x2222, 0x3333, 0x5555};
                                    RGBForeColor(&selBg);
                                    PaintRoundRect(&prodBtnR[numProdSlots], 6, 6);
                                    {
                                        RGBColor selBdr = {0x6666, 0x8888, 0xFFFF};
                                        RGBForeColor(&selBdr);
                                        FrameRoundRect(&prodBtnR[numProdSlots], 6, 6);
                                    }
                                } else {
                                    RGBColor normBg = {0x1A1A, 0x1A1A, 0x2222};
                                    RGBForeColor(&normBg);
                                    PaintRoundRect(&prodBtnR[numProdSlots], 6, 6);
                                    {
                                        RGBColor normBdr = {0x4444, 0x4444, 0x4444};
                                        RGBForeColor(&normBdr);
                                        FrameRoundRect(&prodBtnR[numProdSlots], 6, 6);
                                    }
                                }

                                /* Draw army sprite (use city owner's faction sheet) */
                                {
                                    short pSheet = (owner >= 0 && owner < ARMY_SHEETS) ? owner : 0;
                                    GWorldPtr pGW = sArmyGW[pSheet] ? sArmyGW[pSheet] : sArmyGW[0];
                                    if (sArmyLoaded && pGW != NULL) {
                                        short si = pType;  /* sprite index = unit type */
                                        Rect srcR2, dstR2;
                                        PixMapHandle pm;
                                        SetRect(&srcR2, (si % 16) * 32, (si / 16) * 30,
                                                (si % 16) * 32 + 32, (si / 16) * 30 + 29);
                                        SetRect(&dstR2, xOff + 10, rowY - 6, xOff + 36, rowY + 14);
                                        pm = GetGWorldPixMap(pGW);
                                        if (LockPixels(pm)) {
                                            RGBColor savedBg2;
                                            GetBackColor(&savedBg2);
                                            RGBBackColor(&sArmyBgColor[pSheet]);
                                            CopyBits((BitMap *)*pm,
                                                     (BitMap *)*GetGWorldPixMap(offscreen),
                                                     &srcR2, &dstR2, 36, NULL);
                                            RGBBackColor(&savedBg2);
                                            UnlockPixels(pm);
                                        }
                                    }
                                }

                                /* Unit name */
                                RGBForeColor(isCurrent ? &gold : &white);
                                TextFace(isCurrent ? bold : 0);
                                TextSize(10);
                                MoveTo(xOff + 40, rowY + 4);
                                DrawString(uName);
                                if (isCurrent) {
                                    DrawString("\p *");
                                }

                                /* Stats */
                                RGBForeColor(&valueColor);
                                TextFace(0);
                                TextSize(9);
                                MoveTo(xOff + 130, rowY + 4);
                                NumToString((long)str2, numStr);
                                DrawString(numStr);
                                MoveTo(xOff + 155, rowY + 4);
                                NumToString((long)mov, numStr);
                                DrawString(numStr);
                                {
                                    short pCost = GetUnitTypeStat(pType, 4);
                                    if (pCost > 0) {
                                        MoveTo(xOff + 180, rowY + 4);
                                        NumToString((long)pCost, numStr);
                                        DrawString(numStr);
                                    }
                                }
                                MoveTo(xOff + 205, rowY + 4);
                                NumToString((long)turns, numStr);
                                DrawString(numStr);

                                numProdSlots++;
                            }
                        }

                        if (numProdSlots == 0) {
                            RGBForeColor(&labelColor);
                            TextFace(0);
                            MoveTo(xOff + 12, yBase + 20);
                            DrawString("\pNo production available.");
                        }

                        /* Current production timer */
                        if (producing >= 0) {
                            short prodTurns = *(short *)(extCity + 0x58);
                            short totalTurns = GetProductionTurns(producing);
                            short timerY = yBase + 16 + numProdSlots * 28 + 10;
                            Rect trackR3, fillR3;
                            short elapsed2, fillW2;
                            short barW2 = CITY_WIN_W - xOff - 24;
                            RGBColor trackCol = {0x3333, 0x3333, 0x3333};
                            RGBColor fillCol = {0x3333, 0xBBBB, 0x3333};

                            RGBForeColor(&labelColor);
                            TextFace(0);
                            TextSize(9);
                            MoveTo(xOff + 12, timerY);
                            DrawString("\pProgress: ");
                            NumToString((long)(totalTurns - prodTurns), numStr);
                            DrawString(numStr);
                            DrawString("\p/");
                            NumToString((long)totalTurns, numStr);
                            DrawString(numStr);
                            DrawString("\p turns");

                            elapsed2 = totalTurns - prodTurns;
                            if (elapsed2 < 0) elapsed2 = 0;
                            if (totalTurns > 0) {
                                fillW2 = (elapsed2 * barW2) / totalTurns;
                                SetRect(&trackR3, xOff + 12, timerY + 4, xOff + 12 + barW2, timerY + 12);
                                RGBForeColor(&trackCol);
                                PaintRoundRect(&trackR3, 4, 4);
                                if (fillW2 > 0) {
                                    SetRect(&fillR3, xOff + 12, timerY + 4, xOff + 12 + fillW2, timerY + 12);
                                    RGBForeColor(&fillCol);
                                    PaintRoundRect(&fillR3, 4, 4);
                                }
                                {
                                    RGBColor bdr = {0x6666, 0x6666, 0x6666};
                                    RGBForeColor(&bdr);
                                    FrameRoundRect(&trackR3, 4, 4);
                                }
                            }
                        }
                    }

                } else if (curTab == 2) {
                    /* ARMIES TAB - detailed list of armies at this city */
                    short xOff = CITY_WIN_W / 2;
                    short armyCount = *(short *)(gs + 0x1602);
                    short ai3, armyY = 84;
                    short armiesHere = 0;
                    if (armyCount > 100) armyCount = 100;

                    /* Column headers */
                    RGBForeColor(&labelColor);
                    TextFont(3);
                    TextSize(9);
                    TextFace(bold);
                    MoveTo(xOff + 12, armyY);
                    DrawString("\pArmy Name");
                    MoveTo(xOff + 130, armyY);
                    DrawString("\pStr");
                    MoveTo(xOff + 155, armyY);
                    DrawString("\pMP");
                    MoveTo(xOff + 180, armyY);
                    DrawString("\pUnits");
                    {
                        RGBColor lineCol = {0x4444, 0x4444, 0x4444};
                        RGBForeColor(&lineCol);
                        MoveTo(xOff + 8, armyY + 4);
                        LineTo(CITY_WIN_W - 8, armyY + 4);
                    }
                    armyY += 16;

                    for (ai3 = 0; ai3 < armyCount && armiesHere < 8; ai3++) {
                        unsigned char *a = gs + 0x1604 + ai3 * 0x42;
                        short aax = *(short *)(a + 0x00);
                        short aay = *(short *)(a + 0x02);
                        if (a[0x16] == 0xFF) continue;
                        if (aax == cityX && aay == cityY) {
                            Str255 aName;
                            short alen = 0, ui3, unitCount = 0;
                            short aOwner = (short)(unsigned char)a[0x15];
                            short colorIdx2 = (aOwner >= 0 && aOwner < 8) ? aOwner + 1 : 0;

                            /* Army name */
                            while (alen < 16 && a[0x04 + alen] != 0) alen++;
                            if (alen > 0) {
                                aName[0] = (unsigned char)alen;
                                BlockMoveData(a + 0x04, aName + 1, alen);
                            } else {
                                aName[0] = 5;
                                BlockMoveData("Army ", aName + 1, 5);
                            }

                            /* Owner color bar */
                            {
                                Rect ownerBar;
                                SetRect(&ownerBar, xOff + 8, armyY - 8, xOff + 11, armyY + 4);
                                RGBForeColor(&sPlayerColors[colorIdx2]);
                                PaintRect(&ownerBar);
                            }

                            /* Draw army sprite (use per-faction sheet) */
                            {
                                short aSheet = (aOwner >= 0 && aOwner < ARMY_SHEETS) ? aOwner : 0;
                                GWorldPtr aGW = sArmyGW[aSheet] ? sArmyGW[aSheet] : sArmyGW[0];
                                if (sArmyLoaded && aGW != NULL) {
                                    short si2 = (short)(unsigned char)a[0x14];
                                    Rect srcR3, dstR3;
                                    PixMapHandle pm2;
                                    SetRect(&srcR3, (si2 % 16) * 32, (si2 / 16) * 30,
                                            (si2 % 16) * 32 + 32, (si2 / 16) * 30 + 29);
                                    SetRect(&dstR3, xOff + 14, armyY - 8, xOff + 38, armyY + 10);
                                    pm2 = GetGWorldPixMap(aGW);
                                    if (LockPixels(pm2)) {
                                        RGBColor savedBg3;
                                        GetBackColor(&savedBg3);
                                        RGBBackColor(&sArmyBgColor[aSheet]);
                                        CopyBits((BitMap *)*pm2,
                                                 (BitMap *)*GetGWorldPixMap(offscreen),
                                                 &srcR3, &dstR3, 36, NULL);
                                        RGBBackColor(&savedBg3);
                                        UnlockPixels(pm2);
                                    }
                                }
                            }

                            /* Name */
                            RGBForeColor(&white);
                            TextFace(bold);
                            TextSize(10);
                            MoveTo(xOff + 42, armyY + 2);
                            DrawString(aName);

                            /* Strength */
                            RGBForeColor(&valueColor);
                            TextFace(0);
                            TextSize(9);
                            MoveTo(xOff + 130, armyY + 2);
                            NumToString((long)*(short *)(a + 0x2a), numStr);
                            DrawString(numStr);

                            /* Movement points */
                            MoveTo(xOff + 155, armyY + 2);
                            NumToString((long)(unsigned char)a[0x2e], numStr);
                            DrawString(numStr);

                            /* Unit count */
                            for (ui3 = 0; ui3 < 4; ui3++) {
                                if (a[0x16 + ui3] != 0xFF) unitCount++;
                            }
                            MoveTo(xOff + 180, armyY + 2);
                            NumToString((long)unitCount, numStr);
                            DrawString(numStr);
                            DrawString("\p/4");

                            /* Unit types row */
                            {
                                short ux;
                                TextSize(8);
                                RGBForeColor(&labelColor);
                                ux = xOff + 42;
                                for (ui3 = 0; ui3 < 4; ui3++) {
                                    if (a[0x16 + ui3] != 0xFF) {
                                        Str255 utn;
                                        if ((unsigned char)a[0x16 + ui3] == 0x1C) {
                                            unsigned char *hn = a + 0x04; short nl = 0;
                                            while (nl < 15 && hn[nl]) nl++;
                                            utn[0] = (unsigned char)nl;
                                            BlockMoveData(hn, utn + 1, nl);
                                        } else {
                                            GetUnitTypeName((short)(unsigned char)a[0x16 + ui3], utn);
                                        }
                                        MoveTo(ux, armyY + 14);
                                        DrawString(utn);
                                        ux += StringWidth(utn) + 8;
                                    }
                                }
                            }

                            armyY += 28;
                            armiesHere++;
                        }
                    }

                    if (armiesHere == 0) {
                        RGBForeColor(&valueColor);
                        TextFace(0);
                        TextSize(10);
                        MoveTo(xOff + 12, armyY);
                        DrawString("\pNo armies stationed here.");
                    }
                }

                /* Blit to window */
                if (offscreen != NULL) {
                    UnlockPixels(GetGWorldPixMap(offscreen));
                    SetGWorld(savedPort, savedDevice);
                    SetPort(cityWin);
                    CopyBits((BitMap *)*GetGWorldPixMap(offscreen),
                             &((GrafPtr)cityWin)->portBits,
                             &r, &cityWin->portRect,
                             srcCopy, NULL);
                }

                needsRedraw = false;
            }

            WaitNextEvent(everyEvent, &evt, 30, NULL);

            if (evt.what == mouseDown) {
                Point localPt = evt.where;
                SetPort(cityWin);
                GlobalToLocal(&localPt);

                /* Done button hit test (matches bottom nav bar layout) */
                {
                    short panelX2 = CITY_WIN_W / 2;
                    short navBW = 36;
                    short dBtnX2 = panelX2 + 4 + (navBW + 2) * 3 + 4;
                    short dBtnY2 = CITY_WIN_H - 36 - 6;
                    Rect doneHit;
                    SetRect(&doneHit, dBtnX2, dBtnY2, dBtnX2 + 44, dBtnY2 + 36);
                    if (PtInRect(localPt, &doneHit)) {
                        done = true;
                        continue;
                    }
                }

                /* Tab buttons */
                {
                    short ti2;
                    for (ti2 = 0; ti2 < 3; ti2++) {
                        if (PtInRect(localPt, &tabR[ti2]) && ti2 != curTab) {
                            curTab = ti2;
                            needsRedraw = true;
                            break;
                        }
                    }
                }

                /* Production slot buttons (Build tab only, own city) */
                if (curTab == 1 && isOwnCity && *gExtState != 0) {
                    short pi3;
                    for (pi3 = 0; pi3 < numProdSlots; pi3++) {
                        if (PtInRect(localPt, &prodBtnR[pi3])) {
                            /* Change production to this slot */
                            unsigned char *ext = (unsigned char *)*gExtState;
                            unsigned char *extCity = ext + 0x24c + cityIndex * 0x5c;
                            short selectedType = *(short *)(extCity + 0x06 + pi3 * 2);
                            short curProd = *(short *)(extCity + 0x02);
                            if (selectedType >= 0 && selectedType != curProd) {
                                *(short *)(extCity + 0x02) = selectedType;
                                *(short *)(extCity + 0x58) = GetProductionTurns(selectedType);
                                needsRedraw = true;
                            }
                            break;
                        }
                    }
                }
            }
            else if (evt.what == keyDown) {
                char key = evt.message & charCodeMask;
                if ((TickCount() - startTick) < 30)
                    continue;
                if (key == 0x0D || key == 0x03 || key == 0x1B)
                    done = true;
                else if (key == '1') { curTab = 0; needsRedraw = true; }
                else if (key == '2') { curTab = 1; needsRedraw = true; }
                else if (key == '3') { curTab = 2; needsRedraw = true; }
            }
            else if (evt.what == updateEvt) {
                needsRedraw = true;
            }
        }
    }

    if (offscreen != NULL)
        DisposeGWorld(offscreen);
    DisposeWindow(cityWin);
    #undef CITY_WIN_W
    #undef CITY_WIN_H
}


/* ===================================================================
 * ShowArmyInspect — Modal dialog showing army stack details
 *
 * Shows each unit in the army (up to 4), with type, strength,
 * movement, experience, and bonus.  armyIndex is the index into
 * the army table at gs+0x1604.
 * =================================================================== */
static void ShowArmyInspect(short armyIndex)
{
    WindowPtr  inspWin;
    GWorldPtr  offscreen = NULL;
    Rect       winRect;
    Boolean    done = false;
    Rect       screenRect = qd.screenBits.bounds;
    unsigned char *gs, *army;
    short      armyCount;

    if (*gGameState == 0) return;
    gs = (unsigned char *)*gGameState;
    armyCount = *(short *)(gs + 0x1602);
    if (armyIndex < 0 || armyIndex >= armyCount) return;

    army = gs + 0x1604 + armyIndex * 0x42;

    /* Block inspecting enemy armies when View Enemies is off */
    if (!sOptViewEnemies) {
        short armOwner = (short)(unsigned char)army[0x15];
        short curP = *(short *)(gs + 0x110);
        if (armOwner != curP) {
            ShowBriefMessage("\pCannot inspect enemy armies");
            return;
        }
    }

    /* Center 350x340 window (taller to fit hero items section) */
    SetRect(&winRect,
        (screenRect.right - 350) / 2,
        (screenRect.bottom - 340) / 2,
        (screenRect.right - 350) / 2 + 350,
        (screenRect.bottom - 340) / 2 + 340);

    inspWin = NewCWindow(NULL, &winRect, "\p", true,
                          plainDBox, (WindowPtr)-1L, false, 0);
    if (inspWin == NULL) return;

    SetPort(inspWin);
    {
        Rect obounds;
        SetRect(&obounds, 0, 0, 350, 340);
        NewGWorld(&offscreen, 0, &obounds, NULL, NULL, 0);
    }

    FlushEvents(everyEvent, 0);

    {
        Boolean needsRedraw = true;
        unsigned long startTick = TickCount();

        while (!done) {
            EventRecord evt;

            if (needsRedraw) {
                Rect r;
                CGrafPtr savedPort;
                GDHandle savedDevice;
                short ui;
                SetRect(&r, 0, 0, 350, 340);

                if (offscreen != NULL) {
                    GetGWorld(&savedPort, &savedDevice);
                    SetGWorld(offscreen, NULL);
                    LockPixels(GetGWorldPixMap(offscreen));
                }

                /* Dark background */
                {
                    DrawMarbleBackground(&r);
                }

                /* Owner-colored border */
                {
                    short owner = (short)(unsigned char)army[0x15];
                    short colorIdx = (owner >= 0 && owner < 8) ? owner + 1 : 8;
                    RGBForeColor(&sPlayerColors[colorIdx]);
                    PenSize(3, 3);
                    FrameRect(&r);
                    PenSize(1, 1);

                    /* Owner faction shield */
                    if (owner >= 0 && owner < 8) {
                        Rect shR;
                        SetRect(&shR, 300, 8, 300 + BIG_SHIELD_W, 8 + BIG_SHIELD_H);
                        DrawBigShield(owner, &shR);
                    }
                }

                /* Title: army name */
                {
                    RGBColor gold = {0xFFFF, 0xCCCC, 0x3333};
                    Str255 pName;
                    short nlen = 0;
                    RGBForeColor(&gold);
                    TextFont(2);
                    TextSize(16);
                    TextFace(bold);
                    MoveTo(20, 26);
                    while (nlen < 16 && army[0x04 + nlen] != 0) nlen++;
                    if (nlen > 0) {
                        pName[0] = (unsigned char)nlen;
                        BlockMoveData(army + 0x04, pName + 1, nlen);
                        DrawString(pName);
                    } else {
                        DrawString(GetCachedString(STR_STACK_INFO, 0, "\pArmy Stack"));
                    }
                }

                /* Army strength and movement */
                {
                    RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                    Str255 numStr;
                    RGBForeColor(&white);
                    TextFont(3);
                    TextSize(10);
                    TextFace(0);
                    MoveTo(20, 42);
                    DrawString("\pStrength: ");
                    NumToString((long)*(short *)(army + 0x2a), numStr);
                    DrawString(numStr);
                    DrawString("\p   Movement: ");
                    NumToString((long)(unsigned char)army[0x2e], numStr);
                    DrawString(numStr);
                    /* Defend status */
                    if (army[0x2d] > 0) {
                        RGBColor defColor = {0x8888, 0xFFFF, 0x8888};
                        RGBForeColor(&defColor);
                        DrawString("\p  [Defending]");
                    }
                    /* Orders status */
                    if (*(short *)(army + 0x32) != 0) {
                        RGBColor ordColor = {0xAAAA, 0xAAAA, 0xFFFF};
                        RGBForeColor(&ordColor);
                        DrawString("\p  [Orders]");
                    }
                }

                /* Separator line */
                {
                    RGBColor gray = {0x6666, 0x6666, 0x6666};
                    RGBForeColor(&gray);
                    MoveTo(15, 52);
                    LineTo(335, 52);
                }

                /* Unit slots (up to 4) with sprites */
                TextFace(0);
                for (ui = 0; ui < 4; ui++) {
                    short yPos = 68 + ui * 40;
                    unsigned char unitType = army[0x16 + ui];
                    unsigned char unitMoves = army[0x1a + ui];
                    unsigned char unitHits = army[0x1e + ui];
                    unsigned char unitBonus = army[0x22 + ui];
                    unsigned char unitExp = army[0x26 + ui];
                    RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                    RGBColor dim = {0x5555, 0x5555, 0x5555};
                    Str255 numStr;

                    if (unitType == 0xFF) {
                        /* Empty slot */
                        RGBForeColor(&dim);
                        TextSize(10);
                        MoveTo(50, yPos + 10);
                        DrawString(GetCachedString(STR_STACK_INFO, 9, "\p(empty)"));
                        continue;
                    }

                    /* Row background */
                    {
                        Rect rowBg;
                        RGBColor rowCol = {0x1A1A, 0x1A1A, 0x2222};
                        SetRect(&rowBg, 15, yPos - 6, 335, yPos + 28);
                        RGBForeColor(&rowCol);
                        PaintRoundRect(&rowBg, 4, 4);
                    }

                    /* Draw unit sprite (use army owner's faction sheet) */
                    {
                        short uOwn = (short)(unsigned char)army[0x15];
                        short uSheet = (uOwn >= 0 && uOwn < ARMY_SHEETS) ? uOwn : 0;
                        GWorldPtr uGW = sArmyGW[uSheet] ? sArmyGW[uSheet] : sArmyGW[0];
                        if (sArmyLoaded && uGW != NULL) {
                            short si3 = 0;
                            Rect srcR4, dstR4;
                            PixMapHandle pm3;
                            if (sUnitTypesLoaded && unitType < sUnitTypeCount) {
                                unsigned char *ute = sUnitTypeTable + unitType * UNIT_TYPE_ENTRY;
                                si3 = (short)ute[0x00];
                            }
                            SetRect(&srcR4, (si3 % 16) * 32, (si3 / 16) * 30,
                                    (si3 % 16) * 32 + 32, (si3 / 16) * 30 + 29);
                            SetRect(&dstR4, 18, yPos - 4, 46, yPos + 24);
                            pm3 = GetGWorldPixMap(uGW);
                            if (LockPixels(pm3)) {
                                RGBColor savedBg4;
                                GetBackColor(&savedBg4);
                                RGBBackColor(&sArmyBgColor[uSheet]);
                                CopyBits((BitMap *)*pm3,
                                         (BitMap *)*GetGWorldPixMap(offscreen),
                                         &srcR4, &dstR4, 36, NULL);
                                RGBBackColor(&savedBg4);
                                UnlockPixels(pm3);
                            }
                        }
                    }

                    RGBForeColor(&white);

                    /* Unit type name (large) */
                    TextSize(11);
                    TextFace(bold);
                    MoveTo(52, yPos + 6);
                    {
                        Str255 typeName;
                        GetUnitTypeName((short)unitType, typeName);
                        DrawString(typeName);
                    }

                    /* Stats row below name */
                    {
                        RGBColor statColor = {0xBBBB, 0xBBBB, 0xDDDD};
                        RGBColor labelCol = {0x8888, 0x8888, 0x8888};
                        TextFace(0);
                        TextSize(9);

                        RGBForeColor(&labelCol);
                        MoveTo(52, yPos + 20);
                        DrawString("\pStr:");
                        RGBForeColor(&statColor);
                        /* Base strength from unit type table (not current HP) */
                        {
                            short baseStr = GetUnitTypeStat((short)unitType, 0);
                            NumToString((long)(baseStr > 0 ? baseStr : unitHits), numStr);
                        }
                        DrawString(numStr);

                        RGBForeColor(&labelCol);
                        DrawString("\p  Mov:");
                        RGBForeColor(&statColor);
                        NumToString((long)unitMoves, numStr);
                        DrawString(numStr);

                        RGBForeColor(&labelCol);
                        DrawString("\p  HP:");
                        RGBForeColor(&statColor);
                        NumToString((long)unitHits, numStr);
                        DrawString(numStr);

                        if (unitBonus > 0) {
                            RGBForeColor(&labelCol);
                            DrawString("\p  Bonus:");
                            RGBForeColor(&statColor);
                            DrawString("\p+");
                            NumToString((long)unitBonus, numStr);
                            DrawString(numStr);
                        }

                        if (unitExp > 0) {
                            RGBForeColor(&labelCol);
                            DrawString("\p  XP:");
                            RGBForeColor(&statColor);
                            NumToString((long)unitExp, numStr);
                            DrawString(numStr);
                        }
                    }
                }

                /* Hero items display (if army has a hero) */
                {
                    Boolean hasHero = false;
                    short hi;
                    for (hi = 0; hi < 4; hi++) {
                        if ((unsigned char)army[0x16 + hi] == 0x1C) { hasHero = true; break; }
                    }
                    if (hasHero) {
                        short itemY = 232;
                        RGBColor itemLbl = {0x8888, 0x8888, 0x8888};
                        RGBColor itemVal = {0xFFFF, 0xDDDD, 0x6666};
                        RGBColor sepCol = {0x4444, 0x4444, 0x4444};
                        RGBForeColor(&sepCol);
                        MoveTo(15, itemY - 8);
                        LineTo(335, itemY - 8);
                        TextFont(3); TextSize(9); TextFace(bold);
                        RGBForeColor(&itemLbl);
                        MoveTo(20, itemY);
                        DrawString("\pItems:");
                        TextFace(0);
                        {
                            short ii, itemCount = 0;
                            for (ii = 0; ii < ITEM_SLOTS; ii++) {
                                short itemId = *(short *)(army + 0x3A + ii * 2);
                                if (itemId > 0 && itemId <= GAME_ITEM_COUNT) {
                                    ItemDef itemBuf;
                                    const ItemDef *item = GameItemDef(itemId, &itemBuf);
                                    Str255 pn;
                                    short nl = 0;
                                    while (nl < 19 && item->name[nl] != '\0') nl++;
                                    pn[0] = (unsigned char)nl;
                                    BlockMoveData(item->name, pn + 1, nl);
                                    RGBForeColor(&itemVal);
                                    MoveTo(65, itemY + itemCount * 12);
                                    DrawString(pn);
                                    /* Show bonus type */
                                    RGBForeColor(&itemLbl);
                                    if (item->type == ITEM_TYPE_BATTLE) {
                                        Str255 vs; DrawString("\p +");
                                        NumToString((long)item->value, vs);
                                        DrawString(vs); DrawString("\p str");
                                    } else if (item->type == ITEM_TYPE_COMMAND) {
                                        Str255 vs; DrawString("\p +");
                                        NumToString((long)item->value, vs);
                                        DrawString(vs); DrawString("\p cmd");
                                    } else if (item->type == ITEM_TYPE_FLYING) {
                                        DrawString("\p (fly)");
                                    } else if (item->type == ITEM_TYPE_MOVEMENT) {
                                        DrawString("\p (move)");
                                    } else if (item->type == ITEM_TYPE_GOLD) {
                                        Str255 vs; DrawString("\p +");
                                        NumToString((long)item->value, vs);
                                        DrawString(vs); DrawString("\p gold");
                                    }
                                    itemCount++;
                                }
                            }
                            if (itemCount == 0) {
                                RGBForeColor(&itemLbl);
                                MoveTo(65, itemY);
                                DrawString("\p(none)");
                            }
                        }
                    }
                }

                /* OK button */
                {
                    RGBColor black = {0, 0, 0};
                    RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                    Rect okBtn;
                    SetRect(&okBtn, 135, 304, 215, 326);
                    RGBForeColor(&white);
                    PaintRoundRect(&okBtn, 8, 8);
                    RGBForeColor(&black);
                    FrameRoundRect(&okBtn, 8, 8);
                    PenSize(2, 2);
                    FrameRoundRect(&okBtn, 8, 8);
                    PenSize(1, 1);
                    TextFont(3);
                    TextSize(10);
                    TextFace(bold);
                    MoveTo(okBtn.left + 16, okBtn.bottom - 6);
                    DrawString(GetCachedString(STR_COMMON_BUTTONS, 1, "\pOK"));
                }

                /* Blit */
                if (offscreen != NULL) {
                    UnlockPixels(GetGWorldPixMap(offscreen));
                    SetGWorld(savedPort, savedDevice);
                    SetPort(inspWin);
                    CopyBits((BitMap *)*GetGWorldPixMap(offscreen),
                             &((GrafPtr)inspWin)->portBits,
                             &r, &inspWin->portRect,
                             srcCopy, NULL);
                }
                needsRedraw = false;
            }

            WaitNextEvent(everyEvent, &evt, 30, NULL);

            if (evt.what == mouseDown) {
                Point localPt = evt.where;
                Rect okBtn;
                SetPort(inspWin);
                GlobalToLocal(&localPt);
                SetRect(&okBtn, 135, 304, 215, 326);
                if (PtInRect(localPt, &okBtn))
                    done = true;
            }
            else if (evt.what == keyDown) {
                char key = evt.message & charCodeMask;
                if ((TickCount() - startTick) < 30) continue;
                if (key == 0x0D || key == 0x03 || key == 0x1B)
                    done = true;
            }
            else if (evt.what == updateEvt) {
                needsRedraw = true;
            }
        }
    }

    if (offscreen != NULL)
        DisposeGWorld(offscreen);
    DisposeWindow(inspWin);
}


/* Forward declarations for stack grouping and window refresh */
static void BuildStackArrays(short leadArmyIdx);
static void InvalidateAllGameWindows(void);

/* ===================================================================
 * SelectNextArmy — Select nearest unfinished army for current player
 *
 * Implements "Next Group" (Cmd+N).  68k CODE_115 FUN_000032c0:
 * Uses Manhattan distance from viewport center to pick the nearest
 * army that has movement points, is not fortified, and has no queued
 * orders.  Armies at distance 0 (already at viewport) are penalized
 * to 9000 so they're picked last.
 * =================================================================== */
static void SelectNextArmy(void)
{
    unsigned char *gs;
    short currentPlayer, armyCount, i;
    short bestIdx = -1;
    short bestDist = 10000;
    short vpCenterX, vpCenterY;

    if (*gGameState == 0)
        return;

    gs = (unsigned char *)*gGameState;
    currentPlayer = *(short *)(gs + 0x110);
    armyCount = *(short *)(gs + 0x1602);
    if (armyCount <= 0 || armyCount > 100)
        return;

    /* Viewport center for distance calculation */
    {
        short tilesWide = 10, tilesHigh = 10;
        if (*gMainGameWindow != 0) {
            Rect p = ((WindowPtr)*gMainGameWindow)->portRect;
            tilesWide = (p.right - p.left - SCROLLBAR_W) / TERRAIN_TILE_W;
            tilesHigh = (p.bottom - p.top - SCROLLBAR_H) / TERRAIN_TILE_H;
        }
        vpCenterX = sViewportX + tilesWide / 2;
        vpCenterY = sViewportY + tilesHigh / 2;
    }

    /* Turn 1 special case: select strongest army, ties broken by leftmost (smallest X).
     * After turn 1: 68k CODE_123 FUN_00000262 two-pass distance-based selection. */
    {
      short turnNum = *(short *)(gs + 0x136);
      if (turnNum == 0) {
          /* Turn 1: pick strongest, leftmost army */
          short bestStr = -1, bestX = 30000;
          for (i = armyCount - 1; i >= 0; i--) {
              unsigned char *army = gs + 0x1604 + i * 0x42;
              short owner = (short)(unsigned char)army[0x15];
              short ax, str;
              if (owner != currentPlayer) continue;
              ax = *(short *)(army + 0x00);
              if (ax < 0) continue;
              if (army[0x16] == 0xFF) continue;
              str = (short)(unsigned char)army[0x1e];
              if (str > bestStr || (str == bestStr && ax < bestX)) {
                  bestStr = str;
                  bestX = ax;
                  bestIdx = i;
              }
          }
      } else {
          /* Normal: two-pass selection by Manhattan distance from viewport center.
           * Pass 1: ungrouped armies (army+0x11 == 0) — prefer solo units.
           * Pass 2: already-grouped armies (army+0x11 != 0).
           * If falling back to pass 2, clear all group tags for this player
           * (68k clears 0x200 flag on all player armies — auto-ungroup). */
          short bestUngrouped = -1, bestGrouped = -1;
          short bestUngDist = 10000, bestGrpDist = 10000;
          for (i = armyCount - 1; i >= 0; i--) {
                unsigned char *army = gs + 0x1604 + i * 0x42;
                short owner = (short)(unsigned char)army[0x15];
                short ax, ay, dist, dx, dy;
                short movePts, hasOrders, fortified;

                if (owner != currentPlayer) continue;
                ax = *(short *)(army + 0x00);
                if (ax < 0) continue;  /* not placed */
                if (army[0x16] == 0xFF) continue;  /* dead */

                movePts = (short)(unsigned char)army[0x2e];
                if (movePts <= 0) continue;  /* no movement */
                fortified = army[0x2d];
                if (fortified != 0) continue;  /* fortified/garrisoned */
                hasOrders = *(short *)(army + 0x32);
                if (hasOrders != 0) continue;  /* queued orders */

                /* Manhattan distance from viewport center */
                ay = *(short *)(army + 0x02);
                dx = ax - vpCenterX;
                if (dx < 0) dx = -dx;
                dy = ay - vpCenterY;
                if (dy < 0) dy = -dy;
                dist = dx + dy;

                /* Penalize army at viewport center (68k: distance 0 → 9000) */
                if (dist == 0) dist = 9000;

                if (army[0x11] == 0) {
                    /* Ungrouped */
                    if (dist < bestUngDist) { bestUngDist = dist; bestUngrouped = i; }
                } else {
                    /* Grouped */
                    if (dist < bestGrpDist) { bestGrpDist = dist; bestGrouped = i; }
                }
          }
          if (bestUngrouped >= 0) {
              bestIdx = bestUngrouped;
          } else if (bestGrouped >= 0) {
              /* 68k: clear all group tags for this player (auto-ungroup) */
              for (i = armyCount - 1; i >= 0; i--) {
                  unsigned char *a2 = gs + 0x1604 + i * 0x42;
                  if ((short)(unsigned char)a2[0x15] == currentPlayer)
                      a2[0x11] = 0;
              }
              bestIdx = bestGrouped;
          }
      }
    }

    if (bestIdx < 0)
        return;

    /* Select and center viewport on chosen army */
    {
        unsigned char *army = gs + 0x1604 + bestIdx * 0x42;
        sSelectedArmy = bestIdx;
        BuildStackArrays(bestIdx);

        /* Center viewport on selected army */
        CenterViewportOn(*(short *)(army + 0x00), *(short *)(army + 0x02));

        /* Redraw */
        if (*gMainGameWindow != 0) {
            SetPort((WindowPtr)*gMainGameWindow);
            InvalRect(&((WindowPtr)*gMainGameWindow)->portRect);
        }
        if (*gOverviewWindow != 0) {
            SetPort((WindowPtr)*gOverviewWindow);
            InvalRect(&((WindowPtr)*gOverviewWindow)->portRect);
        }
    }
}


/* ===================================================================
 * BuildStackArrays — Populate parallel arrays for all armies at a tile
 *
 * Called when an army is selected (clicked on map).  Finds all armies
 * at the same tile owned by the same player and builds the stack
 * arrays.  The selected army becomes group 0 and is marked selected.
 * Other armies at the same tile get their own groups.
 *
 * 68k: CODE_123 FUN_00000788 + FUN_000008de
 * =================================================================== */
/* The army whose sprite stands on its tile (one per tile): the selection if
 * it is there, else a hero, else the first army. */
static Boolean ArmyShownOnTile(short i)
{
    unsigned char *gs = (unsigned char *)*gGameState, *a;
    short n, j;
    Boolean iHero;
    if (gs == NULL) return true;
    n = *(short *)(gs + 0x1602);
    a = gs + 0x1604 + i * 0x42;
    if (sSelectedArmy >= 0 && sSelectedArmy < n) {
        unsigned char *sel = gs + 0x1604 + sSelectedArmy * 0x42;
        if (*(short *)(sel + 0) == *(short *)(a + 0) && *(short *)(sel + 2) == *(short *)(a + 2))
            return i == sSelectedArmy;
    }
    iHero = ((unsigned char)a[0x16] == 0x1C);
    for (j = 0; j < n; j++) {
        unsigned char *b = gs + 0x1604 + j * 0x42;
        Boolean jHero;
        if (j == i || b[0x16] == 0xFF) continue;
        if (*(short *)(b + 0) != *(short *)(a + 0) || *(short *)(b + 2) != *(short *)(a + 2)) continue;
        jHero = ((unsigned char)b[0x16] == 0x1C);
        if ((jHero && !iHero) || (jHero == iHero && j < i)) return false;
    }
    return true;
}

/* The army a click on (x,y) selects: the original sorts the stack by group
 * tag (+0x11) then fight order, both descending (hero +50), and takes the
 * first (PPC FUN_10021524 / FUN_10021a3c). */
static short StackLeadAt(short x, short y, short player)
{
    unsigned char *gs, *fo;
    short n, i, best = -1;
    long bestKey = -1;
    if (*gGameState == 0) return -1;
    gs = (unsigned char *)*gGameState;
    n = *(short *)(gs + 0x1602);
    if (n > 100) n = 100;
    fo = gs + 0x60C + player * 0x1D;
    for (i = 0; i < n; i++) {
        unsigned char *a = gs + 0x1604 + i * 0x42;
        long key;
        if (a[0x16] == 0xFF || (short)(unsigned char)a[0x15] != player) continue;
        if (*(short *)(a + 0) != x || *(short *)(a + 2) != y) continue;
        key = (long)a[0x11] * 1000 + fo[a[0x16] % 0x1D] + (a[0x16] == 0x1C ? 50 : 0);
        if (key > bestKey) { bestKey = key; best = i; }
    }
    return best;
}

static void BuildStackArrays(short leadArmyIdx)
{
    unsigned char *gs;
    unsigned char *lead;
    short ax, ay, owner, armyCount;
    short ai, si;

    sInfoStackBackupSaved = false;

    if (*gGameState == 0 || leadArmyIdx < 0)
        return;

    gs = (unsigned char *)*gGameState;
    armyCount = *(short *)(gs + 0x1602);
    if (leadArmyIdx >= armyCount)
        return;

    lead = gs + 0x1604 + leadArmyIdx * 0x42;
    ax = *(short *)(lead + 0x00);
    ay = *(short *)(lead + 0x02);
    owner = (short)(unsigned char)lead[0x15];

    /* Clear arrays */
    for (si = 0; si < MAX_STACK; si++) {
        sStackArmyIdx[si] = -1;
        sStackGroupId[si] = -1;
        sStackSelected[si] = 0;
        sStackSep[si] = -1;
    }
    sStackCount = 0;

    /* Put the lead army first */
    sStackArmyIdx[0] = leadArmyIdx;
    sStackGroupId[0] = 0;
    sStackSelected[0] = 1;
    sStackSep[0] = 0;
    sStackCount = 1;

    /* Find all other armies at the same tile with same owner */
    for (ai = 0; ai < armyCount && sStackCount < MAX_STACK; ai++) {
        unsigned char *army = gs + 0x1604 + ai * 0x42;
        if (ai == leadArmyIdx)
            continue;
        if (*(short *)(army + 0x00) == ax &&
            *(short *)(army + 0x02) == ay &&
            (short)(unsigned char)army[0x15] == owner) {
            si = sStackCount;
            sStackArmyIdx[si] = ai;
            /* Check group tag (army+0x11): if same tag as lead AND non-zero,
             * put in same group.  Otherwise give own group. */
            if (lead[0x11] != 0 && army[0x11] == lead[0x11]) {
                sStackGroupId[si] = 0;
                sStackSelected[si] = 1;
                sStackSep[si] = -1;
            } else {
                sStackGroupId[si] = sStackCount;
                sStackSelected[si] = 0;
                sStackSep[si] = 0;
            }
            sStackCount++;
        }
    }

    /* Sort by groupId, then by fight order priority within group.
     * 68k CODE_123 FUN_000008de: secondary key = gs[0x60c + player*0x1d + unitType] */
    {
        short i, j;
        short curPlayer = *(short *)(gs + 0x110);
        unsigned char *fightOrder = gs + 0x60C + curPlayer * 0x1D;
        for (i = 1; i < sStackCount; i++) {
            short tmpIdx = sStackArmyIdx[i];
            short tmpGrp = sStackGroupId[i];
            short tmpSel = sStackSelected[i];
            short tmpSep = sStackSep[i];
            /* Get fight order priority for this unit type */
            unsigned char *armyI = gs + 0x1604 + tmpIdx * 0x42;
            short prioI = (short)(unsigned char)fightOrder[(unsigned char)armyI[0x16]] +
                          ((unsigned char)armyI[0x16] == 0x1C ? 50 : 0);

            j = i - 1;
            while (j >= 0) {
                unsigned char *armyJ = gs + 0x1604 + sStackArmyIdx[j] * 0x42;
                short prioJ = (short)(unsigned char)fightOrder[(unsigned char)armyJ[0x16]] +
                              ((unsigned char)armyJ[0x16] == 0x1C ? 50 : 0);
                /* Sort: groupId ascending, then fight order DESCENDING with the hero
                 * bias, as the original's FUN_10021a3c (hero first) */
                if (sStackGroupId[j] > tmpGrp ||
                    (sStackGroupId[j] == tmpGrp && prioJ < prioI)) {
                    sStackArmyIdx[j + 1] = sStackArmyIdx[j];
                    sStackGroupId[j + 1] = sStackGroupId[j];
                    sStackSelected[j + 1] = sStackSelected[j];
                    sStackSep[j + 1] = sStackSep[j];
                    j--;
                } else {
                    break;
                }
            }
            sStackArmyIdx[j + 1] = tmpIdx;
            sStackGroupId[j + 1] = tmpGrp;
            sStackSelected[j + 1] = tmpSel;
            sStackSep[j + 1] = tmpSep;
        }
    }

    /* Recalculate separators after sort */
    if (sStackCount > 0) {
        sStackSep[0] = 0;
        for (si = 1; si < sStackCount; si++) {
            sStackSep[si] = (sStackGroupId[si] == sStackGroupId[si - 1]) ? -1 : 0;
        }
    }

    /* Renumber groups to be contiguous (0, 1, 2, ...) */
    {
        short remap[MAX_STACK];
        short nextId = 0, ri;
        for (ri = 0; ri < MAX_STACK; ri++) remap[ri] = -1;
        for (si = 0; si < sStackCount; si++) {
            if (remap[sStackGroupId[si]] == -1)
                remap[sStackGroupId[si]] = nextId++;
            sStackGroupId[si] = remap[sStackGroupId[si]];
        }
    }

    /* Find active slot (first selected entry) */
    sActiveSlot = -1;
    for (si = 0; si < sStackCount; si++) {
        if (sStackSelected[si]) {
            sActiveSlot = si;
            break;
        }
    }

    /* Invalidate info window so it switches between stack UI and normal buttons */
    if (gInfoWindow != NULL && *gInfoWindow != 0) {
        GrafPtr savedPort;
        GetPort(&savedPort);
        SetPort((WindowPtr)*gInfoWindow);
        InvalRect(&((WindowPtr)*gInfoWindow)->portRect);
        SetPort(savedPort);
    }
}


/* ===================================================================
 * StackToggleSlot — Toggle army slot in/out of active group.
 * Extracted from ShowStackDialog toggle logic (68k FUN_00001380).
 * =================================================================== */
static void StackToggleSlot(short idx)
{
    short sj;
    if (idx < 0 || idx >= sStackCount) return;

    if (sStackSelected[idx] == 0) {
        /* Join the active group: find groupId of first selected */
        short activeGrp = 0;
        for (sj = 0; sj < sStackCount; sj++) {
            if (sStackSelected[sj]) {
                activeGrp = sStackGroupId[sj];
                break;
            }
        }
        sStackGroupId[idx] = activeGrp;
        sStackSelected[idx] = 1;
    } else {
        /* Leave the group: only if not the last member */
        short memberCount = 0;
        for (sj = 0; sj < sStackCount; sj++) {
            if (sStackGroupId[sj] == sStackGroupId[idx])
                memberCount++;
        }
        if (memberCount > 1) {
            /* Find first unused groupId */
            short newGrp, gj, gUsed;
            for (newGrp = 0; newGrp < MAX_STACK; newGrp++) {
                gUsed = 0;
                for (gj = 0; gj < sStackCount; gj++) {
                    if (sStackGroupId[gj] == newGrp) { gUsed = 1; break; }
                }
                if (!gUsed) break;
            }
            sStackGroupId[idx] = newGrp;
            sStackSelected[idx] = 0;
        }
    }
    /* Recalculate separators */
    if (sStackCount > 0) sStackSep[0] = 0;
    for (sj = 1; sj < sStackCount; sj++)
        sStackSep[sj] = (sStackGroupId[sj] == sStackGroupId[sj - 1]) ? -1 : 0;
}

/* ===================================================================
 * StackGroupAll — Put all stack members in the same group.
 * =================================================================== */
static void StackGroupAll(void)
{
    short sj;
    for (sj = 0; sj < sStackCount; sj++) {
        sStackGroupId[sj] = 0;
        sStackSelected[sj] = 1;
    }
    if (sStackCount > 0) sStackSep[0] = 0;
    for (sj = 1; sj < sStackCount; sj++) sStackSep[sj] = -1;
}

/* ===================================================================
 * StackUngroupAll — Give each army its own group.
 * =================================================================== */
static void StackUngroupAll(void)
{
    short sj;
    for (sj = 0; sj < sStackCount; sj++) {
        sStackGroupId[sj] = sj;
        sStackSelected[sj] = 0;
    }
    if (sStackCount > 0) sStackSelected[0] = 1;
    if (sStackCount > 0) sStackSep[0] = 0;
    for (sj = 1; sj < sStackCount; sj++) sStackSep[sj] = 0;
}

/* ===================================================================
 * StackCommitGroups — Write group tags to army records (army+0x11).
 * Updates sSelectedArmy to first selected member.
 * =================================================================== */
static void StackCommitGroups(void)
{
    unsigned char *gs;
    short sj;
    unsigned char nextTag = 1;
    short tagMap[MAX_STACK];
    short tj;

    if (*gGameState == 0) return;
    gs = (unsigned char *)*gGameState;

    /* Map groupIds to unique group tags (1-8, 0 = ungrouped) */
    for (tj = 0; tj < MAX_STACK; tj++) tagMap[tj] = 0;
    for (sj = 0; sj < sStackCount; sj++) {
        short grp = sStackGroupId[sj];
        if (grp >= 0 && grp < MAX_STACK && tagMap[grp] == 0) {
            short cnt = 0, ck;
            for (ck = 0; ck < sStackCount; ck++) {
                if (sStackGroupId[ck] == grp) cnt++;
            }
            tagMap[grp] = (cnt > 1) ? nextTag++ : 0;
        }
    }
    for (sj = 0; sj < sStackCount; sj++) {
        short aidx = sStackArmyIdx[sj];
        if (aidx >= 0) {
            unsigned char *army = gs + 0x1604 + aidx * 0x42;
            short grp = sStackGroupId[sj];
            army[0x11] = (grp >= 0 && grp < MAX_STACK) ?
                         (unsigned char)tagMap[grp] : 0;
        }
    }
    /* Update sSelectedArmy to first selected */
    for (sj = 0; sj < sStackCount; sj++) {
        if (sStackSelected[sj] && sStackArmyIdx[sj] >= 0) {
            sSelectedArmy = sStackArmyIdx[sj];
            break;
        }
    }
    sInfoStackBackupSaved = false;
}

/* ===================================================================
 * StackRestoreBackup — Restore backup arrays (Cancel).
 * =================================================================== */
static void StackRestoreBackup(void)
{
    short si;
    sStackCount = sBakStackCount;
    sActiveSlot = sBakActiveSlot;
    for (si = 0; si < MAX_STACK; si++) {
        sStackArmyIdx[si]  = sBakArmyIdx[si];
        sStackGroupId[si]  = sBakGroupId[si];
        sStackSelected[si] = sBakSelected[si];
        sStackSep[si]      = sBakSep[si];
    }
    sInfoStackBackupSaved = false;
}

/* ===================================================================
 * StackTakeBackup — Save current stack state for Cancel.
 * =================================================================== */
static void StackTakeBackup(void)
{
    short si;
    sBakStackCount = sStackCount;
    sBakActiveSlot = sActiveSlot;
    for (si = 0; si < MAX_STACK; si++) {
        sBakArmyIdx[si]  = sStackArmyIdx[si];
        sBakGroupId[si]  = sStackGroupId[si];
        sBakSelected[si] = sStackSelected[si];
        sBakSep[si]      = sStackSep[si];
    }
    sInfoStackBackupSaved = true;
}

/* Forward declarations */
static void RemoveArmy(short armyIndex);
static void GetHeroItemBonus(short armyIdx, short *outBattle, short *outCommand,
                             short *outGold, Boolean *outFlying, Boolean *outDoubleMove);
static Boolean GiveItemToHero(short armyIdx, short itemId);
static void ShowCityProductionDialog(short cityIndex);
static void ShowCityBuildSelection(short cityIndex);
static void CheckQuestProgress(short player);
static short GetHeroLevel(short xp);
static Boolean IsHeroFemale(short armyIdx);
static void GetHeroTitle(short level, Boolean female, Str255 out);
static void HandleInfoStackClick(short lx, short ly, Rect *port);
static void DrawInfoStackUI(WindowPtr win, Rect *r);

/* ===================================================================
 * RecalcArmyStrength — Recalculate strength display value (army+0x2A).
 *
 * Formula: SUM(HP * 2) for all occupied unit slots.
 * Must be called whenever unit HP or slot occupancy changes.
 * =================================================================== */
static void RecalcArmyStrength(unsigned char *army)
{
    short str = 0, i;
    for (i = 0; i < 4; i++) {
        if ((unsigned char)army[0x16 + i] != 0xFF)
            str += (short)(unsigned char)army[0x1e + i] * 2;
    }
    *(short *)(army + 0x2a) = str;
}

/* ===================================================================
 * TryMergeArmies — Merge movingArmy into a friendly army at same tile.
 *
 * Transfers units from movingArmy into empty slots of target army.
 * If all units transferred, removes movingArmy.
 * Returns true if movingArmy was removed (fully merged).
 * =================================================================== */
static Boolean TryMergeArmies(short movingIdx)
{
    unsigned char *gs, *movArmy, *tgtArmy;
    short armyCount, mx, my, mOwner, i, slot, tgtSlot;

    if (*gGameState == 0) return false;
    gs = (unsigned char *)*gGameState;
    armyCount = *(short *)(gs + 0x1602);
    if (armyCount > 100) armyCount = 100;
    if (movingIdx < 0 || movingIdx >= armyCount) return false;

    movArmy = gs + 0x1604 + movingIdx * 0x42;
    mx = *(short *)(movArmy + 0x00);
    my = *(short *)(movArmy + 0x02);
    mOwner = (short)(unsigned char)movArmy[0x15];

    /* Find first friendly army at same location (not self) */
    for (i = 0; i < armyCount; i++) {
        if (i == movingIdx) continue;
        tgtArmy = gs + 0x1604 + i * 0x42;
        if (*(short *)(tgtArmy + 0x00) == mx &&
            *(short *)(tgtArmy + 0x02) == my &&
            (short)(unsigned char)tgtArmy[0x15] == mOwner) {

            /* Try to transfer units from moving to target */
            for (slot = 0; slot < 4; slot++) {
                if (movArmy[0x16 + slot] == 0xFF && movArmy[0x1e + slot] == 0)
                    continue;  /* empty slot in moving army */

                /* Find empty slot in target army */
                for (tgtSlot = 0; tgtSlot < 4; tgtSlot++) {
                    if (tgtArmy[0x16 + tgtSlot] == 0xFF ||
                        (tgtArmy[0x16 + tgtSlot] == 0 && tgtArmy[0x1e + tgtSlot] == 0)) {
                        /* Transfer unit */
                        tgtArmy[0x16 + tgtSlot] = movArmy[0x16 + slot];
                        tgtArmy[0x1a + tgtSlot] = movArmy[0x1a + slot];
                        tgtArmy[0x1e + tgtSlot] = movArmy[0x1e + slot];
                        tgtArmy[0x22 + tgtSlot] = movArmy[0x22 + slot];
                        tgtArmy[0x26 + tgtSlot] = movArmy[0x26 + slot];
                        /* Transfer hero name and items if unit is a hero (0x1C) */
                        if (movArmy[0x16 + slot] == 0x1C) {
                            short hni;
                            for (hni = 0; hni < 16; hni++)
                                tgtArmy[0x04 + hni] = movArmy[0x04 + hni];
                            {
                                short itm;
                                for (itm = 0; itm < ITEM_SLOTS; itm++) {
                                    short itemId = *(short *)(movArmy + 0x3A + itm * 2);
                                    *(short *)(tgtArmy + 0x3A + itm * 2) = itemId;
                                    *(short *)(movArmy + 0x3A + itm * 2) = 0;
                                    /* Update item record carrier to target army */
                                    if (itemId >= 1 && itemId <= 22) {
                                        unsigned char *itemRec = gs + 0xD12 + (itemId - 1) * 0x1E;
                                        if (ITEM_STATUS(itemRec) == ITEM_ST_CARRIED)
                                            *(short *)(itemRec + 0x18) = i;
                                    }
                                }
                            }
                            /* Update hero instance record with new army index */
                            if (mOwner >= 0 && mOwner < 8) {
                                unsigned char *hr = gs + 0x1422 + mOwner * 0x2C;
                                if (hr[0x00] != 0 && *(short *)(hr + 0x04) == movingIdx)
                                    *(short *)(hr + 0x04) = i;
                            }
                        }
                        /* Mark source slot as empty */
                        movArmy[0x16 + slot] = 0xFF;
                        movArmy[0x1e + slot] = 0;
                        break;
                    }
                }
            }

            /* Recalculate target army strength */
            RecalcArmyStrength(tgtArmy);

            /* Check if moving army is now empty */
            {
                Boolean allEmpty = true;
                for (slot = 0; slot < 4; slot++) {
                    if (movArmy[0x16 + slot] != 0xFF || movArmy[0x1e + slot] > 0) {
                        allEmpty = false;
                        break;
                    }
                }
                if (allEmpty) {
                    RemoveArmy(movingIdx);
                    return true;
                }
            }

            /* Recalculate moving army strength if partial transfer */
            RecalcArmyStrength(movArmy);
            return false;
        }
    }
    return false;
}


/* ===================================================================
 * GetTerrainType — Returns raw terrain type at a map tile (0-11).
 *
 * 68k terrain types: 0=Road, 1=Bridge, 2=Water, 3=Shore, 4=Forest,
 * 5=Hills, 6=Mountains, 7=Plains, 8=Marsh, 9=Sea,
 * 10=City, 11=Ruin/Temple.
 * =================================================================== */
static short GetTerrainType(short mapX, short mapY)
{
    unsigned char *gs, *mapData;
    if (*gGameState == 0 || *gMapTiles == 0) return -1;
    if (mapX < 0 || mapX >= sMapWidth || mapY < 0 || mapY >= sMapHeight) return -1;
    gs = (unsigned char *)*gGameState;
    mapData = (unsigned char *)*gMapTiles;
    return (short)gs[mapData[mapY * 0xE0 + mapX * 2] + TERRAIN_TYPE_OFS];
}


/* ===================================================================
 * IsDiagonalBlocked — 68k CODE_115 FUN_000014c2 diagonal restriction.
 *
 * Ground units cannot move diagonally between terrain categories 2/3
 * (forest/hills in gs+0x711 system) and other terrain. Prevents
 * "cutting corners" through difficult terrain. Flying units exempt.
 * =================================================================== */
static Boolean IsDiagonalBlocked(short srcX, short srcY, short dstX, short dstY, short unitClass)
{
    /* The original has no corner-cutting rule: all 8 neighbours cost the
     * same; 68k FUN_000014c2 is the single-step water/land check, which the
     * cost flags in GetMovementCost already cover. */
    (void)srcX; (void)srcY; (void)dstX; (void)dstY; (void)unitClass;
    return false;
}

static Boolean IsDiagonalBlockedOld(short srcX, short srcY, short dstX, short dstY, short unitClass)
{
    short dx, dy, srcTT, dstTT;
    Boolean srcRestricted, dstRestricted;

    if (unitClass == 0x0E) return false;  /* flying: no restriction */

    dx = dstX - srcX; dy = dstY - srcY;
    if (dx == 0 || dy == 0) return false;  /* cardinal: no restriction */

    srcTT = GetTerrainType(srcX, srcY);
    dstTT = GetTerrainType(dstX, dstY);
    if (srcTT < 0 || dstTT < 0) return false;

    /* 68k CODE_115 FUN_000014c2: terrain categories 2 (Water) and 3 (Shore)
     * from gs+0x711 are the restricted types for diagonal movement (the 68k
     * literal bytes are '\x02'/'\x03'). Prevents cutting corners between
     * water/shore and land. */
    srcRestricted = (srcTT == 2 || srcTT == 3);
    dstRestricted = (dstTT == 2 || dstTT == 3);

    /* Blocked if one is restricted terrain and the other isn't */
    return (srcRestricted != dstRestricted);
}


/* ===================================================================
 * HasAdjacentThreat — 68k CODE_115 FUN_0000092a.
 *
 * Returns true if there are any enemy armies, enemy cities, or neutral
 * armies in the 3x3 area around (x,y). Used to halt movement when an
 * army has < 2 MP remaining — prevents auto-advancing into danger.
 * =================================================================== */
static Boolean HasAdjacentThreat(short x, short y, short owner)
{
    unsigned char *gs;
    short dx, dy, ac, ci2;
    if (*gGameState == 0) return false;
    gs = (unsigned char *)*gGameState;

    /* Check for enemy/neutral armies in 3x3 area */
    ac = *(short *)(gs + 0x1602);
    if (ac > 100) ac = 100;
    { short ai;
      for (ai = 0; ai < ac; ai++) {
          unsigned char *a = gs + 0x1604 + ai * 0x42;
          short aOwner = (short)(unsigned char)a[0x15];
          if (a[0x16] == 0xFF) continue;
          if (aOwner == owner) continue;
          /* Check diplomacy: only threats from enemies or neutrals */
          if (aOwner >= 0 && aOwner < 8 && owner >= 0 && owner < 8) {
              if (DIPLO_GET_STATE(*(gs + 0x1582 + owner * 8 + aOwner)) != DIPLO_WAR &&
                  aOwner != 0x0F) continue;
          }
          dx = *(short *)(a + 0x00) - x;
          dy = *(short *)(a + 0x02) - y;
          if (dx >= -1 && dx <= 1 && dy >= -1 && dy <= 1) return true;
      }
    }

    /* 68k CODE_115 FUN_0000092a: check if army is ON an uncleared ruin.
     * Armies halt at ruins so the player can decide to search. */
    { short cc2 = sCityCount;
      if (cc2 > 139) cc2 = 139;
      for (ci2 = 0; ci2 < cc2; ci2++) {
          unsigned char *c2 = sCityData + ci2 * 0x20;
          if (*(short *)(c2 + 0x00) == x && *(short *)(c2 + 0x02) == y) {
              short sType2 = (short)(unsigned char)c2[0x17];
              if (sType2 >= 2) {
                  /* On a ruin/temple: halt if not yet visited by this player */
                  unsigned char visited = c2[0x1E];
                  if (!(visited & (1 << owner))) return true;
              }
              break;
          }
      }
    }

    /* 68k CODE_115 FUN_0000092a: halt near ANY city tile (all owners).
     * The 68k checks terrain type == 10 (city) regardless of city owner,
     * preventing auto-advance into cities during path execution. */
    { short cc = sCityCount;
      if (cc > 139) cc = 139;
      for (ci2 = 0; ci2 < cc; ci2++) {
          unsigned char *c = sCityData + ci2 * 0x20;
          short sType = (short)(unsigned char)c[0x17];
          if (sType >= 2) continue;  /* skip ruins/temples */
          dx = *(short *)(c + 0x00) - x;
          dy = *(short *)(c + 0x02) - y;
          if (dx >= -1 && dx <= 1 && dy >= -1 && dy <= 1) return true;
      }
    }
    return false;
}


/* ===================================================================
 * GetMovementCost — Returns movement point cost to enter a map tile.
 *
 * Uses terrain properties table (gs+0x711) and movement cost table
 * (sMoveCostTable, separate from fight order at gs+0x60C).
 * unitClass is the army's primary unit type (0-28).
 * Returns 0 if impassable, otherwise 1-4 movement points.
 * =================================================================== */
static short GetMovementCost(short mapX, short mapY, short unitClass)
{
    /* The original's rules are hard-coded (68k CODE_042 FUN_00001670 cost map,
     * CODE_115 FUN_00001a70 wavefront; table at 68k 0x15cbe / PPC data
     * 0x17576), per terrain type of gs+0x711:
     *   Road 1, Bridge 1, Water 1 (water), Shore 2 (water), Forest 4,
     *   Hills 6, Mountains blocked, Plains 2, Marsh 5, "Sea" 2, City 1, Ruin 2.
     * Road overlay (RD & 0x1F) makes any tile cost 1. Land stacks can't enter
     * water tiles; units with the hills (DAT byte 0x3A) / forest (0x38)
     * ability cross those at 2. Flyers pay 1 on road/bridge/city, else 2.
     * The hero has no abilities and is a land unit (no mountains).
     * (Foreign cities, which the original blocks except as an attack target,
     * stay enterable here so the remake's attack paths keep working.) */
    static const unsigned char kCost[12] = {1, 1, 1, 2, 4, 6, 0, 2, 5, 2, 1, 2};
    static const unsigned char kFlag[12] = {0x10, 0x18, 0x08, 0x08, 0x50, 0x30,
                                            0x10, 0x10, 0x10, 0x10, 0x90, 0x10};
    unsigned char *gs, *mapData, *ute = NULL;
    short type, c, f;
    Boolean road = false, flying, naval;

    if (*gGameState == 0 || *gMapTiles == 0)
        return 1;
    if (mapX < 0 || mapX >= sMapWidth || mapY < 0 || mapY >= sMapHeight)
        return 0;
    gs = (unsigned char *)*gGameState;
    mapData = (unsigned char *)*gMapTiles;
    type = gs[mapData[mapY * 0xE0 + mapX * 2] + TERRAIN_TYPE_OFS];
    if (type > 11) type = 7;
    if (*gRoadData != 0 && mapX < 112 && mapY < 156)
        road = (((unsigned char *)*gRoadData)[mapY * 112 + mapX] & 0x1F) != 0;
    c = kCost[type];
    f = kFlag[type];
    if (road) c = 1;

    if (unitClass >= 0 && unitClass < sUnitTypeCount && sUnitTypesLoaded)
        ute = sUnitTypeTable + unitClass * UNIT_TYPE_ENTRY;
    flying = (unitClass == UNIT_CLASS_FLIGHT) || (ute && ute[UTE_STAT_FLYING] >= 1);
    naval  = (ute && ute[UTE_STAT_NAVAL] >= 1);

    /* Foreign and neutral cities block movement unless the city itself is the
     * destination (the original routes around them: drag past a neutral
     * city on turn 2 stopped beside it; attacking it targets its footprint). */
    if (type == 10) {
        short ci, n = sCityCount > 139 ? 139 : sCityCount, me = *(short *)(gs + 0x110);
        for (ci = 0; ci < n; ci++) {
            unsigned char *ct = sCityData + ci * 0x20;
            short ddx = mapX - *(short *)(ct + 0), ddy = mapY - *(short *)(ct + 2);
            if (ct[0x17] >= 2 || ddx < 0 || ddx > 1 || ddy < 0 || ddy > 1) continue;
            if (*(short *)(ct + 4) != me) {
                short tdx = sPathTargetX - *(short *)(ct + 0), tdy = sPathTargetY - *(short *)(ct + 2);
                if (!(tdx >= 0 && tdx <= 1 && tdy >= 0 && tdy <= 1)) return 0;
            }
            break;
        }
    }

    if (flying)
        return (type == 0 || type == 1 || type == 10 || road) ? 1 : 2;
    if (naval) {
        if (f & 0x08) return c;                     /* water 1, shore 2 */
        if (type == 1 || type == 10) return 1;      /* bridge / port city */
        return 0;
    }
    if (!(f & 0x10)) return 0;                      /* land stack into water */
    if (c == 0) return 0;                           /* mountains */
    if (c > 2 && ute != NULL &&
        ((ute[0x3A] && (f & 0x20)) || (ute[0x38] && (f & 0x40))))
        c = 2;                                      /* hills / forest ability */
    return c;
}


/* ===================================================================
 * ComputePathGridOnly — Build cost grid without a specific destination.
 *
 * Runs phases 1-3 of ComputeWavefrontPath (terrain cache + init +
 * wavefront expansion) to fill sPathCostGrid[] with shortest costs
 * from (srcX,srcY) to every reachable tile. Used for hover preview
 * so the expensive flood-fill runs once per army selection, and cheap
 * tracebacks can be done per hover tile.
 * =================================================================== */
static void ComputePathGridOnly(short srcX, short srcY, short unitClass)
{
    short x, y, d, pass;
    short maxX, maxY;
    Boolean changed;

    sPreviewGridValid = false;
    if (srcX < 0 || srcY < 0) return;
    maxX = sMapWidth;  if (maxX > PATH_GRID_W) maxX = PATH_GRID_W;
    maxY = sMapHeight; if (maxY > PATH_GRID_H) maxY = PATH_GRID_H;
    if (srcX >= maxX || srcY >= maxY) return;

    /* --- Phase 1: Build terrain cost cache --- */
    for (y = 0; y < maxY; y++) {
        short rowOff = y * PATH_GRID_W;
        for (x = 0; x < maxX; x++) {
            short c = GetMovementCost(x, y, unitClass);
            sPathTerrainCache[rowOff + x] = (unsigned char)(c > 255 ? 255 : c);
            { short tt = GetTerrainType(x, y);
              sPathTerrainTypeCache[rowOff + x] = (unsigned char)(tt < 0 ? 0 : tt); }
        }
    }

    /* --- Phase 2: Initialize cost grid --- */
    {
        long total = PATH_GRID_W * PATH_GRID_H;
        long i;
        for (i = 0; i < total; i++)
            sPathCostGrid[i] = PATH_COST_MAX;
    }
    for (y = 0; y < maxY; y++) {
        short rowOff = y * PATH_GRID_W;
        for (x = 0; x < maxX; x++) {
            if (sPathTerrainCache[rowOff + x] == 0)
                sPathCostGrid[rowOff + x] = PATH_COST_BLOCK;
        }
    }
    if (sOptHiddenMap && *gGameState != 0) {
        unsigned char *pgs = (unsigned char *)*gGameState;
        short curP = *(short *)(pgs + 0x110);
        if (curP >= 0 && curP < 8 && *(short *)(pgs + 0xd0 + curP * 2) == 0) {
            for (y = 0; y < maxY; y++) {
                short rowOff = y * PATH_GRID_W;
                for (x = 0; x < maxX; x++) {
                    if (!FogGetBit(sFogExplored[curP], x, y))
                        sPathCostGrid[rowOff + x] = PATH_COST_BLOCK;
                }
            }
        }
    }
    sPathCostGrid[srcY * PATH_GRID_W + srcX] = 0;

    /* --- Phase 3: Wavefront expansion --- */
    for (pass = 0; pass < 50; pass++) {
        changed = false;
        for (y = 0; y < maxY; y++) {
            for (x = 0; x < maxX; x++) {
                short cur = sPathCostGrid[y * PATH_GRID_W + x];
                if (cur >= PATH_COST_MAX) continue;
                for (d = 0; d < 8; d++) {
                    short nx = x + sPathDX[d], ny = y + sPathDY[d];
                    short nc, newC;
                    if (nx < 0 || nx >= maxX || ny < 0 || ny >= maxY) continue;
                    if (sPathCostGrid[ny * PATH_GRID_W + nx] == PATH_COST_BLOCK) continue;
                    if (0 && (d & 1)) {   /* no diagonal rule in the original (CODE_115) */
                        unsigned char st = sPathTerrainTypeCache[y * PATH_GRID_W + x];
                        unsigned char dt = sPathTerrainTypeCache[ny * PATH_GRID_W + nx];
                        if ((st == 2 || st == 3) != (dt == 2 || dt == 3)) continue;
                    }
                    nc = (short)sPathTerrainCache[ny * PATH_GRID_W + nx];
                    if (nc <= 0) continue;
                    newC = cur + nc;
                    if (newC < sPathCostGrid[ny * PATH_GRID_W + nx]) {
                        sPathCostGrid[ny * PATH_GRID_W + nx] = newC;
                        changed = true;
                    }
                }
            }
        }
        for (y = maxY - 1; y >= 0; y--) {
            for (x = maxX - 1; x >= 0; x--) {
                short cur = sPathCostGrid[y * PATH_GRID_W + x];
                if (cur >= PATH_COST_MAX) continue;
                for (d = 0; d < 8; d++) {
                    short nx = x + sPathDX[d], ny = y + sPathDY[d];
                    short nc, newC;
                    if (nx < 0 || nx >= maxX || ny < 0 || ny >= maxY) continue;
                    if (sPathCostGrid[ny * PATH_GRID_W + nx] == PATH_COST_BLOCK) continue;
                    if (0 && (d & 1)) {   /* no diagonal rule in the original (CODE_115) */
                        unsigned char st = sPathTerrainTypeCache[y * PATH_GRID_W + x];
                        unsigned char dt = sPathTerrainTypeCache[ny * PATH_GRID_W + nx];
                        if ((st == 2 || st == 3) != (dt == 2 || dt == 3)) continue;
                    }
                    nc = (short)sPathTerrainCache[ny * PATH_GRID_W + nx];
                    if (nc <= 0) continue;
                    newC = cur + nc;
                    if (newC < sPathCostGrid[ny * PATH_GRID_W + nx]) {
                        sPathCostGrid[ny * PATH_GRID_W + nx] = newC;
                        changed = true;
                    }
                }
            }
        }
        if (!changed) break;
        changed = false;
        for (y = 0; y < maxY; y++) {
            for (x = maxX - 1; x >= 0; x--) {
                short cur = sPathCostGrid[y * PATH_GRID_W + x];
                if (cur >= PATH_COST_MAX) continue;
                for (d = 0; d < 8; d++) {
                    short nx = x + sPathDX[d], ny = y + sPathDY[d];
                    short nc, newC;
                    if (nx < 0 || nx >= maxX || ny < 0 || ny >= maxY) continue;
                    if (sPathCostGrid[ny * PATH_GRID_W + nx] == PATH_COST_BLOCK) continue;
                    if (0 && (d & 1)) {   /* no diagonal rule in the original (CODE_115) */
                        unsigned char st = sPathTerrainTypeCache[y * PATH_GRID_W + x];
                        unsigned char dt = sPathTerrainTypeCache[ny * PATH_GRID_W + nx];
                        if ((st == 2 || st == 3) != (dt == 2 || dt == 3)) continue;
                    }
                    nc = (short)sPathTerrainCache[ny * PATH_GRID_W + nx];
                    if (nc <= 0) continue;
                    newC = cur + nc;
                    if (newC < sPathCostGrid[ny * PATH_GRID_W + nx]) {
                        sPathCostGrid[ny * PATH_GRID_W + nx] = newC;
                        changed = true;
                    }
                }
            }
        }
        for (y = maxY - 1; y >= 0; y--) {
            for (x = 0; x < maxX; x++) {
                short cur = sPathCostGrid[y * PATH_GRID_W + x];
                if (cur >= PATH_COST_MAX) continue;
                for (d = 0; d < 8; d++) {
                    short nx = x + sPathDX[d], ny = y + sPathDY[d];
                    short nc, newC;
                    if (nx < 0 || nx >= maxX || ny < 0 || ny >= maxY) continue;
                    if (sPathCostGrid[ny * PATH_GRID_W + nx] == PATH_COST_BLOCK) continue;
                    if (0 && (d & 1)) {   /* no diagonal rule in the original (CODE_115) */
                        unsigned char st = sPathTerrainTypeCache[y * PATH_GRID_W + x];
                        unsigned char dt = sPathTerrainTypeCache[ny * PATH_GRID_W + nx];
                        if ((st == 2 || st == 3) != (dt == 2 || dt == 3)) continue;
                    }
                    nc = (short)sPathTerrainCache[ny * PATH_GRID_W + nx];
                    if (nc <= 0) continue;
                    newC = cur + nc;
                    if (newC < sPathCostGrid[ny * PATH_GRID_W + nx]) {
                        sPathCostGrid[ny * PATH_GRID_W + nx] = newC;
                        changed = true;
                    }
                }
            }
        }
        if (!changed) break;
    }

    sPreviewGridValid = true;
}

/* ===================================================================
 * TracePreviewPath — Trace optimal path from precomputed cost grid.
 *
 * Walks backward from (dstX,dstY) to (srcX,srcY) following steepest
 * descent in sPathCostGrid[], storing tile coordinates in
 * sPreviewPathX/Y[]. Requires sPreviewGridValid == true.
 * =================================================================== */
static void TracePreviewPath(short srcX, short srcY, short dstX, short dstY)
{
    short cx = dstX, cy = dstY;
    short maxX, maxY;
    short revLen = 0;
    short revX[PATH_MAX_STEPS], revY[PATH_MAX_STEPS];

    sPreviewPathLen = 0;
    maxX = sMapWidth;  if (maxX > PATH_GRID_W) maxX = PATH_GRID_W;
    maxY = sMapHeight; if (maxY > PATH_GRID_H) maxY = PATH_GRID_H;
    if (dstX < 0 || dstY < 0 || dstX >= maxX || dstY >= maxY) return;
    if (sPathCostGrid[dstY * PATH_GRID_W + dstX] >= PATH_COST_MAX) return;
    if (srcX == dstX && srcY == dstY) return;

    /* Walk backward from dst to src following steepest cost descent */
    while ((cx != srcX || cy != srcY) && revLen < PATH_MAX_STEPS) {
        short bestDir = -1, bestCost = sPathCostGrid[cy * PATH_GRID_W + cx], d;
        short bestNX = cx, bestNY = cy;
        revX[revLen] = cx; revY[revLen] = cy; revLen++;
        for (d = 0; d < 8; d++) {
            short nx = cx + sPathDX[d], ny = cy + sPathDY[d], nc;
            if (nx < 0 || nx >= maxX || ny < 0 || ny >= maxY) continue;
            nc = sPathCostGrid[ny * PATH_GRID_W + nx];
            if (nc < bestCost && nc < PATH_COST_MAX) {
                bestCost = nc; bestDir = d; bestNX = nx; bestNY = ny;
            }
        }
        if (bestDir < 0) break;
        cx = bestNX; cy = bestNY;
    }

    /* Build forward path: source first, then reversed traceback */
    sPreviewPathX[0] = srcX; sPreviewPathY[0] = srcY;
    sPreviewPathLen = 1;
    { short ri;
      for (ri = revLen - 1; ri >= 0 && sPreviewPathLen < PATH_MAX_STEPS; ri--) {
          sPreviewPathX[sPreviewPathLen] = revX[ri];
          sPreviewPathY[sPreviewPathLen] = revY[ri];
          sPreviewPathLen++;
      }
    }
}

/* ===================================================================
 * ComputeWavefrontPath — Dijkstra flood-fill pathfinder.
 *
 * 68k CODE_115 FUN_000012c6: computes optimal path from (srcX,srcY)
 * to (dstX,dstY) for a given unit class. Uses 4-direction alternating
 * sweeps over a 112x156 cost grid.
 *
 * Returns number of direction steps in sPathDirBuffer[], or -1 if
 * destination is unreachable. Direction encoding: 0=N..7=NW, 0xFF=end.
 * =================================================================== */
static short ComputeWavefrontPath(short srcX, short srcY,
                                   short dstX, short dstY,
                                   short unitClass)
{
    short x, y, d, pass;
    sPathTargetX = dstX; sPathTargetY = dstY;    /* a foreign city is enterable only as the target */
    short maxX, maxY;
    Boolean changed;

    if (srcX < 0 || srcY < 0 || dstX < 0 || dstY < 0) return -1;
    maxX = sMapWidth;  if (maxX > PATH_GRID_W) maxX = PATH_GRID_W;
    maxY = sMapHeight; if (maxY > PATH_GRID_H) maxY = PATH_GRID_H;
    if (srcX >= maxX || srcY >= maxY || dstX >= maxX || dstY >= maxY) return -1;
    if (srcX == dstX && srcY == dstY) { sPathLength = 0; sPathDirBuffer[0] = 0xFF; return 0; }

    /* --- Phase 1: Build terrain cost cache (one GetMovementCost per tile) --- */
    for (y = 0; y < maxY; y++) {
        short rowOff = y * PATH_GRID_W;
        for (x = 0; x < maxX; x++) {
            short c = GetMovementCost(x, y, unitClass);
            sPathTerrainCache[rowOff + x] = (unsigned char)(c > 255 ? 255 : c);
            /* Cache terrain type for diagonal restriction check (68k FUN_000014c2) */
            { short tt = GetTerrainType(x, y);
              sPathTerrainTypeCache[rowOff + x] = (unsigned char)(tt < 0 ? 0 : tt); }
        }
    }

    /* --- Phase 2: Initialize cost grid --- */
    {
        long total = PATH_GRID_W * PATH_GRID_H;
        long i;
        for (i = 0; i < total; i++)
            sPathCostGrid[i] = PATH_COST_MAX;
    }
    /* Mark impassable tiles */
    for (y = 0; y < maxY; y++) {
        short rowOff = y * PATH_GRID_W;
        for (x = 0; x < maxX; x++) {
            if (sPathTerrainCache[rowOff + x] == 0)
                sPathCostGrid[rowOff + x] = PATH_COST_BLOCK;
        }
    }
    /* 68k CODE_115 FUN_000025b8: for HUMAN players, unexplored fog tiles
     * are impassable. AI players can pathfind through fog. */
    if (sOptHiddenMap && *gGameState != 0) {
        unsigned char *pgs = (unsigned char *)*gGameState;
        short curP = *(short *)(pgs + 0x110);
        if (curP >= 0 && curP < 8 && *(short *)(pgs + 0xd0 + curP * 2) == 0) {
            for (y = 0; y < maxY; y++) {
                short rowOff = y * PATH_GRID_W;
                for (x = 0; x < maxX; x++) {
                    if (!FogGetBit(sFogExplored[curP], x, y))
                        sPathCostGrid[rowOff + x] = PATH_COST_BLOCK;
                }
            }
        }
    }
    /* Source tile: cost 0 (68k sets -10, but 0 is equivalent for our sweep) */
    sPathCostGrid[srcY * PATH_GRID_W + srcX] = 0;
    /* Destination must be reachable — unblock it even if terrain says impassable
     * (army can move TO a tile with enemies for combat) */
    if (sPathCostGrid[dstY * PATH_GRID_W + dstX] == PATH_COST_BLOCK)
        sPathCostGrid[dstY * PATH_GRID_W + dstX] = PATH_COST_MAX;

    /* --- Phase 3: Wavefront expansion — 4-direction alternating sweeps ---
     * 68k CODE_115 FUN_000015a8: N→S/W→E, S→N/E→W, N→S/E→W, S→N/W→E.
     * Repeat until no cost updates (converged). Max 50 iterations. */
    for (pass = 0; pass < 50; pass++) {
        changed = false;

        /* Sweep 1: N→S, W→E (top-left to bottom-right) */
        for (y = 0; y < maxY; y++) {
            for (x = 0; x < maxX; x++) {
                short cur = sPathCostGrid[y * PATH_GRID_W + x];
                if (cur >= PATH_COST_MAX) continue;
                for (d = 0; d < 8; d++) {
                    short nx = x + sPathDX[d], ny = y + sPathDY[d];
                    short nc, newC;
                    if (nx < 0 || nx >= maxX || ny < 0 || ny >= maxY) continue;
                    if (sPathCostGrid[ny * PATH_GRID_W + nx] == PATH_COST_BLOCK) continue;
                    /* 68k FUN_000014c2: diagonal terrain restriction (types 2/3) */
                    if (0 && (d & 1)) {   /* no diagonal rule in the original (CODE_115) */
                        unsigned char st = sPathTerrainTypeCache[y * PATH_GRID_W + x];
                        unsigned char dt = sPathTerrainTypeCache[ny * PATH_GRID_W + nx];
                        if ((st == 2 || st == 3) != (dt == 2 || dt == 3)) continue;
                    }
                    nc = (short)sPathTerrainCache[ny * PATH_GRID_W + nx];
                    if (nc <= 0) continue;
                    newC = cur + nc;
                    if (newC < sPathCostGrid[ny * PATH_GRID_W + nx]) {
                        sPathCostGrid[ny * PATH_GRID_W + nx] = newC;
                        changed = true;
                    }
                }
            }
        }

        /* Sweep 2: S→N, E→W (bottom-right to top-left) */
        for (y = maxY - 1; y >= 0; y--) {
            for (x = maxX - 1; x >= 0; x--) {
                short cur = sPathCostGrid[y * PATH_GRID_W + x];
                if (cur >= PATH_COST_MAX) continue;
                for (d = 0; d < 8; d++) {
                    short nx = x + sPathDX[d], ny = y + sPathDY[d];
                    short nc, newC;
                    if (nx < 0 || nx >= maxX || ny < 0 || ny >= maxY) continue;
                    if (sPathCostGrid[ny * PATH_GRID_W + nx] == PATH_COST_BLOCK) continue;
                    /* 68k FUN_000014c2: diagonal terrain restriction (types 2/3) */
                    if (0 && (d & 1)) {   /* no diagonal rule in the original (CODE_115) */
                        unsigned char st = sPathTerrainTypeCache[y * PATH_GRID_W + x];
                        unsigned char dt = sPathTerrainTypeCache[ny * PATH_GRID_W + nx];
                        if ((st == 2 || st == 3) != (dt == 2 || dt == 3)) continue;
                    }
                    nc = (short)sPathTerrainCache[ny * PATH_GRID_W + nx];
                    if (nc <= 0) continue;
                    newC = cur + nc;
                    if (newC < sPathCostGrid[ny * PATH_GRID_W + nx]) {
                        sPathCostGrid[ny * PATH_GRID_W + nx] = newC;
                        changed = true;
                    }
                }
            }
        }

        if (!changed) break;  /* Converged */

        /* Sweep 3: N→S, E→W */
        changed = false;
        for (y = 0; y < maxY; y++) {
            for (x = maxX - 1; x >= 0; x--) {
                short cur = sPathCostGrid[y * PATH_GRID_W + x];
                if (cur >= PATH_COST_MAX) continue;
                for (d = 0; d < 8; d++) {
                    short nx = x + sPathDX[d], ny = y + sPathDY[d];
                    short nc, newC;
                    if (nx < 0 || nx >= maxX || ny < 0 || ny >= maxY) continue;
                    if (sPathCostGrid[ny * PATH_GRID_W + nx] == PATH_COST_BLOCK) continue;
                    /* 68k FUN_000014c2: diagonal terrain restriction (types 2/3) */
                    if (0 && (d & 1)) {   /* no diagonal rule in the original (CODE_115) */
                        unsigned char st = sPathTerrainTypeCache[y * PATH_GRID_W + x];
                        unsigned char dt = sPathTerrainTypeCache[ny * PATH_GRID_W + nx];
                        if ((st == 2 || st == 3) != (dt == 2 || dt == 3)) continue;
                    }
                    nc = (short)sPathTerrainCache[ny * PATH_GRID_W + nx];
                    if (nc <= 0) continue;
                    newC = cur + nc;
                    if (newC < sPathCostGrid[ny * PATH_GRID_W + nx]) {
                        sPathCostGrid[ny * PATH_GRID_W + nx] = newC;
                        changed = true;
                    }
                }
            }
        }

        /* Sweep 4: S→N, W→E */
        for (y = maxY - 1; y >= 0; y--) {
            for (x = 0; x < maxX; x++) {
                short cur = sPathCostGrid[y * PATH_GRID_W + x];
                if (cur >= PATH_COST_MAX) continue;
                for (d = 0; d < 8; d++) {
                    short nx = x + sPathDX[d], ny = y + sPathDY[d];
                    short nc, newC;
                    if (nx < 0 || nx >= maxX || ny < 0 || ny >= maxY) continue;
                    if (sPathCostGrid[ny * PATH_GRID_W + nx] == PATH_COST_BLOCK) continue;
                    /* 68k FUN_000014c2: diagonal terrain restriction (types 2/3) */
                    if (0 && (d & 1)) {   /* no diagonal rule in the original (CODE_115) */
                        unsigned char st = sPathTerrainTypeCache[y * PATH_GRID_W + x];
                        unsigned char dt = sPathTerrainTypeCache[ny * PATH_GRID_W + nx];
                        if ((st == 2 || st == 3) != (dt == 2 || dt == 3)) continue;
                    }
                    nc = (short)sPathTerrainCache[ny * PATH_GRID_W + nx];
                    if (nc <= 0) continue;
                    newC = cur + nc;
                    if (newC < sPathCostGrid[ny * PATH_GRID_W + nx]) {
                        sPathCostGrid[ny * PATH_GRID_W + nx] = newC;
                        changed = true;
                    }
                }
            }
        }

        if (!changed) break;
    }

    /* --- Phase 4: Check destination reachability --- */
    if (sPathCostGrid[dstY * PATH_GRID_W + dstX] >= PATH_COST_MAX)
        return -1;

    /* --- Phase 5: Traceback — follow steepest descent from dst to src ---
     * 68k CODE_115 FUN_000029c6: walks backward, stores reversed directions.
     * We collect back-to-source directions, then reverse + rotate by 4. */
    {
        short cx = dstX, cy = dstY;
        short revLen = 0;
        unsigned char revDirs[PATH_MAX_STEPS];

        while ((cx != srcX || cy != srcY) && revLen < PATH_MAX_STEPS - 1) {
            short bestDir = -1;
            short bestCost = sPathCostGrid[cy * PATH_GRID_W + cx];
            short bestNX = cx, bestNY = cy;

            for (d = 0; d < 8; d++) {
                short nx = cx + sPathDX[d], ny = cy + sPathDY[d];
                short nc;
                if (nx < 0 || nx >= maxX || ny < 0 || ny >= maxY) continue;
                nc = sPathCostGrid[ny * PATH_GRID_W + nx];
                if (nc < bestCost && nc < PATH_COST_MAX) {
                    bestCost = nc;
                    bestDir = d;
                    bestNX = nx;
                    bestNY = ny;
                }
            }

            if (bestDir < 0) break;  /* stuck — shouldn't happen */
            revDirs[revLen++] = (unsigned char)bestDir;
            cx = bestNX;
            cy = bestNY;
        }

        /* Reverse and rotate directions: back-to-source dir D → forward dir (D+4)%8 */
        sPathLength = 0;
        {
            short ri;
            for (ri = revLen - 1; ri >= 0; ri--)
                sPathDirBuffer[sPathLength++] = (unsigned char)((revDirs[ri] + 4) % 8);
        }
        sPathDirBuffer[sPathLength] = 0xFF;
    }

    return sPathLength;
}


/* ===================================================================
 * ExecutePathSteps — Execute pre-computed path for an army.
 *
 * Reads directions from sPathDirBuffer[], moves the army step by step,
 * deducting movement costs. Stops when: out of MP, combat encountered,
 * path ends, or tile blocked. Also moves grouped armies.
 *
 * Returns: number of steps actually taken (0 if none possible).
 * =================================================================== */
static short ExecutePathSteps(short armyIdx)
{
    unsigned char *gs, *army;
    short stepsTaken = 0, step;
    short armyCount;

    if (*gGameState == 0) return 0;
    gs = (unsigned char *)*gGameState;
    armyCount = *(short *)(gs + 0x1602);
    if (armyCount > 100) armyCount = 100;
    if (armyIdx < 0 || armyIdx >= armyCount) return 0;

    for (step = 0; step < sPathLength && sPathDirBuffer[step] != 0xFF; step++) {
        short dir, curX, curY, newX, newY;
        short movePts, unitClass, cost;

        /* Re-read army pointer (may shift due to RemoveArmy in combat) */
        armyCount = *(short *)(gs + 0x1602);
        if (armyCount > 100) armyCount = 100;
        if (armyIdx >= armyCount) break;
        army = gs + 0x1604 + armyIdx * 0x42;

        movePts = (short)(unsigned char)army[0x2e];
        if (movePts <= 0) break;

        dir = (short)sPathDirBuffer[step];
        if (dir < 0 || dir > 7) break;

        curX = *(short *)(army + 0x00);
        curY = *(short *)(army + 0x02);
        newX = curX + sPathDX[dir];
        newY = curY + sPathDY[dir];

        if (newX < 0 || newX >= sMapWidth || newY < 0 || newY >= sMapHeight)
            break;

        unitClass = GetEffectiveUnitClass(armyIdx);
        cost = GetMovementCost(newX, newY, unitClass);
        if (cost <= 0 || movePts < cost) break;

        /* 68k CODE_115 FUN_000014c2: diagonal terrain restriction.
         * Ground units can't move diagonally between terrain types 2/3
         * and non-2/3 terrain (prevents cutting corners). */
        if (IsDiagonalBlocked(curX, curY, newX, newY, unitClass)) break;

        /* 68k CODE_115 FUN_000003c4: tile stack limit of 8 armies.
         * Count armies already at destination; if adding our group would exceed 8, stop. */
        { short tileCount = 0, groupSize = 1, gi3;
            for (gi3 = 0; gi3 < sStackCount; gi3++)
                if (sStackSelected[gi3] && sStackArmyIdx[gi3] >= 0 &&
                    sStackArmyIdx[gi3] != armyIdx) groupSize++;
            { short ti;
              for (ti = 0; ti < armyCount; ti++) {
                  unsigned char *ta = gs + 0x1604 + ti * 0x42;
                  if (ta[0x16] == 0xFF) continue;
                  if (*(short *)(ta + 0x00) == newX && *(short *)(ta + 0x02) == newY)
                      tileCount++;
              }
            }
            if (tileCount + groupSize > 8) break;
        }

        /* Group movement: check ALL selected members can afford this step.
         * 68k CODE_115 FUN_00001208: uses LEAD army's cost for the check,
         * not individual per-unit costs. All members pay the same. */
        { short gi2; Boolean groupBlocked = false;
            for (gi2 = 0; gi2 < sStackCount && !groupBlocked; gi2++) {
                if (sStackSelected[gi2] && sStackArmyIdx[gi2] >= 0 &&
                    sStackArmyIdx[gi2] != armyIdx) {
                    unsigned char *ga2 = gs + 0x1604 + sStackArmyIdx[gi2] * 0x42;
                    short gMove2 = (short)(unsigned char)ga2[0x2e];
                    if (cost <= 0 || gMove2 < cost) groupBlocked = true;
                }
            }
            if (groupBlocked) break;
        }

        /* Store undo info for first step */
        if (stepsTaken == 0) {
            sUndoArmyIdx = armyIdx;
            sUndoFromX = curX;
            sUndoFromY = curY;
            sUndoMovePts = movePts;
            sUndoFortify = (short)(unsigned char)army[0x2d];
        }

        /* Move lead army: clear fortification map bit on old tile (68k CODE_080 FUN_00001a30) */
        { short oldX = *(short *)(army + 0x00);
          short oldY = *(short *)(army + 0x02);
          if (*gMapTiles != 0 && oldX >= 0 && oldX < sMapWidth && oldY >= 0 && oldY < sMapHeight) {
              unsigned char *md = (unsigned char *)*gMapTiles;
              md[oldY * 0xE0 + oldX * 2 + 1] &= ~0x20;
          }
        }
        *(short *)(army + 0x00) = newX;
        *(short *)(army + 0x02) = newY;
        army[0x2e] = (unsigned char)(movePts - cost);
        army[0x2d] = 0;  /* clear fortification on move */
        /* Clear ext_state guard flag on move */
        if (*gExtState != 0) ((unsigned char *)*gExtState)[0x56 + armyIdx] = 0;

        /* Move grouped armies — 68k CODE_115 FUN_000003c4: all members
         * deducted the SAME cost as the lead army (path was computed for
         * lead's unit class). Individual per-unit costs are NOT used. */
        { short gi;
            for (gi = 0; gi < sStackCount; gi++) {
                if (sStackSelected[gi] && sStackArmyIdx[gi] >= 0 &&
                    sStackArmyIdx[gi] != armyIdx) {
                    unsigned char *ga = gs + 0x1604 + sStackArmyIdx[gi] * 0x42;
                    short gMove = (short)(unsigned char)ga[0x2e];
                    *(short *)(ga + 0x00) = newX;
                    *(short *)(ga + 0x02) = newY;
                    ga[0x2d] = 0;
                    ga[0x2e] = (unsigned char)(gMove - cost);  /* same cost as lead */
                    if (*gExtState != 0) ((unsigned char *)*gExtState)[0x56 + sStackArmyIdx[gi]] = 0;
                }
            }
        }

        stepsTaken++;

        /* Fog reveal (68k CODE_067: naval=5x5, normal=3x3) */
        if (sOptHiddenMap) {
            short armyOwner = (short)(unsigned char)army[0x15];
            FogRevealUnit(armyOwner, newX, newY, ArmyIsNaval(armyIdx));
        }

        /* 68k CODE_074: auto-pickup ground items (dropped by dead heroes) */
        CheckGroundItemPickup(armyIdx);

        /* Combat check — stops path execution */
        if (CheckAndResolveCombat(armyIdx)) {
            armyCount = *(short *)(gs + 0x1602);
            if (armyCount > 100) armyCount = 100;
            break;
        }

        /* Try merging with friendly army */
        if (TryMergeArmies(armyIdx)) {
            armyCount = *(short *)(gs + 0x1602);
            if (armyCount > 100) armyCount = 100;
            break;
        }

        /* Auto-search ruins */
        TryAutoSearchRuin(armyIdx);

        /* Check if reached destination */
        if (*(short *)(army + 0x00) == *(short *)(army + 0x34) &&
            *(short *)(army + 0x02) == *(short *)(army + 0x36)) {
            *(short *)(army + 0x32) = 0;
            break;
        }

        /* 68k CODE_115 FUN_0000092a + FUN_00001208: adjacent threat halt.
         * Uses MINIMUM MP across all selected group members (not just lead).
         * If min MP < 2 and there's a threat nearby, halt to prevent
         * auto-advancing into danger. */
        { short remainMP = (short)(unsigned char)army[0x2e];
          /* Find minimum MP across group */
          { short gi4;
            for (gi4 = 0; gi4 < sStackCount; gi4++) {
                if (sStackSelected[gi4] && sStackArmyIdx[gi4] >= 0 &&
                    sStackArmyIdx[gi4] != armyIdx) {
                    unsigned char *ga4 = gs + 0x1604 + sStackArmyIdx[gi4] * 0x42;
                    short gmp = (short)(unsigned char)ga4[0x2e];
                    if (gmp < remainMP) remainMP = gmp;
                }
            }
          }
          if (remainMP < 2) {
              short armOwner = (short)(unsigned char)army[0x15];
              if (HasAdjacentThreat(newX, newY, armOwner))
                  break;
          }
        }
    }

    return stepsTaken;
}


/* ===================================================================
 * DropHeroItems — the army's hero dies: every carried item drops at the
 * death tile (status 1), or is lost (status 0, "sunk!") on water terrain
 * (68k CODE_042 FUN_00000930).  Clears the army's item slots.
 * =================================================================== */
static void DropHeroItems(short armyIndex)
{
    unsigned char *gs, *army;
    short ax, ay, si;
    Boolean onWater = false;
    if (*gGameState == 0 || armyIndex < 0) return;
    gs = (unsigned char *)*gGameState;
    army = gs + 0x1604 + armyIndex * 0x42;
    ax = *(short *)(army + 0x00);
    ay = *(short *)(army + 0x02);
    if (*gMapTiles != 0 &&
        ax >= 0 && ax < sMapWidth && ay >= 0 && ay < sMapHeight) {
        unsigned char *md = (unsigned char *)*gMapTiles;
        unsigned char ti = md[ay * 0xE0 + ax * 2];
        unsigned char tt = gs[ti + TERRAIN_TYPE_OFS];
        if (tt == 2) onWater = true;  /* 68k: terrain type 2 (Water) */
    }
    for (si = 0; si < ITEM_SLOTS; si++) {
        short itemId = *(short *)(army + 0x3A + si * 2);
        unsigned char *itemRec = GameItemRec(itemId);
        if (itemRec != NULL) {
            if (onWater) {
                ITEM_STATUS(itemRec) = ITEM_ST_NONE;    /* sunk */
                ITEM_CARRIER(itemRec) = -1;
                *(short *)(itemRec + 0x1A) = -1;
                *(short *)(itemRec + 0x1C) = -1;
            } else {
                ITEM_STATUS(itemRec) = ITEM_ST_GROUND;
                ITEM_CARRIER(itemRec) = -1;
                *(short *)(itemRec + 0x1A) = ax;
                *(short *)(itemRec + 0x1C) = ay;
            }
        }
        *(short *)(army + 0x3A + si * 2) = 0;
    }
}

/* ===================================================================
 * RemoveArmy — Remove an army from the army list by shifting later
 * entries down.  Adjusts sSelectedArmy if needed.
 * =================================================================== */
static void RemoveArmy(short armyIndex)
{
    unsigned char *gs;
    short armyCount, j;

    if (*gGameState == 0) return;
    gs = (unsigned char *)*gGameState;
    armyCount = *(short *)(gs + 0x1602);
    if (armyIndex < 0 || armyIndex >= armyCount) return;

    /* If this army contains a hero, drop items and clear hero record */
    {
        unsigned char *army = gs + 0x1604 + armyIndex * 0x42;
        short owner = (short)(unsigned char)army[0x15];
        short u;
        for (u = 0; u < 4; u++) {
            if ((short)(unsigned char)army[0x16 + u] == 0x1C && owner < 8) {
                unsigned char *heroRec = gs + 0x1422 + owner * 0x2C;
                /* Drop items on hero death (68k CODE_042 FUN_00000930). */
                DropHeroItems(armyIndex);

                heroRec[0x00] = 0;  /* clear active flag */
                /* Record hero death event (68k CODE_054 event type 3) */
                { short turn = *(short *)(gs + 0x136);
                  char heroName[40];
                  short hn;
                  for (hn = 0; hn < 15 && army[0x04 + hn]; hn++)
                      heroName[hn] = army[0x04 + hn];
                  heroName[hn] = 0;
                  RecordEvent(turn, HIST_EVT_HERO_KILL, owner, heroName);
                }
                break;
            }
        }
    }

    /* Shift all armies after this one down by one slot */
    for (j = armyIndex; j < armyCount - 1; j++) {
        unsigned char *dst = gs + 0x1604 + j * 0x42;
        unsigned char *src = gs + 0x1604 + (j + 1) * 0x42;
        short k;
        for (k = 0; k < 0x42; k++)
            dst[k] = src[k];
    }
    *(short *)(gs + 0x1602) = armyCount - 1;

    /* Update hero instance records: decrement army indices above removed slot */
    {
        short p;
        for (p = 0; p < 8; p++) {
            unsigned char *heroRec = gs + 0x1422 + p * 0x2C;
            if (heroRec[0x00] != 0) {
                short heroArmyIdx = *(short *)(heroRec + 0x04);
                if (heroArmyIdx > armyIndex)
                    *(short *)(heroRec + 0x04) = heroArmyIdx - 1;
            }
        }
    }

    /* Update item carrier indices: items referencing armies above removed slot
     * need their carrier index decremented (68k does this in FUN_00000e98). */
    {
        short ii;
        for (ii = 0; ii < 22; ii++) {
            unsigned char *itemRec = gs + 0xD12 + ii * 0x1E;
            if (ITEM_STATUS(itemRec) == ITEM_ST_CARRIED) {  /* status: carried by army */
                short carrierIdx = *(short *)(itemRec + 0x18);
                if (carrierIdx > armyIndex)
                    *(short *)(itemRec + 0x18) = carrierIdx - 1;
            }
        }
    }

    /* Fix selected army reference */
    if (sSelectedArmy == armyIndex) {
        sSelectedArmy = -1; sPreviewPathLen = 0; sPreviewGridValid = false; sInfoStackBackupSaved = false; { GrafPtr _sp; GetPort(&_sp); if (gInfoWindow && *gInfoWindow) { SetPort((WindowPtr)*gInfoWindow); InvalRect(&((WindowPtr)*gInfoWindow)->portRect); } SetPort(_sp); }
    } else if (sSelectedArmy > armyIndex)
        sSelectedArmy--;

    /* Fix stack army indices (shift down those above removed index) */
    {
        short si2;
        for (si2 = 0; si2 < sStackCount; si2++) {
            if (sStackArmyIdx[si2] == armyIndex) {
                /* This stack entry was removed; invalidate it */
                sStackArmyIdx[si2] = -1;
            } else if (sStackArmyIdx[si2] > armyIndex) {
                sStackArmyIdx[si2]--;
            }
        }
    }
}


/* ===================================================================
 * ResolveCombat — Auto-resolve combat between attacker and defender
 *
 * Called when an army moves onto a tile occupied by an enemy army.
 * Uses simplified Warlords II combat: each unit in the attacker
 * fights each unit in the defender based on strength + random roll.
 * Shows a result dialog summarizing the battle.
 * Returns: 1 = attacker wins, 0 = defender wins, -1 = mutual destruction
 * =================================================================== */
/* Battle presentation (ShowBattle) runs the fights quietly and replays the
 * kills: 0 = a defending unit died, 1 = an attacking unit died, in order. */
static Boolean       sBattleQuiet = false;
static unsigned char sBattleKill[128];
static unsigned char sBattleKillT[128];   /* the unit type that died */
static short         sBattleKillN = 0;

static short ResolveCombat(short attackerIdx, short defenderIdx)
{
    unsigned char *gs, *attArmy, *defArmy;
    short attSlots, defSlots, attStrength, defStrength;
    short attHits[4], defHits[4];
    short attType[4], defType[4];
    short attOrigType[4], defOrigType[4];
    short attOrigHits[4], defOrigHits[4];
    short i, round;
    short attAlive, defAlive;
    short result;
    short terrainDef_out = 1, cityDef_out = 0, fortDef_out = 0;
    short defHeroBonus_out = 0;
    long attTotal, defTotal;

    /* Modal result dialog variables */
    WindowPtr combatWin;
    GWorldPtr offGW;
    Rect winRect, gwRect;
    Boolean combatDone;
    EventRecord combatEvt;

    if (*gGameState == 0) return -1;
    gs = (unsigned char *)*gGameState;
    attArmy = gs + 0x1604 + attackerIdx * 0x42;
    defArmy = gs + 0x1604 + defenderIdx * 0x42;

    /* ============================================================
     * Combat system based on decompiled 68k CODE_104 (a1Fight1Possibly)
     *
     * Per-stack attack values computed from:
     *   base strength (HP) + combat bonus (XP) + terrain defense +
     *   hero leader bonus + item bonuses + city/fortification defense.
     * All values capped at scenario max (gs+0x112, default 15).
     *
     * Die-roll mechanic: rand(20) or rand(24) (intense combat).
     * XOR logic: exactly one side must fail per round.
     * 68k HP system: each combatant starts with combat HP=1,
     * dies when HP goes below 0 (2 hits to kill).
     * ============================================================ */

    /* Per-stack attack/defense values (capped at 15) */
    {
        short attValue[4], defValue[4];
        short terrainDef = 1;   /* default terrain defense */
        short cityDef = 0;
        short fortDef = 0;
        /* combatOnWater removed: embarked cap disabled (port system not implemented) */
        short attHeroBonus = 0, defHeroBonus = 0;
        short attItemBonus = 0, defItemBonus = 0;
        short dieRange = (*(short *)(gs + 0x126) == 0) ? 20 : 24;  /* 68k CODE_104: gs+0x126 controls die range (was wrongly sOptIntenseCombat) */

        /* Gather unit stats */
        attSlots = 0;
        defSlots = 0;
        attTotal = 0;
        defTotal = 0;

        for (i = 0; i < 4; i++) {
            attType[i] = (short)(unsigned char)attArmy[0x16 + i];
            attHits[i] = (short)(unsigned char)attArmy[0x1e + i];
            attOrigType[i] = attType[i];
            attOrigHits[i] = attHits[i];
            if (attType[i] != 0xFF && attHits[i] > 0) attSlots++;

            defType[i] = (short)(unsigned char)defArmy[0x16 + i];
            defHits[i] = (short)(unsigned char)defArmy[0x1e + i];
            defOrigType[i] = defType[i];
            defOrigHits[i] = defHits[i];
            if (defType[i] != 0xFF && defHits[i] > 0) defSlots++;
        }

        if (attSlots == 0 || defSlots == 0)
            return (attSlots > 0) ? 1 : ((defSlots > 0) ? 0 : -1);

        /* Terrain defense for defender (68k CODE_104 FUN_00001592):
         * Uses gs+0x711 terrain type table.
         * Type 4 (forest) → +2, types 5/6 (hills/mountains) → +3,
         * types 10/11 (city/ruin) → +0 (city bonus separate),
         * all others → +1. Roads (bit 0x20 set) → +0. */
        if (*gMapTiles != 0) {
            short defX = *(short *)(defArmy + 0x00);
            short defY = *(short *)(defArmy + 0x02);
            if (defX >= 0 && defX < sMapWidth && defY >= 0 && defY < sMapHeight) {
                unsigned char *mapData = (unsigned char *)*gMapTiles;
                unsigned char terrIdx = mapData[defY * 0xE0 + defX * 2];
                unsigned char terrType = gs[terrIdx + TERRAIN_TYPE_OFS];
                /* combatOnWater detection removed: embarked cap disabled */
                switch (terrType) {
                    case 4:             terrainDef = 2; break;  /* forest */
                    case 5: case 6:     terrainDef = 3; break;  /* hills/mountains */
                    case 10: case 11:   terrainDef = 0; break;  /* city/ruin (separate) */
                    default:            terrainDef = 1; break;  /* plains, road, etc. */
                }
                /* Road on tile: remove terrain defense (68k: road bit → return 0) */
                if (terrainDef > 0 && *gRoadData != 0) {
                    unsigned char *rd = (unsigned char *)*gRoadData;
                    if (defX < 112 && defY < 156 && rd[defY * 112 + defX] != 0)
                        terrainDef = 0;
                }
            }
        }

        /* 68k CODE_104: fortification (map byte & 0x20) gives +2 defense.
         * Check if defender tile has the fortification/road bit set. */
        if (*gMapTiles != 0) {
            short defX2 = *(short *)(defArmy + 0x00);
            short defY2 = *(short *)(defArmy + 0x02);
            if (defX2 >= 0 && defX2 < sMapWidth && defY2 >= 0 && defY2 < sMapHeight) {
                unsigned char *mapData2 = (unsigned char *)*gMapTiles;
                unsigned char tileByte = mapData2[defY2 * 0xE0 + defX2 * 2 + 1];
                if (tileByte & 0x20)
                    fortDef = 2;
            }
        }

        /* City defense bonus (68k CODE_104 FUN_0000161a):
         * - Terrain type 10 (city): use city_record+0x06 (defense value) directly
         * - Terrain type 11 (castle/citadel): hardcoded 2
         * - Neutral defenders: defense halved */
        {
            short defX = *(short *)(defArmy + 0x00);
            short defY = *(short *)(defArmy + 0x02);
            if (*gMapTiles != 0 && defX >= 0 && defX < sMapWidth &&
                defY >= 0 && defY < sMapHeight) {
                unsigned char *mapData3 = (unsigned char *)*gMapTiles;
                unsigned char terrIdx3 = mapData3[defY * 0xE0 + defX * 2];
                unsigned char terrType3 = gs[terrIdx3 + TERRAIN_TYPE_OFS];
                if (terrType3 == 11) {
                    cityDef = 2;  /* castle/citadel: hardcoded 2 */
                } else if (terrType3 == 10) {
                    /* City: read defense from city record */
                    short cityCount = sCityCount;
                    short ci;
                    if (cityCount > 139) cityCount = 139;
                    for (ci = 0; ci < cityCount; ci++) {
                        unsigned char *city = sCityData + ci * 0x20;
                        if (*(short *)(city + 0x00) == defX &&
                            *(short *)(city + 0x02) == defY) {
                            cityDef = *(short *)(city + 0x06);
                            break;
                        }
                    }
                }
                /* 68k CODE_104: neutral defenders get halved city defense */
                if (cityDef > 0 && (short)(unsigned char)defArmy[0x15] == 0x0F)
                    cityDef /= 2;
            }
        }

        /* Item bonuses (68k CODE_104): must compute before hero command bonus
         * because battle items feed into hero command strength rating. */
        {
            short attBattleB, attCmdB, attGoldB;
            short defBattleB, defCmdB, defGoldB;
            Boolean attFlyB, attMoveB, defFlyB, defMoveB;
            GetHeroItemBonus(attackerIdx, &attBattleB, &attCmdB, &attGoldB, &attFlyB, &attMoveB);
            GetHeroItemBonus(defenderIdx, &defBattleB, &defCmdB, &defGoldB, &defFlyB, &defMoveB);
            attItemBonus = attCmdB;  /* command items (type 2+8) boost all stacked units */
            defItemBonus = defCmdB;

            /* Hero leader bonus: 68k CODE_104 DAT_00015b54[min(hero_strength + battle_items, 9)].
             * Cap the raw sum at 9 FIRST, then divide by 2. Max leader bonus = 4. */
            for (i = 0; i < 4; i++) {
                if (attType[i] == 0x1C && attHits[i] > 0) {
                    short hs = (short)(unsigned char)attArmy[0x1e + i] + attBattleB;
                    if (hs > 9) hs = 9;
                    { short bonus = hs / 2;
                      if (bonus > attHeroBonus) attHeroBonus = bonus;
                    }
                }
                if (defType[i] == 0x1C && defHits[i] > 0) {
                    short hs = (short)(unsigned char)defArmy[0x1e + i] + defBattleB;
                    if (hs > 9) hs = 9;
                    { short bonus = hs / 2;
                      if (bonus > defHeroBonus) defHeroBonus = bonus;
                    }
                }
            }

            /* 68k CODE_104: Two-stage bonus capping.
             * Stage 1: cap combined bonuses at gs[0x112] (scenario max).
             * Stage 2: add per-unit strength + XP, then final cap at 15 (0x0F).
             * For defender, fortDef is added AFTER the stage 1 cap. */
            {
                short scenarioMax = *(short *)(gs + 0x112);
                short defOwnerByte = (short)(unsigned char)defArmy[0x15];
                if (scenarioMax < 1) scenarioMax = 15;  /* fallback */

                /* Stage 1: cap bonus sums at scenario max */
                {
                    short attBonusCapped = attHeroBonus + attItemBonus;
                    short defTerrAdj = terrainDef;
                    short defBonusCapped;
                    if (defOwnerByte == 0x0F)
                        defTerrAdj = terrainDef / 2;
                    defBonusCapped = defHeroBonus + defItemBonus + defTerrAdj + cityDef;
                    if (attBonusCapped > scenarioMax) attBonusCapped = scenarioMax;
                    if (defBonusCapped > scenarioMax) defBonusCapped = scenarioMax;
                    /* 68k: fortDef added AFTER the cap */
                    defBonusCapped += fortDef;

                    for (i = 0; i < 4; i++) {
                        /* Attacker: base HP + XP bonus + capped bonuses */
                        attValue[i] = (short)(unsigned char)attArmy[0x1e + i]
                                    + (short)(unsigned char)attArmy[0x22 + i]
                                    + attBonusCapped;
                        /* Hero-specific: battle item bonus applies only to hero unit */
                        if (attType[i] == 0x1C)
                            attValue[i] += attBattleB;
                        if (attValue[i] < 1) attValue[i] = 1;
                        if (attValue[i] > 15) attValue[i] = 15;  /* 68k: final cap 0x0F */

                        /* Defender: base HP + XP bonus + capped bonuses */
                        defValue[i] = (short)(unsigned char)defArmy[0x1e + i]
                                    + (short)(unsigned char)defArmy[0x22 + i]
                                    + defBonusCapped;
                        if (defType[i] == 0x1C)
                            defValue[i] += defBattleB;
                        if (defValue[i] < 1) defValue[i] = 1;
                        if (defValue[i] > 15) defValue[i] = 15;  /* 68k: final cap 0x0F */
                    }
                }
            }
            /* Export bonuses for display in combat dialog */
            terrainDef_out = terrainDef;
            cityDef_out = cityDef;
            fortDef_out = fortDef;
            defHeroBonus_out = defHeroBonus;
        }

        /* Sort unit slots by fight order priority (from CODE_060/CODE_104).
         * Fight order table at gs + (player * 0x1D) + 0x60C.
         * Lower value = fights first.
         * 68k CODE_104 FUN_0000161a: heroes always get +50 (0x32) to fight
         * order priority, making them fight LAST in all combat. */
        {
            short attOwner = (short)(unsigned char)attArmy[0x15];
            short defOwner = (short)(unsigned char)defArmy[0x15];
            short attOrder[4], defOrder[4];
            short j, k;

            for (i = 0; i < 4; i++) {
                if (attType[i] != 0xFF && attType[i] < 29 && attOwner < 9) {
                    attOrder[i] = (short)(unsigned char)gs[attType[i] + attOwner * 0x1D + 0x60C];
                    /* 68k: heroes fight last (+50 to priority) */
                    if (attType[i] == 0x1C) attOrder[i] += 50;
                } else {
                    attOrder[i] = 999; /* empty/dead slots sort to end */
                }
                if (defType[i] != 0xFF && defType[i] < 29 && defOwner < 9) {
                    defOrder[i] = (short)(unsigned char)gs[defType[i] + defOwner * 0x1D + 0x60C];
                    if (defType[i] == 0x1C) defOrder[i] += 50;
                } else {
                    defOrder[i] = 999;
                }
            }

            /* 68k CODE_104: insertion sort with stable ordering (no random jitter).
             * Ties are broken by natural array position (earlier units fight first). */

            /* Insertion sort attacker slots by fight order */
            for (j = 1; j < 4; j++) {
                short keyOrd = attOrder[j];
                short keyType = attType[j], keyHits = attHits[j];
                short keyOType = attOrigType[j], keyOHits = attOrigHits[j];
                short keyVal = attValue[j];
                k = j - 1;
                while (k >= 0 && attOrder[k] > keyOrd) {
                    attOrder[k + 1] = attOrder[k];
                    attType[k + 1] = attType[k];
                    attHits[k + 1] = attHits[k];
                    attOrigType[k + 1] = attOrigType[k];
                    attOrigHits[k + 1] = attOrigHits[k];
                    attValue[k + 1] = attValue[k];
                    k--;
                }
                attOrder[k + 1] = keyOrd;
                attType[k + 1] = keyType;
                attHits[k + 1] = keyHits;
                attOrigType[k + 1] = keyOType;
                attOrigHits[k + 1] = keyOHits;
                attValue[k + 1] = keyVal;
            }

            /* Insertion sort defender slots by fight order */
            for (j = 1; j < 4; j++) {
                short keyOrd = defOrder[j];
                short keyType = defType[j], keyHits = defHits[j];
                short keyOType = defOrigType[j], keyOHits = defOrigHits[j];
                short keyVal = defValue[j];
                k = j - 1;
                while (k >= 0 && defOrder[k] > keyOrd) {
                    defOrder[k + 1] = defOrder[k];
                    defType[k + 1] = defType[k];
                    defHits[k + 1] = defHits[k];
                    defOrigType[k + 1] = defOrigType[k];
                    defOrigHits[k + 1] = defOrigHits[k];
                    defValue[k + 1] = defValue[k];
                    k--;
                }
                defOrder[k + 1] = keyOrd;
                defType[k + 1] = keyType;
                defHits[k + 1] = keyHits;
                defOrigType[k + 1] = keyOType;
                defOrigHits[k + 1] = keyOHits;
                defValue[k + 1] = keyVal;
            }
        }

        /* Combat rounds: die-roll based (from decompiled FUN_000003d2).
         * Each round picks the first alive attacker and defender stack.
         * Each side rolls rand(20 or 24) against their OWN stat.
         * Rolling ABOVE your stat = you fail (get hit).
         * XOR logic: exactly one side must fail per round.
         * If both fail or both succeed, the round is skipped (reroll).
         *
         * 68k HP system: each combatant has combat HP initialized to 1.
         * A hit decrements HP. Unit dies when HP < 0 (signed), meaning
         * each unit effectively takes 2 hits to die (1 → 0 → -1=dead).
         * Combat HP is separate from the unit's strength stat. */
        {
            short attCombatHP[4], defCombatHP[4];  /* combat HP: init 1, die at <0 */
            short aiIdx = 0, diIdx = 0;  /* advancing indices like 68k */
            for (i = 0; i < 4; i++) {
                attCombatHP[i] = (attType[i] != 0xFF && attHits[i] > 0) ? 1 : -1;
                defCombatHP[i] = (defType[i] != 0xFF && defHits[i] > 0) ? 1 : -1;
            }
            for (round = 0; round < 10000; round++) {
                short attRoll, defRoll;
                Boolean attFail, defFail;

                /* Advance to next alive unit (68k uses advancing counters) */
                while (aiIdx < 4 && attCombatHP[aiIdx] < 0) aiIdx++;
                while (diIdx < 4 && defCombatHP[diIdx] < 0) diIdx++;
                if (aiIdx >= 4 || diIdx >= 4) break;

                /* Emergency escape: 68k forces attRoll=0, defRoll=100 at round 10000,
                 * which always kills the defender (defRoll=100 > any stat). */
                if (round >= 10000) {
                    defCombatHP[diIdx] = -1;
                    defType[diIdx] = 0xFF;
                    diIdx++;
                    continue;
                }

                /* Each side rolls against own stat (68k FUN_000003d2).
                 * Roll > stat = fail (you get hit). */
                attRoll = (short)((unsigned short)Random() % dieRange);
                defRoll = (short)((unsigned short)Random() % dieRange);

                attFail = (attRoll > attValue[aiIdx]);
                defFail = (defRoll > defValue[diIdx]);

                /* XOR logic: exactly one side must fail.
                 * Both fail or neither fail = skip (reroll). */
                if (attFail == defFail) continue;

                if (attFail) {
                    /* 68k CODE_104 FUN_000003d2: hero vs neutral protection.
                     * In tutorial games (gs+0x12E), a human player's hero attacking
                     * neutral armies is protected from failed die rolls.
                     * 68k enters the defender-hit branch via OR, but the inner
                     * guard (defFail && attSucceed) prevents actual damage.
                     * Net effect: round is skipped, no damage to either side. */
                    if (*(short *)(gs + 0x12e) != 0 &&
                        attType[aiIdx] == 0x1C &&
                        *(short *)(gs + 0xd0 + (short)(unsigned char)attArmy[0x15] * 2) == 0 &&
                        (short)(unsigned char)defArmy[0x15] == 0x0F) {
                        continue;  /* Hero protected: skip round */
                    } else {
                        /* Normal: attacker hit */
                        attCombatHP[aiIdx]--;
                        if (attCombatHP[aiIdx] < 0) {
                            if (sBattleKillN < 128) { sBattleKillT[sBattleKillN] = (unsigned char)attType[aiIdx]; sBattleKill[sBattleKillN++] = 1; }
                            attType[aiIdx] = 0xFF;
                            attHits[aiIdx] = 0;
                            aiIdx++;
                        }
                    }
                } else {
                    /* Defender hit: decrement combat HP, die at < 0 (68k) */
                    defCombatHP[diIdx]--;
                    if (defCombatHP[diIdx] < 0) {
                        if (sBattleKillN < 128) { sBattleKillT[sBattleKillN] = (unsigned char)defType[diIdx]; sBattleKill[sBattleKillN++] = 0; }
                        defType[diIdx] = 0xFF;
                        defHits[diIdx] = 0;
                        diIdx++;
                    }
                }
            }
        }
    }

    /* Count survivors */
    attAlive = 0;
    defAlive = 0;
    for (i = 0; i < 4; i++) {
        if (attType[i] != 0xFF && attHits[i] > 0) attAlive++;
        if (defType[i] != 0xFF && defHits[i] > 0) defAlive++;
    }

    if (attAlive > 0 && defAlive == 0) result = 1;
    else if (defAlive > 0 && attAlive == 0) result = 0;
    else if (attAlive == 0 && defAlive == 0) result = -1;
    else result = (attAlive >= defAlive) ? 1 : 0;  /* shouldn't happen */

    /* Write surviving HP back to winner's army */
    if (result == 1) {
        for (i = 0; i < 4; i++) {
            attArmy[0x16 + i] = (unsigned char)(attType[i] & 0xFF);
            attArmy[0x1e + i] = (unsigned char)(attHits[i] > 0 ? attHits[i] : 0);
            /* XP gain: 68k CODE_042 FUN_00000a3a (AddHeroXP) — ONLY heroes
             * (type 0x1C) earn XP. Non-heroes do NOT gain XP or combat bonuses.
             * 1 XP per combat win, capped at 60. Level thresholds: 15/30/60.
             * 68k: level-up (+2 movement, ceremony) happens at turn start,
             * NOT during combat. See ProcessStartOfTurn section 0d. */
            if (attType[i] == 0x1C && attHits[i] > 0) {
                short xp = (short)(unsigned char)attArmy[0x26 + i];
                if (xp < 60) {
                    xp += 1;
                    if (xp > 60) xp = 60;
                    attArmy[0x26 + i] = (unsigned char)xp;
                }
            }
        }
        /* Recalculate attacker strength display */
        RecalcArmyStrength(attArmy);
    } else if (result == 0) {
        for (i = 0; i < 4; i++) {
            defArmy[0x16 + i] = (unsigned char)(defType[i] & 0xFF);
            defArmy[0x1e + i] = (unsigned char)(defHits[i] > 0 ? defHits[i] : 0);
            /* 68k: only heroes earn XP from combat. Level-up at turn start. */
            if (defType[i] == 0x1C && defHits[i] > 0) {
                short xp = (short)(unsigned char)defArmy[0x26 + i];
                if (xp < 60) {
                    xp += 1;
                    if (xp > 60) xp = 60;
                    defArmy[0x26 + i] = (unsigned char)xp;
                }
            }
        }
        RecalcArmyStrength(defArmy);
    }

    if (sBattleQuiet) return result;   /* ShowBattle presents it */

    /* === Medal award for surviving units (small chance after combat) === */
    {
        static const unsigned char *sMedalNames[] = {
            "\pStar of Battle", "\pWarriors Cross",
            "\pShield of Courage", "\pHeart of Virtue"
        };
        unsigned char *winArmy = (result == 1) ? attArmy : (result == 0) ? defArmy : NULL;
        short winOwner = winArmy ? (short)(unsigned char)winArmy[0x15] : -1;

        if (winArmy != NULL && result != 2) {
            short rng = (short)((unsigned short)Random() % 100);
            /* ~15% chance of medal after each victory */
            if (rng < 15) {
                /* Pick a random surviving unit */
                short candidates[4], nc = 0;
                short *winType = (result == 1) ? attType : defType;
                short *winHits = (result == 1) ? attHits : defHits;
                for (i = 0; i < 4; i++) {
                    if (winType[i] != 0xFF && winHits[i] > 0) candidates[nc++] = i;
                }
                if (nc > 0) {
                    short slot = candidates[(unsigned short)Random() % nc];
                    short medalType = (unsigned short)Random() % 4;
                    short oldVal, newVal;
                    Boolean isStr = (medalType < 2);  /* 0,1 = str; 2,3 = move */

                    if (isStr) {
                        oldVal = (short)(unsigned char)winArmy[0x1e + slot];
                        newVal = oldVal + 1;
                        if (newVal > 9) newVal = 9;
                        winArmy[0x1e + slot] = (unsigned char)newVal;
                        RecalcArmyStrength(winArmy);
                    } else {
                        oldVal = (short)(unsigned char)winArmy[0x1a + slot];
                        newVal = oldVal + 2;
                        if (newVal > 20) newVal = 20;
                        winArmy[0x1a + slot] = (unsigned char)newVal;
                    }

                    /* Show medal notification for human player */
                    if (winOwner >= 0 && winOwner < 8 &&
                        *(short *)(gs + 0xd0 + winOwner * 2) == 0) {
                        WindowPtr mWin;
                        Rect mR;
                        PicHandle medalPict = GetPicture(4410 + medalType);
                        short mW = 310, mH = 90;
                        if (medalPict) {
                            Rect pf = (**medalPict).picFrame;
                            mW = pf.right - pf.left;
                            mH = pf.bottom - pf.top;
                        }
                        SetRect(&mR, 0, 0, mW, mH);
                        OffsetRect(&mR,
                            (qd.screenBits.bounds.right - mW) / 2,
                            (qd.screenBits.bounds.bottom - mH) / 2);
                        mWin = NewCWindow(NULL, &mR, "\p", true,
                                          plainDBox, (WindowPtr)-1, false, 0);
                        if (mWin) {
                            RGBColor mbg = {0x2000, 0x1800, 0x0800};
                            RGBColor mgold = {0xFFFF, 0xDDDD, 0x3333};
                            RGBColor mwh = {0xFFFF, 0xFFFF, 0xFFFF};
                            EventRecord mEvt;
                            unsigned long mTk;
                            Str255 uName, ns;
                            if ((unsigned char)winArmy[0x16 + slot] == 0x1C) {
                                /* Hero: use individual name from army record */
                                unsigned char *hn = winArmy + 0x04;
                                short nl = 0;
                                while (nl < 15 && hn[nl]) nl++;
                                uName[0] = (unsigned char)nl;
                                BlockMoveData(hn, uName + 1, nl);
                            } else {
                                GetUnitTypeName((short)(unsigned char)winArmy[0x16 + slot], uName);
                            }
                            SetPort(mWin);
                            if (medalPict) DrawPicture(medalPict, &mWin->portRect);
                            else { RGBForeColor(&mbg); PaintRect(&mWin->portRect); }
                            RGBForeColor(&mgold); PenSize(2,2); FrameRect(&mWin->portRect); PenNormal();
                            TextFont(3); TextSize(12); TextFace(bold);
                            RGBForeColor(&mgold);
                            MoveTo(15, 20);
                            DrawString(GetCachedString(STR_COMBAT, 5, "\pA Medal!"));
                            TextFace(0); TextSize(10);
                            RGBForeColor(&mwh);
                            MoveTo(15, 40);
                            DrawString(GetCachedString(STR_COMBAT, 6, "\pYour "));
                            DrawString(uName);
                            DrawString(GetCachedString(STR_COMBAT, 7, "\p has been awarded"));
                            MoveTo(15, 56);
                            DrawString(GetCachedString(STR_COMBAT, 8, "\pthe "));
                            RGBForeColor(&mgold);
                            DrawString(sMedalNames[medalType]);
                            RGBForeColor(&mwh);
                            DrawString("\p!");
                            MoveTo(15, 76);
                            if (isStr) {
                                DrawString(GetCachedString(STR_COMBAT, 9, "\pStrength increased from "));
                                NumToString((long)oldVal, ns); DrawString(ns);
                                DrawString(GetCachedString(STR_COMBAT, 10, "\p to "));
                                NumToString((long)newVal, ns); DrawString(ns);
                                DrawString("\p!");
                            } else {
                                DrawString(GetCachedString(STR_COMBAT, 11, "\pMovement increased from "));
                                NumToString((long)oldVal, ns); DrawString(ns);
                                DrawString(GetCachedString(STR_COMBAT, 10, "\p to "));
                                NumToString((long)newVal, ns); DrawString(ns);
                                DrawString("\p!");
                            }
                            mTk = TickCount() + SpeedTicks(120);
                            while (TickCount() < mTk) {
                                if (WaitNextEvent(mDownMask | keyDownMask, &mEvt, 5, NULL)) break;
                            }
                            DisposeWindow(mWin);
                        }
                    }
                }
            }
        }
    }

    /* === Show combat result dialog (only for battles involving human player) === */
    {
        short attOwnerChk = (short)(unsigned char)attArmy[0x15];
        short defOwnerChk = (short)(unsigned char)defArmy[0x15];
        short curPlayer = *(short *)(gs + 0x110);
        Boolean showDialog = (attOwnerChk == curPlayer || defOwnerChk == curPlayer);
        /* Also show if either side is human (with bounds check for neutrals) */
        if (!showDialog) {
            if ((attOwnerChk >= 0 && attOwnerChk < 8 &&
                 *(short *)(gs + 0xd0 + attOwnerChk * 2) == 0) ||
                (defOwnerChk >= 0 && defOwnerChk < 8 &&
                 *(short *)(gs + 0xd0 + defOwnerChk * 2) == 0))
                showDialog = true;
        }
        if (!showDialog) return result;
    }
    SetRect(&winRect, 0, 0, 400, 340);
    OffsetRect(&winRect, 150, 100);
    combatWin = NewCWindow(NULL, &winRect, "\p", true,
                           plainDBox, (WindowPtr)-1L, false, 0);
    SetRect(&gwRect, 0, 0, 400, 340);
    NewGWorld(&offGW, 0, &gwRect, NULL, NULL, 0);

    if (combatWin != NULL && offGW != NULL) {
        CGrafPtr savePort;
        GDHandle saveGD;
        GetGWorld(&savePort, &saveGD);
        SetGWorld(offGW, NULL);
        LockPixels(GetGWorldPixMap(offGW));

        /* Background */
        DrawMarbleBackground(&gwRect);
        /* Gold border */
        {
            RGBColor bdr = {0xCCCC, 0xAAAA, 0x3333};
            RGBForeColor(&bdr);
            PenSize(2, 2);
            FrameRect(&gwRect);
            PenSize(1, 1);
        }

        /* Title */
        {
            RGBColor gold = {0xFFFF, 0xDDDD, 0x5555};
            RGBForeColor(&gold);
            TextFont(2); TextSize(14); TextFace(bold);
            MoveTo(130, 24);
            DrawString(GetCachedString(STR_COMBAT, 12, "\pBattle Results"));
            TextFace(0); TextFont(3); TextSize(10);
        }

        /* Divider line under title */
        {
            RGBColor divCol = {0x6666, 0x5555, 0x4444};
            RGBForeColor(&divCol);
            MoveTo(10, 30); LineTo(390, 30);
        }

        /* Per-unit details: two columns (attacker left, defender right) */
        {
            short attOwner = (short)(unsigned char)attArmy[0x15];
            short defOwner = (short)(unsigned char)defArmy[0x15];
            RGBColor attColor = sPlayerColors[attOwner < 8 ? attOwner + 1 : 8];
            RGBColor defColor = sPlayerColors[defOwner < 8 ? defOwner + 1 : 8];
            RGBColor deadCol = {0xFFFF, 0x4444, 0x4444};
            RGBColor aliveCol = {0x4444, 0xFFFF, 0x4444};
            RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
            RGBColor gray = {0x8888, 0x8888, 0x8888};
            short yPos;
            Str255 numStr;

            /* Attacker column (left) */
            RGBForeColor(&attColor);
            TextFace(bold);
            MoveTo(20, 48);
            DrawString(GetCachedString(STR_COMBAT, 13, "\pAttacker"));
            {
                /* Faction name */
                char *fname = (char *)(gs + attOwner * FACTION_NAME_LEN);
                short fi;
                Str255 pname;
                for (fi = 0; fi < 14 && fname[fi]; fi++)
                    pname[fi + 1] = fname[fi];
                pname[0] = fi;
                MoveTo(90, 48);
                DrawString("\p(");
                DrawString(pname);
                DrawString("\p)");
            }
            TextFace(0);

            yPos = 66;
            for (i = 0; i < 4; i++) {
                Str255 uName;
                if (attOrigType[i] == 0xFF) continue;
                /* Show hero's individual name + title instead of generic "Hero" */
                if (attOrigType[i] == 0x1C) {
                    unsigned char *hn = attArmy + 0x04;
                    short nl = 0;
                    Str255 htitle;
                    short xp = (short)(unsigned char)attArmy[0x26];
                    short lvl = GetHeroLevel(xp);
                    Boolean fem = IsHeroFemale(attackerIdx);
                    while (nl < 15 && hn[nl]) nl++;
                    uName[0] = (unsigned char)nl;
                    BlockMoveData(hn, uName + 1, nl);
                    GetHeroTitle(lvl, fem, htitle);
                    if (uName[0] + htitle[0] + 2 < 250) {
                        uName[uName[0] + 1] = ','; uName[uName[0] + 2] = ' ';
                        BlockMoveData(htitle + 1, uName + uName[0] + 3, htitle[0]);
                        uName[0] += htitle[0] + 2;
                    }
                } else {
                    GetUnitTypeName(attOrigType[i], uName);
                }

                /* Unit sprite */
                {
                    short sSheet = (attOwner >= 0 && attOwner < ARMY_SHEETS) ? attOwner : 0;
                    GWorldPtr sGW = sArmyGW[sSheet] ? sArmyGW[sSheet] : sArmyGW[0];
                    if (sArmyLoaded && sGW != NULL) {
                        short sprIdx = attOrigType[i];
                        short sprCol2, sprRow2;
                        Rect srcR2, dstR2;
                        if (sUnitTypesLoaded && sprIdx < sUnitTypeCount) {
                            unsigned char *ute = sUnitTypeTable + sprIdx * UNIT_TYPE_ENTRY;
                            sprIdx = (short)ute[0x00];
                        }
                        sprCol2 = sprIdx % 16;
                        sprRow2 = sprIdx / 16;
                        SetRect(&srcR2, sprCol2 * 32, sprRow2 * 30,
                                sprCol2 * 32 + 29, sprRow2 * 30 + 28);
                        SetRect(&dstR2, 14, yPos - 12, 14 + 20, yPos + 6);
                        LockPixels(GetGWorldPixMap(sGW));
                        {
                            RGBColor savedBg;
                            GetBackColor(&savedBg);
                            RGBBackColor(&sArmyBgColor[sSheet]);
                            CopyBits((BitMap *)*GetGWorldPixMap(sGW),
                                     (BitMap *)*GetGWorldPixMap(offGW),
                                     &srcR2, &dstR2, 36, NULL);
                            RGBBackColor(&savedBg);
                        }
                        UnlockPixels(GetGWorldPixMap(sGW));
                    }
                }

                MoveTo(38, yPos);
                if (attType[i] == 0xFF || attHits[i] <= 0) {
                    RGBForeColor(&deadCol);
                    DrawString(uName);
                    MoveTo(160, yPos);
                    DrawString(GetCachedString(STR_COMBAT, 14, "\pKILLED"));
                } else {
                    RGBForeColor(&aliveCol);
                    DrawString(uName);
                    MoveTo(160, yPos);
                    RGBForeColor(&white);
                    NumToString((long)attHits[i], numStr);
                    DrawString(numStr);
                    DrawString("\p/");
                    NumToString((long)attOrigHits[i], numStr);
                    DrawString(numStr);
                    DrawString(GetCachedString(STR_COMBAT, 15, "\p HP"));
                }
                yPos += 22;
            }

            /* Separator */
            {
                RGBColor divCol = {0x6666, 0x5555, 0x4444};
                RGBForeColor(&divCol);
                MoveTo(10, yPos + 4);
                LineTo(390, yPos + 4);
            }
            yPos += 16;

            /* Defender column */
            RGBForeColor(&defColor);
            TextFace(bold);
            MoveTo(20, yPos);
            DrawString(GetCachedString(STR_COMBAT, 16, "\pDefender"));
            {
                char *fname = (char *)(gs + defOwner * FACTION_NAME_LEN);
                short fi;
                Str255 pname;
                for (fi = 0; fi < 14 && fname[fi]; fi++)
                    pname[fi + 1] = fname[fi];
                pname[0] = fi;
                MoveTo(90, yPos);
                DrawString("\p(");
                DrawString(pname);
                DrawString("\p)");
            }
            TextFace(0);
            yPos += 18;

            for (i = 0; i < 4; i++) {
                Str255 uName;
                if (defOrigType[i] == 0xFF) continue;
                /* Show hero's individual name + title instead of generic "Hero" */
                if (defOrigType[i] == 0x1C) {
                    unsigned char *hn = defArmy + 0x04;
                    short nl = 0;
                    Str255 htitle;
                    short xp = (short)(unsigned char)defArmy[0x26];
                    short lvl = GetHeroLevel(xp);
                    Boolean fem = IsHeroFemale(defenderIdx);
                    while (nl < 15 && hn[nl]) nl++;
                    uName[0] = (unsigned char)nl;
                    BlockMoveData(hn, uName + 1, nl);
                    GetHeroTitle(lvl, fem, htitle);
                    if (uName[0] + htitle[0] + 2 < 250) {
                        uName[uName[0] + 1] = ','; uName[uName[0] + 2] = ' ';
                        BlockMoveData(htitle + 1, uName + uName[0] + 3, htitle[0]);
                        uName[0] += htitle[0] + 2;
                    }
                } else {
                    GetUnitTypeName(defOrigType[i], uName);
                }

                /* Unit sprite */
                {
                    short sSheet = (defOwner >= 0 && defOwner < ARMY_SHEETS) ? defOwner : 0;
                    GWorldPtr sGW = sArmyGW[sSheet] ? sArmyGW[sSheet] : sArmyGW[0];
                    if (sArmyLoaded && sGW != NULL) {
                        short sprIdx = defOrigType[i];
                        short sprCol2, sprRow2;
                        Rect srcR2, dstR2;
                        if (sUnitTypesLoaded && sprIdx < sUnitTypeCount) {
                            unsigned char *ute = sUnitTypeTable + sprIdx * UNIT_TYPE_ENTRY;
                            sprIdx = (short)ute[0x00];
                        }
                        sprCol2 = sprIdx % 16;
                        sprRow2 = sprIdx / 16;
                        SetRect(&srcR2, sprCol2 * 32, sprRow2 * 30,
                                sprCol2 * 32 + 29, sprRow2 * 30 + 28);
                        SetRect(&dstR2, 14, yPos - 12, 14 + 20, yPos + 6);
                        LockPixels(GetGWorldPixMap(sGW));
                        {
                            RGBColor savedBg;
                            GetBackColor(&savedBg);
                            RGBBackColor(&sArmyBgColor[sSheet]);
                            CopyBits((BitMap *)*GetGWorldPixMap(sGW),
                                     (BitMap *)*GetGWorldPixMap(offGW),
                                     &srcR2, &dstR2, 36, NULL);
                            RGBBackColor(&savedBg);
                        }
                        UnlockPixels(GetGWorldPixMap(sGW));
                    }
                }

                MoveTo(38, yPos);
                if (defType[i] == 0xFF || defHits[i] <= 0) {
                    RGBForeColor(&deadCol);
                    DrawString(uName);
                    MoveTo(160, yPos);
                    DrawString(GetCachedString(STR_COMBAT, 14, "\pKILLED"));
                } else {
                    RGBForeColor(&aliveCol);
                    DrawString(uName);
                    MoveTo(160, yPos);
                    RGBForeColor(&white);
                    NumToString((long)defHits[i], numStr);
                    DrawString(numStr);
                    DrawString("\p/");
                    NumToString((long)defOrigHits[i], numStr);
                    DrawString(numStr);
                    DrawString(GetCachedString(STR_COMBAT, 15, "\p HP"));
                }
                yPos += 22;
            }

            /* Terrain/bonus info line */
            MoveTo(20, yPos + 12);
            RGBForeColor(&gray);
            TextSize(9);
            DrawString(GetCachedString(STR_COMBAT, 17, "\pRounds: "));
            NumToString((long)round, numStr);
            DrawString(numStr);
            /* Show defender's bonuses */
            {
                short bonusX = 20;
                short bonusY = yPos + 24;
                RGBColor bonusCol = {0x8888, 0xAAAA, 0xCCCC};
                RGBForeColor(&bonusCol);
                MoveTo(bonusX, bonusY);
                DrawString("\pDef bonuses: ");
                if (terrainDef_out > 0) {
                    DrawString("\pTerrain +");
                    NumToString((long)terrainDef_out, numStr); DrawString(numStr);
                    DrawString("\p  ");
                }
                if (cityDef_out > 0) {
                    DrawString("\pCity +");
                    NumToString((long)cityDef_out, numStr); DrawString(numStr);
                    DrawString("\p  ");
                }
                if (fortDef_out > 0) {
                    DrawString("\pFort +");
                    NumToString((long)fortDef_out, numStr); DrawString(numStr);
                    DrawString("\p  ");
                }
                if (defHeroBonus_out > 0) {
                    DrawString("\pHero +");
                    NumToString((long)defHeroBonus_out, numStr); DrawString(numStr);
                }
                if (terrainDef_out == 0 && cityDef_out == 0 && fortDef_out == 0 && defHeroBonus_out == 0)
                    DrawString("\pNone");
            }
            TextSize(10);
        }

        /* Outcome banner */
        {
            Rect bannerR;
            RGBColor bannerBg, bannerText;
            SetRect(&bannerR, 20, 280, 380, 304);

            if (result == 1) {
                bannerBg.red = 0x0000; bannerBg.green = 0x4444; bannerBg.blue = 0x0000;
                bannerText.red = 0x4444; bannerText.green = 0xFFFF; bannerText.blue = 0x4444;
            } else if (result == 0) {
                bannerBg.red = 0x4444; bannerBg.green = 0x0000; bannerBg.blue = 0x0000;
                bannerText.red = 0xFFFF; bannerText.green = 0x4444; bannerText.blue = 0x4444;
            } else {
                bannerBg.red = 0x3333; bannerBg.green = 0x3333; bannerBg.blue = 0x3333;
                bannerText.red = 0xFFFF; bannerText.green = 0xFFFF; bannerText.blue = 0xFFFF;
            }
            RGBForeColor(&bannerBg);
            PaintRoundRect(&bannerR, 6, 6);
            RGBForeColor(&bannerText);
            TextFace(bold);
            if (result == 1) {
                MoveTo(110, 297);
                DrawString(GetCachedString(STR_COMBAT, 18, "\pAttacker is VICTORIOUS!"));
            } else if (result == 0) {
                MoveTo(110, 297);
                DrawString(GetCachedString(STR_COMBAT, 19, "\pDefender holds the field!"));
            } else {
                MoveTo(110, 297);
                DrawString(GetCachedString(STR_COMBAT, 20, "\pBoth armies destroyed!"));
            }
            TextFace(0);
        }

        /* OK button */
        {
            Rect okRect;
            RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
            SetRect(&okRect, 160, 310, 240, 332);
            RGBForeColor(&white);
            FrameRoundRect(&okRect, 8, 8);
            MoveTo(186, 326);
            DrawString(GetCachedString(STR_COMMON_BUTTONS, 1, "\pOK"));
        }

        UnlockPixels(GetGWorldPixMap(offGW));
        SetGWorld(savePort, saveGD);

        /* Blit to window */
        SetPort(combatWin);
        {
            Rect dr = combatWin->portRect;
            LockPixels(GetGWorldPixMap(offGW));
            CopyBits((BitMap *)*GetGWorldPixMap(offGW),
                     &((GrafPtr)combatWin)->portBits,
                     &gwRect, &dr, srcCopy, NULL);
            UnlockPixels(GetGWorldPixMap(offGW));
        }
    }

    /* Modal event loop for combat result */
    combatDone = false;
    while (!combatDone) {
        if (WaitNextEvent(mDownMask | keyDownMask | updateMask, &combatEvt, 30, NULL)) {
            if (combatEvt.what == mouseDown || combatEvt.what == keyDown) {
                combatDone = true;
            } else if (combatEvt.what == updateEvt) {
                if ((WindowPtr)combatEvt.message == combatWin && offGW != NULL) {
                    Rect dr;
                    BeginUpdate(combatWin);
                    SetPort(combatWin);
                    dr = combatWin->portRect;
                    LockPixels(GetGWorldPixMap(offGW));
                    CopyBits((BitMap *)*GetGWorldPixMap(offGW),
                             &((GrafPtr)combatWin)->portBits,
                             &gwRect, &dr, srcCopy, NULL);
                    UnlockPixels(GetGWorldPixMap(offGW));
                    EndUpdate(combatWin);
                }
            }
        }
    }

    if (offGW != NULL) DisposeGWorld(offGW);
    if (combatWin != NULL) DisposeWindow(combatWin);

    return result;
}


/* ===================================================================
 * ShowCityCaptureNotification — Brief modal showing city capture
 * =================================================================== */
static void ShowCityCaptureNotification(short capturer, short prevOwner,
                                         short cityX, short cityY)
{
    WindowPtr notWin;
    GWorldPtr offGW;
    Rect winRect, gwRect;
    EventRecord evt;
    CGrafPtr savePort;
    PicHandle bgPict;
    short winW = 300, winH = 100;

    PlaySound(SND_CHORD);
    GDHandle saveGD;
    unsigned long ticks;
    unsigned char *gs = (unsigned char *)*gGameState;

    /* Try to load capture scene PICT */
    bgPict = GetPicture(3800);
    if (bgPict) {
        Rect pf = (**bgPict).picFrame;
        winW = pf.right - pf.left;
        winH = pf.bottom - pf.top;
    }

    SetRect(&winRect, 0, 0, winW, winH);
    OffsetRect(&winRect,
        (qd.screenBits.bounds.right - winW) / 2,
        (qd.screenBits.bounds.bottom - winH) / 2);
    notWin = NewCWindow(NULL, &winRect, "\pCity Captured!", true,
                        dBoxProc, (WindowPtr)-1, false, 0);
    SetRect(&gwRect, 0, 0, winW, winH);
    NewGWorld(&offGW, 0, &gwRect, NULL, NULL, 0);
    if (!notWin || !offGW) {
        if (offGW) DisposeGWorld(offGW);
        if (notWin) DisposeWindow(notWin);
        return;
    }

    GetGWorld(&savePort, &saveGD);
    SetGWorld(offGW, NULL);
    LockPixels(GetGWorldPixMap(offGW));

    /* Background: capture PICT or marble fallback, with capturer's color border */
    {
        RGBColor border = sPlayerColors[capturer < 8 ? capturer + 1 : 8];
        if (bgPict) DrawPicture(bgPict, &gwRect);
        else DrawMarbleBackground(&gwRect);
        RGBForeColor(&border);
        PenSize(3, 3);
        FrameRect(&gwRect);
        PenNormal();
    }

    /* Title */
    {
        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
        RGBColor capColor = sPlayerColors[capturer < 8 ? capturer + 1 : 8];
        char factionName[24];
        short len;
        Str255 numStr;

        RGBForeColor(&white);
        TextSize(12);
        TextFace(bold);
        MoveTo(20, 25);
        DrawString(GetCachedString(STR_CITY_CAPTURE, 2, "\pCity Captured!"));
        TextFace(0);
        TextSize(10);

        /* Show capturer name */
        BlockMoveData(gs + capturer * 20, factionName, 20);
        factionName[19] = 0;
        for (len = 0; len < 19 && factionName[len]; len++) {}
        MoveTo(20, 50);
        RGBForeColor(&capColor);
        {
            Str255 pstr;
            pstr[0] = (unsigned char)len;
            BlockMoveData(factionName, &pstr[1], len);
            DrawString(pstr);
        }

        RGBForeColor(&white);
        DrawString(GetCachedString(STR_CITY_CAPTURE, 3, "\p captures city at ("));
        NumToString((long)cityX, numStr);
        DrawString(numStr);
        DrawString("\p, ");
        NumToString((long)cityY, numStr);
        DrawString(numStr);
        DrawString("\p)");

        /* Show previous owner */
        if (prevOwner >= 0 && prevOwner < 8) {
            RGBColor prevColor = sPlayerColors[prevOwner + 1];
            char prevName[24];
            short plen;
            BlockMoveData(gs + prevOwner * 20, prevName, 20);
            prevName[19] = 0;
            for (plen = 0; plen < 19 && prevName[plen]; plen++) {}

            MoveTo(20, 70);
            RGBForeColor(&white);
            DrawString(GetCachedString(STR_MISC, 16, "\pTaken from "));
            RGBForeColor(&prevColor);
            {
                Str255 pstr2;
                pstr2[0] = (unsigned char)plen;
                BlockMoveData(prevName, &pstr2[1], plen);
                DrawString(pstr2);
            }
        }

        RGBForeColor(&white);
        TextSize(9);
        MoveTo(200, 90);
        DrawString(GetCachedString(STR_MISC, 17, "\pClick to continue"));
    }

    UnlockPixels(GetGWorldPixMap(offGW));
    SetGWorld(savePort, saveGD);

    /* Blit to window */
    {
        PixMapHandle srcPM = GetGWorldPixMap(offGW);
        SetPort(notWin);
        LockPixels(srcPM);
        CopyBits((BitMap *)*srcPM,
                 &((GrafPtr)notWin)->portBits,
                 &gwRect, &gwRect, srcCopy, NULL);
        UnlockPixels(srcPM);
    }

    /* Wait for click or 3 seconds */
    ticks = TickCount() + SpeedTicks(180);
    while (TickCount() < ticks) {
        if (WaitNextEvent(mDownMask | keyDownMask, &evt, 5, NULL))
            break;
    }

    DisposeGWorld(offGW);
    DisposeWindow(notWin);
}


/* ===================================================================
 * ShowEliminationNotification — Announce a player has been eliminated
 * =================================================================== */
static void ShowEliminationNotification(short eliminatedPlayer, short byPlayer)
{
    /* View 1020 notice (PPC): "%s, thy empire has fallen!" / "thou art
     * vanquished!" / "thou art no more!" / "thy cities are as dust!"
     * (DAT 207-210, picked at random), shown at the turn change. */
    unsigned char *gs = (unsigned char *)*gGameState;
    unsigned char *fn = gs + eliminatedPlayer * FACTION_NAME_LEN;
    Str255 nm, fmt, line;
    short len = 0;
    WindowPtr win;
    Rect v;
    EventRecord e;
    (void)byPlayer;
    while (len < 14 && fn[len]) len++;
    nm[0] = (unsigned char)len; BlockMoveData(fn, nm + 1, len);
    GetDATRawString(207 + (short)((unsigned short)Random() % 4), fmt);
    FormatHeroLine(fmt, nm, 0, line);
    win = NewMacAppWindow(392, 94);
    if (win == NULL) return;
    DrawPictAt(1001, 7, 7);
    DrawPictAt(1004, 0, 0); DrawPictAt(1005, 0, 7); DrawPictAt(1006, 0, 87); DrawPictAt(1009, 385, 0);
    SetRect(&v, 19, 35, 19 + 352, 35 + 19);
    DrawSunkenText(&v, line, IlluriaFont(), 17, 1);
    FlushEvents(mDownMask | keyDownMask, 0);
    for (;;) if (WaitNextEvent(mDownMask | keyDownMask, &e, 5, NULL)) break;
    CloseMacAppWindow(win);
}


/* A capture waiting for its notices/choice (shown after the battle window). */
static Boolean sCapPend = false;
static short   sCapOwner, sCapPrev, sCapX, sCapY, sCapCity;
static short   sCaptureLoot = 0;   /* gold looted by the last capture */
static Str255  sCapWho;            /* hero (or player) named on the Victory screen */

/* ===================================================================
 * CaptureCityAt — the city whose anchor tile is (mx,my) passes to mOwner
 * (gold transfer, production reset, notices, raze choice, elimination).
 * =================================================================== */
static void CaptureCityAt(short mOwner, short mx, short my)
{
    unsigned char *gs;
    short armyCount, turnNum;
    if (*gGameState == 0) return;
    gs = (unsigned char *)*gGameState;
    armyCount = *(short *)(gs + 0x1602);
    if (armyCount > 100) armyCount = 100;
    turnNum = *(short *)(gs + 0x136);
                {
                    short cityCount = sCityCount;
                    short ci;
                    if (cityCount > 139) cityCount = 139;
                    for (ci = 0; ci < cityCount; ci++) {
                        unsigned char *city = sCityData +ci * 0x20;
                        if (*(short *)(city + 0x00) == mx &&
                            *(short *)(city + 0x02) == my) {
                            short prevOwner = *(short *)(city + 0x04);

                            /* 68k CODE_133: track origin player at city+0x0A.
                             * If capturing player == origin, reset to 0x0F.
                             * Otherwise save previous owner as origin. */
                            if (prevOwner != 0x0F && prevOwner >= 0 && prevOwner < 8) {
                                short curOrigin = *(short *)(city + 0x0A);
                                if (mOwner == curOrigin)
                                    *(short *)(city + 0x0A) = 0x0F;
                                else
                                    *(short *)(city + 0x0A) = prevOwner;
                            }

                            *(short *)(city + 0x04) = mOwner;  /* capture city */

                            /* Update map tiles to new owner (68k CODE_133: only update owner
                             * nibble in byte+1, preserve existing tile type in byte+0). */
                            if (*gMapTiles != 0) {
                                unsigned char *capMap = (unsigned char *)*gMapTiles;
                                short cdx, cdy;
                                for (cdy = 0; cdy < 2; cdy++) {
                                    for (cdx = 0; cdx < 2; cdx++) {
                                        short ctx = mx + cdx, cty = my + cdy;
                                        if (ctx >= 0 && ctx < sMapWidth && cty >= 0 && cty < sMapHeight) {
                                            unsigned short coff = cty * 0xE0 + ctx * 2;
                                            /* Preserve tile type byte, only update owner nibble */
                                            capMap[coff + 1] = (capMap[coff + 1] & 0xF0) | (mOwner & 0x0F);
                                        }
                                    }
                                }
                            }

                            /* Gold transfer on capture (68k CODE_133 FUN_00000046):
                             * No gold from neutrals.
                             * If defender has < 2 cities remaining: goldPerCity = all gold.
                             * Else: goldPerCity = defender_gold / defender_city_count.
                             * Winner gets goldPerCity / 2.
                             * Loser loses goldPerCity (2x what winner gains). */
                            if (prevOwner >= 0 && prevOwner < 8 && prevOwner != 0x0F &&
                                mOwner >= 0 && mOwner < 8) {
                                short defGold = *(short *)(gs + 0x186 + prevOwner * 0x14);
                                short defCities = 0;
                                short ci2;
                                short goldPerCity;
                                for (ci2 = 0; ci2 < cityCount; ci2++) {
                                    unsigned char *c2 = sCityData +ci2 * 0x20;
                                    if (*(short *)(c2 + 0x04) == prevOwner) defCities++;
                                }
                                /* 68k: defCities < 2 → take ALL gold; else proportional */
                                if (defCities < 2)
                                    goldPerCity = defGold;
                                else
                                    goldPerCity = defGold / defCities;
                                {
                                    short goldTaken = goldPerCity / 2;
                                    if (goldTaken < 0) goldTaken = 0;
                                    if (goldTaken > 0) {
                                        sCaptureLoot = goldTaken;
                                        short newGold = *(short *)(gs + 0x186 + mOwner * 0x14) + goldTaken;
                                        if (newGold > 30000) newGold = 30000;
                                        *(short *)(gs + 0x186 + mOwner * 0x14) = newGold;
                                        /* 68k: loser loses goldPerCity (2x goldTaken) */
                                        {
                                            short loserGold = *(short *)(gs + 0x186 + prevOwner * 0x14) - goldPerCity;
                                            if (loserGold < 0) loserGold = 0;
                                            *(short *)(gs + 0x186 + prevOwner * 0x14) = loserGold;
                                        }
                                    }
                                }
                            }

                            /* 68k CODE_133: clear vectoring targets pointing to captured city.
                             * Armies owned by the previous owner that were vectoring to this
                             * city should have their movement orders cleared. */
                            if (prevOwner >= 0 && prevOwner < 8 && *gExtState != 0) {
                                unsigned char *ext = (unsigned char *)*gExtState;
                                short ci3;
                                short cityCount3 = sCityCount;
                                if (cityCount3 > 139) cityCount3 = 139;
                                for (ci3 = 0; ci3 < cityCount3; ci3++) {
                                    unsigned char *extCity3 = ext + 0x24c + ci3 * 0x5c;
                                    short vecTgt = *(short *)(extCity3 + 0x3e);
                                    if (vecTgt == ci) {
                                        /* Clear vectoring: production stays, target cleared */
                                        *(short *)(extCity3 + 0x3e) = -1;
                                    }
                                }
                            }

                            /* 68k CODE_133: clear production and defend state on capture.
                             * New owner must set their own production. */
                            if (*gExtState != 0) {
                                unsigned char *extC = (unsigned char *)*gExtState + 0x24c + ci * 0x5c;
                                *(short *)(extC + 0x02) = -1;  /* clear production timer */
                                extC[0x00] = 0;                /* clear current production type */
                            }
                            /* 68k CODE_133: clear army defend state at captured city */
                            {
                                short armyCount2 = *(short *)(gs + 0x1602);
                                short ai2;
                                for (ai2 = 0; ai2 < armyCount2; ai2++) {
                                    unsigned char *ar2 = gs + 0x1604 + ai2 * 0x42;
                                    if (*(short *)(ar2 + 0x00) == mx &&
                                        *(short *)(ar2 + 0x02) == my) {
                                        ar2[0x2d] = 0;  /* clear defend/fortify */
                                    }
                                }
                            }

                            RecordEvent(turnNum, HIST_EVT_CAPTURE, mOwner,
                                "Captured a city");
                            sCapPend = true; sCapOwner = mOwner; sCapPrev = prevOwner;
                            sCapX = mx; sCapY = my; sCapCity = ci;
                            break;
                        }
                    }
                }
}

/* ===================================================================
 * Victory (View 3800, PPC FUN_100472f4): after a human takes a city.
 *   396x276 on WDEF 128 variant 7 (0x0807), placed like View 3200 (centred
 *   across, a third of the way down); PICT 1016 frame at (0,0), PICT 3800 at
 *   (38,38); 'head' (38,42) 320x39 TxSt 1005 "Victory!"; str1..str4 at
 *   y 88/108/128/148, 320 wide, TxSt 1015: random 370-373 with the hero's
 *   name (else the player's name), random 374-376 with the city name,
 *   "The city is yours!", "Will you...".  T3DButtons (STR# 3800) occu
 *   (51,204) 64x21 default, pill (128,205), sack (205,204), raze (281,204)
 *   64x20, keys o/p/s/r.  Pillage is dimmed when the last production slot
 *   is worth nothing, Sack when fewer than two slots, Raze when razing is
 *   not allowed.
 * =================================================================== */
#define VICT_W 396
#define VICT_H 276

static void CityNameP(short ci, Str255 out)
{
    short n = 0;
    out[0] = 0;
    if (ci < 0 || ci >= sCityNameCount) return;
    while (n < MAX_CITY_NAME && sCityNames[ci][n]) { out[n + 1] = sCityNames[ci][n]; n++; }
    out[0] = (unsigned char)n;
}

/* production slots of a city (ext +0x06), filled ones first */
static short CitySlots(short ci, short *slot)
{
    unsigned char *ext = (unsigned char *)*gExtState + 0x24c + ci * 0x5c;
    short i, n = 0;
    for (i = 0; i < 4; i++) {
        short t = *(short *)(ext + 0x06 + i * 2);
        if (t < 0 || t >= MAX_UNIT_TYPES) break;
        slot[n++] = t;
    }
    return n;
}

/* FUN_1004645c: half the buy price (stat 4) of the last slot */
static short PillageValue(short ci)
{
    short slot[4], n;
    if (*gExtState == 0) return 0;
    n = CitySlots(ci, slot);
    return n > 0 ? GetUnitTypeStat(slot[n - 1], 4) / 2 : 0;
}

/* FUN_1004639c: half the buy price of every slot but the first */
static short SackValue(short ci)
{
    short slot[4], n, i, g = 0;
    if (*gExtState == 0) return 0;
    n = CitySlots(ci, slot);
    if (n < 2) return 0;
    for (i = 1; i < n; i++) g += GetUnitTypeStat(slot[i], 4) / 2;
    return g;
}

static void DrawT3DButtonDim(const Rect *r, ConstStr255Param label)
{
    RGBColor grey = {0x8888, 0x8888, 0x8888};
    short fnum, w;
    DrawT3DBevel(r);
    GetFNum("\pChicago", &fnum);
    TextFont(fnum); TextSize(12); TextFace(0);
    w = StringWidth(label);
    RGBForeColor(&grey);
    MoveTo((r->left + r->right - w + 1) / 2 - 1, r->bottom - 8);
    DrawString(label);
}

static WindowPtr NewMacAppWindow(short w, short h)
{
    WindowPtr win;
    Rect wr;
    short sw = qd.screenBits.bounds.right, sh = qd.screenBits.bounds.bottom, mb = GetMBarHeight();
    short left = (sw - (w + 6)) / 2, top = mb + (sh - mb - (h + 6)) / 3;
    SetRect(&wr, left, top, left + w, top + h);
    win = NewCWindow(NULL, &wr, "\p", false, 0x0807, (WindowPtr)-1L, false, 0);
    if (win == NULL) return NULL;
    {
        Handle wctb = GetResource('wctb', 1000);
        if (wctb != NULL) SetWinColor(win, (CTabHandle)wctb);
    }
    if (*gMainGameWindow != 0) {
        PaletteHandle pal = GetPalette((WindowPtr)*gMainGameWindow);
        if (pal != NULL) SetPalette(win, pal, false);
    }
    /* paint the window's area with the marble before it shows, so it never
     * flashes white while its pictures decode */
    SetPort(win);
    ShowWindow(win);
    {
        PicHandle m = GetPicture(1001);
        if (m != NULL) { Rect pf = (**m).picFrame; OffsetRect(&pf, -pf.left, -pf.top); DrawPicture(m, &pf); }
        ValidRect(&win->portRect);
    }
    return win;
}

static void DrawPictAt(short id, short x, short y)
{
    PicHandle p = GetPicture(id);
    Rect r;
    if (p == NULL) return;
    r = (**p).picFrame;
    OffsetRect(&r, x - r.left, y - r.top);
    DrawPicture(p, &r);
}

/* Close a game dialog without the white flash: the map area it uncovered
 * is refilled at once from the map's offscreen copy, then the rest updates. */
static void DisposeOverMap(WindowPtr win)
{
    Rect gr = win->portRect;
    GrafPtr sp;
    GetPort(&sp);
    SetPort(win); LocalToGlobal((Point *)&gr.top); LocalToGlobal((Point *)&gr.bottom);
    InsetRect(&gr, -8, -8);   /* frame and shadow */
    DisposeWindow(win);
    if (*gMainGameWindow != 0 && sMapBufGW != NULL) {
        WindowPtr mw = (WindowPtr)*gMainGameWindow;
        Rect lr = gr, mr = mw->portRect;
        SetPort(mw);
        GlobalToLocal((Point *)&lr.top); GlobalToLocal((Point *)&lr.bottom);
        mr.right -= SCROLLBAR_W; mr.bottom -= SCROLLBAR_H;
        if (SectRect(&lr, &mr, &lr) && LockPixels(GetGWorldPixMap(sMapBufGW))) {
            RGBColor bk = {0, 0, 0}, wh = {0xFFFF, 0xFFFF, 0xFFFF};
            RGBForeColor(&bk); RGBBackColor(&wh);
            CopyBits((BitMap *)*GetGWorldPixMap(sMapBufGW), &mw->portBits, &lr, &lr, srcCopy, NULL);
            UnlockPixels(GetGWorldPixMap(sMapBufGW));
        }
    }
    SetPort(sp);
}

static void CloseMacAppWindow(WindowPtr win)
{
    DisposeOverMap(win);
    if (*gMainGameWindow != 0) {
        HiliteWindow((WindowPtr)*gMainGameWindow, true);
        ActivatePalette((WindowPtr)*gMainGameWindow);
    }
    InvalidateAllGameWindows();
    DrainUpdates();
}

/* returns 0 Occupy, 1 Pillage, 2 Sack, 3 Raze */
static short ShowCityVictory(short ci, ConstStr255Param who)
{
    static const short bx[4] = {51, 128, 205, 281}, by[4] = {204, 205, 204, 204}, bh[4] = {21, 20, 20, 20};
    static const char keys[4] = {'o', 'p', 's', 'r'};
    WindowPtr win;
    Rect br[4], v;
    Boolean en[4];
    Str255 s, fmt, cname, label[4];
    short i, choice = -1;
    EventRecord e;
    Handle strs;

    en[0] = true;
    en[1] = PillageValue(ci) > 0;
    en[2] = SackValue(ci) > 0;
    en[3] = (sRazingCities != 2);
    for (i = 0; i < 4; i++) SetRect(&br[i], bx[i], by[i], bx[i] + 64, by[i] + bh[i]);
    strs = GetResource('STR#', 3800);
    for (i = 0; i < 4; i++) {
        if (strs != NULL) GetIndString(label[i], 3800, i + 1); else label[i][0] = 0;
    }
    CityNameP(ci, cname);

    win = NewMacAppWindow(VICT_W, VICT_H);
    if (win == NULL) return 0;
    DrawPictAt(1016, 0, 0);
    DrawPictAt(3800, 38, 38);
    GetDATRawString(367, s);
    SetRect(&v, 38, 42, 38 + 320, 42 + 39);
    DrawSunkenText(&v, s, IlluriaFont(), 36, 1);
    GetDATRawString(370 + (short)((unsigned short)Random() % 4), fmt);
    FormatHeroLine(fmt, who, 0, s);
    SetRect(&v, 38, 88, 358, 107);   DrawSunkenText(&v, s, IlluriaFont(), 17, 1);
    GetDATRawString(374 + (short)((unsigned short)Random() % 3), fmt);
    FormatHeroLine(fmt, cname, 0, s);
    SetRect(&v, 38, 108, 358, 127);  DrawSunkenText(&v, s, IlluriaFont(), 17, 1);
    GetDATRawString(368, s);
    SetRect(&v, 38, 128, 358, 147);  DrawSunkenText(&v, s, IlluriaFont(), 17, 1);
    GetDATRawString(369, s);
    SetRect(&v, 38, 148, 358, 167);  DrawSunkenText(&v, s, IlluriaFont(), 17, 1);
    {
        RGBColor black = {0, 0, 0};
        Rect ring = br[0];
        InsetRect(&ring, -4, -4);
        RGBForeColor(&black);
        PenSize(3, 3);
        FrameRoundRect(&ring, 16, 16);
        PenSize(1, 1);
    }
    for (i = 0; i < 4; i++) {
        if (en[i]) DrawT3DButton(&br[i], label[i]);
        else DrawT3DButtonDim(&br[i], label[i]);
    }

    FlushEvents(mDownMask | keyDownMask | autoKeyMask, 0);
    while (choice < 0) {
        if (!WaitNextEvent(mDownMask | keyDownMask, &e, 5, NULL)) continue;
        if (e.what == mouseDown) {
            Point pt = e.where;
            SetPort(win);
            GlobalToLocal(&pt);
            for (i = 0; i < 4; i++) if (en[i] && PtInRect(pt, &br[i])) choice = i;
        } else {
            char c = (char)(e.message & charCodeMask);
            if (c == '\r' || c == 0x03) choice = 0;
            for (i = 0; i < 4; i++) if (en[i] && (c == keys[i] || c == keys[i] - 32)) choice = i;
        }
    }
    CloseMacAppWindow(win);
    return choice;
}

/* View 1020: 392x94, marble PICT 1001 at (7,7) with edge PICTs 1004 (top),
 * 1005 (left), 1006 (bottom), 1009 (right); '1str' (19,35) 352x19 TxSt 1015. */
