    if (win == NULL) return;
    DrawPictAt(1001, 7, 7);
    DrawPictAt(1004, 0, 0);
    DrawPictAt(1005, 0, 7);
    DrawPictAt(1006, 0, 87);
    DrawPictAt(1009, 385, 0);
