        RGBForeColor(&bg);
        PaintRect(&gwRect);
        RGBForeColor(&black);
        FrameRect(&gwRect);

        /* Title */
        TextSize(14);
        TextFace(bold);
        MoveTo(110, 22);
        DrawString(GetCachedString(STR_MISC, 9, "\pKeyboard Shortcuts"));
        TextFace(0);
        TextSize(10);

        /* Column headers */
        row = 42;
