/* MacApp T3DFrameAdorner, measured on View 3200, drawn over the view's
 * content: the view's own top row and left column 0x6666, bottom row and
 * right column 0xC0C0, and a black ring 1px inside. */
static void DrawT3DFrame(const Rect *v)
{
    RGBColor dark = {0x6666, 0x6666, 0x6666}, light = {0xC0C0, 0xC0C0, 0xC0C0}, black = {0, 0, 0};
    Rect in = *v;
    RGBForeColor(&dark);
    MoveTo(v->left, v->bottom - 2); LineTo(v->left, v->top); LineTo(v->right - 2, v->top);
    RGBForeColor(&light);
    MoveTo(v->right - 1, v->top); LineTo(v->right - 1, v->bottom - 1); LineTo(v->left, v->bottom - 1);
    InsetRect(&in, 1, 1);
    RGBForeColor(&black);
    FrameRect(&in);
}

/* DAT 1000 string by raw position (empty strings count, unlike GetDATString). */
static void GetDATRawString(short rawIdx, Str255 out)
{
    Handle h = GetResource('DAT ', DAT_MASTER_STRINGS);
    out[0] = 0;
    if (h != NULL) {
        const char *p = *h;
        long len = GetHandleSize(h), i = 0;
        short n = 0;
        while (i < len && n < rawIdx) { if (p[i] == 0) n++; i++; }
        while (i < len && p[i] != 0 && out[0] < 255) out[++out[0]] = p[i++];
    }
}

/* Expand a hero offer line's %s (city) and %d (num) */
static void FormatHeroLine(ConstStr255Param fmt, ConstStr255Param city, short num, Str255 out)
{
    short i;
    out[0] = 0;
    for (i = 1; i <= fmt[0]; i++) {
        if (fmt[i] == '%' && i < fmt[0] && (fmt[i + 1] == 's' || fmt[i + 1] == 'd')) {
            Str255 v;
            short k;
            if (fmt[i + 1] == 's') BlockMoveData(city, v, city[0] + 1);
            else NumToString((long)num, v);
            for (k = 1; k <= v[0] && out[0] < 255; k++) out[++out[0]] = v[k];
            i++;
        } else if (out[0] < 255) {
            out[++out[0]] = fmt[i];
        }
    }
}

/* 68k CODE_064 (name picker before FUN_0000068e): on turn 1 take the
 * Random(8)th entry of the player's HERONAM list, later a random entry of all
 * of them; the digit after '#' is the gender (non-'0' = female). */
static Boolean PickHeroName(short playerIdx, Str255 name, Boolean *female)
{
    Handle h = (playerIdx >= 0 && playerIdx < 8) ? sHeroNameDat[playerIdx] : NULL;
    const char *d;
    long len, i;
    short count = 0, want, seen = 0;
    name[0] = 0;
    *female = false;
    if (h == NULL || *gGameState == 0) return false;
    d = *h;
    len = GetHandleSize(h);
    for (i = 0; i < len; i++) if (d[i] == '#') count++;
    if (count == 0) return false;
    if (*(short *)((unsigned char *)*gGameState + 0x136) == 1 && count >= 8)
        count = 8;
    want = (short)((unsigned short)Random() % count) + 1;
    for (i = 0; i < len; i++)
        if (d[i] == '#' && ++seen == want) { i++; break; }
    if (i >= len) return false;
    *female = (d[i] != '0');
    for (i += 2; i < len && d[i] >= ' ' && name[0] < 31; i++)
        name[++name[0]] = d[i];
    return name[0] > 0;
}

static Boolean ShowHeroHire(short playerIdx, Boolean initialOffer)
{
    WindowPtr  hireWin;
    GWorldPtr  offscreen = NULL;
    PicHandle  heroPict = NULL;
    Rect       winRect;
    Boolean    done = false;
    Boolean    hired = false;
    Rect       screenRect = qd.screenBits.bounds;
    unsigned char *gs;

    short      heroStrength, heroMovement, heroCommand, heroCost;
    short      heroNameIdx;
    short      playerGold;
    Boolean    isFemaleHero;
    short      heroX, heroY;  /* spawn location for minimap */

    /* Female hero name indices (Brynhild=1, Thundra=4, Silvara=9, Ravenna=14, Elandra=17) */
    static const short sFemaleIndices[] = {1, 4, 9, 14, 17};
    static const short sMaleIndices[] = {0, 2, 3, 5, 6, 7, 8, 10, 11, 12, 13, 15, 16, 18, 19};
    #define NUM_FEMALE_HEROES 5
    #define NUM_MALE_HEROES 15

    /* Dialog layout constants matching original View 3200 */
    #define HIRE_WIN_W 504
    #define HIRE_WIN_H 352
    Str255     heroName;

    if (*gGameState == 0)
        return false;
    gs = (unsigned char *)*gGameState;

    playerGold = *(short *)(gs + 0x186 + playerIdx * 0x14);

    /* Count heroes for cap check and cost calculation (68k CODE_103) */
    {
        short armyCount = *(short *)(gs + 0x1602);
        short totalHeroes = 0, myHeroes = 0;
        short ai;
        if (armyCount > 100) armyCount = 100;
        for (ai = 0; ai < armyCount; ai++) {
            unsigned char *a = gs + 0x1604 + ai * 0x42;
            if ((unsigned char)a[0x16] == 0x1C) {
                totalHeroes++;
                if ((short)(unsigned char)a[0x15] == playerIdx)
                    myHeroes++;
            }
        }

        /* Hero cap: max 40 total, 5-6 per player (68k CODE_103 FUN_000000be).
         * 68k scales cap to 6 if THIS PLAYER owns > 39 cities (not total sites). */
        {
            short heroCap = 5;
            short myCityCap = 0, ci2;
            short siteCount2 = sCityCount;
            if (siteCount2 > 139) siteCount2 = 139;
            for (ci2 = 0; ci2 < siteCount2; ci2++) {
                unsigned char *c2 = sCityData +ci2 * 0x20;
                if ((unsigned char)c2[0x17] < 2 && *(short *)(c2 + 0x04) == playerIdx)
                    myCityCap++;
            }
            if (myCityCap > 39) heroCap = 6;
            if (!initialOffer && (totalHeroes >= 40 || myHeroes >= heroCap))
                return false;
        }

        /* Initial offer at game start is always shown (hero is free).
         * Subsequent offers (68k CODE_103 FUN_000000be):
         *   1. Generate cost: random(400) if no heroes, random(600) if owned
         *   2. Gold check: player must have >= cost gold
         *   3. Random 23% chance: random(30) < 7 */
        if (!initialOffer) {
            /* 68k: cost generated first, used as gold threshold */
            if (myHeroes == 0)
                heroCost = (short)((unsigned short)Random() % 400);
            else
                heroCost = (short)((unsigned short)Random() % 600);
            if (playerGold < heroCost)
                return false;
            if ((short)((unsigned short)Random() % 30) >= 7)
                return false;
        }

        /* Hero check passed — play voice AFTER probability gate (68k CODE_064).
         * The free turn-1 hero is silent in the original (recorded). */
        if (!initialOffer)
            PlayVoice(SND_VHERO00);

        /* 68k CODE_064 FUN_0000026e: hero stats come from unit type table
         * entry 0x1C (hero type), NOT random generation.  func_0x000049a8
         * copies the DAT 20000 entry and the army record is filled from it.
         * Command bonus starts at 0, gained through combat XP. */
        {
            heroStrength = GetUnitTypeStat(0x1C, 0);  /* from unit type table */
            heroMovement = GetUnitTypeStat(0x1C, 3);  /* from unit type table */
            heroCommand  = 0;                          /* starts at 0, gained via XP */
            /* Fallback if unit type table not loaded or entry missing */
            if (heroStrength < 1) heroStrength = 5;
            if (heroMovement < 1) heroMovement = 14;

            /* Pick name from the full pool of 20. 68k CODE_064 has no gender
             * restriction on the initial offer (the male/female radio works on
             * turn 1 too); the initial hero is just free (heroCost=0). */
            if (initialOffer) {
                heroNameIdx = (short)((unsigned short)Random() % 20);
                heroCost = 0;
            } else {
                heroNameIdx = (short)((unsigned short)Random() % 20);
            }
            /* heroCost already set above for non-initial offers */
        }
    }

    /* Name and gender from the faction's HERONAM list (68k CODE_064) */
    if (!PickHeroName(playerIdx, heroName, &isFemaleHero)) {
        BlockMoveData(sHeroNames[heroNameIdx], heroName, sHeroNames[heroNameIdx][0] + 1);
        isFemaleHero = (heroNameIdx == 1 || heroNameIdx == 4 ||
                        heroNameIdx == 9 || heroNameIdx == 14 || heroNameIdx == 17);
    }

    /* Find spawn location (68k CODE_103 FUN_000000be):
     * Turn 1 (initialOffer): always capital coords (gs+0x186+player*0x14+0x04/0x06).
     * Later: random CITY owned by player (68k iterates extended city records
     * at gs+0x15BE with stride 0x42, NOT army records). */
    heroX = 2; heroY = 2;
    if (initialOffer) {
        /* 68k: turn 1 hero spawns at capital */
        GetCapitalXY(playerIdx, &heroX, &heroY);
    } else {
        short cityCount = sCityCount;
        short myCities = 0, targetN, foundCityIdx = -1, ci;
        if (cityCount > 139) cityCount = 139;
        /* Count player's cities */
        for (ci = 0; ci < cityCount; ci++) {
            unsigned char *c2 = sCityData + ci * 0x20;
            short st2 = (short)(unsigned char)c2[0x17];
            if ((st2 == 0 || st2 == 1) && *(short *)(c2 + 0x04) == playerIdx)
                myCities++;
        }
        /* Pick random city (68k: Random() % playerCityCount, 1-based) */
        targetN = (myCities > 0) ? (short)((unsigned short)Random() % myCities) + 1 : 1;
        { short counted = 0;
          for (ci = 0; ci < cityCount; ci++) {
              unsigned char *c2 = sCityData + ci * 0x20;
              short st2 = (short)(unsigned char)c2[0x17];
              if ((st2 == 0 || st2 == 1) && *(short *)(c2 + 0x04) == playerIdx) {
                  counted++;
                  foundCityIdx = ci;
                  if (counted == targetN) break;
              }
          }
        }
        if (foundCityIdx >= 0) {
            unsigned char *spawnCity = sCityData + foundCityIdx * 0x20;
            heroX = *(short *)(spawnCity + 0x00);
            heroY = *(short *)(spawnCity + 0x02);
        }
    }

    heroPict = GetPicture(isFemaleHero ? 3201 : 3200);

    /* View 3200 "Hire hero": 504x352, positioned like the original at
     * 1024x768 (257,150): centred across, a third of the way down. */
    {
        short sw = screenRect.right, sh = screenRect.bottom, mb = GetMBarHeight();
        short left = (sw - (HIRE_WIN_W + 6)) / 2;
        short top  = mb + (sh - mb - (HIRE_WIN_H + 6)) / 3;
        SetRect(&winRect, left, top, left + HIRE_WIN_W, top + HIRE_WIN_H);
    }

    /* WDEF 128 variant 7: no frame, soft drop shadow (as the tutorial window) */
    LoadAndPlayMusic(MUSIC_STATE_HERO);   /* RINT11; stays until the next state */
    hireWin = NewCWindow(NULL, &winRect, "\p", false,
                          0x0807, (WindowPtr)-1L, false, 0);
    if (hireWin == NULL)
        return false;
    {   /* MacApp windows take their WDEF colours from wctb 1000 */
        Handle wctb = GetResource('wctb', 1000);
        if (wctb != NULL) SetWinColor(hireWin, (CTabHandle)wctb);
    }

    /* Keep game palette active while hire dialog is frontmost */
    if (*gMainGameWindow != 0) {
        PaletteHandle gamePal = GetPalette((WindowPtr)*gMainGameWindow);
        if (gamePal != NULL)
            SetPalette(hireWin, gamePal, false);
    }

    SetPort(hireWin);
    FlushEvents(everyEvent, 0);

    {
        /* View 3200 subviews (content coordinates) */
        Rect overR, pictR, nameR, hireOuter, hireBtnR, dontBtnR, maleR, femaleR;
        TEHandle nameTE = NULL;
        Boolean needsRedraw = true, drawnVisible = false, tutorialChecked = false;
        unsigned long startTick = TickCount();
        Str255 cityName;

        SetRect(&overR, 20, 20, 20 + 224, 20 + 312);           /* 'over' */
        SetRect(&pictR, 258, 64, 258 + 226, 64 + 172);         /* 'pict' */
        SetRect(&nameR, 266, 241, 266 + 210, 241 + 22);         /* 'name' */
        SetRect(&hireOuter, 406, 307, 406 + 82, 307 + 29);      /* 'hire' */
        hireBtnR = hireOuter; InsetRect(&hireBtnR, 4, 4);
        SetRect(&dontBtnR, 323, 311, 323 + 74, 311 + 21);       /* 'dont' */
        SetRect(&maleR, 296, 269, 296 + 75, 269 + 16);          /* cluster (268,295) + (1,1) */
        SetRect(&femaleR, 372, 269, 372 + 75, 269 + 16);        /*                + (1,77) */

        /* City the hero appears in (str4 / "%s") */
        cityName[0] = 0;
        {
            short ci, cc = sCityCount;
            if (cc > 139) cc = 139;
            for (ci = 0; ci < cc; ci++) {
                unsigned char *c = sCityData + ci * 0x20;
                if (c[0x17] >= 2) continue;
                if (heroX >= *(short *)(c + 0) && heroX <= *(short *)(c + 0) + 1 &&
                    heroY >= *(short *)(c + 2) && heroY <= *(short *)(c + 2) + 1) {
                    short n = 0;
                    if (ci < sCityNameCount)
                        while (n < MAX_CITY_NAME - 1 && sCityNames[ci][n]) n++;
                    cityName[0] = (unsigned char)n;
                    BlockMoveData(sCityNames[ci], cityName + 1, n);
                    break;
                }
            }
        }

        {
            Rect te = nameR;
            InsetRect(&te, 4, 3);
            TextFont(ChicagoFont()); TextSize(12); TextFace(0);
            nameTE = TENew(&te, &te);
            if (nameTE != NULL) {
                TESetText(heroName + 1, heroName[0], nameTE);
                TESetSelect(0, 32767, nameTE);
            }
        }

        while (!done) {
            EventRecord evt;

            /* Tutorial: THERO over the drawn hero offer (68k CODE_064). */
            if (drawnVisible && !needsRedraw && !tutorialChecked) {
                tutorialChecked = true;
                if (ShowTutorialScreen("\pTHERO", 0x01)) needsRedraw = true;
                SetPort(hireWin);
            }

            if (needsRedraw) {
                static const short edges[4][5] = {     /* pict, top, left, bottom, right */
                    {1004, 0, 0, 7, HIRE_WIN_W}, {1005, 7, 0, HIRE_WIN_H, 7},
                    {1006, HIRE_WIN_H - 7, 0, HIRE_WIN_H, HIRE_WIN_W},
                    {1008, 0, HIRE_WIN_W - 7, HIRE_WIN_H, HIRE_WIN_W} };
                RGBColor cream = {0xFFFF, 0xFFFF, 0xCCCC}, black = {0, 0, 0};
                Rect r;
                short ei;
                Str255 s;

                SetPort(hireWin);
                SetRect(&r, 7, 7, HIRE_WIN_W - 7, HIRE_WIN_H - 7);
                {
                    PicHandle marble = GetPicture(1001);
                    if (marble != NULL) {
                        Rect pf = (**marble).picFrame;
                        ClipRect(&r);
                        OffsetRect(&pf, 7 - pf.left, 7 - pf.top);
                        DrawPicture(marble, &pf);
                    }
                }
                for (ei = 0; ei < 4; ei++) {
                    PicHandle pic = GetPicture(edges[ei][0]);
                    Rect pf, clip;
                    if (pic == NULL) continue;
                    SetRect(&clip, edges[ei][2], edges[ei][1], edges[ei][4], edges[ei][3]);
                    ClipRect(&clip);
                    pf = (**pic).picFrame;
                    OffsetRect(&pf, edges[ei][2] - pf.left, edges[ei][1] - pf.top);
                    DrawPicture(pic, &pf);
                }
                ClipRect(&hireWin->portRect);

                /* Overview inset with its T3DFrameAdorner */
                r = overR; InsetRect(&r, -1, -1);   /* adorner is on the enclosing view */
                DrawT3DFrame(&r);
                DrawOverviewTo((GrafPtr)hireWin, overR, kOvOverlays);
                SetPort(hireWin);

                /* "A Hero!" — TSunkenText (20,245) 35x252, TxSt 1005 Illuria 36 cream */
                SetRect(&r, 245, 20, 245 + 252, 20 + 35);
                DrawSunkenText(&r, ViewString(s, 3200, 1, "\pA Hero!"), IlluriaFont(), 36, 1);

                /* Portrait with frame, and str1..str4 over it (TxSt 1015 Illuria 17) */
                if (heroPict != NULL) {
                    Rect pr = pictR;
                    InsetRect(&pr, 1, 1);
                    DrawPicture(heroPict, &pr);
                }
                DrawT3DFrame(&pictR);
                {
                    short base = isFemaleHero ? 472 : 464, li;
                    if (!initialOffer) base += 4;
                    for (li = 0; li < 4; li++) {
                        Str255 fmt, line;
                        GetDATRawString(base + li, fmt);
                        /* paid offer: line 2 "join you for %d gold", line 3 "You have %d gold" */
                        FormatHeroLine(fmt, cityName, li == 2 ? playerGold : heroCost, line);
                        if (line[0] == 0) continue;
                        SetRect(&r, pictR.left + 1, pictR.top + 90 + 16 * li,
                                pictR.left + 1 + 224, pictR.top + 106 + 16 * li);
                        DrawSunkenText(&r, line, IlluriaFont(), 17, 1);
                    }
                }

                /* Name field: T3DFrameAdorner + white/lavender background */
                DrawT3DFrame(&nameR);
                {
                    RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF}, lav = {0xDADA, 0xDADA, 0xFFFF};
                    Rect f = nameR;
                    InsetRect(&f, 2, 2);
                    RGBForeColor(&white); FrameRect(&f);
                    InsetRect(&f, 1, 1);
                    RGBForeColor(&lav); PaintRect(&f);
                    RGBForeColor(&black);
                    RGBBackColor(&lav);
                    if (nameTE != NULL) TEUpdate(&nameR, nameTE);
                    RGBBackColor(&white);
                }

                /* Male / Female radios, labels TxSt 1009 Chicago cream embossed */
                TextFont(ChicagoFont()); TextSize(12); TextFace(0);
                DrawT3DRadio(maleR.left, maleR.top, !isFemaleHero);
                DrawEmbossedString(ViewString(s, 3021, 21, "\pMale"), maleR.left + 17, maleR.top + 11, &cream);
                DrawT3DRadio(femaleR.left, femaleR.top, isFemaleHero);
                DrawEmbossedString(ViewString(s, 3021, 22, "\pFemale"), femaleR.left + 17, femaleR.top + 11, &cream);

                /* Hire (default, ringed) and Don't Hire (paid offers only) */
                RGBForeColor(&black);
                PenSize(3, 3);
                FrameRoundRect(&hireOuter, 16, 16);
                PenSize(1, 1);
                DrawT3DButton(&hireBtnR, ViewString(s, 3200, 4, "\pHire"));
                if (!initialOffer)
                    DrawT3DButton(&dontBtnR, ViewString(s, 3200, 5, "\pDon't Hire"));

                if (!((WindowPeek)hireWin)->visible) {
                    ShowWindow(hireWin);      /* draws again on its update event */
                } else {
                    drawnVisible = true;
                }
                needsRedraw = false;
            }

            if (nameTE != NULL) TEIdle(nameTE);
            if (!WaitNextEvent(everyEvent, &evt, 10, NULL))
                continue;

            if (evt.what == mouseDown) {
                Point localPt = evt.where;
                SetPort(hireWin);
                GlobalToLocal(&localPt);

                if (PtInRect(localPt, &hireOuter)) {
                    done = true;
                    hired = true;
                } else if (!initialOffer && PtInRect(localPt, &dontBtnR)) {
                    done = true;
                    hired = false;
                } else if (PtInRect(localPt, &nameR) && nameTE != NULL) {
                    TEClick(localPt, (evt.modifiers & shiftKey) != 0, nameTE);
                } else if ((PtInRect(localPt, &maleR) && isFemaleHero) ||
                           (PtInRect(localPt, &femaleR) && !isFemaleHero)) {
                    isFemaleHero = !isFemaleHero;
                    if (heroPict != NULL) ReleaseResource((Handle)heroPict);
                    heroPict = GetPicture(isFemaleHero ? 3201 : 3200);
                    needsRedraw = true;
                }
            }
            else if (evt.what == keyDown || evt.what == autoKey) {
                char key = evt.message & charCodeMask;
                if ((TickCount() - startTick) < 30)
                    continue;
                if (key == 0x0D || key == 0x03) {
                    done = true;
                    hired = true;
                } else if (key == 0x1B && !initialOffer) {
                    done = true;
                    hired = false;
                } else if (nameTE != NULL &&
                           ((**nameTE).teLength < 19 || key == 0x08 || key < 0x20)) {
                    RGBColor lav = {0xDADA, 0xDADA, 0xFFFF}, white = {0xFFFF, 0xFFFF, 0xFFFF};
                    SetPort(hireWin);
                    RGBBackColor(&lav);
                    TEKey(key, nameTE);
                    RGBBackColor(&white);
                }
            }
            else if (evt.what == updateEvt) {
                WindowPtr updWin = (WindowPtr)evt.message;
                if (updWin == hireWin) {
                    BeginUpdate(updWin);
                    needsRedraw = true;
                    EndUpdate(updWin);
                } else {
                    HandleUpdate(&evt);
                }
            }
        }

        /* The (possibly edited) name */
        if (nameTE != NULL) {
            CharsHandle ch = TEGetText(nameTE);
            short n = (**nameTE).teLength;
            if (n > 19) n = 19;
            if (n > 0) {
                heroName[0] = (unsigned char)n;
                BlockMoveData(*ch, heroName + 1, n);
            }
            TEDispose(nameTE);
        }
    }

    /* Process hire: deduct gold and create army record */
    if (hired && *gGameState != 0) {
        *(short *)(gs + 0x186 + playerIdx * 0x14) -= heroCost;

        {
            short armyCount = *(short *)(gs + 0x1602);
            unsigned char *armyBase = gs + 0x1604 + armyCount * 0x42;
            short b;

            for (b = 0; b < 0x42; b++)
                armyBase[b] = 0;

            /* Place at spawn city */
            *(short *)(armyBase + 0x00) = heroX;
            *(short *)(armyBase + 0x02) = heroY;

            /* Hero name */
            {
                const unsigned char *name = heroName;
                short nlen = name[0];
                for (b = 0; b < 16; b++)
                    armyBase[0x04 + b] = 0;
                for (b = 0; b < nlen && b < 15; b++)
                    armyBase[0x04 + b] = name[b + 1];
            }

            armyBase[0x14] = 0x1C;  /* sprite: hero */
            armyBase[0x15] = (unsigned char)playerIdx;

            armyBase[0x16] = 0x1C;  /* unit slot 0 = hero */
            armyBase[0x17] = 0xFF;
            armyBase[0x18] = 0xFF;
            armyBase[0x19] = 0xFF;

            armyBase[0x1a] = (unsigned char)heroMovement;
            armyBase[0x1b] = 0;
            armyBase[0x1c] = 0;
            armyBase[0x1d] = 0;

            armyBase[0x1e] = (unsigned char)heroStrength;
            armyBase[0x1f] = 0;
            armyBase[0x20] = 0;
            armyBase[0x21] = 0;

            armyBase[0x22] = (unsigned char)heroCommand;
            armyBase[0x23] = 0;
            armyBase[0x24] = 0;
            armyBase[0x25] = 0;

            RecalcArmyStrength(armyBase);
            armyBase[0x2e] = (unsigned char)(heroMovement);
            armyBase[0x31] = 1;  /* hero applied level (for turn-start level-up check) */

            *(short *)(gs + 0x1602) = armyCount + 1;
        }

        /* Store hero name in hero_names table */
        {
            short heroSlot;
            for (heroSlot = 0; heroSlot < 40; heroSlot++) {
                if (*(gs + 0x544 + heroSlot * 2) == 0) {
                    const unsigned char *name = heroName;
                    short nlen = name[0];
                    short b;
                    for (b = 0; b < 20; b++)
                        *(gs + 0x224 + heroSlot * 20 + b) = 0;
                    for (b = 0; b < nlen && b < 19; b++)
                        *(gs + 0x224 + heroSlot * 20 + b) = name[b + 1];
                    *(short *)(gs + 0x544 + heroSlot * 2) = 1;
                    break;
                }
            }
        }

        /* Write per-player hero instance record at gs+0x1422+player*0x2C */
        {
            short armyCount2 = *(short *)(gs + 0x1602) - 1;  /* just incremented above */
            unsigned char *heroRec = gs + 0x1422 + playerIdx * 0x2C;
            const unsigned char *name = heroName;
            short nlen = name[0];
            short b;
            heroRec[0x00] = 1;  /* active */
            heroRec[0x01] = 0;
            heroRec[0x02] = 0;
            heroRec[0x03] = (unsigned char)(TickCount() & 0xFF);  /* random seed */
            *(short *)(heroRec + 0x04) = armyCount2;  /* hero army index */
            for (b = 0; b < 20; b++)
                heroRec[0x06 + b] = 0;
            for (b = 0; b < nlen && b < 19; b++)
                heroRec[0x06 + b] = name[b + 1];
        }

        /* 68k CODE_064 FUN_0000026e: write hero gender to gs+0x594+player*2.
         * 0 = male, 1 = female. Used by IsHeroFemale() for sprite remapping. */
        *(short *)(gs + 0x594 + playerIdx * 2) = isFemaleHero ? 1 : 0;

        /* gs+0xD12+p*0x1E (stride 0x1E) is player p's Standard item record,
         * not a "hero command state": a hero hired on turn 1 (the initial
         * offer) carries its player's Standard (FUN_1003956c). */
        {
            short heroArmyIdx = *(short *)(gs + 0x1602) - 1;  /* just-added hero */
            GiveStartingStandard(playerIdx, heroArmyIdx);
        }

        /* 68k CODE_064 FUN_00000100: allied units join hired hero.
         * Not on initial (free) offer. Random: <70%→1, <95%→2, ≥95%→3 allies.
         * Each ally fills an empty unit slot in the hero's army. */
        if (!initialOffer) {
            short armyCount3 = *(short *)(gs + 0x1602);
            unsigned char *heroArmy = gs + 0x1604 + (armyCount3 - 1) * 0x42;
            short r100 = (short)((unsigned short)Random() % 100);
            short allyN = (r100 < 70) ? 1 : (r100 < 95) ? 2 : 3;
            short spawned = 0, ai2;
            for (ai2 = 0; ai2 < allyN; ai2++) {
                short slot2;
                for (slot2 = 1; slot2 < 4; slot2++) {  /* skip slot 0 (hero) */
                    if ((unsigned char)heroArmy[0x16 + slot2] == 0xFF) {
                        short at = (short)((unsigned short)Random() % 4);
                        short aHP = GetUnitTypeStat(at, 0);
                        short aMv = GetUnitTypeStat(at, 3);
                        if (aHP < 1) aHP = 3;
                        if (aMv < 1) aMv = 10;
                        heroArmy[0x16 + slot2] = (unsigned char)at;
                        heroArmy[0x1a + slot2] = (unsigned char)aMv;
                        heroArmy[0x1e + slot2] = (unsigned char)aHP;
                        heroArmy[0x22 + slot2] = 0;
                        heroArmy[0x26 + slot2] = 0;
                        spawned++;
                        break;
                    }
                }
            }
            if (spawned > 0) RecalcArmyStrength(heroArmy);
        }
    }

    if (heroPict != NULL)
        ReleaseResource((Handle)heroPict);
    if (offscreen != NULL)
        DisposeGWorld(offscreen);
    DisposeOverMap(hireWin);
    if (*gMainGameWindow != 0)
        ActivatePalette((WindowPtr)*gMainGameWindow);
    InvalidateAllGameWindows();
    DrainUpdates();
    return hired;
}


/* ===================================================================
 * CheckVictoryConditions — Check if any player has won or lost
 *
 * Victory: a single player owns all cities, or dominant player has sufficient margin
 * Defeat: current human player has no cities (68k: no cities → eliminated)
 * Returns: 0=no result, 1=victory, -1=defeat
 * =================================================================== */
static short CheckVictoryConditions(void)
{
    unsigned char *gs;
    short cityCount, armyCount;
    short playerCities[8], playerArmies[8];
    short ci, ai, pi;
    short curPlayer;
    short alivePlayers = 0;
    short lastAlive = -1;

    if (*gGameState == 0) return 0;
    gs = (unsigned char *)*gGameState;
    curPlayer = *(short *)(gs + 0x110);

    /* Turn limit: 68k CODE_130 FUN_00000122 line 61 — at turn > 201 (0xC9),
     * the turn processing function returns early without ANY victory checks.
     * Must be checked FIRST, before other conditions. */
    { short turnCount = *(short *)(gs + 0x136);
      if (turnCount > 201)
          return 0;  /* frozen: no victory, no defeat */
    }

    cityCount = sCityCount;
    armyCount = *(short *)(gs + 0x1602);
    if (cityCount > 139) cityCount = 139;
    if (armyCount > 100) armyCount = 100;

    for (pi = 0; pi < 8; pi++) {
        playerCities[pi] = 0;
        playerArmies[pi] = 0;
    }

    for (ci = 0; ci < cityCount; ci++) {
        unsigned char *vc = sCityData +ci * 0x20;
        short owner = *(short *)(vc + 0x04);
        short vst = (short)(unsigned char)vc[0x17];
        if (vst != 0 && vst != 1) continue;  /* only cities + capitals */
        if (owner >= 0 && owner < 8) playerCities[owner]++;
    }
    for (ai = 0; ai < armyCount; ai++) {
        short owner = (short)(unsigned char)*(gs + 0x1604 + ai * 0x42 + 0x15);
        if (owner >= 0 && owner < 8) playerArmies[owner]++;
    }

    for (pi = 0; pi < 8; pi++) {
        if (*(short *)(gs + 0x138 + pi * 2) != 0 && playerCities[pi] > 0) {
            alivePlayers++;
            lastAlive = pi;
        }
    }

    /* Only one player left alive = victory (68k CODE_130 Condition B):
     * Winner must also own > 50% of all cities on the map.
     * Count total cities (including neutral) for threshold. */
    if (alivePlayers == 1 && lastAlive >= 0) {
        short totalC = 0, winnerC = playerCities[lastAlive];
        short cci;
        for (cci = 0; cci < cityCount; cci++) {
            unsigned char *ct = sCityData + cci * 0x20;
            if ((short)(unsigned char)ct[0x17] < 2) totalC++;
        }
        /* the original: every other side eliminated, neutral cities
         * don't matter (Isles hot-seat win with 9 cities still neutral) */
        (void)winnerC; (void)totalC;
        return (lastAlive == curPlayer) ? 1 : -1;
    }

    /* Dominant player victory (68k CODE_130 FUN_000006d2):
     * Uses CITY counts (total cities on map). Conditions:
     * 1. Exactly one human player alive, some AI remain
     * 2. Human's city count > totalCities / 2
     * 3. Human's city count > maxAI_cities + totalCities / 8
     * Sets gs+0x15e as domination flag to suppress hero offers. */
    {
        short totalCities = 0;
        short humanCount = 0, aiCount = 0;
        short humanIdx = -1;
        short maxAICities = 0;
        for (pi = 0; pi < 8; pi++) {
            if (*(short *)(gs + 0x138 + pi * 2) == 0) continue;
            totalCities += playerCities[pi];
            if (*(short *)(gs + 0xd0 + pi * 2) == 0) {
                humanCount++;
                humanIdx = pi;
            } else {
                aiCount++;
                if (playerCities[pi] > maxAICities)
                    maxAICities = playerCities[pi];
            }
        }
        /* Also count neutral cities (68k: total city tiles on map) */
        { short ci;
          short cc = sCityCount;
          if (cc > 139) cc = 139;
          for (ci = 0; ci < cc; ci++) {
              unsigned char *ct = sCityData + ci * 0x20;
              short est = (short)(unsigned char)ct[0x17];
              short cown = *(short *)(ct + 0x04);
              if (est < 2 && (cown == 0x0F || cown == (short)0xFF || cown < 0))
                  totalCities++;  /* neutral city */
          }
        }
        if (humanCount == 1 && aiCount > 0 && humanIdx >= 0 &&
            *(short *)(gs + 0x15e) == 0 && totalCities > 0) {
            short hCities = playerCities[humanIdx];
            if (hCities > totalCities / 2 &&
                hCities > maxAICities + totalCities / 8) {
                *(short *)(gs + 0x15e) = 1;  /* domination flag */
            }
        }
        /* Single remaining human wins if all AI eliminated */
        if (humanCount == 1 && aiCount == 0 && humanIdx >= 0) {
            return (humanIdx == curPlayer) ? 1 : -1;
        }
    }

    /* NOTE: Allied victory was removed — the 68k has NO "all players allied = victory"
     * condition. With diplomacy enabled, players start at peace, and this would
     * falsely trigger shared victory at game start. Conquest/dominant are the only
     * victory paths in the original game. */

    /* Current player has no cities = defeat (68k: no cities → dead) */
    if (playerCities[curPlayer] == 0)
        return -1;

    return 0;
}


/* ===================================================================
 * ShowVictoryDialog — Show victory or defeat screen
 * =================================================================== */
static void ShowVictoryDialog(Boolean victory)
{
    /* View 4510 (PPC FUN_10040a38): 382x378 marble, "Congratulations"
     * (Illuria 36), PICT 4501 framed at (10,47), "You have conquered the
     * world!" (STR# 4510); RINT12/21 plays; a click returns to the map,
     * which stays in a post-victory state (End Turn disabled). */
    WindowPtr win;
    Rect r, v;
    Str255 s;
    EventRecord e;
    if (!victory) return;
    win = NewMacAppWindow(382, 378);
    if (win == NULL) return;
    DrawPictAt(1001, 7, 7);
    DrawPictAt(1004, 0, 0); DrawPictAt(1005, 0, 7); DrawPictAt(1006, 0, 371); DrawPictAt(1007, 375, 0);
    SetRect(&r, 10, 47, 372, 348);
    DrawT3DFrame(&r);
    DrawPictAt(4501, 11, 48);
    GetIndString(s, 4510, 1);
    SetRect(&v, 7, 9, 375, 49); DrawSunkenText(&v, s[0] ? s : "\pCongratulations", IlluriaFont(), 36, 1);
    GetIndString(s, 4510, 2);
    SetRect(&v, 8, 351, 376, 370); DrawSunkenText(&v, s[0] ? s : "\pYou have conquered the world!", IlluriaFont(), 17, 1);
    FlushEvents(mDownMask | keyDownMask, 0);
    for (;;) if (WaitNextEvent(mDownMask | keyDownMask, &e, 5, NULL)) break;
    CloseMacAppWindow(win);
}


/* ===================================================================
 * ShowCityBuildSelection — the city window (View 3300 "City"), production
 * pane (View 3303), measured on the original (Erythea, Mirea, turn 1):
 *   520x352 frameless window with shadow (WDEF 128 v7), placed like every
 *   MacApp dialog: left (screenW-526)/2, top menubar + (rest-358)/3;
 *   marble edges 1004/1005/1006/1008 around PICT 1001;
 *   overview (20,20) 224x312 in a T3DFrameAdorner view, base map only with
 *   the 10x10 selection shield on the city;
 *   name TSunkenText (20,245) 39x268, TxSt 1005 (Illuria 36 cream);
 *   tabs info/buil/prod/vect T3DIconButtons 40x40 at y 287, x 252/299/346/393
 *   (cicn 3300-3303); 'ok' T3DButton (292,437) 29x68, default.
 * Production pane at (20,245): capital banner (8,50) from PICT 30011
 * (owner*36, 36) 36x23; "Current:" (51,48); current TProdView (44,112) with
 * "%dt" at (51,151); TProdViews arm1-4 (82, 8/56/104/152): ABITS ring
 * (owner*32,0) 31x30 + army sprite 32x29 at the view origin; STOP (80,200)
 * 36x36 cicn 3310; when producing: PICT 3300 in a frame at (121,15) 130x130
 * and name / "Time: %d" / "Cost: %d" / "Strength: %d" / "Move: %d" at x 151,
 * y 122/152/172/192/212 (TxSt 1015, Illuria 17 cream).
 * Production is committed on Done (setting it costs nothing); Escape cancels.
 * =================================================================== */
#define CITY_WIN_W 520
#define CITY_WIN_H 352
#define CITY_PANE_L 245
#define CITY_PANE_T 20

static void DrawProdView(short L, short T, short owner, short unitType)
{
    Rect sr, dr;
    RGBColor savedBg, black = {0, 0, 0};
    GrafPtr port;
    short sheet = (owner >= 0 && owner < 8) ? owner : 8;
    GetPort(&port);
    RGBForeColor(&black);
    if (sAbitsLoaded && sAbitsGW != NULL) {
        PixMapHandle pm = GetGWorldPixMap(sAbitsGW);
        LockPixels(pm);
        GetBackColor(&savedBg);
        RGBBackColor(&sAbitsBgColor);
        if (unitType >= 0) SetRect(&sr, sheet * 32, 0, sheet * 32 + 31, 30);
        else               SetRect(&sr, 512, 0, 543, 30);      /* empty "Current" ring */
        SetRect(&dr, L, T, L + 31, T + 30);
        CopyBits((BitMap *)*pm, &port->portBits, &sr, &dr, 36, NULL);
        RGBBackColor(&savedBg);
        UnlockPixels(pm);
    }
    if (unitType >= 0 && sUnitTypesLoaded && unitType < sUnitTypeCount) {
        short idx = sUnitTypeTable[unitType * UNIT_TYPE_ENTRY];
        GWorldPtr gw = sArmyGW[sheet] ? sArmyGW[sheet] : sArmyGW[0];
        if (gw != NULL) {
            PixMapHandle pm = GetGWorldPixMap(gw);
            LockPixels(pm);
            GetBackColor(&savedBg);
            RGBBackColor(&sArmyBgColor[sheet]);
            SetRect(&sr, (idx % 16) * 32, (idx / 16) * 30, (idx % 16) * 32 + 32, (idx / 16) * 30 + 29);
            SetRect(&dr, L, T, L + 32, T + 29);
            CopyBits((BitMap *)*pm, &port->portBits, &sr, &dr, 36, NULL);
            RGBBackColor(&savedBg);
            UnlockPixels(pm);
        }
    }
}

/* T3DButton with a two-line ('\r') label */
static void DrawT3DButton2(const Rect *r, ConstStr255Param label)
{
    RGBColor black = {0, 0, 0};
    Str255 a, b;
    short i, fnum, w;
    a[0] = b[0] = 0;
    for (i = 1; i <= label[0] && label[i] != '\r'; i++) a[++a[0]] = label[i];
    for (i++; i <= label[0]; i++) b[++b[0]] = label[i];
    DrawT3DBevel(r);
    GetFNum("\pChicago", &fnum);
    TextFont(fnum); TextSize(12); TextFace(0);
    if (b[0] == 0) {
        w = StringWidth(a);
        DrawEmbossedStringIn(a, (r->left + r->right - w + 1) / 2 - 1, (r->top + r->bottom) / 2 + 4, &black, 0x8888, 0xDDDD);
    } else {
        w = StringWidth(a);
        DrawEmbossedStringIn(a, (r->left + r->right - w + 1) / 2 - 1, r->top + 15, &black, 0x8888, 0xDDDD);
        w = StringWidth(b);
        DrawEmbossedStringIn(b, (r->left + r->right - w + 1) / 2 - 1, r->top + 29, &black, 0x8888, 0xDDDD);
    }
}

/* Two-line sunken label ('\r' break), TxSt 1015, left aligned */
static void DrawSunkenText2(const Rect *v, ConstStr255Param s)
{
    Str255 a, b;
    short i;
    Rect r = *v;
    a[0] = b[0] = 0;
    for (i = 1; i <= s[0] && s[i] != '\r'; i++) a[++a[0]] = s[i];
    for (i++; i <= s[0]; i++) b[++b[0]] = s[i];
    r.bottom = r.top + 19;
    DrawSunkenText(&r, a, IlluriaFont(), 17, -2);
    OffsetRect(&r, 0, 20);
    if (b[0]) DrawSunkenText(&r, b, IlluriaFont(), 17, -2);
}

static void FormatTwoStr(ConstStr255Param fmt, ConstStr255Param a, ConstStr255Param b, Str255 out)
{
    short i, k = 0;
    out[0] = 0;
    for (i = 1; i <= fmt[0]; i++) {
        if (fmt[i] == '%' && i < fmt[0] && fmt[i + 1] == 's') {
            ConstStr255Param v = (k++ == 0) ? a : b; short j;
            for (j = 1; j <= v[0] && out[0] < 255; j++) out[++out[0]] = v[j];
            i++;
        } else if (out[0] < 255) out[++out[0]] = fmt[i];
    }
}

static void DrawBigShieldAt(short side, short x, short y)
{
    RGBColor key;
    CGrafPtr sp; GDHandle sd;
    GrafPtr port;
    Rect b;
    if (sShieldBigGW == NULL) return;
    GetPort(&port);
    b = (*GetGWorldPixMap(sShieldBigGW))->bounds;
    GetGWorld(&sp, &sd); SetGWorld(sShieldBigGW, NULL);
    GetCPixel(b.right - 1, b.bottom - 1, &key);
    SetGWorld(sp, sd);
    SetPort(port);
    BlitKeyedColor(sShieldBigGW, &key, side * 32, 0, 32, 36, x, y);
}

